	["4. A nivel 60, el mismo instructor enseña la de oficial y el vendedor tiene las rápidas."] = "4. Auf Stufe 60 lehrt derselbe Lehrer Reiten (Geselle), und der Händler hat die schnellen Reittiere.",
	["A %s"] = "%s entfernt",
	["A %s le queda poco"] = "%s läuft bald ab",
	["A Entrañas se baja por elevadores desde las ruinas de la capital de Lordaeron."] = "Nach Unterstadt fährt man mit Aufzügen hinunter, aus den Ruinen der Hauptstadt Lordaerons.",
	["A Mis planes"] = "Zu „Meine Pläne“",
	["A Ragnaros no le gusta que lo despierten antes de tiempo, y su mayordomo Executus lo paga caro."] = "Ragnaros mag es nicht, zu früh geweckt zu werden, und sein Majordomus Exekutus muss teuer dafür bezahlen.",
	["A Silithus se entra desde el Cráter de Un'Goro."] = "Nach Silithus kommt man vom Krater von Un'Goro aus.",
	["A distancia"] = "Fernkampf",
	["A entregar tus misiones"] = "Auf zur Abgabe deiner Quests",
	["A la entrada de Ventormenta, estatuas de los grandes héroes de la Segunda Guerra reciben a los visitantes."] = "Am Eingang von Sturmwind begrüßen Statuen der großen Helden des Zweiten Krieges die Besucher.",
	["A la vista: %d de la manada · %d de tu grupo"] = "In Sicht: %d aus dem Rudel · %d aus deiner Gruppe",
	["A las demás les dice qué les falta: tu nivel o una misión antes."] = "Bei den anderen steht, was ihnen fehlt: deine Stufe oder eine Quest davor.",
	["A los lados del modelo, un botón por ranura: un clic oculta esa pieza y otro la vuelve a poner."] = "Neben dem Modell gibt es einen Knopf pro Platz: Ein Klick blendet das Teil aus, ein weiterer legt es wieder an.",
	["A mitad de la pelea aparecen espectros de hielo: mátenlos rápido o usen ataques en área."] = "Mitten im Kampf erscheinen Frostgeister: Tötet sie schnell oder nutzt Flächenangriffe.",
	["A mitad de la pelea se protege con un escudo y prepara una gran explosión: cuando lo veas brillar, ¡aléjate de él!"] = "Mitten im Kampf schützt er sich mit einem Schild und lädt eine große Explosion auf: Wenn er leuchtet, geh weg von ihm!",
	["A nivel 10 haces las misiones para domar a tu primera mascota."] = "Auf Stufe 10 machst du die Quests, um deinen ersten Begleiter zu zähmen.",
	["A nivel 20 aprendes Lobo fantasmal: ¡te vuelves un lobo como yo! Corre, que te echo una carrera."] = "Auf Stufe 20 lernst du Geisterwolf: Du wirst ein Wolf wie ich! Komm, wir laufen um die Wette.",
	["A nivel 60 sigue la rápida: equitación de oficial y una montura épica."] = "Auf Stufe 60 folgt das schnelle: Reiten (Geselle) und ein episches Reittier.",
	["A probar"] = "Ausprobieren",
	["A quién ir"] = "Zu wem gehen",
	["A su entrenador"] = "Zu seinem Lehrer",
	["A tu gusto"] = "Nach deinem Geschmack",
	["A tu lado"] = "An deiner Seite",
	["A tu nivel los enemigos caen rápido: remata con 3 puntos de combo."] = "Auf deiner Stufe fallen Gegner schnell: Beende mit 3 Combopunkten.",
	["A un clic"] = "Mit einem Klick",
	["A veces"] = "Manchmal",
	["A veces el golpe ni te toca."] = "Manchmal trifft dich der Schlag gar nicht.",
	["A veces pescas cajas y botellas con mensajes que empiezan una misión."] = "Manchmal angelst du Kisten und Flaschen mit Botschaften, die eine Quest starten.",
	["A veces salen gemas al minar: guárdalas, porque varias profesiones las usan en sus recetas."] = "Beim Bergbau springen manchmal Edelsteine heraus: Heb sie auf, denn mehrere Berufe brauchen sie für ihre Rezepte.",
	["Abajo"] = "Unten",
	["Abajo del modelo, elige lo que hace tu personaje (caminar, bailar, saludar...) y páusalo."] = "Unter dem Modell wählst du, was dein Charakter tut (gehen, tanzen, winken...), und kannst es pausieren.",
	["Abalorio"] = "Schmuck",
	["Abalorios"] = "Schmuckstücke",
	["Abandonar"] = "Abbrechen",
	["Abandonar marcadas (%d)"] = "Markierte abbrechen (%d)",
	["Abandonaste %d misiones"] = "Du hast %d Quests abgebrochen",
	["Abierta"] = "Offen",
	["Abiertas"] = "Geöffnet",
	["Abrazo vampírico: tu daño de sombras te cura."] = "Vampirumarmung: Dein Schattenschaden heilt dich.",
	["Abre Heridas profundas."] = "Öffnet Tiefe Wunden.",
	["Abre Paisaje y gráficos"] = "Öffnet Landschaft und Grafik",
	["Abre Recolección. Con «ruta», crea y sigue una ruta de farmeo en tu zona."] = "Öffnet Sammeln. Mit „ruta“ erstellst du eine Farmroute in deinem Gebiet und folgst ihr.",
	["Abre desde el sigilo para empezar con ventaja."] = "Greif aus der Verstohlenheit an, um mit Vorteil zu beginnen.",
	["Abre el mapa del juego en esta misma zona. En combate el mapa del juego no se abre desde Alfa."] = "Öffnet die Karte des Spiels in diesem Gebiet. Im Kampf öffnet sich die Spielkarte nicht über Alfa.",
	["Abre el mapa y haz clic derecho (o Mayús+clic) donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras. En el mapa del juego, Mayús+clic derecho."] = "Öffne die Karte und mach einen Rechtsklick (oder Umschalt+Klick), wo du eine willst: Gib ihr Namen, Symbol und Farbe, und der Pfeil führt dich hin, wann du willst. Auf der Spielkarte: Umschalt+Rechtsklick.",
	["Abre el modo pesca (aquí, con /alfa pesca o al ponerte la caña) y pulsa %s: tu tecla te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "Öffne den Angelmodus (hier, mit /alfa pesca oder beim Anlegen der Angel) und drück %s: Deine Taste legt dir die Ausrüstung an, bringt den Köder an, wirft aus und holt ein, wenn es platscht.",
	["Abre el modo pesca y elige tu tecla: te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "Öffne den Angelmodus und wähl deine Taste: Sie legt dir die Ausrüstung an, bringt den Köder an, wirft aus und holt ein, wenn es platscht.",
	["Abre el modo pesca y pulsa tu tecla: lo que saques aparece aquí."] = "Öffne den Angelmodus und drück deine Taste: Was du fängst, erscheint hier.",
	["Abre la Cocina del juego (el botón lo hace) y vuelve a pulsar."] = "Öffne das Kochkunst-Fenster des Spiels (der Button macht das) und drück noch einmal.",
	["Abre la Enciclopedia y en la ficha del objeto toca «Agregar a mi ruta»."] = "Öffne die Enzyklopädie und klick im Eintrag des Gegenstands auf „Zu meiner Route hinzufügen“.",
	["Abre la casa de subastas para escanear."] = "Öffne das Auktionshaus zum Scannen.",
	["Abre la casa de subastas y pulsa «Escanear con Alfa» para saber cuánto valen tus objetos."] = "Öffne das Auktionshaus und drück „Mit Alfa scannen“, um zu erfahren, was deine Gegenstände wert sind.",
	["Abre la guía de Alfa que te lleva a conseguir este objeto."] = "Öffnet den Alfa-Guide, der dich zu diesem Gegenstand führt.",
	["Abre la pelea a distancia antes de que llegue."] = "Eröffne den Kampf auf Distanz, bevor er dich erreicht.",
	["Abre la pelea: te acerca al enemigo y te da ira."] = "Eröffnet den Kampf: bringt dich zum Gegner und gibt dir Wut.",
	["Abre la siguiente fila."] = "Öffnet die nächste Reihe.",
	["Abre la ventana Historias."] = "Öffnet das Fenster Geschichten.",
	["Abre la ventana de clic para lanzar de Blizzard para que armes ahí los mismos clics y cures igual en sus marcos de grupo (el juego no deja que un addon los copie)."] = "Öffnet Blizzards Fenster für Klickzauber, damit du dort dieselben Klicks einrichtest und in seinen Gruppenrahmen genauso heilst (das Spiel lässt ein Addon sie nicht kopieren).",
	["Abre la ventana de talentos del juego una vez o espera unos segundos: en cuanto Alfa la lea, te dice qué poner. Mientras, abajo ves tu build."] = "Öffne einmal das Talentfenster des Spiels oder warte ein paar Sekunden: Sobald Alfa es liest, sagt es dir, was du nehmen sollst. Unten siehst du so lange deinen Build.",
	["Abre la ventana de tu profesión una vez y Alfa leerá tus recetas para decirte cuáles te dejan ganancia."] = "Öffne einmal das Fenster deines Berufs, dann liest Alfa deine Rezepte und sagt dir, welche Gewinn bringen.",
	["Abre la ventana principal de Alfa."] = "Öffnet das Hauptfenster von Alfa.",
	["Abre o cierra el mapa de Alfa"] = "Öffnet oder schließt Alfas Karte",
	["Abre siempre con Cargar y pon Desgarrar al empezar la pelea."] = "Eröffne immer mit Sturmangriff und setz zu Kampfbeginn Verwunden.",
	["Abre siempre desde el sigilo con tu ataque más fuerte."] = "Eröffne immer aus der Verstohlenheit mit deinem stärksten Angriff.",
	["Abre su ficha."] = "Öffnet den Eintrag.",
	["Abre tus bolsas con su tecla o con el botón de la mochila."] = "Öffne deine Taschen mit ihrer Taste oder dem Rucksack-Knopf.",
	["Abre tus bolsas con tu tecla (%s)."] = "Öffne deine Taschen mit deiner Taste (%s).",
	["Abre un susurro con tu mensaje listo. Si no está conectado, el juego te lo dirá."] = "Öffnet ein Flüstern mit deiner fertigen Nachricht. Ist die Person offline, sagt dir das Spiel Bescheid.",
