	["Abrir su guía"] = "Den Guide öffnen",
	["Abrumar casi siempre crítico."] = "Überwältigen trifft fast immer kritisch.",
	["Abrumar crítico contra pícaros que esquivan."] = "Überwältigen trifft kritisch gegen Schurken, die ausweichen.",
	["Abrumar hace crítico casi siempre."] = "Überwältigen trifft fast jedes Mal kritisch.",
	["Abrumar hace crítico mucho más seguido."] = "Überwältigen trifft viel öfter kritisch.",
	["Acabas de vencer a un enemigo: este ataque es gratis y te cura."] = "Du hast gerade einen Gegner besiegt: Dieser Angriff ist kostenlos und heilt dich.",
	["Accesos rápidos"] = "Schnellzugriff",
	["Acecho"] = "Schleichen",
	["Acento propio (elegido en Ajustes)"] = "Eigene Akzentfarbe (in den Einstellungen gewählt)",
	["Acento: %s"] = "Akzentfarbe: %s",
	["Acepta invitaciones de grupo de tus amigos y de tu hermandad."] = "Nimmt Gruppeneinladungen von deinen Freunden und deiner Gilde an.",
	["Acepta por ti"] = "Nimmt für dich an",
	["Acepta una invocación al momento, salvo en combate."] = "Nimmt eine Beschwörung sofort an, außer im Kampf.",
	["Acepta una resurrección en cuanto se puede. Nunca en Hardcore."] = "Nimmt eine Wiederbelebung an, sobald es geht. Nie im Hardcore-Modus.",
	["Acepta y entrega las demás (normales, diarias y semanales). Nunca las grises ni las que piden oro o materiales."] = "Nimmt die übrigen an und gibt sie ab (normale, tägliche und wöchentliche). Nie graue oder solche, die Gold oder Materialien verlangen.",
	["Aceptar"] = "OK",
	["Aceptar invocaciones"] = "Beschwörungen annehmen",
	["Aceptar las misiones de tu guía"] = "Quests deines Guides annehmen",
	["Aceptar resurrecciones"] = "Wiederbelebungen annehmen",
	["Aceptar solas las misiones de la guía"] = "Quests des Guides automatisch annehmen",
	["Aceptar todas las misiones ya no pierde una diaria porque la ventana se cerraba antes de tiempo."] = "Alle Quests annehmen verpasst keine Tagesquest mehr, weil sich das Fenster zu früh schloss.",
	["Aceptar y entregar"] = "Annehmen und abgeben",
	["Aceptar y entregar misiones"] = "Quests annehmen und abgeben",
	["Aceptar y entregar solo las misiones de mi ruta"] = "Nur die Quests meiner Route annehmen und abgeben",
	["Aceptar y entregar todas las misiones"] = "Alle Quests annehmen und abgeben",
	["Acercar"] = "Vergrößern",
	["Acomoda tus marcos"] = "Platziere deine Rahmen",
	["Actitud de batalla"] = "Kampfhaltung",
	["Actitud defensiva"] = "Verteidigungshaltung",
	["Actitud rabiosa"] = "Berserkerhaltung",
	["Activa el rastreo de hierbas para verlas en el minimapa mientras viajas."] = "Schalte „Kräuter suchen“ ein, um sie beim Reisen auf der Minikarte zu sehen.",
	["Activa el rastreo de minerales y sigue las montañas: ahí están las mejores vetas."] = "Schalte „Mineralien suchen“ ein und folge den Bergen: Dort sind die besten Adern.",
	["Activa máquinas en las paredes que sueltan bombas que caminan: pulsa el botón junto a la máquina para apagarla, o maten las bombas antes de que lleguen."] = "Er schaltet Maschinen an den Wänden ein, die laufende Bomben freilassen: Drück den Knopf neben der Maschine, um sie abzuschalten, oder tötet die Bomben, bevor sie ankommen.",
	["Activar el medidor de daño"] = "Schadensmesser aktivieren",
	["Activar el modo limpio"] = "Fokusmodus einschalten",
	["Activo"] = "Aktiv",
	["Actual"] = "Aktuell",
	["Actualizar mi guía"] = "Meinen Guide aktualisieren",
	["Actualizar mis barras"] = "Meine Leisten aktualisieren",
	["Actualízala con la app de CurseForge o con el zip más reciente y luego usa /reload."] = "Aktualisiere es mit der CurseForge-App oder dem neuesten Zip, dann gib /reload ein.",
	["Actualízalo con la app de CurseForge o con el zip más reciente y luego reinicia el juego o usa /reload."] = "Aktualisiere es mit der CurseForge-App oder dem neuesten Zip, dann starte das Spiel neu oder gib /reload ein.",
	["Además del ícono, un brillo dorado que late alrededor de su barra."] = "Zusätzlich zum Symbol ein goldenes Leuchten, das um ihre Leiste pulsiert.",
	["Afinar siempre"] = "Immer schärfen",
	["Aflicción"] = "Gebrechen",
	["Aflicción para subir"] = "Gebrechen zum Leveln",
	["Agarras a varios enemigos a la vez."] = "Du hältst mehrere Gegner gleichzeitig.",
	["Agilidad"] = "Beweglichkeit",
	["Agrega la primera: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota."] = "Füg das erste hinzu: einen Gegenstand, Gold, einen Beruf, einen Ort, eine Quest, eine Stufe oder eine Notiz.",
	["Agrega tramos arriba: Alfa elige las misiones por ti."] = "Füge oben Etappen hinzu: Alfa wählt die Quests für dich.",
	["Agrega una línea con el objetivo de esa unidad; si te tiene a ti, lo dice."] = "Fügt eine Zeile mit dem Ziel dieser Einheit hinzu; wenn du es bist, steht das da.",
	["Agregada"] = "Hinzugefügt",
	["Agregada a Cerrar mis misiones"] = "Zu „Meine Quests abschließen“ hinzugefügt",
	["Agregado a tu plan"] = "Zu deinem Plan hinzugefügt",
	["Agregado a tu ruta"] = "Zu deiner Route hinzugefügt",
	["Agregar a Cerrar mis misiones"] = "Zu „Meine Quests abschließen“ hinzufügen",
	["Agregar a Mis planes"] = "Zu „Meine Pläne“ hinzufügen",
	["Agregar a mi ruta"] = "Zu meiner Route hinzufügen",
	["Agregar un tramo:"] = "Etappe hinzufügen:",
	["Agregar una meta"] = "Ziel hinzufügen",
	["Agregué lo que falta para %s"] = "Ich habe hinzugefügt, was dir für %s fehlt",
	["Agrégale una en Mis planes."] = "Füg eins in „Meine Pläne“ hinzu.",
	["Agrégale uno en la página Ruta."] = "Füge eine auf der Seite Route hinzu.",
	["Agua"] = "Wasser",
	["Agua y comida"] = "Wasser und Essen",
	["Aguante"] = "Ausdauer",
	["Aguas conocidas"] = "Bekannte Gewässer",
	["Ahora"] = "Jetzt",
	["Ahora ganas la XP normal"] = "Du bekommst jetzt normale EP",
	["Ahora no"] = "Jetzt nicht",
	["Ahora no pude armar el camino a esta misión."] = "Ich konnte gerade keinen Weg zu dieser Quest erstellen.",
	["Ahora no sale: Alfa busca cómo unirse a la manada."] = "Gerade wird nichts gesendet: Alfa sucht einen Weg zum Rudel.",
	["Ahora no se puede"] = "Gerade nicht möglich",
	["Ahora no se puede anunciar"] = "Ansagen gerade nicht möglich",
	["Ahora no se pueden enviar mensajes (en una instancia o con una cuenta de prueba). %s"] = "Gerade können keine Nachrichten gesendet werden (in einer Instanz oder mit einem Testaccount). %s",
	["Ahora toca la colección: completa tu diario, los logros y prueba el concurso de los domingos."] = "Jetzt geht's ans Sammeln: Vervollständige dein Tagebuch und die Erfolge und probier den Angelwettbewerb am Sonntag.",
	["Ahora usan: %s. Activa los pesos de %s para que Alfa compare el equipo como lo pide tu build."] = "Gerade nutzen sie: %s. Aktiviere die Gewichtungen von %s, damit Alfa Ausrüstung so vergleicht, wie dein Build es verlangt.",
	["Ahora va por el canal oculto de Alfa."] = "Es läuft jetzt über Alfas versteckten Kanal.",
	["Ahora va por tu hermandad: el canal oculto de Alfa no está disponible, así que solo te ven quienes comparten en tu hermandad."] = "Es läuft jetzt über deine Gilde: Alfas versteckter Kanal ist nicht verfügbar, daher sehen dich nur die, die in deiner Gilde teilen.",
	["Ahora vas a: %s"] = "Jetzt unterwegs zu: %s",
	["Ahora: %d %% del nivel %d"] = "Jetzt: %d %% von Stufe %d",
	["Ahora: %s"] = "Jetzt: %s",
	["Ahora: %s · De fábrica: %s"] = "Jetzt: %s · Standard: %s",
	["Ahora: %s."] = "Jetzt: %s.",
	["Ahí no hay ninguna zona: pon el marcador sobre tierra."] = "Dort ist kein Gebiet: Setz die Markierung auf Land.",
	["Ahí no se puede poner la flecha."] = "Dort kann der Pfeil nicht gesetzt werden.",
	["Ahí nos organizamos para todo. Haz clic en el enlace y cópialo con Ctrl+C."] = "Dort organisieren wir alles. Klick auf den Link und kopiere ihn mit Strg+C.",
	["Ajustar"] = "Anpassen",
	["Ajustar los avisos"] = "Hinweise anpassen",
	["Ajustes"] = "Einstellungen",
	["Ajustes de Alfa en todos los idiomas: las fechas en el orden de cada uno y los nombres de cada especialización bien puestos."] = "Alfa-Anpassungen in allen Sprachen: Datumsangaben in der Reihenfolge jeder Sprache und die Namen jeder Spezialisierung richtig.",
	["Ajustes de Bolsas"] = "Taschen-Einstellungen",
	["Ajustes de Lya"] = "Lya-Einstellungen",
	["Ajustes de mazmorras"] = "Dungeon-Einstellungen",
	["Ajustes de pesca"] = "Angeleinstellungen",
	["Ajustes del mapa"] = "Karteneinstellungen",
	["Ajustes del medidor"] = "Einstellungen des Schadensmessers",
	["Ajustes en orden: Comodidades y Calidad de vida son una sola página con pestañas, y todo lo de misiones vive en Ajustes > Misiones. Tu configuración se mudó sola, sin perder nada."] = "Einstellungen in Ordnung: Komfort und Lebensqualität sind eine Seite mit Reitern, und alles zu Quests liegt unter Einstellungen > Quests. Deine Einstellungen sind von selbst umgezogen, nichts ging verloren.",
	["Al abrirse el mapa de vuelo, vuela al destino que marca tu ruta."] = "Wenn sich die Flugkarte öffnet, fliegt Alfa zum Ziel deiner Route.",
	["Al acercar o cargar el mapa, cada parte aparece completa de una vez, sin cuadritos sueltos."] = "Beim Heranzoomen oder Laden der Karte erscheint jeder Teil auf einmal vollständig, ohne einzelne Kästchen.",
	["Al acercar se ven las montañas y el relieve, igual que en el minimapa. Apagado: el mapa pintado del juego."] = "Beim Hineinzoomen siehst du Berge und Relief, wie auf der Minikarte. Aus: die gemalte Karte des Spiels.",
	["Al armar tus rutas, Alfa deja fuera las que piden élites."] = "Beim Erstellen deiner Routen lässt Alfa die mit Elitegegnern weg.",
	["Al cambiar de forma o de actitud, el juego usa otra barra de abajo. Si está vacía, Alfa te avisa una vez y puede llenar sus casillas vacías con las habilidades de esa forma que ya sabes, fuera de combate y sin tocar lo que ya tienes."] = "Wenn du Gestalt oder Haltung wechselst, nutzt das Spiel eine andere untere Leiste. Ist sie leer, warnt Alfa dich einmal und kann ihre freien Plätze mit den Fähigkeiten dieser Gestalt füllen, die du schon kennst, außerhalb des Kampfes und ohne anzurühren, was du schon hast.",
	["Al cambiar de forma, el juego cambia tu barra de abajo por la de esa forma, y esta todavía no tiene nada: por eso parece que desaparece. Alfa puede poner en sus casillas vacías las habilidades de esa forma que ya sabes."] = "Wenn du die Gestalt wechselst, tauscht das Spiel deine untere Leiste gegen die dieser Gestalt aus, und die ist noch leer: Deshalb scheint sie zu verschwinden. Alfa kann die Fähigkeiten dieser Gestalt, die du schon kennst, auf ihre freien Plätze legen.",
	["Al comerciante"] = "An Händler",
	["Al comparar objetos, Alfa valora más lo que pide %s: lo de arriba en la lista de estadísticas."] = "Beim Vergleich von Gegenständen gewichtet Alfa stärker, was %s verlangt: das, was oben in der Werteliste steht.",
	["Al día"] = "Aktuell",
	["Al elegir un build, las flechas de mejora de tus bolsas valoran lo que ese build necesita."] = "Wenn du einen Build wählst, bewerten die Upgrade-Pfeile in deinen Taschen, was dieser Build braucht.",
	["Al empezar aturde a quien lo despertó en el altar: es normal."] = "Zu Beginn betäubt er den, der ihn am Altar geweckt hat: Das ist normal.",
	["Al enemigo le queda poca vida: Quemadura de las Sombras lo remata."] = "Der Gegner hat wenig Gesundheit: Schattenbrand erledigt ihn.",
	["Al enemigo le queda poca vida: remátalo al instante."] = "Der Gegner hat wenig Gesundheit: Erledige ihn sofort.",
	["Al enemigo le queda poca vida: remátalo."] = "Der Gegner hat wenig Gesundheit: Erledige ihn.",
	["Al entregar una misión, Lya te ofrece contarte cómo terminó."] = "Wenn du eine Quest abgibst, bietet Lya dir an zu erzählen, wie sie ausging.",
	["Al final de la Tercera Guerra, Arthas subió al Trono Helado, se puso el yelmo y se volvió uno con el Rey Exánime."] = "Am Ende des Dritten Krieges stieg Arthas auf den Frostthron, setzte den Helm auf und wurde eins mit dem Lichkönig.",
	["Al final de la pelea se enfurece y pega más rápido: guarda curación para ese momento."] = "Gegen Ende wird er wütend und schlägt schneller zu: Spar dir Heilung für diesen Moment auf.",
	["Al final se enfurece: guarden su mejor daño para el final."] = "Am Ende wird sie wütend: Hebt euch euren besten Schaden für den Schluss auf.",
	["Al final, habla con el Discípulo de Naralex y protégelo mientras camina: así aparece el último jefe."] = "Sprich am Ende mit dem Jünger von Naralex und beschütze ihn, während er geht: So erscheint der letzte Boss.",
	["Al hablar con el maestro de vuelo, abre su mapa directamente."] = "Beim Gespräch mit dem Flugmeister öffnet sich direkt seine Karte.",
	["Al hablar con quien da una misión de tu ruta, se acepta sola."] = "Wenn du mit jemandem sprichst, der eine Quest deiner Route vergibt, wird sie automatisch angenommen.",
	["Al hablar con quien da una misión de tu ruta, se acepta sola. Mayús la deja para ti."] = "Wenn du mit jemandem sprichst, der eine Quest deiner Route vergibt, wird sie automatisch angenommen. Umschalt überlässt sie dir.",
	["Al hablar con un PNJ"] = "Beim Gespräch mit einem NPC",
	["Al hablar con un banquero se abre el banco de Alfa, con depositar rápido. La primera visita de cada personaje muestra el del juego: así recibe su primera pestaña."] = "Beim Gespräch mit einem Bankier öffnet sich Alfas Bank, mit schnellem Einlagern. Beim ersten Besuch jedes Charakters erscheint die des Spiels: So bekommt er seinen ersten Tab.",
	["Al hurtar a los humanoides ganas monedas y a veces cajas cerradas."] = "Mit Taschendiebstahl bekommst du von Humanoiden Münzen und manchmal verschlossene Kästchen.",
	["Al invitar a una comunidad ya no sale el aviso de bloqueo: Alfa te deja el nombre listo para copiar y te abre la ventana. A tu hermandad, un clic como antes."] = "Beim Einladen in eine Community erscheint keine Sperrwarnung mehr: Alfa legt dir den Namen zum Kopieren bereit und öffnet das Fenster. In deine Gilde mit einem Klick wie bisher.",
	["Al llegar a una ciudad o posada. También repite la nota de entrenar de la guía cuando su ventana está oculta."] = "Beim Erreichen einer Stadt oder eines Gasthauses. Wiederholt auch den Trainingshinweis des Guides, wenn dessen Fenster ausgeblendet ist.",
	["Al morir aparecen cuatro abisarios que caminan juntos por el patio: prepárense para pelear con varios."] = "Wenn er stirbt, erscheinen vier Leerwandler, die gemeinsam über den Hof laufen: Macht euch auf mehrere gefasst.",
	["Al morir en un campo de batalla, liberas tu espíritu al momento."] = "Stirbst du auf einem Schlachtfeld, wird dein Geist sofort freigelassen.",
	["Al morir llegan muchos aprendices: prepárense para muchos enemigos a la vez."] = "Wenn er stirbt, stürmen viele Rekruten herein: Macht euch auf viele Gegner auf einmal gefasst.",
	["Al moverte, la tecla vuelve a la normal"] = "Beim Bewegen wird die Taste wieder normal",
	["Al moverte, solo de lado"] = "Beim Bewegen nur seitlich",
	["Al norte de estas montañas están las Estepas Ardientes y la Montaña Roca Negra, de donde salen los orcos que amenazan Villa del Lago."] = "Nördlich dieser Berge liegen die Brennende Steppe und der Schwarzfels, woher die Orcs kommen, die Seenhain bedrohen.",
	["Al objetivo le queda poca vida: Ejecutar lo remata usando tu ira."] = "Dein Ziel hat wenig Gesundheit: Hinrichten erledigt es mit deiner Wut.",
	["Al objetivo le queda poca vida: el martillo lo remata a distancia."] = "Dein Ziel hat wenig Gesundheit: Der Hammer erledigt es aus der Ferne.",
	["Al pasar el ratón por un objeto: «Tienes 12 (Lobato: 7 en bolsas, Alt: 5 en banco)», con todos tus personajes."] = "Im Tooltip eines Gegenstands: „Du hast 12 (Lobato: 7 in Taschen, Alt: 5 in der Bank)“, über alle deine Charaktere hinweg.",
	["Al pasar el ratón sobre un objeto: su precio en la subasta, lo que paga el comerciante y qué te conviene."] = "Wenn du mit der Maus über einen Gegenstand fährst: sein Auktionspreis, was der Händler zahlt und was sich für dich lohnt.",
	["Al pie de Cima del Trueno está el poblado Pezuña de Sangre, donde Baine, el hijo de Cairne, cuida a su gente."] = "Am Fuß von Donnerfels liegt das Dorf der Bluthufe, wo Baine, Cairnes Sohn, für sein Volk sorgt.",
	["Al recibir daño suelta pedazos más pequeños: mátenlos con ataques en área."] = "Wenn er Schaden nimmt, lösen sich kleinere Splitter: Tötet sie mit Flächenangriffen.",
	["Al sacar algo"] = "Wenn du etwas fängst",
	["Al seguir, Alfa se recarga para cambiar el idioma y esta configuración sigue donde la dejaste."] = "Beim Fortfahren lädt Alfa neu, um die Sprache zu wechseln, und diese Einrichtung geht dort weiter, wo du aufgehört hast.",
	["Al subir de nivel (y al entrar, si te quedan puntos), un aviso dice qué talento poner, con el botón para aplicarlo."] = "Beim Stufenaufstieg (und beim Einloggen, wenn du noch Punkte hast) sagt dir ein Hinweis, welches Talent du nehmen sollst, mit einem Knopf zum Anwenden.",
	["Al subir de nivel te muestra qué aprender y cuánto cuesta."] = "Zeigt dir beim Stufenaufstieg, was du lernen kannst und was es kostet.",
	["Al subir de nivel, un aviso dice qué aprender, cuánto cuesta y con qué entrenador, con el botón Llévame."] = "Beim Stufenaufstieg sagt dir ein Hinweis, was du lernen kannst, was es kostet und bei welchem Lehrer, mit dem Knopf „Bring mich hin“.",
	["Al sur de Cuna del Invierno, una garganta escondida está llena de demonios."] = "Südlich von Winterquell liegt eine versteckte Schlucht voller Dämonen.",
	["Al sur de Los Baldíos, el Gran Elevador baja hasta Las Mil Agujas. ¡No mires hacia abajo!"] = "Im Süden des Brachlands fährt der Große Aufzug hinunter nach Tausend Nadeln. Nicht nach unten schauen!",
	["Al sur está Dalaran, la ciudad de los magos. Archimonde la arrasó en la Tercera Guerra, y sus magos la reconstruyen protegidos bajo una cúpula."] = "Im Süden liegt Dalaran, die Stadt der Magier. Archimonde hat sie im Dritten Krieg zerstört, und ihre Magier bauen sie unter einer schützenden Kuppel wieder auf.",
	["Al sur se alza una muralla enorme: el rey Genn Cringris la levantó para aislar Gilneas del resto del mundo."] = "Im Süden erhebt sich eine riesige Mauer: König Genn Graumähne ließ sie bauen, um Gilneas vom Rest der Welt abzuschotten.",
	["Al terminar una guía de nivel, carga la siguiente sin preguntar."] = "Endet ein Levelguide, lädt Alfa den nächsten, ohne zu fragen.",
	["Al volver con una misión lista, se entrega sola. Si hay recompensas para elegir, eliges tú."] = "Kommst du mit einer fertigen Quest zurück, wird sie automatisch abgegeben. Gibt es Belohnungen zur Auswahl, wählst du.",
	["Alamuerte forjó en secreto el Alma de Demonio, un disco dorado cargado con el poder de los demás Aspectos, que se lo dieron sin saber para qué lo quería."] = "Todesschwinge schmiedete heimlich die Dämonenseele, eine goldene Scheibe voller Macht der anderen Aspekte, die sie ihm gaben, ohne zu wissen, wofür er sie wollte.",
	["Alamuerte se hizo pasar por Lord Daval Prestor, un noble que casi llegó a rey de Alterac. ¡A esa familia le encantan los disfraces!"] = "Todesschwinge gab sich als Lord Daval Prestor aus, ein Adliger, der fast König von Alterac geworden wäre. Diese Familie liebt Verkleidungen!",
	["Alcance de las sombras"] = "Schattenreichweite",
	["Alcanza para %d"] = "Reicht für %d",
	["Alejar"] = "Verkleinern",
	["Alejar la cámara"] = "Kamera herauszoomen",
	["Alejar más la cámara"] = "Kamera weiter herauszoomen",
	["Alertas"] = "Hinweise",
	["Alexandros Mograine empuñaba la Crematoria, y la Plaga le temía como a nadie. Lo traicionó su propio hijo, Renault."] = "Alexandros Mograine führte den Aschenbringer, und die Geißel fürchtete ihn wie keinen anderen. Sein eigener Sohn Renault verriet ihn.",
	["Alfa"] = "Alfa",
	["Alfa %s ya está aquí"] = "Alfa %s ist da",
	["Alfa %s · cliente %s (%s) · %s · Alfa en %s"] = "Alfa %s · Client %s (%s) · %s · Alfa auf %s",
	["Alfa (el estilo propio, por omisión), Clásico WoW (marcos y letras del juego) o Cristal (transparente, con el acento que elijas). El modo compacto y tus colores funcionan en los tres."] = "Alfa (der eigene Stil, Standard), Klassisches WoW (Rahmen und Schriften des Spiels) oder Glas (durchsichtig, mit der Akzentfarbe deiner Wahl). Kompaktmodus und deine Farben funktionieren in allen dreien.",
	["Alfa arma el reporte y tú lo pegas en el buzón privado del Discord de La Jauría. También con /alfa reportar."] = "Alfa erstellt den Bericht, und du fügst ihn in den privaten Briefkasten auf dem Discord von La Jauría ein. Auch mit /alfa reportar.",
	["Alfa arma la ruta más corta para cobrarlas, junta por PNJ. La flecha usa vuelos y tu piedra de hogar cuando conviene, y te avisa si una entrega queda lejos."] = "Alfa erstellt die kürzeste Route, um sie einzulösen, gebündelt nach NPC. Der Pfeil nutzt Flüge und deinen Ruhestein, wenn es sich lohnt, und warnt dich, wenn eine Abgabe weit weg ist.",
	["Alfa borrará lo que guardó de %s: sus bolsas, su banco y su equipo. Si vuelves a jugar con él, se guarda de nuevo."] = "Alfa löscht, was es von %s gespeichert hat: Taschen, Bank und Ausrüstung. Spielst du den Charakter wieder, wird alles neu gespeichert.",
	["Alfa de La Jauría"] = "Alpha von La Jauría",
	["Alfa elige las misiones que más XP dan cerca de ti, en tres tandas."] = "Alfa wählt die Quests in deiner Nähe, die am meisten EP geben, in drei Runden.",
	["Alfa elige todo: misiones ordenadas por XP por distancia y tus misiones de clase."] = "Alfa wählt alles: Quests nach EP pro Wegstrecke sortiert und deine Klassenquests.",
	["Alfa es un addon que toxic3000 creó para sus amigos y quiso compartir con todos."] = "Alfa ist ein Addon, das toxic3000 für seine Freunde gemacht hat und mit allen teilen wollte.",
	["Alfa estable: en orden y en manada"] = "Stabiles Alfa: in Ordnung und im Rudel",
	["Alfa está armando tu ruta..."] = "Alfa baut deine Route...",
	["Alfa está eligiendo..."] = "Alfa wählt aus...",
	["Alfa está leyendo tu clase"] = "Alfa liest deine Klasse",
	["Alfa está oculto: clic para mostrarlo y abrir su ventana"] = "Alfa ist ausgeblendet: Klick, um es einzublenden und sein Fenster zu öffnen",
	["Alfa la vuelve a poner al entrar."] = "Alfa setzt es beim Einloggen wieder.",
	["Alfa le agregó lo que ayuda a arreglarlo: versiones, idioma, tu clase y nivel y dónde estás. No lleva tu nombre ni tu reino."] = "Alfa hat ergänzt, was bei der Behebung hilft: Versionen, Sprache, deine Klasse und Stufe und wo du bist. Dein Name und dein Realm sind nicht dabei.",
	["Alfa lee el medidor oficial del juego. Enciéndelo y aquí verás el daño de tu grupo; su ventana puedes ocultarla en el Modo de edición."] = "Alfa liest den offiziellen Schadensmesser des Spiels. Schalte ihn ein, dann siehst du hier den Schaden deiner Gruppe; sein Fenster kannst du im Bearbeitungsmodus ausblenden.",
	["Alfa lo hace toxic3000 para La Jauría. Es software libre (GPL-3.0) y su código está en github.com/toxic3000/alfa-forever."] = "Alfa wird von toxic3000 für La Jauría gemacht. Es ist freie Software (GPL-3.0), der Code liegt auf github.com/toxic3000/alfa-forever.",
	["Alfa los cambia por el rango nuevo sin moverlos de lugar."] = "Alfa tauscht sie gegen den neuen Rang, ohne sie zu verschieben.",
	["Alfa mantiene %d ajustes que elegiste. Abre la ventana para ver o cambiar cada uno."] = "Alfa behält %d Einstellungen, die du gewählt hast. Öffne das Fenster, um jede anzusehen oder zu ändern.",
	["Alfa mantiene %d ajustes tuyos y los vuelve a poner al entrar."] = "Alfa behält %d deiner Einstellungen und setzt sie beim Einloggen wieder.",
	["Alfa mide los caminos (vuelos y piedra de hogar): tarda unos segundos."] = "Alfa misst die Wege (Flüge und Ruhestein): Das dauert ein paar Sekunden.",
	["Alfa no está afiliado a esos proyectos ni ellos lo respaldan; gracias a todos por compartir su trabajo."] = "Alfa ist mit diesen Projekten weder verbunden noch wird es von ihnen unterstützt; danke an alle, die ihre Arbeit teilen.",
	["Alfa no ha cambiado nada todavía. Prueba «Paisaje de la manada» o abre la ventana para ver los ajustes que el menú del juego no enseña."] = "Alfa hat noch nichts geändert. Probier „Landschaft des Rudels“ oder öffne das Fenster, um die Einstellungen zu sehen, die das Spielmenü nicht zeigt.",
	["Alfa no pudo armar el camino a %s. Míralo en la Enciclopedia."] = "Alfa konnte den Weg zu %s nicht erstellen. Schlag es in der Enzyklopädie nach.",
	["Alfa no tiene datos de esto todavía."] = "Alfa hat dazu noch keine Daten.",
	["Alfa no tiene el instructor de tu raza: busca «equitación» en PNJ."] = "Alfa kennt den Lehrer deines Volkes nicht: Such „Reiten“ unter NPCs.",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones» de Comodidades."] = "Alfa nimmt keine Quests an, die deiner Route nicht dienen, und gibt sie nicht selbst ab. Auch „Alle Quests“ unter Komfort hält sich daran.",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones»."] = "Alfa nimmt keine Quests an, die deine Route nicht braucht, und gibt sie nicht von selbst ab. Auch „alle Quests“ hält sich daran.",
	["Alfa no toma misiones que no sirven a tu ruta. Tu registro queda limpio."] = "Alfa nimmt keine Quests an, die deine Route nicht braucht. Dein Questlog bleibt sauber.",
	["Alfa ordena las paradas para que no camines de más. Tarda unos segundos y no traba el juego."] = "Alfa ordnet die Halte so, dass du keine Umwege läufst. Das dauert ein paar Sekunden und bremst das Spiel nicht.",
	["Alfa recuerda lo que llevabas antes de ponerte lo de pesca y te lo vuelve a poner."] = "Alfa merkt sich, was du vor der Angelausrüstung getragen hast, und legt es dir wieder an.",
	["Alfa revisa lo que elegiste cuando el juego termina de cargar. Si los cambias en el menú del juego, se queda con lo nuevo."] = "Alfa prüft deine Auswahl, wenn das Spiel fertig geladen hat. Änderst du sie im Spielmenü, behält es die neuen.",
	["Alfa revisa su base de objetos sin trabar el juego. Tarda unos segundos la primera vez."] = "Alfa durchsucht seine Gegenstandsdatenbank, ohne das Spiel einzufrieren. Beim ersten Mal dauert das ein paar Sekunden.",
	["Alfa revisa su base de objetos, se queda con lo que tu clase puede usar cerca de tu nivel y lo compara con lo que llevas, con los pesos de tu build."] = "Alfa durchsucht seine Gegenstandsdatenbank, behält, was deine Klasse nahe deiner Stufe nutzen kann, und vergleicht es mit deiner Ausrüstung, mit den Gewichtungen deines Builds.",
	["Alfa se está uniendo al canal oculto de La Jauría. En unos segundos ves a quien comparte."] = "Alfa tritt dem versteckten Kanal von La Jauría bei. In ein paar Sekunden siehst du, wer teilt.",
	["Alfa se muestra en el idioma que elijas, aunque tu juego esté en otro."] = "Alfa erscheint in der Sprache deiner Wahl, auch wenn dein Spiel in einer anderen ist.",
	["Alfa se recarga para cambiar el idioma. La configuración sigue donde la dejaste."] = "Alfa lädt neu, um die Sprache zu wechseln. Die Einrichtung geht dort weiter, wo du aufgehört hast.",
	["Alfa solo leyó tus valores: nada cambia hasta que toques un control."] = "Alfa hat nur deine Werte gelesen: Nichts ändert sich, bis du einen Regler anfasst.",
	["Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus recargas, los efectos que el juego activa y la vida del enemigo cuando se puede leer. Con varios enemigos cambia a las de área. Tú decides qué presionar."] = "Alfa schlägt mit seiner Priorität für %s vor und liest nur deinen Charakter: deine Ressource, deine Abklingzeiten, die Effekte, die das Spiel aufleuchten lässt, und die Gesundheit des Gegners, wenn sie lesbar ist. Bei mehreren Gegnern wechselt es zu Flächenfähigkeiten. Was du drückst, entscheidest du.",
	["Alfa tampoco tiene todavía una prioridad para tu clase con lo que sabes. Los avisos de reacción y el medidor sí funcionan."] = "Alfa hat mit dem, was du kannst, auch noch keine Priorität für deine Klasse. Reaktionshinweise und der Schadensmesser funktionieren aber.",
	["Alfa te avisa aquí de lo importante: equipo por reparar, bolsas llenas, habilidades nuevas, tu buff y tu descanso."] = "Hier sagt dir Alfa, was wichtig ist: Ausrüstung zum Reparieren, volle Taschen, neue Fähigkeiten, dein Buff und dein Ruhebonus.",
	["Alfa te avisa del equipo gastado, las bolsas llenas, lo que puedes entrenar, tu buff y tu descanso. Aquí eliges cuáles y cuándo."] = "Alfa warnt dich vor abgenutzter Ausrüstung, vollen Taschen, neuen Zaubern beim Lehrer, deinem Buff und deiner Erholung. Hier wählst du, welche und wann.",
	["Alfa te lleva paso a paso, con la flecha y la ruta en el mapa. Elige la de tu zona y tu nivel."] = "Alfa führt dich Schritt für Schritt, mit Pfeil und Route auf der Karte. Wähle den für dein Gebiet und deine Stufe.",
	["Alfa todavía no tiene builds para tu clase"] = "Alfa hat noch keine Builds für deine Klasse",
	["Alfa usa código y datos de estos proyectos libres, con sus avisos de autor y sus licencias incluidos en cada carpeta:"] = "Alfa nutzt Code und Daten aus diesen freien Projekten, mit ihren Urheberhinweisen und Lizenzen in jedem Ordner:",
	["Alfa vuelve a elegir desde donde estás ahora (las misiones fijas se quedan)."] = "Alfa wählt neu ab deinem aktuellen Standort (fixierte Quests bleiben).",
	["Alfa · Top %d de %s (%s%s)"] = "Alfa · Top %d %s (%s%s)",
	["Alfa, Clásico WoW o Cristal, la flecha del lobo y el aullido."] = "Alfa, Klassisches WoW oder Glas, der Wolfspfeil und das Heulen.",
	["Alfa: agregar a Cerrar mis misiones"] = "Alfa: zu „Meine Quests abschließen“ hinzufügen",
	["Alfa: capas del mapa"] = "Alfa: Kartenebenen",
	["Alfa: cerrar mis misiones"] = "Alfa: meine Quests abschließen",
	["Alfa: quitar de Cerrar mis misiones"] = "Alfa: aus „Meine Quests abschließen“ entfernen",
	["Alfa_Codex está apagado en la lista de addons."] = "Alfa_Codex ist in der AddOn-Liste ausgeschaltet.",
	["Algo no anda bien en el árbol: los furbolgs que viven en él se están volviendo agresivos."] = "Mit dem Baum stimmt etwas nicht: Die Furbolgs, die darauf leben, werden aggressiv.",
	["Algunas fórmulas de encantamiento muy buscadas caen de enemigos en las Tierras de la Peste."] = "Einige sehr begehrte Verzauberungsformeln droppen von Gegnern in den Pestländern.",
	["Algunas recetas raras se compran a vendedores lejanos o caen de enemigos; vale la pena buscarlas."] = "Manche seltenen Rezepte kauft man bei fernen Händlern oder sie droppen von Gegnern; es lohnt sich, sie zu suchen.",
	["Algunos ajustes, como el HDR, se ven hasta reiniciar los gráficos. Te pide confirmación."] = "Manche Einstellungen, wie HDR, wirken erst nach einem Neustart der Grafik. Fragt nach Bestätigung.",
	["Algunos ogros tienen dos cabezas, y no siempre se ponen de acuerdo entre ellas."] = "Manche Oger haben zwei Köpfe, und die sind sich nicht immer einig.",
	["Algunos orcos nunca siguieron a Thrall: los Roca Negra de la montaña sirven a los dragones negros."] = "Manche Orcs sind Thrall nie gefolgt: Die Schwarzfelsorcs im Berg dienen den schwarzen Drachen.",
	["Alianza"] = "Allianz",
	["Alimenta a tu mascota: si está contenta pega más y te es más leal."] = "Füttere deinen Begleiter: Wenn er zufrieden ist, trifft er härter und wird treuer.",
	["Alquimia"] = "Alchemie",
	["Alt"] = "Alt",
	["Alt+clic en un objeto abre su ficha"] = "Alt+Klick auf einen Gegenstand öffnet seinen Eintrag",
	["Alta"] = "Hoch",
	["Altas"] = "Hoch",
	["Alto"] = "Höhe",
	["Alto [calidad]"] = "Hoch",
	["Alto de las barras"] = "Höhe der Balken",
	["Altos"] = "Hoch",
	["Ambiente mientras pescas"] = "Umgebung beim Angeln",
	["Amenaza"] = "Bedrohung",
	["Anasterian, el rey de los altos elfos, dejó la Alianza tras la Segunda Guerra, y murió frente a Arthas defendiendo la Fuente del Sol."] = "Anasterian, der König der Hochelfen, verließ die Allianz nach dem Zweiten Krieg und starb im Kampf gegen Arthas bei der Verteidigung des Sonnenbrunnens.",
	["Ancho"] = "Breite",
	["Andorhal era el granero de Lordaeron. Kel'Thuzad repartió ahí grano apestado y la plaga se extendió por todo el reino."] = "Andorhal war die Kornkammer Lordaerons. Kel'Thuzad verteilte dort verseuchtes Getreide, und die Seuche breitete sich über das ganze Königreich aus.",
	["Anduin Lothar, el León de Azeroth, llevó a los refugiados de Ventormenta hasta Lordaeron y fue el primer comandante de la Alianza."] = "Anduin Lothar, der Löwe von Azeroth, führte die Flüchtlinge aus Sturmwind nach Lordaeron und war der erste Befehlshaber der Allianz.",
	["Anillos"] = "Ringe",
	["Animación anterior"] = "Vorherige Animation",
	["Animación siguiente"] = "Nächste Animation",
	["Anisotrópico 16x"] = "16x anisotrop",
	["Anisotrópico 2x"] = "2x anisotrop",
	["Anisotrópico 4x"] = "4x anisotrop",
	["Anisotrópico 8x"] = "8x anisotrop",
	["Anterior"] = "Vorheriger",
	["Antes de atacar, mira quién está cerca. Pelear con uno a la vez es más seguro."] = "Schau vor dem Angriff, wer in der Nähe ist. Einer nach dem anderen ist sicherer.",
	["Antes de buscar la espada, Arthas mandó quemar sus propios barcos para que sus soldados no pudieran volver a casa."] = "Bevor er das Schwert suchte, ließ Arthas seine eigenen Schiffe verbrennen, damit seine Soldaten nicht heimkehren konnten.",
	["Antes de comprar algo en la subasta, revisa si un vendedor lo tiene más barato."] = "Bevor du etwas im Auktionshaus kaufst, schau, ob ein Händler es billiger hat.",
	["Antes de empezar, unas palabras de la manada."] = "Bevor wir loslegen, ein paar Worte vom Rudel.",
	["Antes de entrar"] = "Bevor du reingehst",
	["Antes de entregarla te falta: %s."] = "Vor der Abgabe fehlt dir noch: %s.",
	["Antes de pelear"] = "Vor dem Kampf",
	["Antes de pelear: abre con Piroexplosión, tu hechizo más fuerte."] = "Vor dem Kampf: Eröffne mit Pyroschlag, deinem stärksten Zauber.",
	["Antes de salir de caza, configura Alfa a tu medida: el idioma, cómo se ve, qué hace sola por ti y si quieres que la manada te vea en el mapa del juego."] = "Bevor du auf die Jagd gehst, richte Alfa nach deinem Geschmack ein: die Sprache, das Aussehen, was es selbst für dich erledigt und ob das Rudel dich auf der Spielkarte sehen soll.",
	["Antes esto era un pantano. La magia del portal y la guerra lo dejaron rojo, seco y sin vida."] = "Früher war das hier ein Sumpf. Die Magie des Portals und der Krieg haben ihn rot, trocken und leblos zurückgelassen.",
	["Antes hay que hacer otra misión"] = "Zuerst kommt eine andere Quest",
	["Antes necesitas"] = "Zuerst brauchst du",
	["Antes necesitas otra misión"] = "Braucht zuerst eine andere Quest",
	["Antes pide %s (%s)"] = "Erfordert zuerst %s (%s)",
	["Antes que los elfos, los trols tuvieron grandes imperios en Azeroth, como el Amani en el norte y el Gurubashi en el sur."] = "Vor den Elfen hatten die Trolle große Reiche auf Azeroth, wie das der Amani im Norden und das der Gurubashi im Süden.",
	["Antes, el reino de Ventormenta se llamaba Azeroth, igual que el mundo; Ventormenta era solo el nombre de su capital."] = "Früher hieß das Königreich Sturmwind Azeroth, genau wie die Welt; Sturmwind war nur der Name seiner Hauptstadt.",
	["Antes: %s"] = "Zuerst: %s",
	["Antes: %s."] = "Zuerst: %s.",
	["Anunciar"] = "Ansagen",
	["Anunciar en el chat"] = "Im Chat ansagen",
	["Anunciar en el grupo"] = "In der Gruppe ansagen",
	["Apaga la viñeta, el grano, las barras y el tinte de un clic."] = "Schaltet Vignette, Körnung, Balken und Tönung mit einem Klick aus.",
	["Apagada"] = "Aus",
	["Apagadas"] = "Aus",
	["Apagado"] = "Aus",
	["Apagado, el grano se queda quieto."] = "Aus: Die Körnung bleibt still.",
	["Apagado, solo las acepta y la entrega la haces tú."] = "Aus: Sie werden nur angenommen, abgeben musst du selbst.",
	["Apagados"] = "Aus",
	["Apagarlo"] = "Ausschalten",
	["Aparece al final del evento del Discípulo de Naralex: protege al druida mientras camina."] = "Er erscheint am Ende des Ereignisses mit dem Jünger von Naralex: Beschütze den Druiden, während er geht.",
	["Aparece al tocar el gong por tercera vez, después de dos oleadas de arañas."] = "Er erscheint, wenn der Gong zum dritten Mal geschlagen wird, nach zwei Wellen von Spinnen.",
	["Aparece con una misión de la Horda (un objeto en el agua). Lanza escarcha."] = "Er erscheint durch eine Quest der Horde (ein Gegenstand im Wasser). Er wirkt Frostzauber.",
	["Aparece en cuanto termines la bienvenida de Alfa."] = "Sie erscheint, sobald du Alfas Willkommen abgeschlossen hast.",
	["Aparece en el evento de la explosivista: protégela mientras llegan oleadas de troggs."] = "Er erscheint beim Ereignis der Sprengmeisterin: Beschütze sie, während Wellen von Troggs anrücken.",
	["Aparecen marcos de ejemplo: arrástralos a donde los quieras y ajusta su tamaño. Así se verá tu grupo."] = "Beispielrahmen erscheinen: Zieh sie, wohin du willst, und pass ihre Größe an. So wird deine Gruppe aussehen.",
	["Aplaudir"] = "Applaudieren",
	["Aplica la nitidez de abajo aunque no uses el escalado de resolución."] = "Wendet die Schärfe unten an, auch wenn du keine Auflösungsskalierung nutzt.",
	["Aplicar"] = "Anwenden",
	["Aplicar %d puntos"] = "%d Punkte anwenden",
	["Aprende Cocina con un instructor."] = "Lerne Kochkunst bei einem Lehrer.",
	["Aprende Cocina para encender fogatas."] = "Lerne Kochkunst, um Lagerfeuer zu entzünden.",
	["Aprende Minería o Herboristería"] = "Lerne Bergbau oder Kräuterkunde",
	["Aprende Pesca"] = "Lerne Angeln",
	["Aprende Pesca con un instructor"] = "Lerne Angeln bei einem Lehrer",
	["Aprende Pesca con un instructor de pesca y compra una caña: la guía te lleva."] = "Lerne Angeln bei einem Angellehrer und kauf eine Angel: Der Guide führt dich hin.",
	["Aprende Pesca con un instructor, compra una caña y pesca en tu zona de inicio o en la capital. Pide el rango Oficial desde 50."] = "Lerne Angeln bei einem Lehrer, kauf eine Angel und angle in deinem Startgebiet oder in der Hauptstadt. Ab 50 frag nach dem Rang Geselle.",
	["Aprende equitación con %s"] = "Lerne Reiten bei %s",
	["Aprende las dos, consigue una caña y cocina lo que pescas hasta 75."] = "Lerne beide, besorg dir eine Angel und koche, was du fängst, bis 75.",
	["Aprender %s"] = "%s erlernen",
	["Aprender de tus búsquedas"] = "Aus deinen Suchen lernen",
	["Aprender una profesión o llegar a un nivel en ella."] = "Einen Beruf erlernen oder darin eine Stufe erreichen.",
	["Aprendiste un hechizo que le queda mejor a tus clics:"] = "Du hast einen Zauber gelernt, der besser zu deinen Klicks passt:",
	["Aprendiz"] = "Lehrling",
	["Apréndelos con el entrenador de tu clase, en cualquier capital."] = "Lerne sie bei deinem Klassenlehrer, in jeder Hauptstadt.",
	["Apágalo si no quieres que Alfa toque tus teclas, tu equipo ni tus ajustes al pescar."] = "Schalte es aus, wenn Alfa beim Angeln weder deine Tasten noch deine Ausrüstung oder Einstellungen anfassen soll.",
	["Aquí"] = "Hier",
	["Aquí aparecerán los demás módulos de Alfa (bolsas, rutas, mundo y más) en cuanto estén instalados."] = "Hier erscheinen die anderen Module von Alfa (Taschen, Routen, Welt und mehr), sobald sie installiert sind.",
	["Aquí el juego no da tu posición (por ejemplo, dentro de una mazmorra)."] = "Hier gibt das Spiel deine Position nicht preis (zum Beispiel in einem Dungeon).",
	["Aquí el juego no deja compartir nada. Al salir, tu rastro vuelve a salir solo."] = "Hier lässt das Spiel kein Teilen zu. Wenn du rausgehst, wird deine Spur wieder von selbst gesendet.",
	["Aquí estoy, como siempre. Nunca dejo a nadie atrás."] = "Hier bin ich, wie immer. Ich lasse niemanden zurück.",
	["Aquí está el Portal Oscuro: por él cruzó la Horda desde Draenor para invadir Azeroth en la Primera Guerra."] = "Hier steht das Dunkle Portal: Durch es kam die Horde von Draenor, um im Ersten Krieg in Azeroth einzufallen.",
	["Aquí está la tumba de Uther el Iluminado, el maestro de Arthas. Murió a manos de su propio alumno, defendiendo las cenizas del rey Terenas."] = "Hier liegt das Grab von Uther dem Lichtbringer, dem Lehrmeister von Arthas. Er starb durch die Hand seines eigenen Schülers, als er die Asche von König Terenas verteidigte.",
	["Aquí la lees completa: cómo empieza, qué te piden y cómo termina."] = "Hier liest du sie ganz: wie sie beginnt, worum man dich bittet und wie sie endet.",
	["Aquí no hay nodos que recolectar"] = "Hier gibt es nichts zu sammeln",
	["Aquí sale por qué se activó la habilidad."] = "Hier steht, warum die Fähigkeit aufgeleuchtet ist.",
	["Aquí ves cuántas llevas, dónde sale y qué hacer con ella."] = "Hier siehst du, wie viele du hast, woher sie kommen und was du damit machen kannst.",
	["Aquí ves todo lo que hay que saber, con qué hacer después."] = "Hier siehst du alles Wichtige und was du als Nächstes tun kannst.",
	["Aquí: %s %.1f, %.1f. Se guarda este punto."] = "Hier: %s %.1f, %.1f. Dieser Punkt wird gespeichert.",
	["Arañazo: sangrado con el tiempo."] = "Krallenhieb: Blutung über Zeit.",
	["Arcano"] = "Arkan",
	["Arcano para subir"] = "Arkan zum Leveln",
	["Archimonde subió a Hyjal para robar la energía del Árbol del Mundo; en vez de eso, el árbol fue su final."] = "Archimonde stieg auf den Hyjal, um die Energie des Weltenbaums zu stehlen; stattdessen wurde der Baum sein Ende.",
	["Arco"] = "Bogen",
	["Arcos, ballestas y armas de fuego"] = "Bögen, Armbrüste und Schusswaffen",
	["Arena"] = "Sand",
	["Arma"] = "Waffe",
	["Arma con tu ruta lo que necesitas para poder tomarla: el nivel o las misiones de antes."] = "Baut in deine Route ein, was du brauchst, um sie annehmen zu können: die Stufe oder die vorherigen Quests.",
	["Arma de asta"] = "Stangenwaffe",
	["Arma de dos manos"] = "Zweihandwaffe",
	["Arma de dos manos, sellos y juicios: el paladín que mejor sube en solitario."] = "Zweihandwaffe, Siegel und Richturteile: der Paladin, der solo am besten levelt.",
	["Arma de fuego"] = "Schusswaffe",
	["Arma de puño"] = "Faustwaffe",
	["Arma el plan para cerrar las misiones de tu registro y te lleva a cada una."] = "Erstellt den Plan, um die Quests in deinem Questlog abzuschließen, und führt dich zu jeder.",
	["Arma tu grupo de 5 (buscador de grupos o tu manada)."] = "Stell deine 5er-Gruppe zusammen (Gruppensuche oder dein Rudel).",
	["Arma tu primer plan"] = "Erstelle deinen ersten Plan",
	["Arma una ruta de %s en %s"] = "Route für %s in %s erstellen",
	["Arma y escudo"] = "Waffe und Schild",
	["Armadura"] = "Rüstung",
	["Armaduras"] = "Rüstung",
	["Armando"] = "Wird erstellt",
	["Armando «Cerrar mis misiones»..."] = "„Meine Quests abschließen“ wird erstellt...",
	["Armar la ruta"] = "Route erstellen",
	["Armar lo que falta"] = "Fehlendes erstellen",
	["Armar mi plan"] = "Meinen Plan erstellen",
	["Armar un plan nuevo"] = "Neuen Plan erstellen",
	["Armas"] = "Waffen",
	["Armas a dos manos"] = "Waffen mit Zweihänder",
	["Armas a muerte"] = "Waffen, volle Offensive",
	["Armas contra jugadores"] = "Waffen für PvP",
	["Armas para grupo"] = "Waffen für Gruppen",
	["Armas pensado para mazmorras: mucho daño en varios enemigos con Golpes de barrido, Golpe mortal para los jefes y más precisión para no fallar."] = "Waffen für Dungeons: viel Schaden an mehreren Gegnern mit Weitreichende Stöße, Tödlicher Stoß für die Bosse und mehr Trefferchance, damit du nicht verfehlst.",
	["Armas pensando primero en no morir: paras más golpes, frenas a los que huyen y terminas con un poco de Protección para recibir menos daño."] = "Waffen, das zuerst ans Überleben denkt: Du parierst mehr, bremst Fliehende und endest mit etwas Schutz, um weniger Schaden zu nehmen.",
	["Armas seguro"] = "Waffen, sicher",
	["Armas, armaduras, materiales, recetas y monturas: quién los suelta y quién los vende."] = "Waffen, Rüstungen, Materialien, Rezepte und Reittiere: wer sie fallen lässt und wer sie verkauft.",
	["Arrastra cada marco de combate adonde te acomode. Cuando termines, fíjalos para que no estorben."] = "Zieh jeden Kampfrahmen dorthin, wo er dir passt. Wenn du fertig bist, fixiere sie, damit sie nicht stören.",
	["Arrastra otra bolsa aquí para cambiarla."] = "Zieh eine andere Tasche hierher, um sie zu tauschen.",
	["Arrastra para mover tus marcos. Cambia el tamaño y las columnas en la página Curación."] = "Ziehen, um deine Rahmen zu verschieben. Größe und Spalten änderst du auf der Seite Heilung.",
	["Arrastra para mover tus marcos. Haz clic (con o sin Mayús, Ctrl o Alt) para ver qué lanzaría."] = "Zieh, um deine Rahmen zu verschieben. Klick (mit oder ohne Umschalt, Strg oder Alt), um zu sehen, was gewirkt würde.",
	["Arrastra una bolsa aquí para ponerla."] = "Zieh eine Tasche hierher, um sie anzulegen.",
	["Arreglos: «Cerrar mis misiones» vuelve a armar tu ruta, la ayuda de rotación vuelve a decirte qué usar y el mapa ya no muestra rectángulos pegados al acercar."] = "Korrekturen: „Meine Quests abschließen“ erstellt deine Route wieder, die Rotationshilfe sagt dir wieder, was du nutzen sollst, und die Karte zeigt beim Zoomen keine aufgeklebten Rechtecke mehr.",
	["Arriba de la ventana, cada bolsa equipada con su espacio: pasa el ratón para resaltar lo que lleva y arrastra otra bolsa para cambiarla."] = "Oben im Fenster jede angelegte Tasche mit ihrem Platz: Fahr mit der Maus darüber, um ihren Inhalt hervorzuheben, und zieh eine andere Tasche darauf, um sie zu tauschen.",
	["Arriba, lo que Alfa recomienda. Un clic y empiezas."] = "Oben, was Alfa empfiehlt. Ein Klick, und es geht los.",
	["Arriesgado"] = "Riskant",
	["Arrodillarse"] = "Knien",
	["Arrojadiza"] = "Wurfwaffe",
	["Arrástralo para moverlo"] = "Zum Verschieben ziehen",
	["Artefacto"] = "Artefakt",
	["Artesano"] = "Fachmann",
	["Artesanía y comercio"] = "Handwerk und Handwerkswaren",
	["Arthas mató a Kel'Thuzad en Andorhal, pero después lo revivió como liche con el poder de la Fuente del Sol."] = "Arthas tötete Kel'Thuzad in Andorhal, erweckte ihn aber später mit der Macht des Sonnenbrunnens als Lich wieder.",
	["Arthas mató al archimago Antonidas en Dalaran, y después Archimonde destruyó la ciudad."] = "Arthas tötete Erzmagier Antonidas in Dalaran, und danach zerstörte Archimonde die Stadt.",
	["Arthas purgó Stratholme porque su grano estaba infectado. Esa decisión lo separó para siempre de Uther y de Jaina."] = "Arthas säuberte Stratholme, weil das Getreide verseucht war. Diese Entscheidung trennte ihn für immer von Uther und Jaina.",
	["Arthas tomó la espada Agonía de Escarcha en Rasganorte creyendo que salvaría a su pueblo. La espada le robó el alma."] = "Arthas nahm in Nordend das Schwert Frostgram an sich, im Glauben, es würde sein Volk retten. Das Schwert raubte ihm die Seele.",
	["Arthas y Jaina se querían antes de que la plaga los separara."] = "Arthas und Jaina liebten sich, bevor die Seuche sie trennte.",
	["Asesinato"] = "Meucheln",
	["Asesinato para subir"] = "Meucheln zum Leveln",
	["Aspecto"] = "Aspekt",
	["Astranaar es el pueblo élfico en medio de Vallefresno, en una isla del lago."] = "Astranaar ist der Elfenort mitten im Eschental, auf einer Insel im See.",
	["Asusta a todos los que están cerca: si te asusta, intenta no correr hacia otras celdas."] = "Er versetzt alle in der Nähe in Furcht: Wenn es dich trifft, versuch, nicht in andere Zellen zu laufen.",
	["Asusta y duerme a los jugadores: si te asusta, intenta no correr hacia más enemigos."] = "Er versetzt Spieler in Furcht und Schlaf: Wenn es dich trifft, versuch, nicht in weitere Gegner zu laufen.",
	["Así queda tu Alfa"] = "So sieht dein Alfa aus",
	["Así sabes qué hace cada clic antes de tu próxima pelea."] = "So weißt du vor deinem nächsten Kampf, was jeder Klick tut.",
	["Así se lee tu ayuda de rotación"] = "So liest du deine Rotationshilfe",
	["Así se ven tus avisos"] = "So sehen deine Hinweise aus",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo, en Marcos. Pulsa Listo cuando termines."] = "So sehen deine Rahmen aus. Zieh sie, um sie zu verschieben, und ändere ihre Größe unten unter Rahmen. Drück „Fertig“, wenn du so weit bist.",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo. Pulsa Listo cuando termines."] = "So sehen deine Rahmen aus. Zieh sie, um sie zu verschieben, und ändere unten ihre Größe. Drück „Fertig“, wenn du fertig bist.",
	["Así terminó «%s»… ¿Te cuento el final?"] = "So endete „%s“… Soll ich dir das Ende erzählen?",
	["Atajos"] = "Tastenkürzel",
	["Ataque de tormenta: mucho daño, cada vez que esté listo."] = "Sturmschlag: viel Schaden, jedes Mal, wenn er bereit ist.",
	["Ataques más rápidos después de un crítico."] = "Schnellere Angriffe nach einem Krit.",
	["Atardecer"] = "Sonnenuntergang",
	["Atenuar a quien está lejos"] = "Entfernte Mitglieder abblenden",
	["Atiesh, el Gran Bastón del Guardián, fue de Medivh. En el Clásico se puede rehacer con fragmentos que caen en Naxxramas."] = "Atiesh, Großer Stab des Wächters, gehörte Medivh. In Classic kann man ihn aus Splittern neu schaffen, die in Naxxramas droppen.",
	["Atravesar objetos pequeños"] = "Durch kleine Objekte hindurch",
	["Atronar fuerte: juntas varios monstruos y los frenas a todos."] = "Starker Donnerknall: Du ziehst mehrere Monster und verlangsamst sie alle.",
	["Atronar más barato para agarrar varios."] = "Günstigerer Donnerknall, um mehrere zu halten.",
	["Atronar más fuerte y barato: agarras a varios enemigos a la vez."] = "Stärkerer und günstigerer Donnerknall: Du hältst mehrere Gegner gleichzeitig.",
	["Atrás"] = "Zurück",
	["Aturde al tanque con su martillo: mantén la vida del tanque alta."] = "Er betäubt den Tank mit seinem Hammer: Halte die Gesundheit des Tanks hoch.",
	["Aturdes a uno mientras peleas con otro."] = "Du betäubst einen, während du gegen einen anderen kämpfst.",
	["Aturdes al enemigo más peligroso."] = "Du betäubst den gefährlichsten Gegner.",
	["Aturdimiento a demanda."] = "Betäubung auf Abruf.",
	["Auberdine es el puerto de los elfos de la noche: de ahí salen barcos a Teldrassil y a los Reinos del Este."] = "Auberdine ist der Hafen der Nachtelfen: Von dort fahren Schiffe nach Teldrassil und in die Östlichen Königreiche.",
	["Aullido al abrir Alfa"] = "Heulen beim Öffnen von Alfa",
	["Aura"] = "Aura",
	["Automática"] = "Automatisch",
	["Avanzado"] = "Erweitert",
	["Aventura"] = "Abenteuer",
	["Aventura (2): explorar todo el mapa del mundo con un personaje y terminar la cadena de Lord Valthalak (el conjunto de mazmorra 2)."] = "Abenteuer (2): mit einem Charakter die ganze Weltkarte erkunden und die Questreihe von Lord Valthalak abschließen (Dungeonset 2).",
	["Aventura: descanso más rápido, vida y maná tras cada muerte, ver mejor a los sigilosos, talentos hasta 5 niveles antes y vuelos más baratos y rápidos."] = "Abenteuer: schnellere Erholung, Gesundheit und Mana nach jedem Kill, Verstohlene besser sehen, Talente bis zu 5 Stufen früher und billigere, schnellere Flüge.",
	["Avienta a todos los que están cerca: si peleas de lejos, aléjate."] = "Er schleudert alle in seiner Nähe weg: Wenn du auf Distanz kämpfst, halte Abstand.",
	["Avienta y aturde a todos los que están cerca: ponte con la espalda en la pared."] = "Sie schleudert alle in ihrer Nähe weg und betäubt sie: Stell dich mit dem Rücken an eine Wand.",
	["Avisar antes de una misión que cierra otra"] = "Vor einer Quest warnen, die eine andere ausschließt",
	["Avisar con estos espacios libres o menos"] = "Warnen bei so vielen freien Plätzen oder weniger",
	["Avisar cuando baje de"] = "Warnen, wenn sie unter diesen Wert fällt",
	["Avisar cuando los precios tengan más de"] = "Warnen, wenn Preise älter sind als",
	["Avisar cuando queden"] = "Warnen bei freien Plätzen",
	["Avisar los hechizos nuevos para entrenar"] = "Neue Zauber zum Trainieren melden",
	["Avisar rangos viejos en tus barras"] = "Alte Ränge in meinen Leisten melden",
	["Avisar si la barra de una forma está vacía"] = "Warnen, wenn die Leiste einer Gestalt leer ist",
	["Avisar también si le quedan menos de"] = "Auch warnen, wenn weniger übrig ist als",
	["Avisarme al descubrir un jefe"] = "Melden, wenn ich einen Boss entdecke",
	["Avisarme al entrar a una mazmorra"] = "Melden, wenn ich einen Dungeon betrete",
	["Avisarme cuando mi equipo se gaste"] = "Warnen, wenn meine Ausrüstung verschleißt",
	["Avisarme cuando mis bolsas se llenen"] = "Warnen, wenn meine Taschen voll werden",
	["Avisarme de mi XP descansada"] = "Mich über meinen Ruhebonus informieren",
	["Avisarme del talento que toca"] = "Das nächste Talent melden",
	["Avisarme en la ciudad si tengo habilidades por aprender"] = "In der Stadt erinnern, wenn ich Fähigkeiten lernen kann",
	["Avisarme si me falta mi buff fuera de combate"] = "Erinnern, wenn mir mein Buff außerhalb des Kampfes fehlt",
	["Aviso"] = "Signal",
	["Aviso al poner la flecha"] = "Hinweis beim Setzen des Pfeils",
	["Aviso con lo que sacas"] = "Hinweis mit deinem Fang",
	["Aviso urgente, con sonido"] = "Dringende Warnung, mit Ton",
	["Avisos"] = "Hinweise",
	["Avisos con sonido"] = "Hinweise mit Ton",
	["Avisos de jefes"] = "Boss-Warnungen",
	["Avisos de jefes como los recomienda Alfa"] = "Bosshinweise, wie Alfa sie empfiehlt",
	["Avisos de jefes del juego"] = "Boss-Warnungen des Spiels",
	["Avisos de reacción"] = "Reaktionshinweise",
	["Avisos y diario"] = "Hinweise und Tagebuch",
	["Avisos, golpe y estadísticas"] = "Hinweise, Schlag und Werte",
	["Ayuda de rotación"] = "Rotationshilfe",
	["Ayuda de rotación para las 27 especializaciones y la ventana /alfa paisaje con 68 ajustes gráficos explicados."] = "Rotationshilfe für alle 27 Spezialisierungen und das Fenster /alfa paisaje mit 68 erklärten Grafikeinstellungen.",
	["Ayudas de combate"] = "Kampfhilfen",
	["Ayudas para tu personaje"] = "Hilfen für deinen Charakter",
	["Azeroth"] = "Azeroth",
	["Azeroth tiene dos continentes en el Clásico: Kalimdor al oeste y los Reinos del Este. En medio está el Gran Mar."] = "In Classic hat Azeroth zwei Kontinente: Kalimdor im Westen und die Östlichen Königreiche. Dazwischen liegt das Große Meer.",
	["Azshara lleva el nombre de la reina de los elfos que abrió la puerta a la Legión Ardiente. Tras la Gran División se convirtió en la reina de los naga."] = "Azshara trägt den Namen der Elfenkönigin, die der Brennenden Legion das Tor öffnete. Nach der Großen Teilung wurde sie zur Königin der Naga.",
	["Azshara y los Altonato que se hundieron con su palacio no murieron: se transformaron en los naga."] = "Azshara und die Hochgeborenen, die mit ihrem Palast versanken, sind nicht gestorben: Sie wurden zu den Naga.",
	["Azul"] = "Blau",
	["Aún no conozco ese objeto. Pásale el ratón encima y vuelve a intentarlo."] = "Diesen Gegenstand kenne ich noch nicht. Fahr mit der Maus darüber und versuch es erneut.",
	["Aún no está terminada: te falta %s."] = "Noch nicht abgeschlossen: Dir fehlt noch %s.",
	["Aún no está terminada: termínala antes de entregarla."] = "Noch nicht abgeschlossen: Schließ sie ab, bevor du sie abgibst.",
	["Aún no hay historias"] = "Noch keine Geschichten",
	["Aún no hay misiones de clase para ti: la próxima abre a nivel %d."] = "Noch keine Klassenquests für dich: Die nächste gibt es ab Stufe %d.",
	["Aún no hay personajes guardados"] = "Noch keine Charaktere gespeichert",
	["Aún no la aprendes"] = "Noch nicht erlernt",
	["Aún no la tomas"] = "Noch nicht angenommen",
	["Aún no lo aprendes"] = "Noch nicht gelernt",
	["Aún no los aprendes"] = "Noch nicht gelernt",
	["Aún no picaba"] = "Es hatte noch nichts angebissen",
	["Aún no puedes tomar %s"] = "Du kannst %s noch nicht annehmen",
	["Aún no tienes el nivel"] = "Deine Stufe ist noch zu niedrig",
	["Aún no tienes nada abierto. Mira Todas o usa los filtros de arriba para encontrar una guía."] = "Du hast noch nichts geöffnet. Schau unter Alle oder nutze die Filter oben, um einen Guide zu finden.",
	["Aún no tienes precios de la subasta: escanéala para saber cuánto vale de verdad."] = "Du hast noch keine Auktionspreise: Scanne das Auktionshaus, um zu erfahren, was die Dinge wirklich wert sind.",
	["Aún no tienes precios. Pulsa «Escanear con Alfa»."] = "Noch keine Preise. Drück „Mit Alfa scannen“.",
	["Aún no tienes rutas. Ármalas en la ventana de Alfa: Aventura > Rutas; cada una aparece aquí como guía."] = "Du hast noch keine Routen. Bau sie im Alfa-Fenster unter Abenteuer > Routen; jede erscheint hier als Guide.",
	["Aún sin abrir: gana tu primer punto"] = "Noch nicht freigeschaltet: Verdiene deinen ersten Punkt",
	["Bahía del Botín es el puerto del cártel Bonvapor, y ahí manda el barón Revilgaz."] = "Beutebucht ist der Hafen des Dampfdruckkartells, und dort hat Baron Revilgaz das Sagen.",
