	["Básico"] = "Basis",
	["Búscalo por su nombre; se cumple cuando lo tienes en tus bolsas."] = "Such ihn nach Namen; erfüllt, sobald er in deinen Taschen ist.",
	["CPS"] = "HPS",
	["Cabeza"] = "Kopf",
	["Cada 2 niveles"] = "Alle 2 Stufen",
	["Cada Aspecto guía un vuelo de dragones: Alexstrasza el rojo, Ysera el verde, Nozdormu el bronce, Malygos el azul y Neltharion el negro."] = "Jeder Aspekt führt einen Drachenschwarm: Alexstrasza den roten, Ysera den grünen, Nozdormu den bronzenen, Malygos den blauen und Neltharion den schwarzen.",
	["Cada ajuste que Alfa cambió vuelve al valor que tenía antes. Los filtros no cambian."] = "Jede Einstellung, die Alfa geändert hat, kehrt zu ihrem vorherigen Wert zurück. Die Filter ändern sich nicht.",
	["Cada aviso y cada porqué sale con texto hasta %d veces y luego solo queda el ícono."] = "Jeder Hinweis und jede Begründung erscheint bis zu %d-mal mit Text, danach bleibt nur das Symbol.",
	["Cada bloqueo te da ira: nunca te falta."] = "Jeder Block gibt dir Wut: Sie geht dir nie aus.",
	["Cada bolsa en su bloque, con su nombre y su espacio."] = "Jede Tasche in einem eigenen Block, mit Namen und Platz.",
	["Cada botón de acción con el borde y el fondo del estilo, el ícono cuadrado y la letra de Alfa en la tecla y la cuenta."] = "Jeder Aktionsbutton mit Rand und Hintergrund des Stils, quadratischem Symbol und Alfas Schrift für Taste und Anzahl.",
	["Cada casilla en su lugar, como en tus bolsas."] = "Jeder Platz an seiner Stelle, wie in deinen Taschen.",
	["Cada clase da retos del Legado al llegar a 25, 45 y 60: subir otras clases también le suma a tu cuenta."] = "Jede Klasse gibt Vermächtnis-Herausforderungen auf 25, 45 und 60: Andere Klassen zu leveln zählt auch für deinen Account.",
	["Cada cofre o tesoro conocido."] = "Jede bekannte Truhe und jeder bekannte Schatz.",
	["Cada crítico hace sangrar."] = "Jeder Krit verursacht Blutung.",
	["Cada domingo en Tuercespina: el primero en llevar 40 pescados sabrosos de los bancos especiales gana. También salen peces raros que se cambian por premios."] = "Jeden Sonntag im Schlingendorntal: Wer als Erster 40 Gefleckte Leckerfische aus den besonderen Schwärmen abliefert, gewinnt. Außerdem gibt es seltene Fische, die man gegen Preise eintauschen kann.",
	["Cada entrada de mazmorra y banda con su rango de niveles. Clic: su página; Mayús+clic: la flecha te lleva."] = "Jeder Dungeon- und Schlachtzugseingang mit seinem Stufenbereich. Klick: seine Seite; Umschalt+Klick: Der Pfeil führt dich hin.",
	["Cada frase sale tres veces como mucho. Con esto vuelven a salir desde el principio."] = "Jeder Satz erscheint höchstens dreimal. Hiermit kommen sie alle wieder von vorn.",
	["Cada golpe crítico deja al enemigo sangrando: daño extra sin hacer nada."] = "Jeder kritische Treffer lässt den Gegner bluten: Extraschaden ohne Aufwand.",
	["Cada hierba tiene su lugar: unas junto al agua, otras en las montañas o bajo los árboles."] = "Jedes Kraut hat seinen Ort: manche am Wasser, andere in den Bergen oder unter Bäumen.",
	["Cada lugar conocido donde aparece un enemigo raro."] = "Jeder bekannte Ort, an dem ein seltener Gegner erscheint.",
	["Cada meseta de Cima del Trueno tiene su función: una para los ancianos y los druidas, otra para los espíritus y otra para los cazadores."] = "Jede Hochebene von Donnerfels hat ihre Aufgabe: eine für die Ältesten und Druiden, eine für die Geister und eine für die Jäger.",
	["Cada misión que terminas te hace más fuerte."] = "Jede Quest, die du abschließt, macht dich stärker.",
	["Cada nivel"] = "Jede Stufe",
	["Cada paso de la bienvenida deja bajar hasta el final, sin cerrar y volver a abrir."] = "Jeder Schritt der Begrüßung lässt sich bis ganz nach unten scrollen, ohne zu schließen und neu zu öffnen.",
	["Cada preajuste llena tus clics con los hechizos que ya sabes. Después cambias lo que quieras en la página Curación."] = "Jede Voreinstellung belegt deine Klicks mit den Zaubern, die du schon kannst. Später änderst du auf der Seite Heilung, was du willst.",
	["Cada reto da 1 punto. Al salir Forever hay %d retos, y cada personaje puede gastar hasta %d."] = "Jede Herausforderung bringt 1 Punkt. Zum Start von Forever gibt es %d Herausforderungen, und jeder Charakter kann bis zu %d ausgeben.",
	["Cada versión nueva te recibe con la intro del lobo y sus notas, como estas."] = "Jede neue Version empfängt dich mit dem Wolfsintro und ihren Notizen, so wie diesen.",
	["Cada vez que entras al juego, la intro del lobo y la luna te da la bienvenida. Un clic o Esc la saltan."] = "Jedes Mal, wenn du ins Spiel kommst, begrüßt dich das Intro mit Wolf und Mond. Ein Klick oder Esc überspringt es.",
	["Cada ícono del mapa con su tamaño exacto en tu pantalla, nítido de orilla a orilla."] = "Jedes Kartensymbol in seiner genauen Größe auf deinem Bildschirm, scharf von Rand zu Rand.",
	["Cairne Pezuña de Sangre gobierna desde Cima del Trueno, aunque Magatha, de los Tótem Siniestro, no lo quiere tanto como aparenta."] = "Cairne Bluthuf herrscht von Donnerfels aus, auch wenn Magatha von den Grimmtotem ihn nicht so sehr mag, wie sie vorgibt.",
	["Cairne Pezuña de Sangre peleó en el Monte Hyjal junto a Thrall contra la Legión."] = "Cairne Bluthuf kämpfte am Berg Hyjal an Thralls Seite gegen die Legion.",
	["Caja para escribir con el estilo"] = "Eingabefeld im Stil",
	["Calculando"] = "Wird berechnet",
	["Calculando la vuelta más corta…"] = "Kürzeste Runde wird berechnet…",
	["Calidad"] = "Qualität",
	["Calidad de la niebla"] = "Nebelqualität",
	["Calidad de las sombras"] = "Schattenqualität",
	["Calla las voces de /bailar, /reír, /aplaudir y otros gestos."] = "Schaltet die Stimmen von /tanzen, /lachen, /applaudieren und anderen Emotes stumm.",
