	["Cintura"] = "Taille",
	["Ciudad Manitas, dentro de Forjaz, es el barrio de los gnomos: ruido, vapor e inventos por todos lados."] = "Tüftlerstadt in Eisenschmiede ist das Viertel der Gnome: Lärm, Dampf und Erfindungen überall.",
	["Clase"] = "Klasse",
	["Clases (27): llegar a nivel 25, 45 y 60 con cada una de las 9 clases."] = "Klassen (27): mit jeder der 9 Klassen Stufe 25, 45 und 60 erreichen.",
	["Clic derecho (o Mayús+clic): un marcador ahí. Ctrl+clic: la flecha y la ruta te llevan ahí sin guardar nada."] = "Rechtsklick (oder Umschalt+Klick): eine Markierung dort. Strg+Klick: Pfeil und Route führen dich hin, ohne etwas zu speichern.",
	["Clic derecho en un jugador (su retrato, su nombre en el chat o tu grupo) y elige tu hermandad: la invitación le llega sin escribir su nombre. Para una comunidad, Alfa te deja el nombre listo para pegar en la ventana del juego."] = "Rechtsklick auf einen Spieler (sein Porträt, sein Name im Chat oder deine Gruppe) und wähle deine Gilde: Die Einladung kommt an, ohne dass du den Namen tippen musst. Für eine Community legt Alfa dir den Namen zum Einfügen im Spielfenster bereit.",
	["Clic derecho en un jugador y «Invitar al clan»: eliges tu hermandad o tu comunidad y la invitación le llega sin escribir su nombre."] = "Rechtsklick auf einen Spieler und „In Gilde oder Community einladen“: Wähle deine Gilde oder Community, und die Einladung kommt an, ohne dass du den Namen tippen musst.",
	["Clic derecho: dejarla sin acción."] = "Rechtsklick: ohne Aktion lassen.",
	["Clic derecho: opciones de esta guía"] = "Rechtsklick: Optionen dieses Guides",
	["Clic derecho: reiniciar, quitar o llevar a Mis planes."] = "Rechtsklick: zurücksetzen, entfernen oder zu „Meine Pläne“.",
	["Clic en Llévame: la flecha te lleva"] = "Klick auf „Bring mich hin“: Der Pfeil führt dich",
	["Clic en un marcador: su ficha (cambiarlo, compartirlo, borrarlo o seguirlo). Mayús+clic: seguirlo de una vez. Clic derecho en cualquier otro pin: seguirlo o guardarlo como marcador."] = "Klick auf eine Markierung: ihr Eintrag (ändern, teilen, löschen oder folgen). Umschalt+Klick: sofort folgen. Rechtsklick auf jeden anderen Pin: folgen oder als Markierung speichern.",
	["Clic en una casilla para elegir qué hace sobre el compañero bajo tu ratón; clic derecho la deja sin acción. Los cambios se aplican fuera de combate."] = "Klick auf ein Feld, um zu wählen, was es beim Gruppenmitglied unter deiner Maus tut; Rechtsklick lässt es ohne Aktion. Änderungen gelten außerhalb des Kampfes.",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta."] = "Klick auf eine: Alfas Karte springt dorthin. „Folgen“ setzt Pfeil und Route.",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta; la huella del grupo lo comparte con quien use Alfa."] = "Klick auf eine: Alfas Karte springt dorthin. „Folgen“ setzt Pfeil und Route; der Pfotenabdruck der Gruppe teilt sie mit allen, die Alfa nutzen.",
	["Clic en uno: el mapa va hasta él. Clic derecho en el mapa: uno nuevo."] = "Klick auf eine: Die Karte springt dorthin. Rechtsklick auf die Karte: eine neue.",
