	["Común"] = "Verbreitet",
	["Con 10 de furia o más lo lanzas."] = "Ab 10 Wut kannst du ihn wirken.",
	["Con Cocina puedes encender tu propia fogata en cualquier lado."] = "Mit Kochkunst kannst du überall dein eigenes Lagerfeuer entzünden.",
	["Con Redención reviven tus compañeros caídos: en una mazmorra vale oro."] = "Mit Erlösung belebst du gefallene Gefährten wieder: In einem Dungeon ist das Gold wert.",
	["Con aullido"] = "Mit Heulen",
	["Con buena reputación, los vendedores de esa facción te hacen descuento."] = "Mit gutem Ruf geben dir die Händler dieser Fraktion Rabatt.",
	["Con calma, nos pasa a todos. Mira qué te pegó y vuelve con todo."] = "Ganz ruhig, das passiert uns allen. Schau, was dich erwischt hat, und komm stark zurück.",
	["Con dos armas pega más rápido: guarda maná para el final."] = "Mit zwei Waffen schlägt er schneller zu: Spar dir Mana für das Ende auf.",
	["Con el correo puedes enviar contra reembolso: mandas el objeto y cobras al entregarlo."] = "Mit der Post kannst du per Nachnahme verschicken: Du schickst den Gegenstand und kassierst bei Annahme.",
	["Con el cuadro oculto en combate, mantén presionado Mayús para verlo."] = "Wenn der Tooltip im Kampf ausgeblendet ist, halte Umschalt gedrückt, um ihn zu sehen.",
	["Con el cursor encima no se cierra."] = "Solange der Cursor darauf ist, schließt er sich nicht.",
	["Con el entrenador más cercano en tu camino."] = "Mit dem nächsten Lehrer auf deinem Weg.",
	["Con el modo pesca abierto y alguna meta, la ventanita de metas se ve sola."] = "Bei offenem Angelmodus und gesetztem Ziel erscheint das kleine Zielfenster von selbst.",
	["Con el modo pesca abierto, esta tecla lo hace todo: equipo, cebo, lanzar y recoger. Al cerrarlo vuelve a ser la de siempre."] = "Bei offenem Angelmodus erledigt diese Taste alles: Ausrüstung, Köder, Auswerfen und Einholen. Beim Schließen wird sie wieder zur gewohnten Taste.",
	["Con el modo pesca abierto, un aviso suave para volver a lanzar."] = "Bei offenem Angelmodus ein sanfter Hinweis, wieder auszuwerfen.",
	["Con el tiempo, los magos humanos se reunieron en Dalaran, que se volvió la ciudad de la magia de los Reinos del Este."] = "Mit der Zeit versammelten sich die menschlichen Magier in Dalaran, das zur Stadt der Magie in den Östlichen Königreichen wurde.",
	["Con la interfaz de mando el mapa del juego se abre con su tecla."] = "Mit der Controller-Oberfläche öffnet sich die Spielkarte mit ihrer eigenen Taste.",
	["Con la interfaz para mando, Alfa deja las bolsas del juego. Igual puedes abrir la ventana de Alfa desde aquí."] = "Mit der Controller-Oberfläche überlässt Alfa die Taschen dem Spiel. Du kannst Alfas Fenster trotzdem von hier öffnen.",
	["Con la tecla en Espacio, Mayús+Espacio salta mientras el modo está abierto."] = "Liegt die Taste auf Leertaste, springst du bei offenem Modus mit Umschalt+Leertaste.",
	["Con las de Alfa ves todo en una ventana: tres vistas, búsqueda, la barra de tus bolsas y qué vender cuando se llenan."] = "Mit Alfas Taschen siehst du alles in einem Fenster: drei Ansichten, Suche, deine Taschenleiste und was du verkaufen kannst, wenn sie voll werden.",
	["Con mando, se quedan las bolsas del juego"] = "Mit Controller bleiben die Taschen des Spiels",
	["Con o sin Mayús, Ctrl o Alt. No lanza nada: aquí ves qué lanzaría sobre tu compañero."] = "Mit oder ohne Umschalt, Strg oder Alt. Es wird nichts gewirkt: Hier siehst du, was auf dein Gruppenmitglied gewirkt würde.",
	["Con poca vida llama a dos ayudantes: si a él le queda poco, terminen con él; si no, maten a los ayudantes."] = "Bei wenig Gesundheit ruft er zwei Helfer: Hat er nur noch wenig, erledigt ihn; sonst tötet zuerst die Helfer.",
	["Con poca vida se convierte en serpiente y pega más fuerte: guarda tus mejores ataques para ese momento."] = "Bei wenig Gesundheit verwandelt er sich in eine Schlange und schlägt härter zu: Spar dir deine besten Angriffe für diesen Moment auf.",
	["Con qué prioridad sugiere Alfa. Automática: la de tus talentos o, mientras subes, la de tu clase."] = "Mit welcher Priorität Alfa vorschlägt. Automatisch: die deiner Talente oder, solange du levelst, die deiner Klasse.",
	["Con reputación %s"] = "Ab Ruf %s",
	["Con sonido"] = "Mit Ton",
	["Con tu build, Alfa sabe qué estadísticas te sirven y qué equipo buscar."] = "Mit deinem Build weiß Alfa, welche Werte dir nützen und welche Ausrüstung du suchen solltest.",
	["Con tu punto libre se compra 1 rango de %s:"] = "Mit deinem freien Punkt kaufst du 1 Rang von %s:",
	["Con tu ritual de invocación y la ayuda de dos compañeros, traes a otro miembro del grupo hasta donde estés."] = "Mit deinem Ritual der Beschwörung und der Hilfe zweier Gefährten holst du ein anderes Gruppenmitglied zu dir.",
	["Con tus %d puntos libres se compran %d rangos de %s:"] = "Mit deinen %d freien Punkten werden %d Ränge von %s gekauft:",
	["Con un brillo suave"] = "Mit sanftem Leuchten",
	["Con un enemigo elegido, antes de empezar la pelea, y transparente para que no estorbe."] = "Mit einem Gegner im Ziel, vor Kampfbeginn, und durchsichtig, damit es nicht stört.",
	["Concurso"] = "Wettbewerb",
	["Concurso de pesca de Tuercespina"] = "Anglerwettbewerb im Schlingendorntal",
	["Configura tu Alfa"] = "Richte dein Alfa ein",
	["Configuración terminada"] = "Einrichtung abgeschlossen",
	["Configuración y ayuda"] = "Einrichtung und Hilfe",
	["Configurar"] = "Einrichten",
	["Configurar con el asistente"] = "Mit dem Assistenten einrichten",
	["Confirmado por Blizzard (su noticia del sistema de Legado de WoW Forever): los 65 retos de 1 punto, el tope de 16 por personaje, los tres árboles, los cuatro premios del registro y lo del modo extremo."] = "Von Blizzard bestätigt (ihre News zum Vermächtnis-System von WoW Forever): die 65 Herausforderungen zu je 1 Punkt, die Obergrenze von 16 pro Charakter, die drei Bäume, die vier Belohnungen der Leiste und die Hardcore-Regeln.",
	["Conflagrar: consume tu Inmolar para un golpe fuerte."] = "Feuersbrunst: verbraucht deinen Feuerbrand für einen starken Treffer.",
	["Congela a los que están cerca: si peleas de lejos, aléjate."] = "Er friert alle in seiner Nähe ein: Wenn du auf Distanz kämpfst, halte Abstand.",
	["Congela al monstruo con Nova de escarcha y aléjate antes de seguir lanzando."] = "Friere das Monster mit Frostnova ein und geh auf Abstand, bevor du weiterzauberst.",
	["Congela en el lugar y lanza rayos: si peleas de lejos, sepárate del grupo."] = "Sie friert Spieler fest und wirkt Blitze: Wenn ihr auf Distanz kämpft, verteilt euch.",
	["Congelas y frenas a los monstruos para que nunca te alcancen: el mago más seguro para subir."] = "Du frierst Monster ein und verlangsamst sie, damit sie dich nie erreichen: der sicherste Magier zum Leveln.",
	["Conjúralas fuera de combate."] = "Zaubere sie außerhalb des Kampfes herbei.",
	["Conocido"] = "Vertraut",
	["Conseguir %d de %s"] = "%d %s besorgen",
	["Conseguir %d × %s"] = "%d × %s besorgen",
	["Conseguir %s"] = "%s besorgen",
	["Conseguir un objeto"] = "Einen Gegenstand besorgen",
	["Consejo en el cuadro de los objetos"] = "Tipp im Tooltip der Gegenstände",
	["Consejos"] = "Tipps",
	["Consejos de equipo apagados."] = "Ausrüstungsberatung ist aus.",
	["Consejos para jugarlo"] = "Tipps zum Spielen",
	["Consejos vistos"] = "Gesehene Tipps",
	["Consejos: muchos"] = "Tipps: viele",
	["Consejos: pocos"] = "Tipps: wenige",
	["Consejos: solo importantes"] = "Tipps: nur wichtige",
	["Conserva %s: vale más de otra forma."] = "Behalte %s: Anders ist es mehr wert.",
	["Considerar desencantar"] = "Entzaubern berücksichtigen",
	["Consigue %s"] = "Besorge %s",
	["Consigue bolsas más grandes en cuanto puedas: más espacio, más botín."] = "Besorg dir größere Taschen, sobald du kannst: mehr Platz, mehr Beute.",
	["Consigue una caña de pescar"] = "Besorg dir eine Angelrute",
	["Consumibles"] = "Verbrauchsgüter",
	["Contar tu avance en el chat del grupo"] = "Deinen Fortschritt im Gruppenchat melden",
	["Contenta"] = "Zufrieden",
	["Contigo"] = "Bei dir",
	["Continuar"] = "Weiter",
	["Continuar mi ruta"] = "Meine Route fortsetzen",
	["Contra jefes de nivel alto fallas mucho: esto lo arregla."] = "Gegen hochstufige Bosse verfehlst du oft: Das behebt es.",
	["Contra jefes fallas mucho: esto te ayuda."] = "Gegen Bosse verfehlst du oft: Das hilft dir.",
	["Contra no-muertos y demonios: Exorcismo pega muy fuerte."] = "Gegen Untote und Dämonen: Exorzismus trifft sehr hart.",
	["Control de animación"] = "Animationssteuerung",
	["Contármela"] = "Erzähl sie mir",
	["Contármelo"] = "Erzähl es mir",
	["Coordenadas en el mapa"] = "Koordinaten auf der Karte",
	["Coordenadas en el minimapa"] = "Koordinaten auf der Minikarte",
	["Copia este texto (Ctrl+C) y pásalo a tu manada. Lo pegan en Importar."] = "Kopiere diesen Text (Strg+C) und gib ihn an dein Rudel weiter. Sie fügen ihn unter „Importieren“ ein.",
	["Copia la cadena de abajo y pásala por el chat o por Discord: con Alfa la pegan en Importar y tienen tu mismo build."] = "Kopiere die Zeichenkette unten und gib sie im Chat oder auf Discord weiter: Mit Alfa fügen sie sie unter „Importieren“ ein und haben denselben Build wie du.",
	["Copiar"] = "Kopieren",
	["Copiar el Discord"] = "Discord kopieren",
	["Copiar y editar"] = "Kopieren und bearbeiten",
	["Coral"] = "Koralle",
	["Correr"] = "Laufen",
	["Cortar"] = "Unterbrechen",
	["Costa Oscura está llena de ruinas élficas, como Ameth'Aran, de una época mucho más antigua."] = "Die Dunkelküste ist voller Elfenruinen aus viel älterer Zeit, wie Ameth'Aran.",
	["Costasur y Molino Tarren están a un paso uno del otro, y la Alianza y la Horda se miran feo desde siempre."] = "Süderstade und Tarrens Mühle liegen nur einen Katzensprung voneinander entfernt, und Allianz und Horde schauen sich hier seit jeher böse an.",
	["Costuras, una abominación enorme, ataca Villa Oscura en una de las misiones más famosas del bosque."] = "Flickwerk, eine riesige Monstrosität, greift Dunkelhain in einer der berühmtesten Quests des Waldes an.",
	["Crear %s ≈ %s"] = "%s herstellen ≈ %s",
	["Crear ruta"] = "Route erstellen",
	["Crecen hacia"] = "Wachsen nach",
	["Criaturas de nivel %d a %d"] = "Kreaturen der Stufe %d bis %d",
	["Criaturas raras y tesoros: dónde aparecen y lo que sueltan."] = "Seltene Kreaturen und Schätze: wo sie erscheinen und was sie fallen lassen.",
	["Cristal"] = "Glas",
	["Créditos y licencias"] = "Credits und Lizenzen",
	["Crítico"] = "Kritisch",
	["Crítico con hechizos"] = "Zauberkrit",
	["Críticos enormes: matas antes de que te curen."] = "Riesige Krits: Du tötest, bevor sie geheilt werden.",
	["Críticos más fuertes."] = "Stärkere Krits.",
	["Críticos un poco más fuertes."] = "Etwas stärkere Krits.",
	["Ctrl"] = "Strg",
	["Cuadro de información"] = "Tooltip",
	["Cualquier criatura de su nivel"] = "Jede Kreatur seiner Stufe",
	["Cualquier habilidad tuya que el juego resalte por un efecto."] = "Jede deiner Fähigkeiten, die das Spiel wegen eines Effekts hervorhebt.",
	["Cualquier instructor de pesca te la enseña. Luego compra una caña y unas lombrices: con eso empiezas."] = "Jeder Angellehrer bringt es dir bei. Kauf dann eine Angel und ein paar Würmer: Mehr brauchst du für den Anfang nicht.",
	["Cualquier profesión"] = "Beliebiger Beruf",
	["Cualquiera"] = "Beliebig",
	["Cuando al monstruo le quede poca vida, usa Ejecutar (Alfa te avisa)."] = "Wenn das Monster wenig Gesundheit hat, nutze Hinrichten (Alfa warnt dich).",
	["Cuando aprendas %s, también."] = "Sobald du %s lernst, auch diese.",
	["Cuando aprendas %s, te avisa al momento de usarlas."] = "Sobald du %s lernst, sagt es dir genau, wann du sie nutzen sollst.",
	["Cuando aprendes un rango nuevo, un aviso ofrece cambiarlo en tus barras."] = "Wenn du einen neuen Rang lernst, bietet dir ein Hinweis an, ihn in deinen Leisten zu tauschen.",
	["Cuando buscas algo en la subasta, Alfa guarda el precio más bajo que ves."] = "Wenn du im Auktionshaus etwas suchst, merkt sich Alfa den niedrigsten Preis, den du siehst.",
	["Cuando el Pozo de la Eternidad explotó, el gran continente antiguo se partió en pedazos. A eso le llaman la Gran División."] = "Als der Brunnen der Ewigkeit explodierte, zerbrach der große alte Kontinent in Stücke. Das nennt man die Große Teilung.",
	["Cuando el juego termina de cargar, Alfa revisa lo que elegiste aquí y lo vuelve a poner si algo lo cambió. Si después los cambias en el menú del juego, Alfa se queda con lo nuevo."] = "Wenn das Spiel fertig geladen hat, prüft Alfa, was du hier gewählt hast, und setzt es wieder, falls etwas es geändert hat. Änderst du es danach im Spielmenü, behält Alfa das Neue.",
	["Cuando entras a una posada o ciudad, y cuando tu XP descansada se acaba."] = "Wenn du ein Gasthaus oder eine Stadt betrittst und wenn dein Ruhebonus aufgebraucht ist.",
	["Cuando hay un festival, vale la pena darse una vuelta: casi siempre trae mascotas, ropa o comida que no salen el resto del año."] = "Wenn ein Fest ist, lohnt sich ein Abstecher: Fast immer gibt es Haustiere, Kleidung oder Essen, die es den Rest des Jahres nicht gibt.",
	["Cuando hay varias para elegir, toma la que más te sirve."] = "Gibt es mehrere zur Auswahl, nimmt es die, die dir am meisten nützt.",
	["Cuando huelo salchichas se me olvida todo. Bueno, menos tú."] = "Wenn ich Würstchen rieche, vergesse ich alles. Na ja, außer dich.",
	["Cuando la Legión volvió en la Tercera Guerra, Malfurion y Tyrande hicieron sonar el Cuerno de Cenarius para despertar a los druidas dormidos."] = "Als die Legion im Dritten Krieg zurückkehrte, bliesen Malfurion und Tyrande das Horn des Cenarius, um die schlafenden Druiden zu wecken.",
	["Cuando la meta de ahora de tu plan es un lugar, la flecha lo toma sin que hagas clic."] = "Ist das aktuelle Ziel deines Plans ein Ort, übernimmt der Pfeil es ohne Klick.",
	["Cuando le baja la vida aturde a todos y corre a su cofre a cambiar de arma: espérenlo, no lo persigan."] = "Wenn seine Gesundheit sinkt, betäubt er alle und rennt zu seiner Truhe, um die Waffe zu wechseln: Wartet auf ihn, verfolgt ihn nicht.",
	["Cuando lleves algo, Alfa te dice si conviene venderlo, subastarlo o transformarlo, y cuánto ganas."] = "Wenn du etwas trägst, sagt dir Alfa, ob du es beim Händler verkaufen, versteigern oder verarbeiten solltest, und wie viel du verdienst.",
	["Cuando los orcos se volvieron brujos, dejaron de oír a los elementos. Thrall les devolvió ese camino."] = "Als die Orcs zu Hexenmeistern wurden, hörten sie die Elemente nicht mehr. Thrall gab ihnen diesen Weg zurück.",
	["Cuando otro lobo con Alfa comparta su ubicación, aparece aquí y en tu mapa. Para que la manada crezca, invita a tus amigos: que instalen Alfa, acepten compartir y entren al Discord de La Jauría."] = "Wenn ein anderer Wolf mit Alfa seinen Standort teilt, erscheint er hier und auf deiner Karte. Damit das Rudel wächst, lade deine Freunde ein: Sie installieren Alfa, stimmen dem Teilen zu und treten dem Discord von La Jauría bei.",
	["Cuando se abre una misión de clase para ti, te ofrece su guía."] = "Wird eine Klassenquest für dich verfügbar, bietet es dir ihren Guide an.",
	["Cuando se escapa"] = "Wenn er entkommt",
	["Cuando se llenan"] = "Wenn sie voll werden",
	["Cuando te quedes sin maná, cambia a forma felina para terminar la pelea."] = "Wenn dir das Mana ausgeht, wechsle in die Katzengestalt, um den Kampf zu beenden.",
	["Cuando tengas pescado que sepas cocinar, aparece aquí."] = "Sobald du Fisch hast, den du kochen kannst, erscheint er hier.",
	["Cuando tu paso lo pide y hablas con su posadero. Nunca en otra posada."] = "Wenn dein Schritt es verlangt und du mit dessen Gastwirt sprichst. Nie in einem anderen Gasthaus.",
	["Cuando tus bolsas se llenan, Hoy te dice qué puedes vender y cuánto te dan."] = "Wenn deine Taschen voll werden, sagt dir Heute, was du verkaufen kannst und wie viel du dafür bekommst.",
	["Cuando tú o tu grupo peleen, aquí sale quién hace más daño."] = "Wenn du oder deine Gruppe kämpft, siehst du hier, wer den meisten Schaden macht.",
	["Cuando un elfo de la noche muere, su espíritu toma forma de fuego fatuo y corre más rápido hasta su cuerpo."] = "Wenn ein Nachtelf stirbt, nimmt sein Geist die Gestalt eines Irrwischs an und läuft schneller zu seinem Körper zurück.",
	["Cuando una pieza baja de este porcentaje."] = "Wenn ein Teil unter diesen Prozentsatz fällt.",
	["Cuando venzas a tu primer jefe, tu progreso aparecerá aquí."] = "Sobald du deinen ersten Boss besiegst, erscheint hier dein Fortschritt.",
	["Cuando ya casi se rompe."] = "Wenn es fast kaputt ist.",
	["Cuello"] = "Hals",
	["Cuenta:"] = "Account:",
	["Cuero"] = "Leder",
	["Cuerpo a cuerpo con tótems y golpes elementales: el chamán que mejor sube."] = "Nahkampf mit Totems und Elementarschlägen: der Schamane, der am besten levelt.",
	["Cuesta %s."] = "Kostet %s.",
	["Cuestan %s: te alcanza."] = "Sie kosten %s: Das reicht.",
	["Cuestan %s; llevas %s."] = "Sie kosten %s; du hast %s.",
	["Cuidado al nadar mar adentro: en aguas profundas te cansas y te puedes ahogar."] = "Vorsicht beim Schwimmen aufs offene Meer: In tiefem Wasser ermüdest du und kannst ertrinken.",
	["Cuidado con atraer varios a la vez: Fuego no tiene tanto control."] = "Vorsicht beim Ziehen mehrerer Gegner: Feuer hat nicht so viel Kontrolle.",
	["Cumpliste todas sus metas."] = "Du hast alle seine Ziele erfüllt.",
	["Cumpliste todas sus metas. Elige otro plan o arma uno nuevo."] = "Du hast alle seine Ziele erfüllt. Wähl einen anderen Plan oder erstelle einen neuen.",
	["Cura"] = "Heiler",
	["Cura a quien tenga el dolor de sombras; la pelea es corta."] = "Heile alle, die den Schattenschmerz haben; der Kampf ist kurz.",
	["Cura a sus ayudantes y a sí misma: interrúmpanla."] = "Sie heilt ihre Helfer und sich selbst: Unterbrecht sie.",
	["Cura a tu grupo con un clic."] = "Heil deine Gruppe mit einem Klick.",
	["Curación"] = "Heilung",
	["Curación con clic"] = "Heilen per Klick",
	["Curación: arrastra para mover"] = "Heilung: zum Verschieben ziehen",
	["Curandero"] = "Heiler",
	["Curar con un clic"] = "Mit einem Klick heilen",
	["Curas que van llegando"] = "Eingehende Heilung",
	["Cursor"] = "Cursor",
	["Cuándo"] = "Wann",
	["Cuándo vuelve sola detrás de tu personaje."] = "Wann sie von selbst hinter deinen Charakter zurückschwenkt.",
	["Cuánta lluvia, nieve y polvo se ve cuando hay mal tiempo."] = "Wie viel Regen, Schnee und Staub du bei schlechtem Wetter siehst.",
	["Cuántas capas de sombra se dibujan: con más capas, las sombras nítidas llegan más lejos."] = "Wie viele Schattenebenen gezeichnet werden: Mit mehr Ebenen reichen scharfe Schatten weiter.",
	["Cuántas casillas caben en cada fila."] = "Wie viele Plätze in jede Reihe passen.",
	["Cuántas casillas libres quedan cuando Alfa te avisa."] = "Wie viele freie Plätze übrig sind, wenn Alfa dich warnt.",
	["Cuántas habilidades después"] = "Wie viele Fähigkeiten danach",
	["Cuánto daño quita cada bloqueo; también sube el daño de Embate con escudo."] = "Wie viel Schaden jeder Block abfängt; erhöht auch den Schaden von Schildschlag.",
	["Cuánto dura un aviso en pantalla"] = "Wie lange ein Hinweis auf dem Bildschirm bleibt",
	["Cuánto falta para tu siguiente golpe automático, con cada mano. Ayuda a meter Embate o Golpe heroico sin perder golpes."] = "Wie lange es bis zu deinem nächsten automatischen Schlag dauert, für jede Hand. Hilft dir, Zerschmettern oder Heldenhafter Stoß einzubauen, ohne Schläge zu verlieren.",
	["Cuánto más brillan las luces que en una pantalla normal. El juego no pasa del máximo de tu monitor."] = "Wie viel heller Lichter werden als auf einem normalen Bildschirm. Das Spiel geht nie über das Maximum deines Monitors hinaus.",
	["Cuánto oro"] = "Wie viel Gold",
	["Cuánto pasto, flores y hierbas cubren el suelo."] = "Wie viel Gras, Blumen und Kräuter den Boden bedecken.",
	["Cuánto se ve el fondo de las ventanas de chat; en cero solo queda el borde."] = "Wie sichtbar der Hintergrund der Chatfenster ist; bei null bleibt nur der Rand.",
	["Cuántos"] = "Wie viele",
	["Cuántos consejos"] = "Wie viele Tipps",
	["Cuántos en el top"] = "Wie viele im Top",
	["Cuántos se anuncian"] = "Wie viele angesagt werden",
	["Cuántos tienes, en el cuadro de cada objeto"] = "Wie viele du hast, im Tooltip jedes Gegenstands",
	["Cuántos van en cada columna (o fila) antes de empezar otra. 5 es un grupo por columna."] = "Wie viele in jede Spalte (oder Reihe) kommen, bevor eine neue beginnt. 5 ist eine Gruppe pro Spalte.",
	["Cuéntame algo"] = "Erzähl mir etwas",
	["Cuéntame algo de aquí"] = "Erzähl mir etwas über diesen Ort",
	["Cuéntanos qué te parece en La Jauría."] = "Sag uns bei La Jauría, wie du es findest.",
	["Cálido"] = "Warm",
	["Cámara"] = "Kamera",
	["Cámbialo en el menú del juego: Opciones > %s > «%s». Alfa no lo cambia por ti: el juego lo lee en combate y fallaría."] = "Ändere es im Spielmenü: Optionen > %s > „%s“. Alfa ändert es nicht für dich: Das Spiel liest es im Kampf und würde dabei fehlschlagen.",
	["Cólera de las bestias: tu mascota pega mucho más un rato."] = "Zorn des Wildtiers: Dein Begleiter trifft eine Weile viel härter.",
	["Cómo cambiarlo"] = "So änderst du es",
	["Cómo conseguir cualquier objeto, misión o PNJ, y qué guía te lleva ahí."] = "Wie du jeden Gegenstand, jede Quest und jeden NPC bekommst und welcher Guide dich hinführt.",
	["Cómo conseguir cualquier objeto, montura, PNJ, misión o lugar."] = "Wie du an jeden Gegenstand, jedes Reittier, jeden NPC, jede Quest oder jeden Ort kommst.",
	["Cómo conseguirla"] = "So bekommst du es",
	["Cómo conseguirlo"] = "So bekommst du es",
	["Cómo decide Alfa"] = "Wie Alfa entscheidet",
	["Cómo encenderlo"] = "So schaltest du es ein",
	["Cómo hacer oro"] = "So verdienst du Gold",
	["Cómo juego"] = "Wie ich spiele",
	["Cómo se consigue"] = "So bekommst du es",
	["Cómo se ganan"] = "So verdienst du sie",
	["Cómo se mueve"] = "Wie sie sich bewegt",
	["Cómo se usa"] = "So geht's",
	["Cómo se ven las zonas sin descubrir"] = "Wie unentdeckte Gebiete aussehen",
	["Cómo subir"] = "So levelst du",
	["Cómo subirla"] = "So steigerst du ihn",
	["Cómo trabaja tu ruta"] = "So funktioniert deine Route",
	["Cómprala con un vendedor."] = "Kauf sie bei einem Händler.",
	["Cópialo con Ctrl+C. Luego abre «Hermandad y comunidades», elige %s, pulsa «Invitar a miembro» y pégalo con Ctrl+V."] = "Kopiere ihn mit Strg+C. Öffne dann „Gilde & Communitys“, wähle %s, klicke auf „Mitglied einladen“ und füge ihn mit Strg+V ein.",
	["DPS"] = "DPS",
	["DPS del arma"] = "Waffen-DPS",
	["Daga"] = "Dolch",
	["Dale de comer a tu mascota para que esté contenta y pegue más."] = "Füttere dein Tier, damit es zufrieden ist und härter zuschlägt.",
	["Dale de comer para que esté feliz: pega más fuerte."] = "Füttere es, damit es glücklich ist: Dann schlägt es härter zu.",
	["Dar a las barras el estilo de Alfa"] = "Den Leisten Alfas Stil geben",
	["Dar al chat el estilo de Alfa"] = "Dem Chat Alfas Stil geben",
	["Dar al minimapa el estilo de Alfa"] = "Der Minikarte Alfas Stil geben",
	["Darnassus está en las ramas de Teldrassil. La suma sacerdotisa Tyrande Susurravientos gobierna desde el Templo de la Luna."] = "Darnassus liegt in den Ästen von Teldrassil. Die Hohepriesterin Tyrande Wisperwind herrscht vom Tempel des Mondes aus.",
	["Dath'Remar Caminante del Sol guió a los altos elfos hasta Quel'Thalas. De su linaje viene el príncipe Kael'thas."] = "Dath'Remar Sonnenwanderer führte die Hochelfen nach Quel'Thalas. Aus seiner Linie stammt Prinz Kael'thas.",
	["Datos"] = "Daten",
	["Datos curiosos de Lya, escritos por Alfa."] = "Lyas kuriose Fakten, geschrieben von Alfa.",
	["Daño"] = "Schaden",
	["Daño a distancia"] = "Fernkampfschaden",
	["Daño con el tiempo: ponla al empezar la pelea."] = "Schaden über Zeit: Zu Kampfbeginn wirken.",
	["Daño de arcos, armas de fuego y ballestas."] = "Schaden von Bögen, Schusswaffen und Armbrüsten.",
	["Daño de fuego con el tiempo."] = "Feuerschaden über Zeit.",
	["Daño del arma"] = "Waffenschaden",
	["Daño directo de fuego y sombras: matas antes de que el monstruo llegue."] = "Direkter Feuer- und Schattenschaden: Du tötest, bevor das Monster ankommt.",
	["Daño directo de tus armas y habilidades."] = "Direkter Schaden deiner Waffen und Fähigkeiten.",
	["Daño en grupo de cinco: pegar fuerte sin robarle los monstruos al tanque."] = "Schaden in einer Fünfergruppe: hart zuschlagen, ohne dem Tank die Monster zu stehlen.",
	["Daño extra después de recibir críticos."] = "Extraschaden, nachdem du Krits erlitten hast.",
	["Daño extra después de recibir un golpe crítico."] = "Extraschaden, nachdem du einen kritischen Treffer erlitten hast.",
	["Daño periódico"] = "Regelmäßiger Schaden",
	["Daño por segundo"] = "Schaden pro Sekunde",
	["Daño sobre tus enemigos"] = "Schaden über deinen Gegnern",
	["De 1 a 300"] = "Von 1 bis 300",
	["De 1 a 300, dónde pescar cerca de ti, equipo, cebos, misiones y el concurso."] = "Von 1 bis 300, wo du in deiner Nähe angelst, Ausrüstung, Köder, Quests und der Wettbewerb.",
	["De Forever"] = "Forever",
	["De La Jauría"] = "Von La Jauría",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono. Lo que el juego hace brillar pasa al frente; las de área salen con varios enemigos peleando. Solo aparecen las que ya aprendiste."] = "Von oben nach unten: Die erste, die das Spiel dich einsetzen lässt, erscheint im Symbol. Was das Spiel leuchten lässt, rückt nach vorn; Flächenfähigkeiten erscheinen, wenn du gegen mehrere Gegner kämpfst. Es erscheinen nur die, die du schon erlernt hast.",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono; las de área, solo con 3 o más enemigos peleando."] = "Von oben nach unten: Die erste, die das Spiel dich nutzen lässt, erscheint im Symbol; Flächenfähigkeiten nur bei 3 oder mehr kämpfenden Gegnern.",
	["De clase"] = "Klasse",
	["De clase: %s"] = "Klasse: %s",
	["De este lugar Lya todavía no sabe datos curiosos. Elige una misión de la lista para leer su historia."] = "Über diesen Ort kennt Lya noch keine kuriosen Fakten. Wähl eine Quest aus der Liste, um ihre Geschichte zu lesen.",
	["De este lugar todavía no sé mucho. ¿Vemos tus historias?"] = "Über diesen Ort weiß ich noch nicht viel. Sehen wir uns deine Geschichten an?",
	["De fábrica el seguimiento muestra solo lo que estás haciendo; encendido, muestra el paso completo con sus notas."] = "Standardmäßig zeigt der Tracker nur, was du gerade tust; eingeschaltet zeigt er den ganzen Schritt mit seinen Notizen.",
	["De la base de datos incluida"] = "Aus der mitgelieferten Datenbank",
	["De la otra facción"] = "Andere Fraktion",
	["De los que se presumen"] = "Einer zum Angeben",
	["De misión"] = "Questgegenstände",
	["De nivel %.1f a %.1f, con unos %s de oro. Solo misiones que ya puedes tomar; lo que pide más nivel va después de un paso que lo espera."] = "Von Stufe %.1f auf %.1f, mit etwa %s Gold. Nur Quests, die du schon annehmen kannst; was eine höhere Stufe braucht, kommt nach einem Schritt, der darauf wartet.",
	["De todo %s, ¿qué rincón te gusta más?"] = "Welcher Winkel von %s gefällt dir am besten?",
	["De tu gente todavía no sé mucho. ¿Te cuento otra cosa?"] = "Über dein Volk weiß ich noch nicht viel. Soll ich dir etwas anderes erzählen?",
	["Debajo del ícono: útil mientras aprendes."] = "Unter dem Symbol: nützlich, solange du lernst.",
	["Dedo"] = "Finger",
	["Defensa"] = "Verteidigung",
	["Deja que el tanque golpee primero unos segundos antes de usar tus golpes fuertes."] = "Lass den Tank ein paar Sekunden zuerst zuschlagen, bevor du deine starken Schläge nutzt.",
	["Deja que la manada te vea en el mapa"] = "Lass das Rudel dich auf der Karte sehen",
	["Deja que tu mascota empiece la pelea y dispara cuando el monstruo la esté atacando."] = "Lass dein Tier den Kampf beginnen und schieß, wenn das Monster es angreift.",
	["Deja solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Lässt nur das Wesentliche: dich, deine Gruppe, deine Markierungen und den nächsten Schritt des Guides.",
	["Dejar"] = "Beenden",
	["Dejar de seguir"] = "Nicht mehr folgen",
	["Dejar de seguirlo"] = "Nicht mehr folgen",
	["Dejar el chat"] = "Chat behalten",
	["Dejar el minimapa"] = "Minikarte behalten",
	["Dejarlo como recomienda Alfa"] = "So einstellen, wie Alfa es empfiehlt",
	["Del Legado"] = "Aus dem Vermächtnis",
	["Del agua"] = "Aus dem Wasser",
	["Del color del estilo"] = "In der Farbe des Stils",
	["Del motor de Alfa: al subir de nivel te muestra qué aprender y cuánto cuesta."] = "Aus Alfas Kern: Beim Stufenaufstieg zeigt er dir, was du lernen kannst und was es kostet.",
	["Del motor de Alfa: con el entrenador más cercano en tu camino."] = "Aus Alfas Kern: mit dem nächsten Lehrer auf deinem Weg.",
	["Del preajuste"] = "Aus der Voreinstellung",
	["Demonología"] = "Dämonologie",
	["Demonología para subir"] = "Dämonologie zum Leveln",
	["Densidad de partículas"] = "Partikeldichte",
	["Dentro"] = "Drinnen",
	["Dentro de"] = "Enthalten in",
	["Dentro de %s (mazmorra)"] = "In %s (Dungeon)",
	["Dentro de la mazmorra"] = "Im Dungeon",
	["Dentro de mazmorras y ciudades no hay nodos. Sal al mundo y tu ruta se arma en un clic."] = "In Dungeons und Städten gibt es keine Vorkommen. Geh hinaus in die Welt, dann ist deine Route einen Klick entfernt.",
	["Dentro de una instancia el juego no deja compartir: sale solo cuando salgas."] = "In einer Instanz lässt das Spiel kein Teilen zu: Es wird von selbst gesendet, wenn du sie verlässt.",
	["Dentro de una instancia no se puede seguir a nadie."] = "In einer Instanz kannst du niemandem folgen.",
	["Depositar"] = "Einlagern",
	["Depositar rápido"] = "Schnell einlagern",
	["Depósito detenido: guardaste %d."] = "Einlagern gestoppt: %d eingelagert.",
	["Derecho"] = "Rechts",
	["Derrota a %s"] = "Besiege %s",
	["Derrotar al último jefe de todas las mazmorras de un rango de niveles da un punto del Legado por cada rango."] = "Den letzten Boss aller Dungeons eines Stufenbereichs zu besiegen gibt einen Vermächtnispunkt pro Bereich.",
	["Desarmar más seguido: quitas el arma a los enemigos que pegan fuerte."] = "Öfter entwaffnen: Du nimmst hart zuschlagenden Gegnern die Waffe ab.",
	["Desbloquear %s"] = "%s freischalten",
	["Desbloquear posición"] = "Position entsperren",
	["Descansa en una posada o una ciudad para juntar más."] = "Ruh dich in einem Gasthaus oder einer Stadt aus, um mehr Ruhebonus zu sammeln.",
	["Descansando%s%d%% de un nivel"] = "Du erholst dich%s%d%% einer Stufe",
	["Descansando: %d %%"] = "Erholung: %d %%",
	["Descanso"] = "Erholung",
	["Descanso %d %%"] = "Ruhebonus %d %%",
	["Desconectado"] = "Offline",
	["Descontenta"] = "Unglücklich",
	["Descubriste a %s"] = "Du hast %s entdeckt",
	["Descubriste a %s (%s)."] = "Du hast %s entdeckt (%s).",
	["Desde Auberdine sale un barco al muelle de Rut'theran, al pie de Teldrassil."] = "Von Auberdine fährt ein Schiff zum Steg von Rut'theran am Fuß von Teldrassil.",
	["Desde cero"] = "Von Grund auf",
	["Desde cuántas habilidades"] = "Ab wie vielen Fähigkeiten",
	["Desde el nivel 10"] = "Ab Stufe 10",
	["Desde el nivel 20"] = "Ab Stufe 20",
	["Desde nivel %d"] = "Ab Stufe %d",
	["Desde siempre"] = "Insgesamt",
	["Desde tu última visita también hubo cambios en %s: los ves en «Ver todo lo nuevo»."] = "Seit deinem letzten Besuch gab es auch Änderungen in %s: Du findest sie unter „Alle Neuerungen ansehen“.",
	["Desencanta los objetos verdes y azules que no uses para sacar polvos, esencias y fragmentos."] = "Entzaubere grüne und blaue Gegenstände, die du nicht brauchst, um Staub, Essenzen und Splitter zu bekommen.",
	["Desencantar ≈ %s"] = "Entzaubern ≈ %s",
	["Desencantar: ≈ %s por objeto%s. Pide Encantamiento %d."] = "Entzaubern: ≈ %s pro Gegenstand%s. Benötigt Verzauberkunst %d.",
	["Deseo de muerte: mucho más daño un rato; úsalo en peleas largas."] = "Todeswunsch: eine Weile viel mehr Schaden; nutze ihn in langen Kämpfen.",
	["Desgarrar hace más daño mientras el monstruo sangra; lo necesitas para Heridas profundas."] = "Verwunden macht mehr Schaden, solange das Monster blutet; du brauchst es für Tiefe Wunden.",
	["Desgarrar hace más daño; lo necesitas para Heridas profundas."] = "Verwunden macht mehr Schaden; du brauchst es für Tiefe Wunden.",
	["Desgarrar te prepara más Abrumar: más golpes que no se pueden esquivar."] = "Verwunden bereitet mehr Überwältigen vor: mehr Schläge, denen man nicht ausweichen kann.",
	["Deshacer"] = "Rückgängig",
	["Deshacer preajuste"] = "Voreinstellung rückgängig",
	["Desmarca las metas hechas de este personaje (las que ya se cumplen se vuelven a marcar solas)."] = "Hebt die Markierung der erledigten Ziele dieses Charakters auf (bereits erfüllte werden von selbst wieder markiert).",
	["Desmarcar"] = "Markierung aufheben",
	["Desollar es de las formas más fáciles de hacer oro mientras subes de nivel."] = "Kürschnerei ist einer der leichtesten Wege, beim Leveln Gold zu verdienen.",
	["Desollar y Peletería van de la mano: tú consigues el cuero y tú lo trabajas."] = "Kürschnerei und Lederverarbeitung gehen Hand in Hand: Du besorgst das Leder und du verarbeitest es.",
	["Despojar más rápido"] = "Schneller plündern",
	["Después"] = "Später",
	["Después de"] = "Nach",
	["Después de cada golpe, regresa a tu lugar rápido."] = "Kehr nach jedem Schlag schnell an deinen Platz zurück.",
	["Después de estos siguen %d más."] = "Danach folgen noch %d weitere.",
	["Después de otra"] = "Nach einer anderen",
	["Después de tu segunda pelea, aquí ves la de antes."] = "Nach deinem zweiten Kampf siehst du hier den vorherigen.",
	["Después de un crítico atacas más rápido: más golpes, más ira."] = "Nach einem Krit greifst du schneller an: mehr Schläge, mehr Wut.",
	["Después de él se encienden los braseros del altar y llegan oleadas de enemigos: prepárense antes."] = "Danach entzündet ihr die Kohlenbecken am Altar, und Wellen von Gegnern kommen: Bereitet euch vorher vor.",
	["Después del combate"] = "Nach dem Kampf",
	["Después del primer jefe, un prisionero de tu facción abre la puerta: háblale."] = "Nach dem ersten Boss öffnet ein Gefangener deiner Fraktion die Tür: Sprich mit ihm.",
	["Después sigue"] = "Danach folgt",
	["Después: %d %% del nivel %d"] = "Danach: %d %% von Stufe %d",
	["Después: nivel %d"] = "Danach: Stufe %d",
	["Destino"] = "Ziel",
	["Destrucción"] = "Zerstörung",
	["Destrucción para subir"] = "Zerstörung zum Leveln",
	["Desuellas lo que matas y lo conviertes en armaduras de cuero para ti; lo que sobra se vende."] = "Du häutest, was du tötest, und machst daraus Lederrüstung für dich; der Rest lässt sich verkaufen.",
	["Desuello"] = "Kürschnerei",
	["Desvanecer objetos lejanos"] = "Entfernte Objekte ausblenden",
	["Desvías golpes con tu arma."] = "Du lenkst Schläge mit deiner Waffe ab.",
	["Detalle al pasar el ratón"] = "Details beim Darüberfahren",
	["Detalle de la guía"] = "Guide-Details",
	["Detalle de los edificios"] = "Gebäudedetails",
	["Detalle de los objetos"] = "Objektdetails",
	["Detalle del agua"] = "Wasserdetails",
	["Detalle del terreno"] = "Geländedetails",
	["Detalle fino"] = "Feine Details",
	["Detener"] = "Stopp",
	["Detener (%d/%d)"] = "Stopp (%d/%d)",
	["Detrás de «%s» hay más de lo que parece. ¿Te la cuento?"] = "Hinter „%s“ steckt mehr, als man denkt. Soll ich sie dir erzählen?",
	["Devolver"] = "Zurücksetzen",
	["Devolver los avisos a su lugar"] = "Hinweise an ihren Platz zurücksetzen",
	["Devuelve cada ajuste que Alfa tocó al valor que tenía antes y deja de mantenerlos."] = "Setzt jede Einstellung, die Alfa angefasst hat, auf ihren vorherigen Wert zurück und hört auf, sie zu behalten.",
	["Devuelve los valores que tenías antes del último preajuste."] = "Holt die Werte zurück, die du vor der letzten Voreinstellung hattest.",
	["Diario"] = "Tagebuch",
	["Diario de mazmorras"] = "Dungeonkompendium",
	["Diario de pesca"] = "Angeltagebuch",
	["Dibuja el arte completo de cada zona recortado a su forma, con las texturas de detalle incluidas. Sin ellas el mapa sigue completo, solo más suave entre zona y zona."] = "Zeichnet die vollständige Grafik jedes Gebiets, auf seine Form zugeschnitten, mit den mitgelieferten Detailtexturen. Ohne sie ist die Karte trotzdem vollständig, nur weicher zwischen den Gebieten.",
	["Dibuja la ruta hasta tu objetivo: por dónde caminar, volar o navegar."] = "Zeichnet die Route zu deinem Ziel: wo du laufen, fliegen oder segeln musst.",
	["Dice en el chat qué misión perderías y te deja aceptarla a ti."] = "Sagt im Chat, welche Quest du verlieren würdest, und überlässt dir das Annehmen.",
	["Dicen que el Bosque del Ocaso se oscureció por estar tan cerca de Karazhan, y desde entonces vive en penumbra."] = "Man sagt, der Dämmerwald sei dunkel geworden, weil er so nah an Karazhan liegt, und seitdem lebt er im Zwielicht.",
	["Dicen que en Thelsamar venden morcilla. ¡Es casi una salchicha! Solo digo."] = "Man sagt, in Thelsamar gibt es Blutwurst. Das ist fast ein Würstchen! Ich sag ja nur.",
	["Diestro"] = "Geschickt",
	["Diez mil años atrás, Illidan creó en la cima de Hyjal un nuevo Pozo de la Eternidad, y sobre él se plantó Nordrassil."] = "Vor zehntausend Jahren erschuf Illidan auf dem Gipfel des Hyjal einen neuen Brunnen der Ewigkeit, und darüber wurde Nordrassil gepflanzt.",
	["Dinero de toda la cuenta"] = "Gold des ganzen Accounts",
	["Dinero de tus personajes"] = "Gold deiner Charaktere",
	["Disciplina"] = "Disziplin",
	["Disciplina para subir"] = "Disziplin zum Leveln",
	["Dispara desde lejos: alguien debe ir por él."] = "Er schießt aus der Ferne: Jemand muss zu ihm hin.",
	["Disparo apuntado: tu disparo más fuerte."] = "Gezielter Schuss: dein stärkster Schuss.",
	["Disparo arcano: instantáneo, úsalo cuando esté listo."] = "Arkaner Schuss: spontan, nutze ihn, sobald er bereit ist.",
	["Disponible a nivel %d"] = "Verfügbar ab Stufe %d",
	["Distancia"] = "Distanz",
	["Distancia a la que ciudades, torres y cuevas conservan su detalle."] = "Entfernung, bis zu der Städte, Türme und Höhlen ihre Details behalten.",
	["Distancia a la que el suelo conserva su forma completa."] = "Entfernung, bis zu der der Boden seine volle Form behält.",
	["Distancia de las placas"] = "Entfernung der Namensplaketten",
	["Distancia de visión"] = "Sichtweite",
	["Distancia del pasto"] = "Grasweite",
	["Distancia y velocidad"] = "Entfernung und Geschwindigkeit",
	["Doble clic derecho"] = "Doppel-Rechtsklick",
	["Doble clic derecho para lanzar"] = "Doppel-Rechtsklick zum Auswerfen",
	["Doble clic mientras pescas vuelve a lanzar"] = "Doppelklick beim Angeln wirft erneut aus",
	["Dolanaar es la aldea élfica en el camino a Darnassus; su posada huele a bosque."] = "Dolanaar ist das Elfendorf auf dem Weg nach Darnassus; sein Gasthaus riecht nach Wald.",
	["Domingo de concurso"] = "Wettbewerbssonntag",
	["Dominio de bestias"] = "Tierherrschaft",
	["Dominio de bestias para subir"] = "Tierherrschaft zum Leveln",
	["Donde antes estaba el Pozo de la Eternidad hoy gira el Maelstrom, un remolino eterno en medio del Gran Mar."] = "Wo einst der Brunnen der Ewigkeit lag, dreht sich heute der Mahlstrom, ein ewiger Strudel mitten im Großen Meer.",
	["Donde lo sacas: %s."] = "Wo du ihn fängst: %s.",
	["Donde puedes seguir en varias zonas, toma la recomendada sin preguntar."] = "Wo du in mehreren Zonen weitermachen könntest, nimmt es die empfohlene, ohne zu fragen.",
	["Dormir"] = "Schlafen",
	["Dos armas"] = "Zwei Waffen",
	["Dos armas y mucha ira. Furia pega más que Armas cuando tiene buen equipo, y Sed de sangre llega al nivel 40. Necesitas dos armas de una mano desde el nivel 20."] = "Zwei Waffen und viel Wut. Furor trifft mit guter Ausrüstung härter als Waffen, und Blutdurst kommt auf Stufe 40. Ab Stufe 20 brauchst du zwei Einhandwaffen.",
	["Dos clics y Alfa te lleva"] = "Zwei Klicks, und Alfa bringt dich hin",
	["Dos manos"] = "Zweihändig",
	["Dos monstruos a la vez dejan de ser un problema."] = "Zwei Monster auf einmal sind kein Problem mehr.",
	["Dos profesiones de recolección: oro constante sin perder tiempo, justo cuando más lo necesitas."] = "Zwei Sammelberufe: stetiges Gold ohne Zeitverlust, genau dann, wenn du es am meisten brauchst.",
	["Drek'Thar, el viejo chamán ciego del clan Lobo Gélido, le enseñó a Thrall a hablar con los espíritus. ¡Un sabio de los lobos!"] = "Drek'Thar, der alte blinde Schamane des Frostwolfklans, brachte Thrall bei, mit den Geistern zu sprechen. Ein Weiser der Wölfe!",
	["Drenar alma al rematar te da uno."] = "Seelendieb beim Todesstoß gibt dir einen.",
	["Druida"] = "Druide",
	["Druidas, guerreros y pícaros: si tu barra de forma o de actitud está vacía, Alfa te avisa y la llena con un clic."] = "Druiden, Krieger und Schurken: Ist deine Leiste für Gestalt oder Haltung leer, sagt Alfa dir Bescheid und füllt sie mit einem Klick.",
	["Duelos"] = "Duelle",
	["Duerme a un jugador y lanza sombras: interrúmpelo."] = "Er schläfert einen Spieler ein und wirkt Schattenzauber: Unterbrich ihn.",
	["Dun Algaz es el túnel enano que une Los Humedales con Loch Modan."] = "Dun Algaz ist der Zwergentunnel, der das Sumpfland mit Loch Modan verbindet.",
	["Duplicar"] = "Duplizieren",
	["Durabilidad"] = "Haltbarkeit",
	["Duración"] = "Dauer",
	["Durante la pelea despierta a guardianes de piedra: alguien debe tanquearlos o mátenlos rápido."] = "Im Kampf weckt er Steinwächter: Jemand muss sie tanken, oder tötet sie schnell.",
	["Durante siglos los druidas durmieron en el Sueño Esmeralda mientras las Centinelas cuidaban el bosque."] = "Jahrhundertelang schliefen die Druiden im Smaragdgrünen Traum, während die Schildwachen den Wald hüteten.",
	["Durotan y su clan Lobo Gélido se negaron a beber la sangre de Mannoroth. Gul'dan nunca se lo perdonó."] = "Durotan und sein Frostwolfklan weigerten sich, Mannoroths Blut zu trinken. Gul'dan hat ihm das nie verziehen.",
	["Durotar lleva el nombre de Durotan, el padre de Thrall y jefe del clan Lobo Gélido. Thrall honró su memoria al nombrar así la tierra de los orcos."] = "Durotar ist nach Durotan benannt, Thralls Vater und Häuptling des Frostwolfklans. Thrall ehrte sein Andenken, indem er das Land der Orcs nach ihm benannte.",
	["Dónde"] = "Wo",
	["Dónde aprender Pesca y sus rangos. Se llenan al abrir la guía de pesca."] = "Wo du Angeln lernst und seine Ränge. Werden ausgefüllt, wenn du den Angelguide öffnest.",
	["Dónde empieza el paisaje lejano simplificado."] = "Wo die vereinfachte ferne Landschaft beginnt.",
	["Dónde entregar"] = "Wo abgeben",
	["Dónde está"] = "Wo es ist",
	["Dónde está cada uno, lo que vende, lo que suelta y sus misiones."] = "Wo jeder ist, was er verkauft, was er fallen lässt und seine Quests.",
	["Dónde mandarlo"] = "Wohin damit",
	["Dónde sale"] = "Woher es kommt",
	["Dónde se entrega"] = "Wo man sie abgibt",
	["Dónde se ven"] = "Wo sie erscheinen",
	["Editar"] = "Bearbeiten",
	["Edwin VanCleef, el jefe Defias, era maestro cantero. Cuando la nobleza no pagó la reconstrucción de Ventormenta, juró venganza."] = "Edwin VanCleef, der Anführer der Defias, war Steinmetzmeister. Als der Adel den Wiederaufbau Sturmwinds nicht bezahlte, schwor er Rache.",
	["Efecto activo"] = "Aktiver Effekt",
	["Efecto del vacío"] = "Nethereffekt",
	["Efectos"] = "Effekte",
	["Efectos de pantalla del juego"] = "Bildschirmeffekte des Spiels",
	["Ej.: Comprar bolsas de 10 casillas"] = "z. B.: Taschen mit 10 Plätzen kaufen",
	["Ejecutar cuesta menos ira: rematas antes."] = "Hinrichten kostet weniger Wut: Du erledigst sie früher.",
	["Ejecutar más barato para rematar jefes."] = "Günstigeres Hinrichten, um Bosse zu erledigen.",
	["El Alba Argenta pelea contra la Plaga sin el fanatismo de los Escarlatas, y recibe por igual a la Alianza y a la Horda."] = "Die Argentumdämmerung kämpft gegen die Geißel ohne den Fanatismus der Scharlachroten und nimmt Allianz und Horde gleichermaßen auf.",
	["El Bastión Plumaluna, en una isla frente a la costa, es el puesto de las centinelas élficas."] = "Die Mondfederfeste auf einer Insel vor der Küste ist der Außenposten der elfischen Schildwachen.",
	["El Bosque del Ocaso y las Montañas Crestagrana también son tierras del reino, y piden ayuda porque los soldados no alcanzan."] = "Der Dämmerwald und das Rotkammgebirge gehören auch zum Königreich, und sie bitten um Hilfe, weil die Soldaten nicht reichen.",
	["El Campamento Mojache es el hogar de la Horda en Feralas."] = "Camp Mojache ist die Heimat der Horde in Feralas.",
	["El Castillo de Colmillo Oscuro fue de Arugal, un mago de Dalaran que convocó a los worgen para pelear contra la Plaga y terminó perdiendo la razón."] = "Burg Schattenfang gehörte Arugal, einem Magier aus Dalaran, der die Worgen gegen die Geißel beschwor und am Ende den Verstand verlor.",
	["El Claro de la Luna es un santuario de druidas; ahí se reúne el Círculo Cenarion."] = "Die Mondlichtung ist ein Heiligtum der Druiden; dort versammelt sich der Zirkel des Cenarius.",
	["El Codex no sabe de dónde sale; si ya la tienes, la ves en tu diario de monturas."] = "Der Codex weiß nicht, woher es stammt; wenn du es schon hast, siehst du es in deiner Reittiersammlung.",
	["El Cruce es un puesto de la Horda justo en medio de Los Baldíos, donde se juntan los caminos principales. De ahí su nombre."] = "Das Wegekreuz ist ein Außenposten der Horde mitten im Brachland, wo sich die Hauptstraßen treffen. Daher der Name.",
	["El Culto de los Malditos lo fundó Kel'Thuzad: les prometía a los campesinos de Lordaeron una vida eterna y más justa."] = "Kel'Thuzad gründete den Kult der Verdammten: Er versprach den Bauern Lordaerons ein ewiges, gerechteres Leben.",
	["El Discord de La Jauría"] = "Der Discord von La Jauría",
	["El Fuerte Cenarion es la base del Círculo Cenarion en Silithus, frente a los qiraji."] = "Burg Cenarius ist der Stützpunkt des Zirkels des Cenarius in Silithus, den Qiraji gegenüber.",
	["El Gran Manitas Gelbin Mekkatorque es el líder de los gnomos."] = "Hochtüftler Gelbin Mekkadrill ist der Anführer der Gnome.",
	["El Guardián Remulos, hijo de Cenarius, cuida el Claro de la Luna desde su santuario."] = "Bewahrer Remulos, Sohn des Cenarius, wacht von seinem Schrein aus über die Mondlichtung.",
	["El Horado Rajacieno y la Zahúrda Rajacieno son guaridas de los jabaespines, entre Los Baldíos y Las Mil Agujas."] = "Der Kral der Klingenhauer und die Hügel der Klingenhauer sind Höhlen der Stacheleber, zwischen dem Brachland und Tausend Nadeln.",
	["El Legado se abre con tu primer punto (casi siempre, al llegar a nivel 25), con la tecla Y o con su botón del menú."] = "Das Vermächtnis wird mit deinem ersten Punkt freigeschaltet (meist beim Erreichen von Stufe 25), mit der Taste Y oder seinem Button im Menü.",
	["El Loto negro crece solo en zonas de nivel muy alto, y es tan raro que vale una fortuna."] = "Schwarzer Lotus wächst nur in sehr hochstufigen Zonen und ist so selten, dass er ein Vermögen wert ist.",
	["El Loto negro es rarísimo: crece en Cuna del Invierno, las Estepas Ardientes, las Tierras de la Peste del Este y Silithus."] = "Schwarzer Lotus ist extrem selten: Er wächst in Winterquell, der Brennenden Steppe, den Östlichen Pestländern und Silithus.",
	["El Martillo Crepuscular tiene campamentos en Silithus, donde intenta invocar a los señores elementales."] = "Der Schattenhammer hat Lager in Silithus, wo er versucht, die Elementarfürsten zu beschwören.",
	["El Núcleo de Magma, en el fondo de la Montaña Roca Negra, es el hogar de Ragnaros, el Señor del Fuego."] = "Der Geschmolzene Kern tief im Schwarzfels ist die Heimat von Ragnaros, dem Feuerfürsten.",
	["El Paso de la Muerte no tiene ni un pueblo: solo ogros, bestias y la sombra de Karazhan."] = "Der Gebirgspass der Totenwinde hat keinen einzigen Ort: nur Oger, Bestien und den Schatten Karazhans.",
	["El Paso de la Muerte une el Bosque del Ocaso con el Pantano de las Penas."] = "Der Gebirgspass der Totenwinde verbindet den Dämmerwald mit den Sümpfen des Elends.",
	["El Portal Oscuro está apagado en el Clásico. En Burning Crusade vuelve a abrirse rumbo a Terrallende."] = "Das Dunkle Portal ist in Classic erloschen. In Burning Crusade öffnet es sich wieder in Richtung Scherbenwelt.",
	["El Portal Oscuro lo abrieron Medivh y Gul'dan juntos, cada uno desde su lado."] = "Das Dunkle Portal öffneten Medivh und Gul'dan gemeinsam, jeder von seiner Seite.",
	["El Puente Thandol, al norte, une Khaz Modan con Arathi; los Hierro Negro lo dejaron medio destruido."] = "Der Thandolübergang im Norden verbindet Khaz Modan mit Arathi; die Dunkeleisenzwerge haben ihn halb zerstört.",
	["El Puerto de Menethil lleva el apellido de la familia real de Lordaeron. De ahí salen barcos a Theramore y a Auberdine."] = "Der Hafen von Menethil trägt den Namen der Königsfamilie Lordaerons. Von dort fahren Schiffe nach Theramore und Auberdine.",
	["El Puesto Hachazo es el campamento de la Horda que tala Vallefresno."] = "Der Splitterholzposten ist das Lager der Horde, das das Eschental abholzt.",
	["El Refugio Roca del Sol es el hogar de los tauren en estas montañas."] = "Sonnenfels ist die Heimat der Tauren in diesen Bergen.",
	["El Refugio de la Zaga es el campamento de la Alianza en Arathi, entre ruinas, trols y ogros."] = "Die Zuflucht ist das Lager der Allianz in Arathi, zwischen Ruinen, Trollen und Ogern.",
	["El Refugio del Mariscal es el único campamento del cráter, y lo comparten todos."] = "Marschalls Zuflucht ist das einzige Lager im Krater, und alle teilen es sich.",
	["El SI:7 de Ventormenta y Ravenholdt son nombres que todo pícaro conoce."] = "SI:7 aus Sturmwind und Rabenholdt sind Namen, die jeder Schurke kennt.",
	["El Sepulcro es el puesto de los Renegados en el bosque; desde ahí vigilan a los worgen y a los magos de Dalaran."] = "Das Grabmal ist der Außenposten der Verlassenen im Wald; von dort behalten sie die Worgen und die Magier Dalarans im Auge.",
	["El Sindicato, los nobles caídos de Alterac, también asalta caminos y granjas por estas tierras."] = "Das Syndikat, die gefallenen Adligen Alteracs, überfällt hier ebenfalls Straßen und Höfe.",
	["El Sueño Esmeralda se está volviendo pesadilla: algo corrompe a los dragones verdes que lo cuidan."] = "Der Smaragdgrüne Traum wird zum Albtraum: Etwas verdirbt die grünen Drachen, die ihn hüten.",
	["El Tranvía Subterráneo une Forjaz con Ventormenta por debajo de la tierra. Lo construyeron los gnomos."] = "Die Tiefenbahn verbindet Eisenschmiede und Sturmwind unter der Erde. Die Gnome haben sie gebaut.",
	["El Trono Helado es la armadura de hielo donde quedó atrapado Ner'zhul, en lo alto de la Corona de Hielo."] = "Der Frostthron ist die Eisrüstung, in der Ner'zhul gefangen ist, hoch oben auf der Eiskrone.",
	["El Valle Calcinado, al sur de la sierra, quedó quemado y lleno de elementales de fuego."] = "Das Verkohlte Tal südlich des Gebirges ist verbrannt und voller Feuerelementare.",
	["El Vigía de Morgan es el puesto de la Alianza en las estepas, desde donde vigilan la Montaña Roca Negra."] = "Morgans Wacht ist der Außenposten der Allianz in der Steppe, von dem aus der Schwarzfels beobachtet wird.",
	["El aguante es tu mejor amigo: más vida para más Transfusión de vida."] = "Ausdauer ist dein bester Freund: mehr Gesundheit für mehr Aderlass.",
	["El almirante Daelin Valiente, padre de Jaina, cayó en Theramore tras atacar a la Horda. Su hija eligió la paz."] = "Admiral Daelin Prachtmeer, Jainas Vater, fiel in Theramore, nachdem er die Horde angegriffen hatte. Seine Tochter wählte den Frieden.",
	["El archidruida Fandral Corzocelada enseña en el Enclave Cenarion de Darnassus."] = "Erzdruide Fandral Hirschhaupt lehrt in der Enklave des Cenarius in Darnassus.",
	["El archidruida Fandral Corzocelada plantó Teldrassil con la esperanza de recuperar la inmortalidad que los elfos perdieron en el Monte Hyjal."] = "Erzdruide Fandral Hirschhaupt pflanzte Teldrassil in der Hoffnung, die Unsterblichkeit zurückzugewinnen, die die Elfen am Berg Hyjal verloren hatten.",
	["El archidruida Hamuul Tótem de Runa enseña a los druidas tauren, y fue de los primeros tauren aceptados en el Círculo Cenarion."] = "Erzdruide Hamuul Runentotem lehrt die Druiden der Tauren und war einer der ersten Tauren, die in den Zirkel des Cenarius aufgenommen wurden.",
	["El arma principal debe ser la más lenta y fuerte; la secundaria, la más rápida."] = "Die Waffe in der Waffenhand sollte die langsamste und stärkste sein, die in der Schildhand die schnellste.",
	["El aro y la cabecera del minimapa con tu estilo."] = "Ring und Kopfzeile der Minikarte in deinem Stil.",
	["El banco está lleno: compra otra casilla o pon una bolsa más grande en el banco."] = "Die Bank ist voll: Kauf einen weiteren Platz oder steck eine größere Tasche in die Bank.",
	["El barco goblin une Bahía del Botín con Trinquete, y lo pueden usar los dos bandos."] = "Das Goblinschiff verbindet Beutebucht mit Ratschet, und beide Fraktionen können es nutzen.",
	["El barón Osahendido manda en Stratholme como caballero de la muerte de la Plaga."] = "Baron Totenschwur herrscht über Stratholme als Todesritter der Geißel.",
	["El blanco de la interfaz y del cielo de día."] = "Das Weiß der Oberfläche und des Taghimmels.",
	["El bonus de tu arma al máximo."] = "Der Bonus deiner Waffe auf dem Maximum.",
	["El borde del minimapa, redondo o cuadrado («Minimapa cuadrado», arriba), y la barra con la zona y la hora toman el estilo que elijas, como la ventana del mapa. Al apagarlo vuelve el de siempre."] = "Der Rand der Minikarte, rund oder eckig („Eckige Minikarte“, oben), und die Leiste mit Zone und Uhrzeit übernehmen den gewählten Stil, wie das Kartenfenster. Ausgeschaltet kommt der gewohnte zurück.",
	["El borde toma el color del perjuicio (magia, maldición, enfermedad o veneno) cuando tú lo puedes quitar."] = "Der Rand nimmt die Farbe des Schwächungszaubers an (Magie, Fluch, Krankheit oder Gift), wenn du ihn entfernen kannst.",
	["El botón «Escanear con Alfa» bajo la ventana de la subasta."] = "Der Knopf „Mit Alfa scannen“ unter dem Auktionshausfenster.",
	["El brillo más alto que da tu monitor; viene en su caja o su ficha."] = "Die höchste Helligkeit deines Monitors; sie steht auf der Verpackung oder im Datenblatt.",
	["El brillo suave de luces y cielo en toda la pantalla."] = "Das sanfte Leuchten von Lichtern und Himmel auf dem ganzen Bildschirm.",
	["El brujo Zalazane les robó las Islas del Eco a los Lanza Negra con su vudú."] = "Der Hexendoktor Zalazane hat den Dunkelspeeren mit seinem Voodoo die Echoinseln geraubt.",
	["El buscador de Ajustes ya encuentra todo: también Pesca, Comercio, Ruta, Bolsas, Combate, Curación, Lya y Estilo y sonido."] = "Die Suche in den Einstellungen findet jetzt alles: auch Angeln, Handel, Route, Taschen, Kampf, Heilung, Lya sowie Stil und Klang.",
	["El buscador del motor está apagado (Ajustes > Descubrir): enciéndelo para que Alfa arme guías."] = "„Nachschlagen“ im Kern ist aus (Einstellungen > Entdecken): Schalte es ein, damit Alfa Guides erstellen kann.",
	["El buscador no está disponible."] = "Die Suche ist nicht verfügbar.",
	["El camino a Entrañas pasa por las ruinas de la Ciudad Capital de Lordaeron, donde Arthas mató a su padre."] = "Der Weg nach Unterstadt führt durch die Ruinen der Hauptstadt Lordaerons, wo Arthas seinen Vater tötete.",
	["El camino a la meta en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o montas, y los tramos que siguen más tenues."] = "Der Weg zum Ziel auf der Weltkarte und der Minikarte: eine Linie oder Punkte, wo du läufst, Linien, wo du fliegst, segelst oder reitest, und die folgenden Etappen blasser.",
	["El camino en el mapa y el minimapa"] = "Der Weg auf Karte und Minikarte",
	["El camino hasta el destino dibujado en el mapa."] = "Der Weg zum Ziel, auf die Karte gezeichnet.",
	["El camino más sencillo para subir: un arma grande, golpes que hacen sangrar y Golpe mortal al nivel 40. Aguantas bien y matas rápido."] = "Der einfachste Weg zum Leveln: eine große Waffe, Schläge, die bluten lassen, und Tödlicher Stoß auf Stufe 40. Du hältst viel aus und tötest schnell.",
	["El camino que baja de la sierra hacia Los Baldíos está lleno de arañas. ¡Brrr!"] = "Der Weg vom Gebirge hinunter ins Brachland ist voller Spinnen. Brrr!",
	["El chat"] = "Der Chat",
	["El chat usa la letra de Alfa (la de Ajustes > Apariencia). El tamaño se sigue cambiando en el menú de la pestaña."] = "Der Chat nutzt Alfas Schrift (die unter Einstellungen > Aussehen). Die Größe änderst du weiterhin im Menü des Tabs.",
	["El clan"] = "Der Clan",
	["El clan Lobo Gélido monta lobos de verdad. Por eso es mi clan favorito, no lo voy a negar."] = "Der Frostwolfklan reitet echte Wölfe. Deshalb ist er mein Lieblingsklan, das gebe ich zu.",
	["El clan Lobo Gélido vive exiliado en el valle de Alterac. Thrall, hijo de su antiguo jefe, los encontró ahí después de escapar de Durnholde."] = "Der Frostwolfklan lebt im Exil im Alteractal. Thrall, Sohn ihres früheren Häuptlings, fand sie dort nach seiner Flucht aus Durnholde.",
	["El clic derecho solo sigue alejando el mapa del juego, como siempre."] = "Ein einfacher Rechtsklick zoomt die Spielkarte weiterhin heraus, wie immer.",
	["El clic izquierdo solo selecciona"] = "Linksklick wählt nur als Ziel",
	["El clásico para pelear contra jugadores: Golpe mortal corta las curas del rival, Seccionar mejorado lo deja quieto y Cargar mejorado te da ira para empezar."] = "Der Klassiker für den Kampf gegen Spieler: Tödlicher Stoß kürzt die Heilung des Gegners, Verbesserte Kniesehne hält ihn fest und Verbesserter Sturmangriff gibt dir Wut zum Start.",
	["El color de mi clase"] = "Meine Klassenfarbe",
	["El comerciante no lo compra"] = "Händler kaufen es nicht",
	["El contenido va en una columna centrada y se acomoda solo si cambias la resolución o la escala."] = "Der Inhalt steht in einer zentrierten Spalte und passt sich von selbst an, wenn du Auflösung oder Skalierung änderst.",
	["El corcho quedó lejos · relanza con %s"] = "Der Schwimmer ist weit weg gelandet · wirf neu aus mit %s",
	["El corcho quedó lejos · vuelve a lanzar"] = "Der Schwimmer ist weit weg gelandet · wirf neu aus",
	["El cuadro del jugador al pasar el ratón. En combate no sale, para no estorbar."] = "Der Tooltip des Spielers beim Darüberfahren. Im Kampf erscheint er nicht, damit er nicht stört.",
	["El cártel Bonvapor controla Bahía del Botín, Trinquete, Gadgetzan y Vista Eterna. Por eso esos puertos reciben a todos."] = "Das Dampfdruckkartell kontrolliert Beutebucht, Ratschet, Gadgetzan und die Ewige Warte. Deshalb empfangen diese Häfen alle.",
	["El daño por segundo de tu arma a distancia."] = "Der Schaden pro Sekunde deiner Fernkampfwaffe.",
	["El daño por segundo del arma: para el guerrero, lo que más cuenta al subir."] = "Der Schaden pro Sekunde der Waffe: für den Krieger das Wichtigste beim Leveln.",
	["El de tu juego"] = "Die deines Spiels",
	["El demosaurio es el gran depredador del cráter: si oyes pasos que retumban, escóndete."] = "Der Teufelssaurier ist das größte Raubtier des Kraters: Wenn du dröhnende Schritte hörst, versteck dich.",
	["El destino de la flecha y sus zonas en el minimapa."] = "Das Ziel des Pfeils und seine Bereiche auf der Minikarte.",
	["El destino de la flecha, su camino y las otras metas del paso, en el mapa."] = "Das Ziel des Pfeils, der Weg dorthin und die anderen Ziele des Schritts, auf der Karte.",
	["El diario de mazmorras del motor está apagado (Ajustes > Descubrir > Mazmorras)."] = "Das Dungeonkompendium des Kerns ist aus (Einstellungen > Entdecken > Dungeons).",
	["El diario de mazmorras está apagado"] = "Das Dungeonkompendium ist aus",
	["El dragón azul Azuregos ronda Azshara, cuidando la magia antigua que quedó en sus ruinas."] = "Der blaue Drache Azuregos streift durch Azshara und hütet die alte Magie, die in den Ruinen zurückblieb.",
	["El druida hace de todo: puedes tanquear, curar o pegar según lo que pida el grupo."] = "Der Druide kann alles: Du kannst tanken, heilen oder Schaden machen, je nachdem, was die Gruppe braucht.",
	["El emperador Dagran Thaurissan gobierna la Ciudad de Hierro Negro, en las Profundidades de Roca Negra."] = "Imperator Dagran Thaurissan herrscht über die Stadt der Dunkeleisenzwerge in den Schwarzfelstiefen.",
	["El enemigo esquivó: Abrumar no se puede esquivar y pega fuerte."] = "Der Gegner ist ausgewichen: Überwältigen kann man nicht ausweichen, und es trifft hart.",
	["El enemigo esquivó: este golpe cuerpo a cuerpo está listo."] = "Der Gegner ist ausgewichen: Dieser Nahkampfschlag ist bereit.",
	["El enemigo esquivó: este golpe está listo."] = "Der Gegner ist ausgewichen: Dieser Schlag ist bereit.",
	["El enemigo está encima: golpéalo cuerpo a cuerpo."] = "Der Gegner ist direkt bei dir: Schlag ihn im Nahkampf.",
	["El enemigo está lanzando un hechizo: Choque de tierra lo corta."] = "Der Gegner wirkt einen Zauber: Erdschock unterbricht ihn.",
	["El enemigo está lanzando un hechizo: aturdirlo lo corta."] = "Der Gegner wirkt einen Zauber: Ein Betäuben unterbricht ihn.",
	["El enemigo está lanzando un hechizo: córtalo con tu escudo."] = "Der Gegner wirkt einen Zauber: Unterbrich ihn mit deinem Schild.",
	["El enemigo está lanzando un hechizo: córtalo."] = "Der Gegner wirkt einen Zauber: Unterbrich ihn.",
	["El enemigo está lanzando un hechizo: el golpe lo corta."] = "Der Gegner wirkt einen Zauber: Der Schlag unterbricht ihn.",
	["El enemigo está por caer: drénale el alma y gana un fragmento."] = "Der Gegner fällt gleich: Entzieh ihm die Seele und erhalte einen Splitter.",
	["El enlace del Discord ya está elegido: cópialo con Ctrl+C y pégalo en tu navegador."] = "Der Discord-Link ist markiert: Kopiere ihn mit Strg+C und füge ihn in deinen Browser ein.",
	["El entrenador de oficio más cercano"] = "Der nächste Berufslehrer",
	["El espíritu te devuelve maná rápido: descansas muy poco."] = "Willenskraft gibt dir Mana schnell zurück: Du musst kaum rasten.",
	["El estilo del mapa (terreno como el minimapa, o el arte clásico) y las opciones de Mundo."] = "Der Kartenstil (Gelände wie auf der Minikarte oder die klassische Grafik) und die Optionen von Welt.",
	["El estilo que elegiste también puede vestir el chat, el minimapa, las barras de abajo y el mapa. Se apaga cuando quieras y todo vuelve a como estaba."] = "Der gewählte Stil kann auch Chat, Minikarte, die unteren Leisten und die Karte einkleiden. Schalte ihn aus, wann du willst, und alles ist wie vorher.",
	["El final"] = "Das Ende",
	["El final de cada misión"] = "Das Ende jeder Quest",
	["El final lo verás al entregarla."] = "Das Ende siehst du, wenn du sie abgibst.",
	["El fondo se ve deformado a través del agua."] = "Der Grund wirkt durch das Wasser verzerrt.",
	["El fuego pega a todos los de cerca: mantén la vida alta de quienes pelean cuerpo a cuerpo."] = "Das Feuer trifft alle in der Nähe: Halte die Gesundheit der Nahkämpfer hoch.",
	["El general Drakkisath guarda la entrada a la Guarida Alanegra, en lo alto de la Cumbre de Roca Negra."] = "General Drakkisath bewacht den Zugang zum Pechschwingenhort hoch oben in der Schwarzfelsspitze.",
	["El gran cruzado de la Cruzada Escarlata, Saidan Dathrohan, es en realidad el demonio Balnazzar. Lo encuentras en Stratholme."] = "Der Großkreuzzügler des Scharlachroten Kreuzzugs, Saidan Dathrohan, ist in Wahrheit der Dämon Balnazzar. Du findest ihn in Stratholme.",
	["El guerrero que más daño hace en mazmorras. Con un tanque delante, tus dos armas no paran, y Ejecutar mejorado remata a los jefes."] = "Der Krieger mit dem meisten Schaden in Dungeons. Mit einem Tank vorne stehen deine zwei Waffen nie still, und Verbessertes Hinrichten erledigt die Bosse.",
	["El hacha de Grom Grito Infernal tiene nombre propio, y dicen que aúlla cuando corta el aire. ¡Aullar es cosa seria!"] = "Die Axt von Grom Höllschrei hat einen eigenen Namen, und man sagt, sie heult, wenn sie durch die Luft schneidet. Heulen ist eine ernste Sache!",
	["El hierro negro solo se funde en la Forja Negra de las Profundidades de Roca Negra."] = "Dunkeleisen lässt sich nur an der Schwarzen Schmiede in den Schwarzfelstiefen schmelzen.",
	["El hijo de Cairne, Baine, cuida el poblado Pezuña de Sangre en Mulgore."] = "Cairnes Sohn Baine sorgt für das Dorf der Bluthufe in Mulgore.",
	["El idioma, el estilo, lo que Alfa hace sola por ti y La Jauría, con «Cambiar» en cada cosa. También con /alfa bienvenida."] = "Die Sprache, der Stil, was Alfa selbst für dich erledigt und La Jauría, mit „Ändern“ bei jedem Punkt. Auch mit /alfa bienvenida.",
	["El izquierdo selecciona y el derecho abre el menú."] = "Links visiert an und rechts öffnet das Menü.",
	["El izquierdo selecciona y el derecho abre el menú. Tus buffs para otros se suman aquí al aprenderlos."] = "Links visiert an und rechts öffnet das Menü. Deine Buffs für andere kommen hier dazu, sobald du sie lernst.",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "Links visiert an und rechts öffnet das Menü. Den Rest wählst du.",
	["El izquierdo selecciona y el derecho abre el menú: lo básico, porque tu clase no lanza hechizos sobre sus compañeros."] = "Links visiert an und rechts öffnet das Menü: das Nötigste, weil deine Klasse keine Zauber auf Verbündete wirkt.",
	["El juego elige entre estas según la situación; el ícono te muestra cuál conviene ahora."] = "Das Spiel wählt je nach Lage zwischen diesen; das Symbol zeigt dir, welche jetzt am besten ist.",
	["El juego la hizo brillar: es buen momento para usarla."] = "Das Spiel hat sie aufleuchten lassen: ein guter Moment, sie zu nutzen.",
	["El juego manda la imagen en HDR."] = "Das Spiel sendet das Bild in HDR.",
	["El juego no aceptó el lote."] = "Das Spiel hat den Durchgang nicht angenommen.",
	["El juego no aceptó esa tecla."] = "Das Spiel hat diese Taste nicht angenommen.",
	["El juego no aceptó la prueba."] = "Das Spiel hat den Test nicht angenommen.",
	["El juego no da tu posición aquí (en una instancia, por ejemplo)."] = "Das Spiel gibt deine Position hier nicht preis (zum Beispiel in einer Instanz).",
	["El juego no deja cambiar talentos ahora mismo"] = "Das Spiel erlaubt gerade keine Talentänderung",
	["El juego no deja cocinar desde aquí."] = "Das Spiel lässt von hier aus nicht kochen.",
	["El juego no deja enviar mensajes en este momento (un encuentro o una partida). Tu rastro vuelve a salir solo cuando termine."] = "Das Spiel erlaubt gerade keine Nachrichten (eine Begegnung oder ein Match). Deine Spur wird danach wieder von selbst gesendet.",
	["El juego no deja que las cuentas de prueba envíen mensajes de addon ni usen canales propios. Tu grupo sí se ve."] = "Das Spiel lässt Testaccounts keine Addon-Nachrichten senden und keine eigenen Kanäle nutzen. Deine Gruppe siehst du trotzdem.",
	["El juego no dejó cambiar las demás."] = "Das Spiel hat das Ändern der übrigen nicht erlaubt.",
	["El juego no dejó compartir el marcador ahora. Prueba en un momento."] = "Das Spiel hat das Teilen der Markierung gerade nicht erlaubt. Versuch es gleich noch mal.",
	["El juego no dejó comprar ese rango."] = "Das Spiel hat den Kauf dieses Rangs nicht erlaubt.",
	["El juego no dejó entrar al canal oculto de Alfa y, sin hermandad, no hay otro camino para compartir. Alfa lo vuelve a intentar sola en unos minutos. Tu grupo sí se ve."] = "Das Spiel hat uns nicht in Alfas versteckten Kanal gelassen, und ohne Gilde gibt es keinen anderen Weg zu teilen. Alfa versucht es in ein paar Minuten von selbst erneut. Deine Gruppe siehst du trotzdem.",
	["El juego no dice si la tienes"] = "Das Spiel sagt nicht, ob du es hast",
	["El juego no dio tus puntos todavía: se ven desde que ganas el primero."] = "Das Spiel hat deine Punkte noch nicht geliefert: Sie erscheinen, sobald du den ersten verdienst.",
	["El juego no la ofrece ahora mismo."] = "Das Spiel bietet sie gerade nicht an.",
	["El juego no lo dice ahora."] = "Das Spiel verrät es gerade nicht.",
	["El juego no permite usar el medidor ahora."] = "Das Spiel erlaubt den Schadensmesser gerade nicht.",
	["El juego no trae la ayuda de Blizzard, así que Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus efectos y lo que el juego te deja usar. Con 3 o más enemigos cambia a las de área. Tú decides qué presionar."] = "Das Spiel hat keinen Kampfassistenten von Blizzard, also schlägt Alfa mit seiner eigenen Priorität für %s vor und liest dabei nur deinen Charakter: deine Ressource, deine Effekte und was das Spiel dich nutzen lässt. Bei 3 oder mehr Gegnern wechselt es zu Flächenfähigkeiten. Du entscheidest, was du drückst.",
	["El juego oculta los números exactos mientras peleas: la barra y la cifra se ven, el detalle al salir de combate."] = "Das Spiel verbirgt die genauen Zahlen, während du kämpfst: Balken und Wert siehst du, die Details nach dem Kampf.",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "Das Spiel hat die Bestätigung der Änderungen abgelehnt. Sie wurden rückgängig gemacht, damit dein Baum bleibt, wie er war.",
	["El juego solo deja cambiarla fuera de combate."] = "Das Spiel lässt sie nur außerhalb des Kampfes ändern.",
	["El juego todavía no carga tu árbol"] = "Das Spiel hat deinen Baum noch nicht geladen",
	["El juego todavía no carga tu árbol."] = "Das Spiel hat deinen Baum noch nicht geladen.",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "Das Spiel hat deine Talente noch nicht geladen. Warte ein paar Sekunden oder öffne einmal das Talentfenster (Taste N).",
	["El juego todavía no dio la lista de retos: ábrelo con la tecla Y."] = "Das Spiel hat die Liste der Herausforderungen noch nicht geliefert: Öffne es mit der Taste Y.",
	["El juego todavía no la abre: se abre con tu primer punto del Legado (casi siempre, al llegar a nivel 25)."] = "Das Spiel schaltet es noch nicht frei: Es öffnet sich mit deinem ersten Vermächtnispunkt (fast immer beim Erreichen von Stufe 25).",
	["El juego todavía no tiene los datos de algunos objetos. En un momento aparecen."] = "Das Spiel hat die Daten einiger Gegenstände noch nicht. Gleich erscheinen sie.",
	["El juego todavía oculta los números o los nombres (pasa en combate y dentro de mazmorras). Inténtalo al salir."] = "Das Spiel verbirgt die Zahlen oder Namen noch (das passiert im Kampf und in Dungeons). Versuch es danach noch mal.",
	["El lago Lordamere separa el Bosque de Argénteos de las Laderas de Trabalomas y de las Montañas de Alterac."] = "Der Lordameresee trennt den Silberwald vom Vorgebirge des Hügellands und vom Alteracgebirge.",
	["El lago de Loch Modan existe gracias a una enorme presa enana. Si se rompiera, el agua arrasaría las tierras de abajo."] = "Der See von Loch Modan existiert dank eines riesigen Zwergendamms. Bräche er, würde das Wasser die Lande darunter fortreißen.",
	["El lago del Claro de la Luna se llama Elune'ara, en honor a la diosa de la luna."] = "Der See der Mondlichtung heißt Elune'ara, zu Ehren der Mondgöttin.",
	["El lago helado de Kel'Theril guarda ruinas de los Altonato."] = "Der zugefrorene See von Kel'Theril birgt Ruinen der Hochgeborenen.",
	["El lobo de la intro aúlla de pie sobre la peña, con un aullido largo que otro lobo contesta; y al entrar, Lya llega corriendo a decirte que te extrañó."] = "Der Wolf im Intro heult jetzt stehend auf dem Felsen, ein langes Heulen, das ein anderer Wolf beantwortet; und wenn du ins Spiel kommst, rennt Lya herbei und sagt dir, dass sie dich vermisst hat.",
	["El lobo te recibe al entrar"] = "Der Wolf begrüßt dich beim Einloggen",
	["El lobo te recibe cada vez que entras al juego, redibujado: cabeza, orejas y hocico de lobo de verdad."] = "Der Wolf begrüßt dich bei jedem Einloggen, neu gezeichnet: Kopf, Ohren und Schnauze eines echten Wolfs.",
	["El maestro de vuelo, la posada, reparar, el banco y más, con la flecha."] = "Flugmeister, Gasthaus, Reparatur, Bank und mehr, mit dem Pfeil.",
	["El maestro de vuelo, la posada, reparar, el banco y más: el más cercano, con la flecha y la ruta."] = "Flugmeister, Gasthaus, Reparatur, Bank und mehr: der nächstgelegene, mit Pfeil und Route.",
	["El maestro de vuelo, la posada, reparar, el banco... el más cercano (/alfa cerca ayuda)."] = "Flugmeister, Gasthaus, Reparatur, Bank... der nächstgelegene (/alfa cerca ayuda).",
	["El mago Rhonin y el dragón Korialstrasz ayudaron a liberar a Alexstrasza en Grim Batol, y ahí quedó destruida el Alma de Demonio."] = "Der Magier Rhonin und der Drache Korialstrasz halfen, Alexstrasza in Grim Batol zu befreien, und dort wurde die Dämonenseele zerstört.",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "Der Magier mit dem meisten Schaden: Feuerzauber und Krits, die brennen.",
	["El mapa a tu gusto"] = "Die Karte nach deinem Geschmack",
	["El mapa abre sin errores con M y se arrastra suave, aunque empieces encima de un ícono."] = "Die Karte öffnet sich mit M ohne Fehler und lässt sich sanft ziehen, auch wenn du auf einem Symbol beginnst.",
	["El mapa de Alfa"] = "Alfas Karte",
	["El mapa de Alfa muestra el terreno real, con puntos de vuelo, mazmorras, barcos, zepelines y portales."] = "Alfas Karte zeigt das echte Gelände, mit Flugpunkten, Dungeons, Schiffen, Zeppelinen und Portalen.",
	["El mapa de Alfa, el del juego y el minimapa. Si algo te estorba, apágalo aquí; los otros módulos de Alfa agregan sus capas a esta misma lista."] = "Alfas Karte, die des Spiels und die Minikarte. Wenn dich etwas stört, schalte es hier aus; die anderen Module von Alfa fügen ihre Ebenen zu derselben Liste hinzu.",
	["El mapa del mundo entero con zoom, tus marcadores y un solo control para todo lo que se pinta."] = "Die ganze Welt auf einer Karte mit Zoom, deinen Markierungen und einer einzigen Steuerung für alles, was darauf gezeichnet wird.",
	["El mapa no se abre en combate."] = "Die Karte öffnet sich nicht im Kampf.",
	["El mapa se ve más limpio: sin líneas finas entre sus pedazos ni halos oscuros en las orillas de las zonas."] = "Die Karte sieht sauberer aus: keine feinen Linien zwischen ihren Teilen und keine dunklen Ränder an den Kanten der Zonen.",
	["El mar paga"] = "Das Meer zahlt sich aus",
	["El marco de las barras de experiencia y reputación; el relleno conserva sus colores."] = "Der Rahmen der Erfahrungs- und Rufleiste; die Füllung behält ihre Farben.",
	["El marco del menú del juego y de las bolsas, abajo a la derecha."] = "Der Rahmen von Spielmenü und Taschen, unten rechts.",
	["El mariscal Dughan cuida Villadorada y siempre anda buscando quien le eche la mano con los problemas de Elwynn."] = "Marschall Dughan wacht über Goldhain und sucht immer jemanden, der ihm bei den Problemen in Elwynn hilft.",
	["El medallón bajo cada marca del mapa y del minimapa: el de Alfa o solo el símbolo, sin medallón."] = "Das Medaillon unter jeder Markierung auf Karte und Minikarte: das von Alfa oder nur das Symbol, ohne Medaillon.",
	["El medidor de daño aguanta en combate y la ayuda de rotación ya no te pide interrumpir lo que no se puede."] = "Der Schadensmesser hält im Kampf durch, und die Rotationshilfe fordert dich nicht mehr auf, zu unterbrechen, was sich nicht unterbrechen lässt.",
	["El medidor no está disponible"] = "Der Schadensmesser ist nicht verfügbar",
	["El mejor que tengas"] = "Das Beste, was du hast",
	["El mekigeniero Termochufe, el traidor de Gnomeregan, sigue escondido dentro de la ciudad: es su último jefe."] = "Robogenieur Thermadraht, der Verräter von Gnomeregan, versteckt sich noch in der Stadt: Er ist ihr letzter Boss.",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "Das Lupenmenü der Spielkarte enthält auch alle Ebenen von Alfa.",
	["El mineral se funde en barras en cualquier forja."] = "Erz wird an jeder Schmiede zu Barren geschmolzen.",
	["El minimapa"] = "Die Minikarte",
	["El minimapa de Recolección descansa cuando no tiene nada que mostrar."] = "Die Minikarte von Sammeln ruht, wenn sie nichts zu zeigen hat.",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "Die Minikarte wird von rund zu eckig, mit dünnem Rand. Nicht empfohlen zusammen mit drehender Minikarte.",
	["El mismo arreglo llegó a los asistentes de Ruta y de Curación."] = "Dieselbe Korrektur hat auch die Assistenten von Route und Heilung erreicht.",
	["El mitril abunda en las Tierras Inhóspitas, las Tierras del Interior y Tanaris."] = "Mithril gibt es reichlich im Ödland, im Hinterland und in Tanaris.",
	["El modelo no lleva nada aquí."] = "Das Modell trägt hier nichts.",
	["El modo pesca se abre al salir de combate."] = "Der Angelmodus öffnet sich, sobald du den Kampf verlässt.",
	["El modo prueba se usa fuera de combate."] = "Der Testmodus geht nur außerhalb des Kampfes.",
	["El motor no aceptó la guía."] = "Der Kern hat den Guide nicht angenommen.",
	["El motor no puede armar guías ahora."] = "Der Kern kann gerade keine Guides erstellen.",
	["El mundo entero en un mapa"] = "Die ganze Welt auf einer Karte",
	["El mundo pierde el color mientras eres espíritu."] = "Die Welt verliert ihre Farbe, solange du ein Geist bist.",
	["El más cercano cuando le toque, por tiempo de camino."] = "Der nächstgelegene, wenn er dran ist, nach Reisezeit.",
	["El más cercano, por tiempo de camino"] = "Der nächstgelegene, nach Reisezeit",
	["El más cercano: %s"] = "Der nächstgelegene: %s",
	["El módulo Curación no está cargado."] = "Das Modul Heilung ist nicht geladen.",
	["El nombre de cada zona sobre el mapa de Alfa."] = "Der Name jedes Gebiets auf Alfas Karte.",
	["El número abajo a la izquierda de cada pieza de equipo."] = "Die Zahl unten links an jedem Ausrüstungsteil.",
	["El número es el orden en que se toma. Pasa el ratón por un talento para ver qué hace."] = "Die Zahl ist die Reihenfolge, in der es genommen wird. Fahr mit der Maus über ein Talent, um zu sehen, was es tut.",
	["El número que cuenta hacia atrás. Apagado, solo la barra."] = "Die Zahl, die herunterzählt. Aus: nur die Leiste.",
	["El objeto"] = "Der Gegenstand",
	["El objeto que usa el paso actual, o el objeto de misión que junta, brilla en tus bolsas. Un objeto que necesita un paso más adelante lleva un candado, para que no lo vendas."] = "Der Gegenstand, den der aktuelle Schritt benutzt, oder der Questgegenstand, den er sammelt, leuchtet in deinen Taschen. Ein Gegenstand, den ein späterer Schritt braucht, bekommt ein Schloss, damit du ihn nicht verkaufst.",
	["El orden importa más que los números: busca piezas con las primeras de la lista."] = "Die Reihenfolge zählt mehr als die Zahlen: Such Teile mit den ersten Werten der Liste.",
	["El paisaje lejano deja de perderse en la niebla espesa."] = "Die ferne Landschaft verschwindet nicht mehr im dichten Nebel.",
	["El paisaje lejano deja de perderse en la niebla espesa. A veces se nota dónde termina lo que está cargado."] = "Die ferne Landschaft verschwindet nicht mehr im dichten Nebel. Manchmal sieht man, wo der geladene Bereich endet.",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "Alfas Datenpaket (Alfa_Codex) ist deaktiviert: Aktiviere es in der Addon-Liste und lade neu.",
	["El paso de ahora de tu guía te lleva a entrenar."] = "Der aktuelle Schritt deines Guides führt dich zum Trainieren.",
	["El pequeño rey Anduin Wrynn lleva su nombre en honor a Anduin Lothar, el héroe que salvó a su pueblo."] = "Der junge König Anduin Wrynn trägt seinen Namen zu Ehren von Anduin Lothar, dem Helden, der sein Volk rettete.",
	["El primer clic abre la Cocina del juego; el siguiente cocina el lote. Tienes que estar junto a un fuego."] = "Der erste Klick öffnet das Kochkunst-Fenster des Spiels; der nächste kocht den Durchgang. Du musst an einem Feuer stehen.",
	["El primer jefe de guerra de la Horda fue Mano Negra. Su hijo Rend Mano Negra hoy sirve a Nefarian en la Cumbre de Roca Negra."] = "Der erste Kriegshäuptling der Horde war Schwarzfaust. Sein Sohn Rend Schwarzfaust dient heute Nefarian in der Schwarzfelsspitze.",
	["El primer punto del Legado suele llegar al nivel 25, y con él se abre el Legado."] = "Der erste Vermächtnispunkt kommt meist auf Stufe 25, und mit ihm wird das Vermächtnis freigeschaltet.",
	["El próximo: %s"] = "Der nächste: %s",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "Der einfachste Schurke zum Leveln: Er schlägt von vorne zu, weicht viel aus und hält mehr aus als die anderen.",
	["El rango Experto viene en un libro que vende el pescador de Bahía del Botín, en Tuercespina."] = "Den Rang Experte gibt es als Buch beim Angler in Beutebucht im Schlingendorntal.",
	["El rango de niveles de cada zona, con color según tu nivel."] = "Der Stufenbereich jedes Gebiets, eingefärbt nach deiner Stufe.",
	["El rastreador te avisa si tu plan se quedó sin paso y lo rearma con un clic."] = "Der Tracker sagt dir, wenn dein Plan keinen Schritt mehr hat, und erstellt ihn mit einem Klick neu.",
	["El rastreador te dice el siguiente paso y la flecha te lleva."] = "Der Tracker sagt dir den nächsten Schritt, und der Pfeil führt dich hin.",
	["El registro de daño del juego está apagado"] = "Die Schadensaufzeichnung des Spiels ist aus",
	["El registro de daño del juego está apagado: enciéndelo para ver el top de tu grupo."] = "Die Schadensaufzeichnung des Spiels ist aus: Schalte sie ein, um das Top deiner Gruppe zu sehen.",
	["El registro del Legado"] = "Die Vermächtnis-Belohnungsleiste",
	["El reino humano de Alterac traicionó a la Alianza en la Segunda Guerra: su rey, Aiden Perenolde, se alió con la Horda. Por eso el reino desapareció."] = "Das Menschenkönigreich Alterac verriet die Allianz im Zweiten Krieg: Sein König Aiden Perenolde verbündete sich mit der Horde. Deshalb ging das Königreich unter.",
	["El reino limita los mensajes de addon salientes: %s"] = "Der Realm begrenzt ausgehende Addon-Nachrichten: %s",
	["El rey Llane Wrynn murió en la Primera Guerra a manos de Garona, la espía de la Horda."] = "König Llane Wrynn starb im Ersten Krieg durch die Hand von Garona, der Spionin der Horde.",
	["El rey Magni Barbabronce gobierna Forjaz; sus hermanos son Muradin y Brann, el explorador."] = "König Magni Bronzebart herrscht über Eisenschmiede; seine Brüder sind Muradin und Brann, der Forscher.",
	["El rey Thoradin unió a las tribus humanas en Arathor, y los altos elfos les enseñaron magia para vencer juntos a los trols Amani."] = "König Thoradin einte die Menschenstämme in Arathor, und die Hochelfen lehrten sie Magie, um gemeinsam die Amanitrolle zu besiegen.",
	["El rey Varian Wrynn es hijo de Llane, el rey que murió en la Primera Guerra."] = "König Varian Wrynn ist der Sohn von Llane, dem König, der im Ersten Krieg starb.",
	["El rey Varian desapareció camino a una reunión de paz. Mientras tanto reina su hijo Anduin, todavía niño, con el alto señor Bolvar Fordragón como regente."] = "König Varian verschwand auf dem Weg zu einem Friedensgipfel. Inzwischen regiert sein junger Sohn Anduin, mit Hochlord Bolvar Fordragon als Regent.",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "Der Heiler der Schamanen: Kettenheilungen und Totems, die der ganzen Gruppe helfen.",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "Der Heiler der Druiden: Du heilst jede Gruppe und überlebst gut, auch wenn du solo langsam tötest.",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "Der Heiler der Paladine: starke Heilungen und viel Rüstung, ideal für Gruppen.",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "Der reine Heiler: große Heilungen und Heilungen für die ganze Gruppe.",
	["El servicio"] = "Der Dienst",
	["El sistema de equipo de Alfa no está disponible."] = "Alfas Ausrüstungssystem ist nicht verfügbar.",
	["El sol aquí no perdona: las Tierras Inhóspitas son tierra de coyotes, buitres y basiliscos."] = "Die Sonne hier kennt keine Gnade: Das Ödland ist ein Land der Kojoten, Geier und Basilisken.",
	["El suelo y los muros se ven nítidos aunque estén lejos o de lado."] = "Boden und Mauern bleiben scharf, auch wenn sie weit weg oder schräg sind.",
	["El talento que toca"] = "Dein nächstes Talent",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "Der klassische Tank: Du blockst viel, erzeugst Bedrohung mit Rache und Schildschlag und hast Letztes Gefecht für den Fall, dass alles schiefgeht.",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "Der am schwersten zu tötende Tank: alle Verteidigungstalente, Verbesserter Schildwall und früh Letztes Gefecht. Perfekt, um mit dem Tanken anzufangen.",
	["El terreno real en el mapa"] = "Echtes Gelände auf der Karte",
	["El texto es demasiado largo."] = "Der Text ist zu lang.",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "Der Text kam gekürzt oder verändert an: Kopiere ihn erneut.",
	["El tipo de nodos que une la ruta."] = "Die Art der Vorkommen, die die Route verbindet.",
	["El tono de los fondos: Grafito es el de Alfa, Noche el más oscuro y Pizarra un gris neutro."] = "Der Ton der Hintergründe: Graphit ist der von Alfa, Nacht der dunkelste und Schiefer ein neutrales Grau.",
	["El top de DPS de tu grupo o banda en una ventana pequeña, con la pelea actual y la anterior."] = "Das DPS-Top deiner Gruppe oder deines Schlachtzugs in einem kleinen Fenster, mit dem aktuellen und dem vorherigen Kampf.",
	["El torio abunda en el Cráter de Un'Goro y en Cuna del Invierno."] = "Thorium gibt es reichlich im Krater von Un'Goro und in Winterquell.",
	["El velo de pantalla de algunas zonas y hechizos de las sombras."] = "Der Bildschirmschleier mancher Zonen und Schattenzauber.",
	["El vendedor más cercano"] = "Der nächste Händler",
	["El verdadero nombre de Thrall es Go'el, el que le dieron sus padres."] = "Thralls wahrer Name ist Go'el, der, den ihm seine Eltern gaben.",
	["El viejo ermitaño Abercrombie parece amable... hasta que descubres a quién intenta revivir."] = "Der alte Einsiedler Abercrombie wirkt freundlich... bis du herausfindest, wen er wiederbeleben will.",
	["El «zug zug» de los peones quiere decir algo así como «de acuerdo». ¡Zug zug, jefe!"] = "Das „Zug zug“ der Peons bedeutet so etwas wie „In Ordnung“. Zug zug, Boss!",
	["El árbol de ruta de Alfa, misiones que se liberan y un catálogo de objetos."] = "Alfas Routenbaum, Quests, sobald sie freigeschaltet werden, und ein Gegenstandskatalog.",
	["El ícono grande es lo que conviene presionar ahora y los pequeños, lo que sigue. Si late, el juego activó esa habilidad; el barrido oscuro es su recarga. Tú decides: Alfa nunca aprieta nada."] = "Das große Symbol ist, was du jetzt am besten drückst, die kleinen, was danach kommt. Pulsiert es, hat das Spiel die Fähigkeit aufleuchten lassen; die dunkle Animation ist ihre Abklingzeit. Du entscheidest: Alfa drückt nie etwas.",
	["El último punto: paras un poco más."] = "Der letzte Punkt: Du parierst etwas mehr.",
	["Elegida por ti en los ajustes."] = "Von dir in den Einstellungen gewählt.",
	["Elegida por tus talentos."] = "Von deinen Talenten gewählt.",
	["Elegido"] = "Gewählt",
	["Elegido por ti"] = "Von dir gewählt",
	["Elegir capas"] = "Ebenen wählen",
	["Elegir la siguiente guía"] = "Nächsten Guide wählen",
	["Elegir lo que pide tu paso"] = "Wählen, was dein Schritt verlangt",
	["Elegir mi camino"] = "Meinen Weg wählen",
	["Elegir mi primera guía"] = "Meinen ersten Guide wählen",
	["Elegir mi tecla"] = "Meine Taste wählen",
	["Elegir otra guía"] = "Anderen Guide wählen",
	["Elegir para copiar"] = "Zum Kopieren markieren",
	["Elegir qué sigue"] = "Wählen, was als Nächstes kommt",
	["Elegir todo"] = "Alles markieren",
	["Elegir una guía"] = "Guide wählen",
	["Elegir una guía por ti"] = "Einen Guide für dich wählen",
	["Elegiste: %s"] = "Gewählt: %s",
	["Elemental"] = "Elementar",
	["Elemental para subir"] = "Elementar zum Leveln",
	["Elfos de la noche"] = "Nachtelfen",
	["Elige abajo qué cocinar y cuánto: la cola espera tu clic para cada lote."] = "Wähl unten, was und wie viel du kochst: Die Warteschlange wartet bei jedem Durchgang auf deinen Klick.",
	["Elige algo de la lista"] = "Wähle etwas aus der Liste",
	["Elige el objeto"] = "Wähle den Gegenstand",
	["Elige el objeto en la Enciclopedia."] = "Wähle den Gegenstand in der Enzyklopädie.",
	["Elige la opción que nombra tu guía, o abre la tienda o el entrenamiento que necesitas."] = "Wählt die Option, die dein Guide nennt, oder öffnet den Laden oder die Ausbildung, die du brauchst.",
	["Elige qué guardar: lo que ya tienes en el banco, los materiales, una categoría o todo lo que no sea equipo. Se mueve de una vez, fuera de combate."] = "Wähle, was du einlagerst: was du schon in der Bank hast, die Materialien, eine Kategorie oder alles außer Ausrüstung. Alles wird auf einmal verschoben, außerhalb des Kampfes.",
	["Elige qué quieres hacer y Alfa te lleva paso a paso."] = "Wähle, was du tun willst, und Alfa führt dich Schritt für Schritt.",
	["Elige qué se ve en el mapa: guía, misiones, raros, viajes, zonas y lo que agregan otros módulos."] = "Wähle, was die Karte zeigt: Guide, Quests, Rares, Reisen, Gebiete und was andere Module hinzufügen.",
	["Elige sola la única opción de los PNJ sin misiones."] = "Wählt von selbst die einzige Option von NPCs ohne Quests.",
	["Elige solo misiones que ya puedes tomar."] = "Es wählt nur Quests, die du schon annehmen kannst.",
	["Elige tu camino. Si no sabes, empieza por subir de nivel: Alfa te dice qué conviene."] = "Wähle deinen Weg. Wenn du unsicher bist, fang mit dem Leveln an: Alfa sagt dir, was sich lohnt.",
	["Elige tu estilo"] = "Wähle deinen Stil",
	["Elige tu tecla para pescar"] = "Wähle deine Angeltaste",
	["Elige tus clics"] = "Wähle deine Klicks",
	["Elige tus clics, acomoda tus marcos y pruébalos. Te toma un minuto."] = "Wähle deine Klicks, platziere deine Rahmen und teste sie. Das dauert eine Minute.",
	["Elige tú la zona."] = "Du wählst das Gebiet.",
	["Elige un camino: Alfa arma tu plan y te guía paso a paso."] = "Wähle einen Weg: Alfa erstellt deinen Plan und führt dich Schritt für Schritt.",
	["Elige un marcador."] = "Wähl eine Markierung.",
	["Elige un servicio."] = "Wähl einen Dienst.",
	["Elige una captura"] = "Wähl einen Fang",
	["Elige una guía para empezar"] = "Wähle einen Guide, um zu beginnen",
	["Elige una mazmorra."] = "Wähl einen Dungeon.",
	["Elige una misión"] = "Wähl eine Quest",
	["Elige una profesión"] = "Wähl einen Beruf",
	["Elige una profesión."] = "Wähl einen Beruf.",
	["Elige uno y lo ves al instante en esta ventana y en todas las de Alfa, también la flecha."] = "Wähl einen aus und sieh ihn sofort in diesem Fenster und in allen Fenstern von Alfa, auch am Pfeil.",
	["Eliges una"] = "Du wählst eine",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "Sie schläfert die ganze Gruppe ein und belebt dann Mograine wieder: Das ist normal, keine Panik.",
	["Elune, la diosa de la luna, es la fe de los elfos de la noche. Sus sacerdotisas son las Hermanas de Elune, y Tyrande es su suma sacerdotisa."] = "Elune, die Mondgöttin, ist der Glaube der Nachtelfen. Ihre Priesterinnen sind die Schwesternschaft der Elune, und Tyrande ist ihre Hohepriesterin.",
	["Embate con escudo: mucho daño y amenaza."] = "Schildschlag: viel Schaden und Bedrohung.",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "Zerschmettern setzt deinen Angriff nicht mehr zurück: ein Extraschlag zwischen zwei Schlägen.",
	["Embate sin perder tu ataque automático."] = "Zerschmettern, ohne deinen automatischen Angriff zu verlieren.",
	["Embate sin perder tu ataque."] = "Zerschmettern, ohne deinen Schlag zu verlieren.",
	["Embate sin perder tu golpe automático."] = "Zerschmettern, ohne deinen automatischen Schlag zu verlieren.",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "Zerschmettern, ohne deinen Angriff zurückzusetzen: ein Extraschlag.",
	["Embate: un golpe fuerte entre golpe y golpe."] = "Zerschmettern: ein starker Schlag zwischen zwei Schwüngen.",
	["Empezar"] = "Los geht's",
	["Empezar de cero"] = "Von vorn beginnen",
	["Empezar de nuevo"] = "Neu anfangen",
	["Empezar otra"] = "Neue beginnen",
	["Empezar otra sesión"] = "Neue Sitzung beginnen",
	["Empezó %s"] = "Begonnen %s",
	["Empezó %s."] = "Begonnen: %s.",
	["Empieza al usar este objeto"] = "Beginnt, wenn du diesen Gegenstand benutzt",
	["Empieza aquí"] = "Hier anfangen",
	["Empieza con %s, que se consigue en la mazmorra."] = "Sie beginnt mit %s, das man im Dungeon findet.",
	["Empieza con %s, que suelta %s."] = "Sie beginnt mit %s, das %s fallen lässt.",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "Beginne aus der Ferne mit deinem langsamsten Zauber und beende mit den Spontanzaubern.",
	["Empieza dentro"] = "Beginnt drinnen",
	["Empieza una misión"] = "Startet eine Quest",
	["Empiezas: nivel %d"] = "Du startest: Stufe %d",
	["En %s"] = "In %s",
	["En 9 idiomas"] = "In 9 Sprachen",
	["En Burning Crusade, Karazhan abre sus puertas como banda."] = "In Burning Crusade öffnet Karazhan seine Tore als Schlachtzug.",
	["En Burning Crusade, el Vuelo Bronce pide ayuda en las Cavernas del Tiempo contra dragones que quieren cambiar la historia."] = "In Burning Crusade bittet der bronzene Drachenschwarm in den Höhlen der Zeit um Hilfe gegen Drachen, die die Geschichte ändern wollen.",
	["En Burning Crusade, las Cavernas del Tiempo te regresan a estas laderas para ver la huida de Thrall de Durnholde."] = "In Burning Crusade bringen dich die Höhlen der Zeit zurück an diese Hänge, um Thralls Flucht aus Durnholde mitzuerleben.",
	["En Caer Darrow, junto al lago, todavía rondan los fantasmas de sus antiguos vecinos."] = "In Caer Darrow am See streifen noch die Geister seiner früheren Bewohner umher.",
	["En Ciudad Manitas, dentro de Forjaz, viven los gnomos que escaparon de Gnomeregan."] = "In Tüftlerstadt in Eisenschmiede leben die Gnome, die aus Gnomeregan geflohen sind.",
	["En Costa Oscura la Liga de Expedicionarios desentierra fósiles gigantes."] = "An der Dunkelküste gräbt die Forscherliga riesige Fossilien aus.",
	["En Costa Oscura viven lechúcicos, criaturas mitad búho y mitad oso que veneran la luna."] = "An der Dunkelküste leben Mondkin, halb Eule, halb Bär, die den Mond verehren.",
	["En Desolace está el cementerio de los kodos, donde los viejos kodos van a morir."] = "In Desolace liegt der Kodofriedhof, wohin alte Kodos zum Sterben gehen.",
	["En Durotar ya te topas con el Filo Ardiente, un culto de brujos orcos que sigue adorando a los demonios."] = "Schon in Durotar triffst du auf die Brennende Klinge, einen Kult von Orc-Hexenmeistern, die noch immer die Dämonen anbeten.",
	["En Elwynn, una señora vende gatitos de compañía. ¡Yo me llevo bien con los gatos... casi siempre!"] = "In Elwynn verkauft eine Dame Kätzchen als Haustiere. Mit Katzen komme ich gut aus... meistens!",
	["En Entrañas venden cucarachas de mascota. Cada quien sus gustos."] = "In Unterstadt verkaufen sie Kakerlaken als Haustiere. Jedem das Seine.",
	["En Feralas está uno de los grandes árboles por los que los dragones verdes entran al Sueño Esmeralda."] = "In Feralas steht einer der großen Bäume, durch die die grünen Drachen den Smaragdgrünen Traum betreten.",
	["En Forever, Onyxia, la Cumbre Hyjal y Barrow Deeps dan retos del Legado al vencerlas."] = "In Forever geben Onyxia, der Hyjalgipfel und die Barrow Deeps Vermächtnis-Herausforderungen, wenn du sie besiegst.",
	["En Forever, el banco vende casillas de bolsa una tras otra: más espacio para tus tesoros."] = "In Forever verkauft die Bank Taschenplätze, einen nach dem anderen: mehr Platz für deine Schätze.",
	["En Forever, los rangos de honor y la reputación de los campos de batalla también dan retos del Legado."] = "In Forever geben auch Ehrenränge und der Ruf der Schlachtfelder Vermächtnis-Herausforderungen.",
	["En Forever, los retos del Legado dan puntos a toda tu cuenta, y cada personaje los gasta en sus árboles. Ábrelo con la tecla Y."] = "In Forever geben die Vermächtnis-Herausforderungen Punkte für deinen ganzen Account, und jeder Charakter gibt sie in seinen Bäumen aus. Öffne es mit der Taste Y.",
	["En Forjaz, la sala de la Liga de Expedicionarios tiene un museo con fósiles enormes. Brann Barbabronce es su explorador más famoso."] = "In Eisenschmiede hat die Halle der Forscherliga ein Museum mit riesigen Fossilien. Brann Bronzebart ist ihr berühmtester Forscher.",
	["En Gadgetzan, el cocinero Dirge enseña una de las mejores recetas del Clásico, con carne de quimerok."] = "In Gadgetzan lehrt der Koch Dirge eines der besten Rezepte von Classic, mit Schimärokfleisch.",
	["En Jaedenar se esconde el Consejo de la Sombra, brujos que sirven a la Legión Ardiente."] = "In Jaedenar versteckt sich der Schattenrat, Hexenmeister im Dienst der Brennenden Legion.",
	["En Jardín Noble se esconden huevos de colores por los pueblos iniciales; dentro hay dulces y a veces ropa de primavera."] = "Zum Nobelgarten werden in den Startorten bunte Eier versteckt; darin gibt es Süßigkeiten und manchmal Frühlingskleidung.",
	["En Kharanos, la posada y la destilería Cebatruenos son la parada obligada para calentarse... por dentro y por fuera."] = "In Kharanos sind das Gasthaus und die Brauerei Donnerbräu der Pflichthalt zum Aufwärmen... innen wie außen.",
	["En Molino Ámbar se refugian magos de Dalaran, y no les gustan nada las visitas de los Renegados."] = "In der Bernsteinmühle haben sich Magier aus Dalaran verschanzt, und Besuch von den Verlassenen mögen sie gar nicht.",
	["En Naxxramas, el gran Alexandros Mograine reaparece como uno de los Cuatro Jinetes de la Plaga. Qué triste destino para un héroe."] = "In Naxxramas kehrt der große Alexandros Mograine als einer der Vier Reiter der Geißel zurück. Was für ein trauriges Schicksal für einen Helden.",
	["En Nethergarde, unos magos de sangre te cambian partes de las bestias de aquí por elixires que te potencian un buen rato."] = "In Nethergarde tauschen dir Blutmagier Teile der hiesigen Bestien gegen Elixiere, die dich eine gute Weile stärken.",
	["En Orgrimmar, el Valle de la Sabiduría guarda la fortaleza de Thrall, y el Valle del Honor reúne a guerreros y cazadores."] = "In Orgrimmar liegt im Tal der Weisheit Thralls Festung, und im Tal der Ehre treffen sich Krieger und Jäger.",
	["En Pico Nidal manda el thane Falstad Martillo Salvaje, señor de los jinetes de grifo."] = "Am Nistgipfel herrscht Thane Falstad Wildhammer, Herr der Greifenreiter.",
	["En Pico Nidal viven los enanos Martillo Salvaje, famosos por volar sobre grifos."] = "Am Nistgipfel leben die Wildhammerzwerge, berühmt dafür, auf Greifen zu fliegen.",
	["En Seradane hay uno de los grandes árboles que llevan al Sueño Esmeralda, y los dragones verdes lo custodian."] = "In Seradane steht einer der großen Bäume, die in den Smaragdgrünen Traum führen, und die grünen Drachen bewachen ihn.",
	["En Tanaris están las Cavernas del Tiempo, donde el Vuelo Bronce de Nozdormu vigila la historia."] = "In Tanaris liegen die Höhlen der Zeit, wo Nozdormus bronzener Drachenschwarm über die Geschichte wacht.",
	["En Tirisfal está la entrada al Monasterio Escarlata, uno de los lugares más visitados por los aventureros de nivel medio."] = "In Tirisfal liegt der Eingang zum Scharlachroten Kloster, einem der meistbesuchten Orte für Abenteurer mittlerer Stufe.",
	["En Uldaman están los Discos de Norgannon, registros de los titanes que cuentan cómo crearon a los terráneos, los antepasados de piedra de los enanos."] = "In Uldaman liegen die Scheiben von Norgannon, Aufzeichnungen der Titanen darüber, wie sie die Irdenen schufen, die steinernen Vorfahren der Zwerge.",
	["En Vallefresno, Grom Grito Infernal mató al semidiós Cenarius cuando la Horda empezó a talar el bosque."] = "Im Eschental tötete Grom Höllschrei den Halbgott Cenarius, als die Horde begann, den Wald abzuholzen.",
	["En Vallefresno, Grom volvió a beber sangre demoníaca; Thrall lo rescató y Grom pudo redimirse antes de morir."] = "Im Eschental trank Grom erneut Dämonenblut; Thrall rettete ihn, und Grom konnte sich vor seinem Tod erlösen.",
	["En Ventormenta hay un barrio de enanos, uno de magos y un parque donde se reúnen los elfos de la noche."] = "Sturmwind hat ein Zwergenviertel, ein Magierviertel und einen Park, in dem sich die Nachtelfen treffen.",
	["En Warcraft III, si le das muchos clics a una unidad empieza a decir cosas chistosas. Yo, en cambio, te doy consejos."] = "Wenn du in Warcraft III oft auf eine Einheit klickst, sagt sie irgendwann lustige Dinge. Ich dagegen gebe dir Tipps.",
	["En arco"] = "Im Bogen",
	["En bancos de peces de: %s."] = "In Fischschwärmen von: %s.",
	["En camino"] = "Unterwegs",
	["En cero los números suben derechos; más alto, salen disparados hacia los lados."] = "Bei null steigen Zahlen gerade auf; höher fliegen sie seitlich davon.",
	["En combate"] = "Im Kampf",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "Im Kampf verbirgt das Spiel die genauen Zahlen: Balken und Werte siehst du trotzdem, Details und Ansage nach dem Kampf.",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "Im Kampf öffnet sich die Spielkarte nicht über Alfa: Nutze die von Alfa.",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "Im Kampf erscheint der Tooltip von Charakteren und Kreaturen in der Welt nicht (der der Rahmen schon).",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "Im Kampf gibt es keinen Test: Verlass den Kampf und komm zu diesem Schritt zurück.",
	["En combate no puedo buscar: inténtalo al terminar la pelea."] = "Im Kampf kann ich nicht suchen: Versuch es nach dem Kampf.",
	["En combate no se puede: espera a terminar."] = "Im Kampf geht das nicht: Warte, bis er vorbei ist.",
	["En combate · la pesca espera"] = "Im Kampf · das Angeln wartet",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "Im Kampf zeigt das Symbol die Fähigkeit, die Blizzards Kampfassistent vorschlägt, und die %d folgenden. Du entscheidest, was du drückst: Alfa drückt nie etwas für dich.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "Im Kampf zeigt das Symbol die Fähigkeit, die Blizzards Kampfassistent vorschlägt. Du entscheidest, was du drückst: Alfa drückt nie etwas für dich.",
	["En combate: espera a terminar"] = "Im Kampf: Warte, bis er vorbei ist",
	["En curso"] = "Läuft",
	["En el Casco Antiguo está el SI:7, los espías y pícaros al servicio del reino."] = "In der Altstadt sitzt SI:7, die Spione und Schurken im Dienst des Königreichs.",
	["En el Clásico mandan Thrall en Orgrimmar, Cairne en Cima del Trueno, Sylvanas en Entrañas y Vol'jin con los Lanza Negra."] = "In Classic herrschen Thrall in Orgrimmar, Cairne in Donnerfels, Sylvanas in Unterstadt, und Vol'jin führt die Dunkelspeere.",
	["En el Clásico nadie sabe dónde anda Alamuerte; los que dan la cara son sus hijos, Onyxia y Nefarian."] = "In Classic weiß niemand, wo Todesschwinge steckt; wer sich zeigt, sind seine Kinder Onyxia und Nefarian.",
	["En el Clásico necesitas flechas o balas: lleva siempre de más en tu carcaj o tu bolsa de munición."] = "In Classic brauchst du Pfeile oder Kugeln: Trag immer genug in deinem Köcher oder Munitionsbeutel.",
	["En el Clásico necesitas un cuchillo de desollar en tus bolsas."] = "In Classic brauchst du ein Kürschnermesser in deinen Taschen.",
	["En el Clásico solo puedes tener dos profesiones principales, pero Cocina, Pesca y Primeros auxilios se aprenden aparte."] = "In Classic kannst du nur zwei Hauptberufe haben, aber Kochkunst, Angeln und Erste Hilfe lernt man zusätzlich.",
	["En el Clásico, Costasur contra Molino Tarren era la pelea entre bandos más famosa del mundo."] = "In Classic war Süderstade gegen Tarrens Mühle der berühmteste Fraktionskampf der Welt.",
	["En el Clásico, a nivel 20 aprendes a teletransportarte a las capitales, y a 40 a abrir portales para los demás."] = "In Classic lernst du auf Stufe 20, dich in die Hauptstädte zu teleportieren, und auf 40, Portale für andere zu öffnen.",
	["En el Clásico, a nivel 20 haces la misión de los venenos; después los mejoras con tu entrenador."] = "In Classic machst du auf Stufe 20 die Giftquest; danach verbesserst du die Gifte bei deinem Lehrer.",
	["En el Clásico, a nivel 40 haces la misión de tu caballo de guerra, y a 60 la cadena épica del destrero."] = "In Classic machst du auf Stufe 40 die Quest für dein Schlachtross und auf 60 die epische Questreihe für das Streitross.",
	["En el Clásico, a nivel 40 recibes un corcel vil, y a 60 una cadena épica en La Masacre te da uno aún más temible."] = "In Classic bekommst du auf Stufe 40 ein Teufelsross, und auf 60 gibt dir eine epische Questreihe in Düsterbruch ein noch furchterregenderes.",
	["En el Clásico, abrir las puertas de Ahn'Qiraj pidió un esfuerzo de guerra de todo el servidor: montañas de materiales y una cadena larguísima."] = "In Classic brauchte es für das Öffnen der Tore von Ahn'Qiraj eine Kriegsanstrengung des ganzen Servers: Berge von Materialien und eine endlose Questreihe.",
	["En el Clásico, algunos peces solo pican de noche o de día."] = "In Classic beißen manche Fische nur nachts oder nur tagsüber an.",
	["En el Clásico, cada raza de sacerdote tiene un hechizo propio. Pregúntale a tu entrenador cuál te toca."] = "In Classic hat jedes Priestervolk einen eigenen Zauber. Frag deinen Lehrer, welcher deiner ist.",
	["En el Clásico, después de vendarte queda un rato en que no puedes usar otra venda."] = "In Classic kannst du nach dem Verbinden eine Weile keinen weiteren Verband benutzen.",
	["En el Clásico, el Cetro de las Arenas Movedizas abrió las puertas de Ahn'Qiraj tras una larguísima cadena de misiones."] = "In Classic öffnete das Szepter der Treibsande die Tore von Ahn'Qiraj nach einer endlos langen Questreihe.",
	["En el Clásico, el arco épico de los cazadores sale de una cadena contra demonios que empieza en el Claro de la Luna."] = "In Classic stammt der epische Bogen der Jäger aus einer Questreihe gegen Dämonen, die auf der Mondlichtung beginnt.",
	["En el Clásico, el chat de Los Baldíos era famoso por sus pláticas eternas... y por preguntar dónde estaba la esposa de Mankrik."] = "In Classic war der Chat im Brachland berühmt für seine endlosen Gespräche... und für die Frage, wo Mankriks Frau ist.",
	["En el Clásico, el nivel máximo es 60 y llegar lleva su tiempo. Por eso cada nivel se festeja."] = "In Classic ist die Höchststufe 60, und bis dahin dauert es. Darum wird jede Stufe gefeiert.",
	["En el Clásico, el rango de honor 14 es Gran Mariscal para la Alianza y Gran Señor de la Guerra para la Horda."] = "In Classic ist Ehrenrang 14 Großmarschall für die Allianz und Oberster Kriegsfürst für die Horde.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala en Mulgore, cerca del poblado Pezuña de Sangre."] = "In Classic schlägt der Dunkelmond-Jahrmarkt manchmal in Mulgore auf, nahe dem Dorf der Bluthufe.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala junto a Villadorada."] = "In Classic schlägt der Dunkelmond-Jahrmarkt manchmal bei Goldhain auf.",
	["En el Clásico, la Horda la forman orcos, trols Lanza Negra, tauren y Renegados; la Alianza, humanos, enanos, gnomos y elfos de la noche."] = "In Classic besteht die Horde aus Orcs, Dunkelspeertrollen, Tauren und Verlassenen; die Allianz aus Menschen, Zwergen, Gnomen und Nachtelfen.",
	["En el Clásico, la Plaga invadió el mundo con necrópolis flotantes antes de que se abriera Naxxramas."] = "In Classic fiel die Geißel mit schwebenden Nekropolen über die Welt her, bevor Naxxramas öffnete.",
	["En el Clásico, la actitud defensiva se gana con una misión al nivel 10, y la rabiosa con otra al nivel 30."] = "In Classic bekommst du die Verteidigungshaltung mit einer Quest auf Stufe 10 und die Berserkerhaltung mit einer weiteren auf Stufe 30.",
	["En el Clásico, la casa de subastas de Forjaz es la más movida de toda la Alianza."] = "In Classic ist das Auktionshaus von Eisenschmiede das belebteste der ganzen Allianz.",
	["En el Clásico, la forma de oso se gana con una misión a nivel 10 y la acuática con otra a nivel 16; luego vienen la felina y la de viaje."] = "In Classic bekommst du die Bärengestalt mit einer Quest auf Stufe 10 und die Wassergestalt mit einer weiteren auf 16; danach kommen Katzen- und Reisegestalt.",
	["En el Clásico, la montura de nivel 40 es mucho más rápida que correr, y la épica de nivel 60 todavía más."] = "In Classic ist das Reittier auf Stufe 40 viel schneller als Laufen, und das epische auf Stufe 60 noch mehr.",
	["En el Clásico, la tela se puede donar en tu capital a cambio de reputación."] = "In Classic kannst du in deiner Hauptstadt Stoff gegen Ruf spenden.",
	["En el Clásico, las bandas grandes son de 40 jugadores, y Zul'Gurub y las Ruinas de Ahn'Qiraj, de 20."] = "In Classic sind die großen Schlachtzüge für 40 Spieler, Zul'Gurub und die Ruinen von Ahn'Qiraj für 20.",
	["En el Clásico, los Renegados se quitan el miedo, el encanto y el sueño con su voluntad."] = "In Classic schütteln die Verlassenen mit ihrem Willen Furcht, Bezauberung und Schlaf ab.",
	["En el Clásico, los domingos por la tarde Bahía del Botín organizaba un concurso de pesca: ganaba quien entregara primero cuarenta peces de una especie especial."] = "In Classic veranstaltete Beutebucht sonntagnachmittags einen Angelwettbewerb: Es gewann, wer zuerst vierzig Fische einer besonderen Art abgab.",
	["En el Clásico, los enanos pueden buscar tesoros con un rastreo propio. ¡Ideal para encontrar cofres!"] = "In Classic können Zwerge mit einer eigenen Suche Schätze aufspüren. Ideal, um Truhen zu finden!",
	["En el Clásico, los enanos se convierten en piedra para quitarse venenos y sangrados, y son buenos con las armas de fuego."] = "In Classic verwandeln sich Zwerge in Stein, um Gifte und Blutungen abzuschütteln, und sie können gut mit Schusswaffen umgehen.",
	["En el Clásico, los gnomos pueden ser guerreros, pícaros, magos o brujos."] = "In Classic können Gnome Krieger, Schurken, Magier oder Hexenmeister sein.",
	["En el Clásico, los gnomos son más listos que el resto, tienen talento para la ingeniería y se zafan de lo que los inmoviliza."] = "In Classic sind Gnome klüger als der Rest, haben Talent für Ingenieurskunst und befreien sich aus allem, was sie festhält.",
	["En el Clásico, los humanos ganan reputación más rápido gracias a su diplomacia, y tienen buen ojo para ver a los sigilosos."] = "In Classic gewinnen Menschen dank ihrer Diplomatie schneller Ruf und haben ein gutes Auge für Verstohlene.",
	["En el Clásico, los maestros de armas de las capitales te enseñan a usar armas nuevas."] = "In Classic bringen dir die Waffenmeister der Hauptstädte neue Waffen bei.",
	["En el Clásico, los orcos resisten mejor los aturdimientos y sus mascotas pegan más fuerte."] = "In Classic widerstehen Orcs Betäubungen besser, und ihre Begleiter treffen härter.",
	["En el Clásico, los tauren tienen más vida, un pisotón que aturde a los enemigos cercanos y mano verde con las hierbas."] = "In Classic haben Tauren mehr Gesundheit, einen Kriegsdonner, der nahe Gegner betäubt, und einen grünen Daumen für Kräuter.",
	["En el Clásico, los trols se regeneran rápido, entran en frenesí, pegan más fuerte a las bestias y son buenos con arcos y armas arrojadizas."] = "In Classic regenerieren Trolle schnell, verfallen in Berserker, treffen Wildtiere härter und können gut mit Bögen und Wurfwaffen umgehen.",
	["En el Clásico, muchas comidas te dejan bien alimentado y te suben estadísticas un buen rato."] = "In Classic machen dich viele Gerichte satt und erhöhen eine gute Weile deine Werte.",
	["En el Clásico, para pasar de 225 hay una misión de triaje en Theramore o en Sentencia."] = "In Classic gibt es für mehr als 225 eine Triage-Quest in Theramore oder Hammerfall.",
	["En el Clásico, quienes terminaron la cadena del cetro y tocaron el gong de Ahn'Qiraj ganaron un título y una montura únicos."] = "In Classic bekamen alle, die die Szepterquestreihe abschlossen und den Gong von Ahn'Qiraj schlugen, einen einzigartigen Titel und ein einzigartiges Reittier.",
	["En el Clásico, solo elfos de la noche y tauren pueden ser druidas."] = "In Classic können nur Nachtelfen und Tauren Druiden sein.",
	["En el Clásico, solo humanos y enanos pueden ser paladines."] = "In Classic können nur Menschen und Zwerge Paladine sein.",
	["En el Clásico, solo orcos, trols y tauren pueden ser chamanes."] = "In Classic können nur Orcs, Trolle und Tauren Schamanen sein.",
	["En el Clásico, tu Reencarnación te revive a ti mismo, pero necesita un ankh en tus bolsas."] = "In Classic belebt dich deine Reinkarnation selbst wieder, braucht aber ein Ankh in deinen Taschen.",
	["En el Enclave Cenarion los druidas enseñan a los suyos el camino de la naturaleza."] = "In der Enklave des Cenarius lehren die Druiden die Ihren den Weg der Natur.",
	["En el Festival Lunar, la gente viene al Claro de la Luna a honrar a sus ancestros."] = "Zum Mondfest kommen die Leute zur Mondlichtung, um ihre Ahnen zu ehren.",
	["En el Festival Lunar, un emisario en las capitales te puede llevar al Claro de la Luna para celebrar con los druidas."] = "Zum Mondfest kann dich ein Abgesandter in den Hauptstädten zur Mondlichtung bringen, um mit den Druiden zu feiern.",
	["En el Festival de Fuego del Solsticio de Verano hay hogueras en muchos pueblos: honrar las de tu bando da premios, y apagar las del otro también."] = "Zum Sonnenwendfest brennen in vielen Orten Feuer: Die deiner Fraktion zu ehren bringt Belohnungen, die der anderen zu löschen auch.",
	["En el Festival de Invierno venden bolas de nieve. ¡Lánzaselas a tus amigos, que yo las atrapo!"] = "Zum Winterhauchfest gibt es Schneebälle zu kaufen. Bewirf deine Freunde, ich fange sie!",
	["En el Festival de Invierno, el Gran Padre Invierno reparte regalos en Forjaz y Orgrimmar, y bajo el árbol aparecen paquetes el día 25."] = "Zum Winterhauchfest verteilt Großvater Winter Geschenke in Eisenschmiede und Orgrimmar, und am 25. tauchen Päckchen unter dem Baum auf.",
	["En el Festival de la Cosecha, la Horda honra a Grom Grito Infernal y la Alianza a Uther, en sus monumentos."] = "Zum Erntedankfest ehrt die Horde Grom Höllschrei und die Allianz Uther, an ihren Denkmälern.",
	["En el Núcleo de Magma se desuellan perros del núcleo para un cuero muy especial."] = "Im Geschmolzenen Kern kann man Kernhunde für ein ganz besonderes Leder häuten.",
	["En el Santuario Esmeralda, los druidas intentan sanar el bosque enfermo."] = "Im Smaragdgrünen Sanktuarium versuchen die Druiden, den kranken Wald zu heilen.",
	["En el Valle de Alterac pelean la Guardia Pico Tormenta de los enanos y el clan Lobo Gélido. Yo ya sé a quién le voy."] = "Im Alteractal kämpft die Sturmlanzengarde der Zwerge gegen den Frostwolfklan. Ich weiß schon, für wen ich bin.",
	["En el Valle de la Fuerza están el banco y la casa de subastas: el corazón del comercio de la Horda."] = "Im Tal der Stärke liegen Bank und Auktionshaus: das Herz des Handels der Horde.",
	["En el camino"] = "Auf dem Weg",
	["En el centro de aquel Kalimdor estaba el Pozo de la Eternidad, un lago de pura magia. Unos trols que vivían a su orilla cambiaron con los siglos y se volvieron los elfos de la noche."] = "Im Zentrum dieses alten Kalimdor lag der Brunnen der Ewigkeit, ein See aus reiner Magie. Trolle, die an seinem Ufer lebten, veränderten sich über die Jahrhunderte und wurden zu den Nachtelfen.",
	["En el centro de la garganta hay un enorme pozo de lava, la Caldera, donde trabajan esclavos de los Hierro Negro."] = "Mitten in der Schlucht liegt eine riesige Lavagrube, der Kessel, wo Sklaven der Dunkeleisenzwerge schuften.",
	["En el centro del cráter humea un volcán donde viven elementales de fuego."] = "In der Mitte des Kraters raucht ein Vulkan, in dem Feuerelementare leben.",
	["En el chat"] = "Im Chat",
	["En el corazón del Templo de la Luna hay un pozo lunar, donde las sacerdotisas rezan a Elune."] = "Im Herzen des Tempels des Mondes liegt ein Mondbrunnen, an dem die Priesterinnen zu Elune beten.",
	["En el cráter, un tal Linken perdió la memoria y busca su espada y su escudo: un guiño a cierto héroe de orejas puntiagudas."] = "Im Krater hat ein gewisser Linken sein Gedächtnis verloren und sucht Schwert und Schild: eine Anspielung auf einen gewissen Helden mit spitzen Ohren.",
	["En el este de las Tierras Inhóspitas viven dragones negros y sus siervos. Pasa lejitos si no llevas compañía."] = "Im Osten des Ödlands leben schwarze Drachen und ihre Diener. Halt Abstand, wenn du allein bist.",
	["En el este del lago viven ogros que les hacen la vida difícil a los enanos de Thelsamar."] = "Im Osten des Sees leben Oger, die den Zwergen von Thelsamar das Leben schwer machen.",
	["En el gran salar del este, goblins y gnomos organizan carreras; la rivalidad es feroz."] = "Auf der großen Salzebene im Osten veranstalten Goblins und Gnome Rennen; die Rivalität ist erbittert.",
	["En el juego"] = "Im Spiel",
	["En el lago de Villa del Lago hay múrlocs, ¡como en casi todo lago de Azeroth!"] = "Im See von Seenhain gibt es Murlocs, wie in fast jedem See Azeroths!",
	["En el mapa"] = "Auf der Karte",
	["En el mapa de Alfa, clic: seguirla con la flecha o guardarla como marcador."] = "Auf Alfas Karte, Klick: mit dem Pfeil folgen oder als Markierung speichern.",
	["En el mapa del mundo"] = "Auf der Weltkarte",
	["En el marco del objetivo"] = "Auf dem Zielrahmen",
	["En el minimapa"] = "Auf der Minikarte",
	["En el mundo"] = "In der Welt",
	["En el nivel 10 domas tu bestia."] = "Auf Stufe 10 zähmst du dein Tier.",
	["En el nivel 20 aprendes venenos."] = "Auf Stufe 20 lernst du Gifte.",
	["En el norte de estas tierras, la Cruzada Escarlata domina un pueblo amurallado y lo defiende con fanatismo."] = "Im Norden dieser Lande hält der Scharlachrote Kreuzzug einen ummauerten Ort und verteidigt ihn fanatisch.",
	["En el oeste de Las Mil Agujas anidan dracoleones salvajes."] = "Im Westen von Tausend Nadeln nisten wilde Wyvern.",
	["En el pueblo de los druidas del Claro de la Luna conviven Alianza y Horda: el Círculo Cenarion recibe a todos."] = "Im Druidendorf der Mondlichtung leben Allianz und Horde zusammen: Der Zirkel des Cenarius heißt alle willkommen.",
	["En el sur de Desolace, demonios y sátiros se reúnen en un aquelarre."] = "Im Süden von Desolace treffen sich Dämonen und Satyrn zu einem Hexenzirkel.",
	["En el sur de Tanaris hay colmenas de silítidos, primos de los de Silithus."] = "Im Süden von Tanaris gibt es Silithidenstöcke, Vettern derer in Silithus.",
	["En el sureste, la Mano de Tyr es la ciudad más fuerte que le queda a la Cruzada Escarlata."] = "Im Südosten ist Tyrs Hand die stärkste Stadt, die dem Scharlachroten Kreuzzug geblieben ist.",
	["En espera"] = "Wartet",
	["En esta zona"] = "In diesem Gebiet",
	["En estas laderas está Durnholde, donde Aedelas Blackmoore crió a Thrall como gladiador."] = "An diesen Hängen liegt Durnholde, wo Aedelas Schwarzmoor Thrall als Gladiator aufzog.",
	["En estas tierras cayó Anduin Lothar, el León de Azeroth, durante la Segunda Guerra."] = "In diesen Landen fiel Anduin Lothar, der Löwe von Azeroth, während des Zweiten Krieges.",
	["En estas tierras estuvo Strom, la capital de Arathor, el primer gran reino humano."] = "In diesen Landen stand einst Strom, die Hauptstadt von Arathor, dem ersten großen Menschenreich.",
	["En este pantano se hundió el Templo de Atal'Hakkar: los dragones verdes lo hundieron para frenar a los sacerdotes de Hakkar."] = "In diesem Sumpf versank der Tempel von Atal'Hakkar: Die grünen Drachen versenkten ihn, um die Priester Hakkars aufzuhalten.",
	["En grifo, la línea de tu vuelo en el mapa: por dónde vas, dónde aterrizas y el tiempo que falta."] = "Auf dem Greifen die Linie deines Flugs auf der Karte: wo du gerade bist, wo du landest und wie lange es noch dauert.",
	["En grupo"] = "In der Gruppe",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "In der Gruppe gibt es fast immer mehrere Gegner: Du triffst zwei gleichzeitig.",
	["En grupo y aguantando: Furia justa te da más amenaza."] = "In der Gruppe als Tank: Zorn der Gerechtigkeit gibt dir mehr Bedrohung.",
	["En grupo, cura al tanque antes que a nadie."] = "Heile in der Gruppe den Tank vor allen anderen.",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "Heile in der Gruppe zuerst den Tank und zieh selbst keine Monster.",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "Heile in der Gruppe, bevor die Gesundheit stark sinkt: Das ist günstiger.",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "Stell in der Gruppe deine Mana- und Heiltotems nahe der Gruppe auf.",
	["En la Arena Gurubashi aparece de vez en cuando un cofre que todos se pelean. ¡Sálvese quien pueda!"] = "In der Arena der Gurubashi taucht ab und zu eine Truhe auf, um die sich alle prügeln. Rette sich, wer kann!",
	["En la Enciclopedia"] = "In der Enzyklopädie",
	["En la Feria canjeas vales por premios; los vales se ganan entregando cosas que hiciste con tu profesión o que juntaste cazando."] = "Auf dem Jahrmarkt tauschst du Lose gegen Preise; Lose bekommst du für Dinge, die du mit deinem Beruf hergestellt oder auf der Jagd gesammelt hast.",
	["En la Feria de la Luna Negra, la adivina Sayge te hace unas preguntas y te da una fortuna que sube tus estadísticas un buen rato."] = "Auf dem Dunkelmond-Jahrmarkt stellt dir die Wahrsagerin Sayge ein paar Fragen und gibt dir ein Schicksal, das eine gute Weile deine Werte erhöht.",
	["En la Fortaleza de Grommash, Thrall recibe a quien venga; muy cerca está Eitrigg, el viejo orco amigo de Tirion."] = "In der Feste Grommash empfängt Thrall jeden, der kommt; ganz in der Nähe steht Eitrigg, der alte Orc, der sich mit Tirion anfreundete.",
	["En la Guerra de las Arenas Movedizas, el archidruida Fandral perdió a su hijo Valstann a manos de los qiraji."] = "Im Krieg der Treibsande verlor Erzdruide Fandral seinen Sohn Valstann an die Qiraji.",
	["En la Segunda Guerra, la Horda sumó a los trols Amani, a los ogros y a dragones rojos esclavizados."] = "Im Zweiten Krieg schlossen sich der Horde die Amanitrolle, die Oger und versklavte rote Drachen an.",
	["En la Semana de los Niños, los huérfanos de Ventormenta y Orgrimmar te piden que los lleves de paseo; al final te dan una mascota."] = "In der Kinderwoche bitten dich die Waisen von Sturmwind und Orgrimmar, mit ihnen Ausflüge zu machen; am Ende schenken sie dir ein Haustier.",
	["En la Tercera Guerra, orcos, humanos y elfos se unieron aquí contra Archimonde, y Nordrassil sacrificó su energía para destruirlo."] = "Im Dritten Krieg verbündeten sich hier Orcs, Menschen und Elfen gegen Archimonde, und Nordrassil opferte seine Energie, um ihn zu vernichten.",
	["En la Terraza de los Artesanos de Darnassus están los maestros de profesiones."] = "Auf der Terrasse der Handwerker in Darnassus sind die Berufslehrer.",
	["En la Vega se encuentran páginas sueltas de un libro de Nesingwary; junta un capítulo completo y llévaselo."] = "Im Schlingendorntal findet man lose Seiten eines Buchs von Nesingwary; sammle ein ganzes Kapitel und bring es ihm.",
	["En la batalla de Hyjal, Malfurion hizo sonar el Cuerno de Cenarius y miles de fuegos fatuos rodearon a Archimonde hasta destruirlo."] = "In der Schlacht am Hyjal blies Malfurion das Horn des Cenarius, und tausende Irrwische umringten Archimonde, bis er vernichtet war.",
	["En la casa de subastas, mira los precios unos días antes de vender: cambian según la hora y quién esté jugando."] = "Beobachte im Auktionshaus die Preise ein paar Tage vor dem Verkauf: Sie ändern sich je nach Uhrzeit und wer gerade spielt.",
	["En la cima del Monte Hyjal crece Nordrassil, el Árbol del Mundo, que los dragones bendijeron."] = "Auf dem Gipfel des Bergs Hyjal wächst Nordrassil, der Weltenbaum, den die Drachen gesegnet haben.",
	["En la costa de Durotar, soldados de Kul Tiras ocupan el Fuerte Tiragarde: una espina clavada en la tierra de la Horda."] = "An der Küste von Durotar halten Soldaten aus Kul Tiras die Burg Tiragarde: ein Dorn im Land der Horde.",
	["En la costa de Tanaris se esconden piratas de los Mares del Sur."] = "An der Küste von Tanaris verstecken sich Südmeerpiraten.",
	["En la costa del pantano hay naga, y no reciben bien a los curiosos."] = "An der Küste des Sumpfes gibt es Naga, und Neugierige empfangen sie nicht freundlich.",
	["En la costa este vive una tribu trol amiga de la Horda, enemiga de los trols de Jintha'Alor."] = "An der Ostküste lebt ein Trollstamm, der mit der Horde befreundet und mit den Trollen von Jintha'Alor verfeindet ist.",
	["En la costa oeste de Vallefresno, las Cavernas de Brazanegra fueron un templo de Elune; hoy están hundidas y llenas de naga."] = "An der Westküste des Eschentals war die Tiefschwarze Grotte einst ein Tempel der Elune; heute ist sie versunken und voller Naga.",
	["En la costa se ven ruinas de antiguos palacios élficos, medio hundidos en el mar."] = "An der Küste sieht man Ruinen alter Elfenpaläste, halb im Meer versunken.",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "In der Schiffshöhle sind viele Piraten: Springt nicht alle auf einmal zum Steg hinunter.",
	["En la excavación de Ironband, los troggs salieron de la tierra y se quedaron con todo."] = "An der Ausgrabungsstätte der Eisenbands kamen die Troggs aus der Erde und haben alles übernommen.",
	["En la granja de los Saldean, la vieja yegua Blanchy necesita avena. Es de las misiones más tiernitas de los Páramos."] = "Auf dem Hof der Saldeans braucht die alte Stute Blanchy Hafer. Eine der süßesten Quests in Westfall.",
	["En la guarida de Onyxia, a los lados hay nidos con huevos: si alguien los pisa salen dragoncitos... muchísimos."] = "In Onyxias Hort liegen an den Seiten Nester mit Eiern: Wenn jemand drauftritt, schlüpfen Welpen... jede Menge.",
	["En la pelea, el juego te avisa"] = "Im Kampf warnt dich das Spiel",
	["En la sala de la Liga de Expedicionarios de Forjaz hay biblioteca, mapas y un museo con fósiles gigantes."] = "In der Halle der Forscherliga in Eisenschmiede gibt es eine Bibliothek, Karten und ein Museum mit riesigen Fossilien.",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "Tötet sie im zweiten Teil zuerst: Sie heilt viel.",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "Beim Auktionshaus zählt der niedrigste gesehene Preis abzüglich des Anteils (%d%%, geschätzt). Beim Entzaubern nutzt Alfa Tabellen aus dem klassischen Spiel, ebenfalls geschätzt.",
	["En la subasta, unos %s."] = "Im Auktionshaus etwa %s.",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "Im Fenster und hier. Wenn du nicht dabei bist, erscheint deine Zeile am Ende.",
	["En las Cuevas de los Lamentos, el druida Naralex soñó con devolverle el verdor a Los Baldíos, y su sueño se volvió pesadilla."] = "In den Höhlen des Wehklagens träumte der Druide Naralex davon, das Brachland wieder ergrünen zu lassen, und sein Traum wurde zum Albtraum.",
	["En las Guerras Trol, los altos elfos enseñaron magia a cien humanos para vencer juntos a los Amani. Fueron los primeros magos de la humanidad."] = "In den Trollkriegen lehrten die Hochelfen hundert Menschen Magie, um gemeinsam die Amani zu besiegen. Sie waren die ersten Magier der Menschheit.",
	["En las Mazmorras de Ventormenta los presos se amotinaron, y la guardia pide ayuda para calmar el desastre."] = "Im Verlies von Sturmwind haben die Gefangenen gemeutert, und die Wache bittet um Hilfe, das Chaos zu beruhigen.",
	["En las Pozas de la Visión, bajo una de las mesetas, entrenan los magos y sacerdotes Renegados."] = "In den Teichen der Visionen unter einer der Hochebenen üben die Magier und Priester der Verlassenen.",
	["En las cuevas de Cuna del Invierno viven yetis peludos y gruñones."] = "In den Höhlen von Winterquell leben zottelige, grummelige Yetis.",
	["En las cuevas de Feralas viven yetis, y los ogros Gordunni tienen sus campamentos en el norte."] = "In den Höhlen von Feralas leben Yetis, und die Gordunni-Oger haben ihre Lager im Norden.",
	["En las cuevas nevadas de Dun Morogh viven trols de las nieves que no quieren a los enanos ni tantito."] = "In den verschneiten Höhlen von Dun Morogh leben Eistrolle, die Zwerge kein bisschen mögen.",
	["En las dos armas"] = "Auf beiden Waffen",
	["En las granjas del oeste hay calderos de la Plaga que siguen esparciendo la peste; la Alianza manda aventureros a destruirlos."] = "Auf den Höfen im Westen verbreiten Kessel der Geißel weiter die Seuche; die Allianz schickt Abenteurer, um sie zu zerstören.",
	["En las ruinas de la ciudad de Alterac hoy mandan los ogros y el Sindicato, la banda de nobles caídos del viejo reino."] = "In den Ruinen von Alterac herrschen heute die Oger und das Syndikat, die Bande gefallener Adliger des alten Königreichs.",
	["En lo alto de la sierra hay un pico sagrado para los druidas elfos, donde anidan aves enormes."] = "Hoch oben im Gebirge liegt ein Gipfel, der den Druiden der Elfen heilig ist und auf dem riesige Vögel nisten.",
	["En lo más alto de la Montaña Roca Negra manda Nefarian, hijo de Alamuerte."] = "Ganz oben im Schwarzfels herrscht Nefarian, Sohn von Todesschwinge.",
	["En los mapas"] = "Auf den Karten",
	["En lugar de las del juego"] = "Statt der des Spiels",
	["En marcha"] = "Läuft",
	["En marcha hacia %s"] = "Unterwegs nach %s",
	["En mazmorra"] = "Im Dungeon",
	["En mazmorras y bandas"] = "In Dungeons und Schlachtzügen",
	["En memoria"] = "In Erinnerung",
	["En memoria de una gran perrita"] = "In Erinnerung an eine wunderbare kleine Hündin",
	["En mi zona"] = "In meinem Gebiet",
	["En movimiento"] = "Bewegt",
	["En orco, «Lok'tar ogar» quiere decir «victoria o muerte»."] = "Auf Orcisch bedeutet „Lok'tar ogar“ „Sieg oder Tod“.",
	["En otra zona: %s"] = "In einem anderen Gebiet: %s",
	["En pantalla"] = "Auf dem Bildschirm",
	["En pausa"] = "Pausiert",
	["En pausa dentro de la instancia"] = "Pausiert in der Instanz",
	["En pausa por ahora"] = "Vorerst pausiert",
	["En pausa: hay otro addon de pesca activo"] = "Pausiert: Ein anderes Angel-Addon ist aktiv",
	["En plena Segunda Guerra, Gul'dan abandonó a la Horda para buscar la Tumba de Sargeras. Ahí lo despedazaron los demonios que encontró."] = "Mitten im Zweiten Krieg verließ Gul'dan die Horde, um das Grabmal des Sargeras zu suchen. Dort rissen ihn die Dämonen in Stücke, die er fand.",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "In Gasthäusern und Städten sammelst du Ruhebonus: Du bekommst doppelte EP pro Gegner, bis er aufgebraucht ist. Wenn du dich hier ausloggst, sammelt er sich auch.",
	["En posadas y ciudades juntas XP descansada: ganas el doble por enemigo hasta gastarla."] = "In Gasthäusern und Städten sammelst du Ruhebonus: doppelte EP pro Gegner, bis er aufgebraucht ist.",
	["En qué orden aparecen."] = "In welcher Reihenfolge sie erscheinen.",
	["En qué se gastan"] = "Wofür man sie ausgibt",
	["En silencio"] = "Stumm",
	["En solitario es lento: usa la varita para rematar."] = "Solo ist es langsam: Nutze deinen Zauberstab zum Erledigen.",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "Solo: Setz Heilungen über Zeit und kämpf mit Zorn.",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "Solo: Kämpf mit Schocks und heil dich zwischen den Monstern.",
	["En su ficha toca «Agregar a mi ruta»."] = "Klick in seinem Eintrag auf „Zu meiner Route hinzufügen“.",
	["En sus inicios, una batalla del Valle de Alterac podía durar horas... ¡y hasta días!"] = "Anfangs konnte eine Schlacht im Alteractal Stunden dauern... und sogar Tage!",
	["En tu arma"] = "Auf deiner Waffe",
	["En tu marco"] = "Auf deinem Rahmen",
	["En tu plan"] = "In deinem Plan",
	["En tu registro"] = "In deinem Questlog",
	["En tus bolsas"] = "In deinen Taschen",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "In deinen Taschen, in der Beute, im Chat oder bei jedem Link: Alt+Klick öffnet den Guide, um es zu bekommen, oder, falls es keinen gibt, seinen Eintrag in der Enzyklopädie.",
	["En tus bolsas: úsala para aprenderla"] = "In deinen Taschen: Benutze es, um es zu erlernen",
	["En un aviso"] = "Als Hinweis",
	["En un aviso y en el chat"] = "Als Hinweis und im Chat",
	["En un cañón de Vallefresno, Grom mató al señor demonio Mannoroth y liberó a los orcos de su sangre maldita."] = "In einer Schlucht im Eschental tötete Grom den Dämonenfürsten Mannoroth und befreite die Orcs von seinem verfluchten Blut.",
	["En un valle de Frondavil cayeron infernales del cielo, y todavía se ven sus cráteres."] = "In ein Tal des Teufelswalds stürzten Höllenbestien vom Himmel, und ihre Krater sind noch zu sehen.",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "Bei einem Flug mit Zwischenstopps zeigt eine Zeile unter dem Timer, wo der nächste Halt ist und wie lange es noch dauert. Dafür muss der Flug-Timer an sein.",
	["En una aldea del sur del bosque, los vecinos parecen normales de día... y de noche se convierten en worgen."] = "In einem Dorf im Süden des Waldes wirken die Bewohner tagsüber normal... und nachts werden sie zu Worgen.",
	["En una de las mesetas, los tauren honran a los espíritus de sus ancestros."] = "Auf einer der Hochebenen ehren die Tauren die Geister ihrer Ahnen.",
	["En una instancia: la flecha vuelve al salir"] = "In einer Instanz: Der Pfeil kommt zurück, wenn du sie verlässt",
	["En una isla de Azshara vive el duque Hydraxis, señor del agua; su gente te ayuda a apagar las runas del Núcleo de Magma."] = "Auf einer Insel vor Azshara lebt Herzog Hydraxis, ein Herr des Wassers; seine Leute helfen dir, die Runen des Geschmolzenen Kerns zu löschen.",
	["En una pestaña nueva"] = "In einem neuen Tab",
	["En unos segundos aparece tu build."] = "In ein paar Sekunden erscheint dein Build.",
	["En uso"] = "In Verwendung",
	["En uso, a tu gusto"] = "In Verwendung, nach deinem Geschmack",
	["En vivo"] = "Live",
	["En vivo si estás con un banquero; si no, la última foto."] = "Live, wenn du bei einem Bankier bist; sonst der letzte Stand.",
	["En vuelo a %s"] = "Flug nach %s",
	["En vuelo: la flecha sigue al bajar"] = "Im Flug: Der Pfeil geht nach der Landung weiter",
	["En vuelo: la flecha sigue al bajar."] = "Im Flug: Der Pfeil macht nach der Landung weiter.",
	["Enanos"] = "Zwerge",
	["Encanta tu arma antes de pelear."] = "Verzaubere deine Waffe vor dem Kampf.",
	["Encantada"] = "Verzaubert",
	["Encantamiento"] = "Verzauberkunst",
	["Encantar a otros es un servicio: anúnciate en el chat de comercio de la ciudad."] = "Für andere zu verzaubern ist eine Dienstleistung: Biete sie im Handelschat der Stadt an.",
	["Encender el registro"] = "Aufzeichnung einschalten",
	["Encender la pesca"] = "Angeln einschalten",
	["Encender las recomendadas"] = "Die empfohlenen einschalten",
	["Encender una fogata"] = "Ein Lagerfeuer entzünden",
	["Encenderla"] = "Einschalten",
	["Encenderlos"] = "Einschalten",
	["Encendida: entra al plan aunque el filtro la deje fuera. Apagada: queda fuera."] = "An: Sie kommt in den Plan, auch wenn der Filter sie auslässt. Aus: Sie bleibt draußen.",
	["Encendido"] = "An",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "An: Ein Doppelklick beim Angeln wirft erneut aus, mit Umschalt, Strg oder Alt holst du ein. Aus: umgekehrt.",
	["Enciclopedia"] = "Enzyklopädie",
	["Enciende las comodidades recomendadas"] = "Schalte die empfohlenen Komfortfunktionen ein",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "Schaltet die Änderungen unten für den Tooltip ein, der erscheint, wenn du mit der Maus über einen Charakter oder eine Kreatur fährst.",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "Schaltet die Änderungen unten für die Anprobe ein (Strg + Klick auf einen Gegenstand).",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "Schaltet die Änderungen unten ein; jede lässt sich einzeln ausschalten. Manche Addons passen ihre Knöpfe erst nach /reload an die eckige Form an.",
	["Enciende primero la guía en el minimapa."] = "Schalte zuerst den Guide auf der Minikarte ein.",
	["Enciende primero los servicios."] = "Schalte zuerst die Dienste ein.",
	["Enciéndela para ver en combate qué habilidad conviene ahora y cuáles siguen, en un ícono pequeño que puedes mover."] = "Schalte sie ein, um im Kampf zu sehen, welche Fähigkeit jetzt am besten ist und welche folgen, in einem kleinen, verschiebbaren Symbol.",
	["Enciéndelo en el menú del juego: Opciones > %s > «%s». Alfa no lo cambia por ti: el medidor del juego lo lee en combate y fallaría."] = "Schalte es im Spielmenü ein: Optionen > %s > „%s“. Alfa ändert es nicht für dich: Der Schadensmesser des Spiels liest es im Kampf und würde dabei fehlschlagen.",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "Schalte sie unten unter „Rahmen“ ein, um die Gesundheit deiner Gruppe zu sehen und mit einem Klick zu heilen.",
	["Enciéndelos en la página Curación."] = "Schalte sie auf der Seite Heilung ein.",
	["Enciéndelos para ver a tu grupo con su vida y curar con un clic."] = "Schalte sie ein, um die Gesundheit deiner Gruppe zu sehen und mit einem Klick zu heilen.",
	["Enemigo raro"] = "Seltener Gegner",
	["Enemigos menores"] = "Unbedeutende Gegner",
	["Enfoque interno: tu siguiente hechizo es gratis y más crítico."] = "Innerer Fokus: Dein nächster Zauber ist kostenlos und trifft öfter kritisch.",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "Wurzle das Monster fest und geh auf Abstand, bevor du deine langen Zauber wirkst.",
	["Entendido"] = "Verstanden",
	["Entereza"] = "Seelenstärke",
	["Entorno"] = "Umgebung",
	["Entra al juego con él una vez."] = "Logg dich einmal mit ihm ein.",
	["Entra con el registro limpio: entrega lo que ya tienes."] = "Geh mit leerem Questlog rein: Gib ab, was du schon hast.",
	["Entra en el plan que termina y entrega tus misiones por el camino más corto, con lo que pide antes."] = "Kommt in den Plan, der deine Quests auf dem kürzesten Weg abschließt und abgibt, samt dem, was sie vorher braucht.",
	["Entrada"] = "Eingang",
	["Entrada enemiga"] = "Feindlicher Eingang",
	["Entradas de mazmorras"] = "Dungeon-Eingänge",
	["Entradas en el minimapa"] = "Eingänge auf der Minikarte",
	["Entradas y salidas"] = "Ein- und Ausgänge",
	["Entraron %s, con lo que piden antes de entregarlas."] = "%s sind dazugekommen, samt dem, was sie vor der Abgabe brauchen.",
	["Entraste a %s"] = "Du hast %s betreten",
	["Entraste a %s."] = "Du hast %s betreten.",
	["Entrañas son las criptas y catacumbas bajo la antigua capital de Lordaeron."] = "Unterstadt besteht aus den Krypten und Katakomben unter der alten Hauptstadt Lordaerons.",
	["Entrañas tiene barrios para magos, pícaros, guerreros y boticarios, y en el anillo central están el banco y la casa de subastas."] = "Unterstadt hat Viertel für Magier, Schurken, Krieger und Apotheker, und im mittleren Ring liegen Bank und Auktionshaus.",
	["Entre Entrañas y Grom'gol también hay zepelín: así bajas al sur sin cruzar todo el continente."] = "Zwischen Unterstadt und Grom'gol gibt es auch einen Zeppelin: So kommst du in den Süden, ohne den ganzen Kontinent zu durchqueren.",
	["Entre los druidas están los de la Garra, que se vuelven osos, y los del Espolón, que toman forma de cuervo."] = "Unter den Druiden gibt es die Druiden der Klaue, die zu Bären werden, und die Druiden der Kralle, die die Gestalt eines Raben annehmen.",
	["Entrega tus %d misiones listas"] = "Gib deine %d fertigen Quests ab",
	["Entregada"] = "Abgegeben",
	["Entregar"] = "Abgeben",
	["Entregar %s"] = "%s abgeben",
	["Entregar las completadas"] = "Abgeschlossene abgeben",
	["Entregar las misiones de tu guía"] = "Quests deines Guides abgeben",
	["Entregar mis misiones"] = "Meine Quests abgeben",
	["Entregar misiones"] = "Quests abgeben",
	["Entregar solas las misiones de la guía"] = "Quests des Guides automatisch abgeben",
	["Entregar todas"] = "Alle abgeben",
	["Entregarla"] = "Abgeben",
	["Entregarlas ahora"] = "Jetzt abgeben",
	["Entrenador"] = "Lehrer",
	["Entrenador al día"] = "Lehrer: alles gelernt",
	["Entrenador de %s"] = "Lehrer für %s",
	["Entrenador de tu clase"] = "Lehrer deiner Klasse",
	["Entrenador: %s, en %s."] = "Lehrer: %s, in %s.",
	["Entrenador: %s."] = "Lehrer: %s.",
	["Entrenadores de profesión"] = "Berufslehrer",
	["Entrenar"] = "Trainieren",
	["Entrenar la rápida"] = "Das schnelle trainieren",
	["Entrégala a %s."] = "Gib sie bei %s ab.",
	["Entró %s, con lo que pide antes de entregarla."] = "%s ist dazugekommen, samt dem, was sie vor der Abgabe braucht.",
	["Envenena y lanza rayos: quita el veneno si puedes."] = "Er vergiftet und wirkt Blitze: Entferne das Gift, wenn du kannst.",
	["Equilibrada"] = "Ausgewogen",
	["Equilibrado"] = "Ausgewogen",
	["Equilibrado: se ve bien y corre bien en casi cualquier equipo."] = "Ausgewogen: sieht gut aus und läuft auf fast jedem Rechner flüssig.",
	["Equilibrio"] = "Gleichgewicht",
	["Equilibrio para subir"] = "Gleichgewicht zum Leveln",
	["Equipa tu caña de pescar"] = "Leg deine Angelrute an",
	["Equipo"] = "Ausrüstung",
	["Equipo %d %%"] = "Ausrüstung %d %%",
	["Equipo a punto de romperse."] = "Ausrüstung fast kaputt.",
	["Equipo de pesca"] = "Angelausrüstung",
	["Equipo y cebos"] = "Ausrüstung und Köder",
	["Equipo y estadísticas"] = "Ausrüstung und Werte",
	["Equipo, consumibles, misiones, materiales... con encabezados que se pliegan."] = "Ausrüstung, Verbrauchsgüter, Questgegenstände, Materialien... unter einklappbaren Überschriften.",
	["Equitación"] = "Reiten",
	["Equitación de aprendiz (nivel 40)"] = "Reiten (Lehrling, Stufe 40)",
	["Equitación de oficial (la rápida, nivel 60)"] = "Reiten (Geselle, das schnelle, Stufe 60)",
	["Eranikus, el consorte de Ysera, quedó atrapado en la pesadilla; su sombra ronda el Templo de Atal'Hakkar."] = "Eranikus, Yseras Gefährte, ist im Albtraum gefangen; sein Schatten spukt im Tempel von Atal'Hakkar.",
	["Eres de la manada"] = "Du bist im Rudel",
	["Eres nivel %d"] = "Du bist Stufe %d",
	["Eres nivel %d y se recomienda el %d: desde ahí cuenta así."] = "Du bist Stufe %d, empfohlen ist Stufe %d: Ab da sieht die Rechnung so aus.",
	["Eres nivel %d."] = "Du bist Stufe %d.",
	["Error"] = "Fehler",
	["Errores de Lua de Alfa en esta sesión:"] = "Lua-Fehler von Alfa in dieser Sitzung:",
	["Errores de Lua de Alfa en esta sesión: ninguno"] = "Lua-Fehler von Alfa in dieser Sitzung: keine",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "Kurzer Dungeon mitten in Sturmwind. Die Gefangenen sitzen in Zellen an den Seiten: Geht langsam vor.",
	["Es de la otra facción"] = "Gehört zur anderen Fraktion",
	["Es de una misión."] = "Questgegenstand.",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "Diesen Boss verlangt eine Quest der Allianz: Prüf deine Quests, bevor du reingehst.",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "Der erste Boss und ein einfacher. Wenn er stirbt, öffnet der Gefangene deiner Fraktion die Tür zum Hof.",
	["Es el primer reto: con él se abre el Legado."] = "Es ist die erste Herausforderung: Mit ihr wird das Vermächtnis freigeschaltet.",
	["Es el punto %d de %d de tu build."] = "Es ist Punkt %d von %d deines Builds.",
	["Es el que toca ahora."] = "Dieses ist jetzt dran.",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "Der letzte Boss des Friedhofs. Er schleudert Flammen um sich: Wenn du auf Distanz kämpfst, bleib weg.",
	["Es el único lobo a la vista."] = "Das ist der einzige Wolf in Sicht.",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "Groß, und man verirrt sich leicht: Folgt einer einzigen Person und lauft nicht allein los.",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "Das ist Sneeds Maschine: Zerstört sie, dann kommt er zum Kämpfen heraus.",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "Der erste Dungeon der Horde: kurz und gut, um Gruppenspiel zu lernen.",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "Der erste große Dungeon der Allianz: Geht langsam vor und zieht eine Gruppe nach der anderen.",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "Lang, mit zwei Eingängen. Viele Gegner sind aus Stein und schlagen hart zu.",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "Lang, mit vielen Robotern: Manche legen Bomben oder lösen Alarme aus, die mehr Gegner herbeirufen.",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "Er ist langsam: Wenn du auf Distanz kämpfst, greif ihn an, während er näher kommt.",
	["Es muy veloz: frénalo si tu clase puede."] = "Er ist sehr schnell: Verlangsame ihn, wenn deine Klasse das kann.",
	["Es opcional. Si dices que sí, los lobos de La Jauría que usan Alfa ven a tu personaje en el mapa de WoW, como ves a tu grupo, y pueden llegar a donde estás con la flecha; y tú a ellos. Alfa solo comparte dónde anda tu personaje dentro del juego: la zona, el punto en el mapa, su nivel y su clase. Nada de tu ubicación real, tu computadora ni tu cuenta."] = "Es ist freiwillig. Wenn du Ja sagst, sehen die Wölfe von La Jauría, die Alfa nutzen, deinen Charakter auf der WoW-Karte, so wie du deine Gruppe siehst, und können mit dem Pfeil zu dir finden; und du zu ihnen. Alfa teilt nur, wo dein Charakter im Spiel unterwegs ist: die Zone, den Punkt auf der Karte, seine Stufe und Klasse. Nichts über deinen echten Standort, deinen Computer oder deinen Account.",
	["Es opcional: tu personaje aparece en el mapa de WoW de los lobos de La Jauría que usan Alfa, y ellos en el tuyo, para encontrarse y llegar con la flecha. Solo se comparte dónde anda tu personaje dentro del juego (zona, punto en el mapa, nivel y clase), nunca tu ubicación real ni nada de tu computadora, y nunca dentro de mazmorras. Va por un canal oculto que no sale en el chat, aunque alguien que entre a él con otro addon podría verlo. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "Es ist freiwillig: Dein Charakter erscheint auf der WoW-Karte der Wölfe von La Jauría, die Alfa nutzen, und sie auf deiner, damit ihr euch findet und mit dem Pfeil hinkommt. Geteilt wird nur, wo dein Charakter im Spiel ist (Zone, Punkt auf der Karte, Stufe und Klasse), nie dein echter Standort oder etwas von deinem Computer und nie in Dungeons. Es läuft über einen versteckten Kanal, der nicht im Chat erscheint, auch wenn jemand, der ihm mit einem anderen Addon beitritt, es sehen könnte. Deine Gruppe siehst du immer. Du änderst es jederzeit in La Jauría.",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "Er ist für Stufen %s, und du bist %d: Dir fehlen %d Stufen.",
	["Es para otra raza."] = "Sie ist für ein anderes Volk.",
	["Es raro del Cementerio y no siempre aparece."] = "Seltener Gegner auf dem Friedhof, nicht immer da.",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "Seltener Gegner auf dem Friedhof, nicht immer da. Er vergiftet: Entferne das Gift.",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "Seltener Gegner auf dem Friedhof, nicht immer da. Er kann Zauberwirker zum Schweigen bringen.",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "Selten und nur ab und zu da. Er setzt Feuer um sich herum ein.",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "Selten und in einer versteckten Höhle. Eine Fledermaus, die schnell zuschlägt.",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "Selten und nicht immer da. Er schlägt für seine Stufe sehr hart zu: Zieht ihn vorsichtig.",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "Selten und nicht immer da. Er trifft alle vor ihm hart.",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "Selten. Er stellt ein Erdtotem auf: Zerstör es.",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "Selten: nicht immer da. Er schläfert Spieler ein und explodiert mit Magie um sich herum.",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "Ein einfacher: guter Moment, vor dem letzten Boss etwas zu trinken.",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "Er ist ein Zauberwirker: Unterbrich ihn, wenn deine Klasse kann (Tritt, Schildhieb, Erdschock...).",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "Ein Schamane mit Totems: Zerstört die Totems, sie sind leicht zu töten.",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "Ein Zwerg mit Schild: hält viel aus, hat aber keine Tricks.",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "Ein starker Gegner in der Mine: Behandelt ihn wie einen kleinen Boss.",
	["Es un grupo: cada uno suelta su propio botín."] = "Es ist eine Gruppe: Jeder lässt seine eigene Beute fallen.",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "Er ist ein Paladin und heilt sich mit Heiligem Licht. Unterbrich seine Heilung.",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "Ein schneller Satyr, der vergiftet: Wenn deine Klasse Gifte entfernen kann, nutze es.",
	["Es un trogg que lanza rayos: interrúmpelo."] = "Ein Trogg, der Blitze wirkt: Unterbrich ihn.",
	["Es una mejora para ti"] = "Das ist ein Upgrade für dich",
	["Es una montura de tu clase: pregunta a tu instructor de clase cuándo y cómo se consigue."] = "Es ist ein Reittier deiner Klasse: Frag deinen Klassenlehrer, wann und wie du es bekommst.",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "Eine riesige Schildkröte mit viel Rüstung: schlägt langsam, aber hart zu.",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "Eine sehr zähe Schildkröte, die aber nur zuschlägt: keine Tricks.",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "Dieser Text enthält keinen Wert, den Alfa bewertet.",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "Diese Reihe ist noch nicht offen: Dir fehlen Punkte in diesem Zweig.",
	["Esa tecla ya tiene dueño"] = "Diese Taste ist schon belegt",
	["Esbirros enemigos"] = "Gegnerische Diener",
	["Escala de estadísticas"] = "Werteskala",
	["Escalas:"] = "Zwischenstopps:",
	["Escaneando..."] = "Scanne...",
	["Escanear ahora"] = "Jetzt scannen",
	["Escanear con Alfa"] = "Mit Alfa scannen",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "Vollständiger Scan: %s Gegenstände mit Preis (%s Auktionen).",
	["Escarcha"] = "Frost",
	["Escarcha para subir"] = "Frost zum Leveln",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "Blendet beim Angeln Namensplaketten und NPC-Namen aus (feindliche Gegner behalten ihren Namen), damit du den Schwimmer besser siehst und triffst.",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "Blendet aus, was mehr Fertigkeit braucht, als du hast. Ohne diese Option erscheint es grau und blass.",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "Gib %s ein oder klick auf den Wolf an der Minikarte, um es zu öffnen. Es startet auf Heute, mit dem, was deine Klasse braucht; %s blendet das Guide-Fenster ein oder aus.",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "Gib %s ein und sag uns auf dem Discord von La Jauría Bescheid.",
	["Escribe al menos dos letras."] = "Gib mindestens zwei Buchstaben ein.",
	["Escribe arriba el nombre de una mazmorra para buscarla."] = "Gib oben den Namen eines Dungeons ein, um ihn zu suchen.",
	["Escribe cuánto oro (1 o más)."] = "Gib ein, wie viel Gold (1 oder mehr).",
	["Escribe el número que quieras y presiona Enter."] = "Gib die gewünschte Zahl ein und drück Enter.",
	["Escribe el top %d en el chat de tu grupo o banda."] = "Schreibt das Top %d in den Chat deiner Gruppe oder deines Schlachtzugs.",
	["Escribe en el chat del grupo cuando terminas un objetivo de una misión compartida. Viene apagado para no llenar el chat de nadie."] = "Schreibt in den Gruppenchat, wenn du ein Ziel einer geteilten Quest erfüllst. Standardmäßig aus, damit niemandes Chat überläuft.",
	["Escribe tu nota."] = "Schreib deine Notiz.",
	["Escribe un nivel (2 o más)."] = "Gib eine Stufe ein (2 oder mehr).",
	["Escribe un nombre corto para reconocerla."] = "Gib einen kurzen Namen ein, an dem du sie erkennst.",
	["Escribir a %s"] = "An %s schreiben",
	["Escuchar"] = "Anhören",
	["Escuchar el aullido"] = "Heulen anhören",
	["Escudo"] = "Schild",
	["Escudo de relámpagos"] = "Blitzschlagschild",
	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "Schild und Verteidigung: Du hältst alle Monster, damit deine Gruppe nicht leidet.",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "Schild und heiliges Licht: ein sehr zäher Tank, der sein eigenes Mana zurückholt.",
