	["Este cliente no deja compartir"] = "Dieser Client erlaubt kein Teilen",
	["Este cliente no deja compartir marcadores."] = "Dieser Client erlaubt kein Teilen von Markierungen.",
	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "Dieser Client kann deine Belegung nicht selbst kopieren: Blizzards Klickzauber-Fenster wurde geöffnet, damit du sie dort einrichtest.",
	["Este cliente no tiene %d de estos ajustes: no se muestran."] = "Diesem Client fehlen %d dieser Einstellungen: Sie werden nicht angezeigt.",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "Dieser Client hat keine Klickzauber von Blizzard. Deine Klicks funktionieren in Alfas Rahmen.",
	["Este paso"] = "Dieser Schritt",
	["Este paso no tiene punto en el mapa."] = "Dieser Schritt hat keinen Punkt auf der Karte.",
	["Este paso une el Bosque del Ocaso con el Pantano de las Penas, y casi todos lo cruzan sin detenerse."] = "Dieser Pass verbindet den Dämmerwald mit den Sümpfen des Elends, und fast alle durchqueren ihn ohne Halt.",
	["Este talento no está en tu build."] = "Dieses Talent ist nicht in deinem Build.",
	["Este tramo quedó vacío."] = "Diese Etappe ist leer geblieben.",
