	["Estilo y sonido"] = "Stil und Klang",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "Das lässt sich im Kampf nicht ändern. Versuch es nach dem Kampf.",
	["Esto no se puede vincular."] = "Das lässt sich nicht verlinken.",
	["Estos filtros los dibuja Alfa, no el juego: quedan detrás de toda la interfaz (nunca la tapan) y también se ven con la interfaz oculta (Alt+Z), para tus capturas."] = "Diese Filter zeichnet Alfa, nicht das Spiel: Sie liegen hinter der ganzen Oberfläche (verdecken sie nie) und sind auch bei ausgeblendeter Oberfläche (Alt+Z) zu sehen, für deine Screenshots.",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "Er ist auf dem Friedhof. Er wirkt einen Schattenschmerz, der mit der Zeit Schaden macht.",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "Er ist im Wasser am Wasserfall: Lockt ihn an Land, bevor ihr kämpft.",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "In der Waffenkammer. Wenn er schreit, wirbelt er mit seiner Axt und trifft alle in der Nähe: Geh weg.",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "In der Bibliothek, mit seinen Hunden: Tötet sie zuerst oder nutzt Flächenangriffe.",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "Versteckt in der Kathedrale. Er verflucht und heilt sich: Unterbrich ihn.",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "Voller Stacheleber in Dornentunneln: Zieht nur wenige auf einmal.",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "Um ihn herum arbeiten Goblins: Zieht zuerst die Goblins, einen nach dem anderen.",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "Murlocs umgeben ihn: Zieht seine Freunde vor ihm.",
	["Estás aquí"] = "Du bist hier",
	["Estás con un banquero: desde su ventana depositas lo que quieras con un clic."] = "Du bist bei einem Bankier: In seinem Fenster lagerst du mit einem Klick ein, was du willst.",
	["Estás dentro"] = "Du bist drinnen",
	["Estás descansando"] = "Du erholst dich",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "Du bist im Kampf. Talente lassen sich nur außerhalb des Kampfes ändern: Beende den Kampf und versuch es erneut.",
	["Estás en combate: busca el equipo al terminar la pelea."] = "Du bist im Kampf: Such die Ausrüstung, wenn der Kampf vorbei ist.",
	["Estás en combate: lo que cambies se aplica al salir."] = "Du bist im Kampf: Änderungen gelten, sobald du ihn verlässt.",
	["Estás en combate: lo que cambies se aplica en cuanto termine."] = "Du bist im Kampf: Was du änderst, wird angewendet, sobald er vorbei ist.",
	["Estás en combate: se aplica en cuanto termine."] = "Du bist im Kampf: Es wird angewendet, sobald er vorbei ist.",
	["Estás en combate: tus cambios se aplican en cuanto termine."] = "Du bist im Kampf: Deine Änderungen werden angewendet, sobald er vorbei ist.",
	["Estás en grupo y otro aguanta al enemigo: apuñálalo por la espalda."] = "Du bist in einer Gruppe und jemand anderes hält den Gegner: Meuchle ihn.",
