	["Furia desatada"] = "Entfesselter Furor",
	["Furia para grupo"] = "Furor für Gruppen",
	["Furia para pelear contra jugadores: muchísimo daño, Ira rabiosa mejorada contra el miedo e Interceptar más seguido para no soltar al rival."] = "Furor für den Kampf gegen Spieler: enorm viel Schaden, Verbesserte Berserkerwut gegen Furcht und öfter Abfangen, damit du den Gegner nicht loslässt.",
	["Furia sangrienta te da más ira para empezar peleas difíciles."] = "Blutrausch gibt dir mehr Wut, um schwere Kämpfe zu beginnen.",
