	["Golpe siniestro: suma puntos de combo."] = "Finsterer Stoß: baut Combopunkte auf.",
	["Golpea a los que tiene alrededor: gíralo lejos del grupo."] = "Er trifft alle um sich herum: Dreh ihn von der Gruppe weg.",
	["Golpea a todos los que están cerca y los avienta: si peleas cuerpo a cuerpo, cuida tu vida."] = "Er trifft alle in der Nähe und schleudert sie weg: Wenn du im Nahkampf kämpfst, achte auf deine Gesundheit.",
	["Golpea a todos los que tiene enfrente: ataca desde su espalda si peleas cuerpo a cuerpo."] = "Er trifft alle vor ihm: Greif von hinten an, wenn du im Nahkampf kämpfst.",
	["Golpea a todos los que tiene enfrente: si peleas cuerpo a cuerpo, ataca por detrás."] = "Er trifft alle vor ihm: Im Nahkampf greifst du von hinten an.",
	["Golpea a varios enemigos a tu alrededor."] = "Trifft mehrere Gegner um dich herum.",
	["Golpea fuerte con su cuchilla y hace sangrar: vigila la vida del tanque."] = "Er schlägt hart mit seinem Hackbeil zu und verursacht Blutungen: Achte auf die Gesundheit des Tanks.",
	["Golpea y avienta al tanque: regresa a tu lugar rápido."] = "Er schlägt den Tank weg: Kehr schnell an deinen Platz zurück.",
	["Golpea y frena a todos los enemigos que tienes cerca."] = "Trifft und verlangsamt alle Gegner in deiner Nähe.",
	["Golpeas a dos a la vez: puedes juntar monstruos de dos en dos."] = "Du triffst zwei gleichzeitig: Du kannst Monster zu zweit ziehen.",
	["Golpes de tu mascota"] = "Nahkampftreffer deines Begleiters",
	["Gracias por dejarme acompañarte."] = "Danke, dass ich dich begleiten darf.",
	["Grafito"] = "Graphit",
	["Grafito con esquinas cortadas y el verde de La Jauría. El de siempre."] = "Graphit mit abgeschrägten Ecken und dem Grün von La Jauría. Der Bewährte.",
	["Gran aumento de daño para los jefes."] = "Großer Schadensschub gegen Bosse.",
	["Gran aumento de daño y te libra del miedo."] = "Großer Schadensschub, und er befreit dich von Furcht.",
	["Gran aumento de daño."] = "Großer Schadensschub.",
	["Gran golpe de escudo con mucha amenaza."] = "Ein großer Schildschlag mit viel Bedrohung.",
	["Grano"] = "Körnung",
	["Grano de película"] = "Filmkörnung",
	["Gratis"] = "Kostenlos",
	["Gratis tras vencer a un enemigo, y te cura."] = "Kostenlos nach einem besiegten Gegner, und er heilt dich.",
	["Grifos"] = "Greifen",
	["Grim Batol fue una ciudad enana. Después, los orcos Faucedraco la usaron para tener presa a Alexstrasza, la Reina Dragón."] = "Grim Batol war eine Zwergenstadt. Später nutzten die Orcs vom Drachenmalklan sie, um Alexstrasza, die Drachenkönigin, gefangen zu halten.",
	["Grito de batalla"] = "Schlachtruf",
	["Grito de batalla para el guerrero; Intelecto Arcano y una armadura para el mago; Entereza y Fuego interno para el sacerdote; y lo suyo para cada clase."] = "Schlachtruf für Krieger; Arkane Intelligenz und eine Rüstung für Magier; Seelenstärke und Inneres Feuer für Priester; und das Passende für jede Klasse.",
	["Grom Grito Infernal fue el primer jefe orco en beber la sangre de Mannoroth, y así ató a su pueblo a los demonios."] = "Grom Höllschrei war der erste Orcanführer, der Mannoroths Blut trank, und band so sein Volk an die Dämonen.",
	["Grom Grito Infernal y Varian Wrynn son guerreros legendarios de la historia."] = "Grom Höllschrei und Varian Wrynn sind legendäre Krieger der Geschichte.",
	["Grom'gol es el campamento de la Horda en la Vega, con zepelines a Orgrimmar y a Entrañas."] = "Grom'gol ist das Lager der Horde im Schlingendorntal, mit Zeppelinen nach Orgrimmar und Unterstadt.",
	["Grupo"] = "Gruppe",
	["Grupo de %d"] = "Gruppe mit %d",
	["Grupo de 5"] = "Gruppe mit 5",
	["Guarda %d misiones: las entregas en una guía que sigue."] = "Behalte %d Quests: Du gibst sie in einem späteren Guide ab.",
	["Guarda Grito intimidador para cuando estés en peligro."] = "Heb dir Drohruf für Gefahrenmomente auf.",
	["Guarda Muro de escudo para los peores momentos del jefe."] = "Heb dir Schildwall für die schlimmsten Momente des Bosses auf.",
	["Guarda en el banco los materiales que todavía no usas, y deja las bolsas libres para el botín."] = "Lagere Materialien, die du noch nicht brauchst, in der Bank, und halte deine Taschen frei für Beute.",
	["Guarda o cambia tu mascota"] = "Begleiter einstallen oder tauschen",
	["Guarda un poco de tela para vendas: Primeros auxilios también la usa."] = "Heb etwas Stoff für Verbände auf: Erste Hilfe braucht ihn auch.",
	["Guardada el %s"] = "Gespeichert am %s",
	["Guardar"] = "Speichern",
	["Guardar %d"] = "%d behalten",
	["Guardar [conservar]"] = "Behalten",
	["Guardar como marcador"] = "Als Markierung speichern",
	["Guardar y seguir"] = "Speichern und folgen",
	["Guardas ira al cambiar de actitud."] = "Du behältst Wut beim Haltungswechsel.",
	["Guardas tu ira al cambiar de actitud; así Cargar, Abrumar y Revancha salen casi gratis."] = "Du behältst deine Wut beim Haltungswechsel; so sind Sturmangriff, Überwältigen und Rache fast gratis.",
	["Guardaste %d objeto en el banco."] = "Du hast %d Gegenstand in der Bank eingelagert.",
	["Guardaste %d objetos en el banco."] = "Du hast %d Gegenstände in der Bank eingelagert.",
	["Guardaste tu sesión de pesca y empezaste otra."] = "Du hast deine Angelsitzung gespeichert und eine neue begonnen.",
	["Guardianes enemigos"] = "Gegnerische Wächter",
	["Guerrero"] = "Krieger",
	["Guiarme"] = "Hinführen",
	["Gul'dan fue el primer brujo orco, y su historia no terminó nada bien. Tú úsalo con más cabeza."] = "Gul'dan war der erste Orc-Hexenmeister, und seine Geschichte endete gar nicht gut. Geh du klüger damit um.",
	["Gul'dan fundó el Consejo de la Sombra, un grupo de brujos que movía a la Horda desde las sombras."] = "Gul'dan gründete den Schattenrat, eine Gruppe von Hexenmeistern, die die Horde aus dem Schatten lenkte.",
	["Guía"] = "Guide",
	["Guía a tu manada"] = "Führe dein Rudel",
	["Guía abierta en una pestaña nueva: sigue la flecha."] = "Guide in einem neuen Tab geöffnet: Folge dem Pfeil.",
	["Guía actual"] = "Aktueller Guide",
	["Guía de pesca"] = "Angelguide",
	["Guía para desbloquearla en marcha"] = "Guide zum Freischalten läuft",
	["Guía: %s"] = "Guide: %s",
	["Guíame"] = "Führ mich",
	["Guíame a Bahía del Botín"] = "Führ mich nach Beutebucht",
	["Guíame a la misión"] = "Führ mich zur Quest",
	["Guíame a la receta"] = "Führ mich zum Rezept",
	["Guíame a una caña"] = "Führ mich zu einer Angel",
	["Guíame al pescador"] = "Führ mich zum Angler",
	["Guíame aquí"] = "Führ mich hierher",
	["Guíame te lleva paso a paso."] = "„Führ mich“ führt dich Schritt für Schritt.",
	["Guías"] = "Guides",
	["Guías con %s"] = "Guides mit %s",
	["Guías de la comunidad"] = "Community-Guides",
	["Guías y planes"] = "Guides und Pläne",
	["HDR (Windows)"] = "HDR (Windows)",
	["Habilidades más baratas."] = "Günstigere Fähigkeiten.",
	["Habilidades más baratas: más golpes de amenaza."] = "Günstigere Fähigkeiten: mehr Bedrohungsschläge.",
	["Habilidades nuevas por aprender: %d. Tu entrenador te espera."] = "Neue Fähigkeiten zu erlernen: %d. Dein Lehrer wartet.",
	["Habilidades por entrenar"] = "Fähigkeiten zum Trainieren",
	["Habilidades que vigila la ayuda de Blizzard"] = "Fähigkeiten, die Blizzards Kampfassistent beobachtet",
	["Habitual"] = "Gewöhnlich",
	["Habla con %s"] = "Sprich mit %s",
	["Habla con el maestro de vuelo de cada pueblo nuevo: así aprendes la ruta."] = "Sprich in jedem neuen Ort mit dem Flugmeister: So lernst du die Route.",
	["Habla con un banquero para comprarla."] = "Sprich mit einem Bankier, um ihn zu kaufen.",
	["Hablar"] = "Reden",
	["Hace heridas que sangran: vigila la vida del tanque."] = "Er verursacht blutende Wunden: Achte auf die Gesundheit des Tanks.",
	["Hace mil años, en la Guerra de las Arenas Movedizas, los elfos y los dragones encerraron a los qiraji tras el Muro del Escarabajo."] = "Vor tausend Jahren, im Krieg der Treibsande, sperrten Elfen und Drachen die Qiraji hinter dem Skarabäuswall ein.",
	["Hace más de diez mil años todas las tierras eran un solo continente: Kalimdor, que en élfico quiere decir «tierra de la eterna luz de las estrellas»."] = "Vor mehr als zehntausend Jahren waren alle Lande ein einziger Kontinent: Kalimdor, was auf Elfisch „Land des ewigen Sternenlichts“ bedeutet.",
	["Hace sangrar al enemigo: ponlo al empezar la pelea."] = "Lässt den Gegner bluten: Setz es zu Kampfbeginn ein.",
	["Hace sangrar mucho: vale la pena con enemigos que duran."] = "Lässt ihn stark bluten: lohnt sich bei Gegnern, die lange durchhalten.",
	["Hace siglos, Aegwynn venció a un avatar de Sargeras y escondió su cuerpo en la Tumba de Sargeras, en las Islas Abruptas."] = "Vor Jahrhunderten besiegte Aegwynn einen Avatar des Sargeras und versteckte seinen Körper im Grabmal des Sargeras auf den Verheerten Inseln.",
	["Hacen falta al menos 3 lugares distintos de ese recurso en la zona."] = "Eine Route braucht mindestens 3 verschiedene Fundorte dieser Ressource im Gebiet.",
	["Hacer mazmorras con tu grupo da botín, misiones y reputación: es farmeo con plática incluida."] = "Dungeons mit deiner Gruppe bringen Beute, Quests und Ruf: Farmen mit Plauderei inklusive.",
	["Hacer oro"] = "Gold machen",
	["Haces de luz entre árboles, nubes y montañas."] = "Lichtstrahlen zwischen Bäumen, Wolken und Bergen.",
	["Hacha de dos manos"] = "Zweihandaxt",
	["Hacha de una mano"] = "Einhandaxt",
	["Hacia %s"] = "Nach %s",
	["Hacia %s (niv. %s)"] = "Nach %s (St. %s)",
	["Hacia abajo"] = "Nach unten",
	["Hacia arriba"] = "Nach oben",
	["Hacia dónde se acomodan tus compañeros."] = "In welche Richtung deine Gruppenmitglieder angeordnet werden.",
	["Hacia:"] = "Ziel:",
	["Hacia: %s"] = "Ziel: %s",
	["Halloween recuerda el día en que los Renegados se liberaron del Rey Exánime: por eso queman al Hombre de Mimbre."] = "Die Schlotternächte erinnern an den Tag, an dem sich die Verlassenen vom Lichkönig befreiten: Darum verbrennen sie den Weidenmann.",
	["Hamuul Tótem de Runa, el archidruida de Cima del Trueno, fue de los primeros tauren aceptados en el Círculo Cenarion."] = "Hamuul Runentotem, der Erzdruide von Donnerfels, war einer der ersten Tauren, die in den Zirkel des Cenarius aufgenommen wurden.",
	["Hasta dónde llegan las montañas lejanas."] = "Wie weit die fernen Berge reichen.",
	["Hasta dónde puedes alejar la cámara con la rueda. El juego puede limitarlo: Alfa muestra el valor que de verdad quedó."] = "Wie weit du die Kamera mit dem Mausrad herauszoomen kannst. Das Spiel kann es begrenzen: Alfa zeigt den Wert, der wirklich gilt.",
	["Hasta dónde se dibuja el mundo. Es lo que más FPS cuesta."] = "Wie weit die Welt gezeichnet wird. Das kostet die meisten FPS.",
	["Hasta dónde se dibuja el pasto. Más lejos, menos «alfombra» que aparece al caminar."] = "Wie weit Gras gezeichnet wird. Weiter heißt weniger „Teppich“, der beim Laufen auftaucht.",
	["Hasta el alfa se cae. Lo importante es levantarse. ¡Vamos!"] = "Selbst der Alpha stürzt mal. Wichtig ist, wieder aufzustehen. Los!",
	["Hasta el nivel 20 usa un arma de dos manos; luego cambia a dos armas de una mano."] = "Nutze bis Stufe 20 eine Zweihandwaffe; wechsle danach auf zwei Einhandwaffen.",
	["Hasta mi nivel"] = "Bis zu meiner Stufe",
	["Hasta qué distancia se ven las placas de nombre. El juego puede limitarlo."] = "Bis zu welcher Entfernung Namensplaketten zu sehen sind. Das Spiel kann es begrenzen.",
	["Hasta qué nivel"] = "Bis zu welcher Stufe",
	["Hay enemigos que se convierten en lobos y otros que asustan: no corran si los asustan, esperen."] = "Manche Gegner verwandeln sich in Wölfe, andere versetzen in Furcht: Lauft nicht in Panik los, wartet es ab.",
	["Hay mucha agua: si nadas bajo el agua, mira tu barra de respiración y sube a tomar aire."] = "Hier gibt es viel Wasser: Wenn du tauchst, achte auf deine Atemleiste und tauch zum Luftholen auf.",
	["Hay muchas tribus trol: Amani, Gurubashi, Furiarena, Zandalar... y casi todas pelean entre sí."] = "Es gibt viele Trollstämme: Amani, Gurubashi, Sandwut, Zandalar... und fast alle bekämpfen sich gegenseitig.",
	["Hay muchos no-muertos y jabaespines: lleven algo para quitar enfermedades si su grupo puede."] = "Viele Untote und Stacheleber: Bringt etwas gegen Krankheiten mit, wenn eure Gruppe das kann.",
	["Hay muchos troggs y elementales de fuego juntos: tiren de uno o dos grupos a la vez, no más."] = "Viele Troggs und Feuerelementare stehen dicht beieinander: Zieht ein oder zwei Gruppen auf einmal, nicht mehr.",
	["Hay nueve clases en el Clásico, pero solo la Alianza tiene paladines y solo la Horda tiene chamanes."] = "In Classic gibt es neun Klassen, aber nur die Allianz hat Paladine und nur die Horde Schamanen.",
	["Hay una guía de Alfa"] = "Es gibt einen Alfa-Guide",
	["Haz clic derecho (o Mayús+clic) en el mapa donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras."] = "Mach einen Rechtsklick (oder Umschalt+Klick) auf die Karte, wo du eine willst: Gib ihr Namen, Symbol und Farbe, und der Pfeil führt dich hin, wann du willst.",
	["Haz clic en un marco de ejemplo"] = "Klick auf einen Beispielrahmen",
	["Haz clic y pulsa la tecla que quieras (Esc cancela). Clic derecho la quita."] = "Klick und drück die gewünschte Taste (Esc bricht ab). Rechtsklick entfernt sie.",
	["Haz clic y pulsa la tecla, un botón del ratón o la rueda (con Mayús, Ctrl o Alt si quieres). Esc cancela; clic derecho la quita."] = "Klick und drück die Taste, eine Maustaste oder das Mausrad (auf Wunsch mit Umschalt, Strg oder Alt). Esc bricht ab; Rechtsklick entfernt sie.",
	["Haz doble clic derecho en el mundo para lanzar la caña, sin usar la tecla. Nunca en combate ni en vuelo."] = "Doppel-Rechtsklick in die Welt wirft die Angel aus, ganz ohne Taste. Nie im Kampf oder im Flug.",
	["Hecha"] = "Erledigt",
	["Hecha %d veces"] = "%d-mal erledigt",
	["Hechas"] = "Erledigt",
	["Hechizo del preajuste"] = "Zauber aus der Voreinstellung",
	["Hechizo desconocido"] = "Unbekannter Zauber",
	["Hechizo elegido por ti"] = "Von dir gewählter Zauber",
	["Hechizo nuevo para tus clics de Curación. Ábrelo en /alfa curacion."] = "Neuer Zauber für deine Heilungsklicks. Öffne /alfa curacion.",
	["Hechizos de sombras que hacen daño con el tiempo: el sacerdote que mejor sube en solitario, casi sin descansar."] = "Schattenzauber mit Schaden über Zeit: der Priester, der solo am besten levelt, fast ohne Rast.",
	["Hechizos de tu mascota"] = "Zauber deines Begleiters",
	["Hechizos desde lejos y raíces para que el monstruo no te alcance. Al final llega la forma de lechúcico."] = "Zauber aus der Ferne und Wurzeln, damit dich das Monster nicht erreicht. Am Ende kommt die Mondkingestalt.",
	["Hecho"] = "Fertig",
	["Hemet Nesingwary organiza safaris por toda la Vega: sus encargos de cazar panteras, tigres y raptores son famosos."] = "Hemet Nesingwary veranstaltet Safaris im ganzen Schlingendorntal: Seine Jagdaufträge auf Panther, Tiger und Raptoren sind berühmt.",
	["Hemorragia: suma puntos de combo y el enemigo recibe más daño."] = "Blutsturz: baut Combopunkte auf, und der Gegner erleidet mehr Schaden.",
	["Hender armadura más barato."] = "Günstigeres Rüstung zerreißen.",
	["Hender armadura más barato: amenaza constante."] = "Günstigeres Rüstung zerreißen: stetige Bedrohung.",
	["Hender armadura más barato: más amenaza a varios enemigos."] = "Günstigeres Rüstung zerreißen: mehr Bedrohung auf mehrere Gegner.",
	["Hender armadura: amenaza constante y el enemigo recibe más daño."] = "Rüstung zerreißen: stetige Bedrohung, und der Gegner erleidet mehr Schaden.",
	["Herboristería"] = "Kräuterkunde",
	["Herboristería combina bien con Alquimia, y también con Desollar o Minería para recolectar el doble."] = "Kräuterkunde passt gut zu Alchemie, und auch zu Kürschnerei oder Bergbau, um doppelt zu sammeln.",
	["Herramienta"] = "Werkzeug",
	["Herramientas"] = "Werkzeuge",
	["Herrería"] = "Schmiedekunst",
	["Herrería fabrica armas y armadura de placas muy buenas para tu nivel, y Minería te da el material gratis."] = "Schmiedekunst stellt für deine Stufe sehr gute Waffen und Plattenrüstung her, und Bergbau liefert dir das Material gratis.",
	["Herrería fabrica escudos y piezas resistentes."] = "Schmiedekunst stellt Schilde und robuste Teile her.",
	["Herrería fabrica escudos y placas con defensa y aguante, justo lo que un tanque necesita."] = "Schmiedekunst stellt Schilde und Platte mit Verteidigung und Ausdauer her, genau das, was ein Tank braucht.",
	["Herrería y Minería van de la mano: tú sacas el metal y tú lo forjas."] = "Schmiedekunst und Bergbau gehen Hand in Hand: Du förderst das Metall und du schmiedest es.",
	["Hielo"] = "Eis",
	["Hierbas"] = "Kräuter",
	["Historias"] = "Geschichten",
	["Historias de tus misiones"] = "Geschichten deiner Quests",
	["Historias guardadas"] = "Gespeicherte Geschichten",
	["Historias y datos curiosos"] = "Geschichten und kuriose Fakten",
	["Hogger es un gnoll de Elwynn tan temido que, para muchos aventureros, fue su primer gran reto."] = "Hogger ist ein Gnoll in Elwynn, so gefürchtet, dass er für viele Abenteurer die erste große Herausforderung war.",
	["Hombros"] = "Schultern",
	["Honor"] = "Ehre",
	["Horarios de barcos y zepelines"] = "Fahrpläne von Schiffen und Zeppelinen",
	["Horda"] = "Horde",
	["Hoy"] = "Heute",
	["Hoy en números"] = "Heute in Zahlen",
	["Hoy te guía"] = "„Heute“ führt dich",
	["Hoy te pone tu siguiente paso primero, y en combate ninguna ventana de Alfa te deja atrapado."] = "„Heute“ zeigt deinen nächsten Schritt zuerst, und im Kampf hält dich kein Alfa-Fenster mehr fest.",
	["Hoy, Aventura, Personaje, Mundo, Oficios y Manada en una sola ventana: %s o el lobo del minimapa."] = "Heute, Abenteuer, Charakter, Welt, Berufe und Rudel in einem einzigen Fenster: %s oder der Wolf an der Minikarte.",
	["Hoy, a tu clase"] = "Heute, für deine Klasse",
	["Huele a pan recién hecho por aquí… se me antoja."] = "Hier riecht es nach frischem Brot… da hätte ich Lust drauf.",
	["Huele a salchichas asadas por aquí… ¿o es mi imaginación?"] = "Hier riecht es nach gegrillten Würstchen… oder bilde ich mir das ein?",
	["Huella"] = "Pfotenabdruck",
	["Humanos"] = "Menschen",
	["Humo, agua y efectos se funden con lo que tocan en lugar de cortarse en seco."] = "Rauch, Wasser und Effekte gehen weich in das über, was sie berühren, statt hart abzuschneiden.",
	["Huracán: golpea a todos a tu alrededor."] = "Wirbelwind: trifft alle um dich herum.",
	["Háblame de mi gente"] = "Erzähl mir von meinem Volk",
	["Iconos de viaje en el minimapa"] = "Reisesymbole auf der Minikarte",
	["Idioma"] = "Sprache",
	["Igual que Alfa"] = "Wie Alfa",
	["Igual que lo tuyo"] = "Gleich wie deins",
	["Igual que los otros señores: lanza rayos y se cura. Interrumpe su curación."] = "Wie die anderen Fürsten: Er wirkt Blitze und heilt sich. Unterbrich seine Heilung.",
	["Illidan absorbió el poder del Cráneo de Gul'dan y se volvió mitad demonio. Por eso Malfurion lo desterró."] = "Illidan nahm die Macht des Schädels von Gul'dan in sich auf und wurde halb Dämon. Darum verbannte ihn Malfurion.",
	["Illidan guardó agua del Pozo antes de su caída y creó uno nuevo en Hyjal. Por eso Malfurion lo encerró bajo tierra durante diez mil años."] = "Illidan bewahrte vor dem Fall des Brunnens Wasser auf und schuf einen neuen auf dem Hyjal. Darum sperrte Malfurion ihn zehntausend Jahre unter die Erde.",
	["Illidan se fue a Terrallende, lo que quedó de Draenor, y ahí se hizo de un ejército propio."] = "Illidan ging in die Scherbenwelt, das, was von Draenor übrig ist, und baute sich dort ein eigenes Heer auf.",
	["Illidan, el gemelo de Malfurion, amaba a Tyrande, pero ella eligió a su hermano. Esa herida lo acompañó por diez mil años."] = "Illidan, Malfurions Zwilling, liebte Tyrande, doch sie wählte seinen Bruder. Diese Wunde begleitete ihn zehntausend Jahre lang.",
	["Imagen HDR"] = "HDR-Bild",
	["Importa una cadena de escala de estadísticas y usa, renombra, exporta o borra las escalas que tienes."] = "Importiere einen Werteskala-Text und benutze, benenne um, exportiere oder lösche die Skalen, die du hast.",
	["Importado"] = "Importiert",
	["Importado: %s. Ya puedes seguirlo."] = "Importiert: %s. Du kannst ihm jetzt folgen.",
	["Importar"] = "Importieren",
	["Importar un build"] = "Einen Build importieren",
	["Importar una ruta"] = "Route importieren",
	["Importar..."] = "Importieren...",
	["Inclina la cámara al subir y bajar cuestas."] = "Neigt die Kamera an Steigungen und Gefällen.",
	["Ingeniería"] = "Ingenieurskunst",
	["Ingeniería da aturdimientos y trucos que ganan duelos; Minería da el material."] = "Ingenieurskunst bringt Betäubungen und Tricks, die Duelle gewinnen; Bergbau liefert das Material.",
	["Ingeniería da granadas y redes para controlar al rival; Minería da el material."] = "Ingenieurskunst bringt Granaten und Netze, um den Gegner zu kontrollieren; Bergbau liefert das Material.",
	["Ingeniería da granadas, redes y bombas que deciden peleas contra jugadores; Minería da el material."] = "Ingenieurskunst bringt Granaten, Netze und Bomben, die Kämpfe gegen Spieler entscheiden; Bergbau liefert das Material.",
	["Ingeniería te salva con trucos de escape; Sastrería hace tu ropa."] = "Ingenieurskunst rettet dich mit Fluchttricks; Schneiderei macht deine Kleidung.",
	["Inicio"] = "Start",
	["Inicio de Alfa"] = "Alfa-Start",
	["Inicio del horizonte"] = "Beginn des Horizonts",
	["Insignias de La Jauría: los Alfas y los miembros llevan su lobo en el cuadro, en La Jauría y en el mapa; y quienes comparten se ven con una huella."] = "Abzeichen von La Jauría: Alphas und Mitglieder tragen ihren Wolf im Tooltip, in La Jauría und auf der Karte; und wer teilt, erscheint als Pfotenabdruck.",
	["Instantánea: úsala cada vez que esté lista."] = "Spontan: Nutze sie jedes Mal, wenn sie bereit ist.",
	["Instructor"] = "Lehrer",
	["Instructor de %s"] = "Lehrer für %s",
	["Instructor de Herboristería"] = "Lehrer für Kräuterkunde",
	["Instructor de Minería"] = "Lehrer für Bergbau",
	["Instructor de equitación"] = "Reitlehrer",
	["Instructor de pesca"] = "Angellehrer",
	["Instructores"] = "Lehrer",
	["Instructores de %s"] = "Lehrer für %s",
	["Instructores de pesca"] = "Angellehrer",
	["Instructores y vendedores"] = "Lehrer und Händler",
	["Intelecto"] = "Intelligenz",
	["Intelecto Arcano"] = "Arkane Intelligenz",
	["Intentar ahora"] = "Jetzt versuchen",
	["Intentar otra vez"] = "Erneut versuchen",
	["Interceptar más seguido: el rival no se escapa."] = "Öfter Abfangen: Der Gegner entkommt dir nicht.",
	["Interfaz"] = "Interface",
	["Interfaz del juego"] = "Spieloberfläche",
	["Interrumpes hechizos y los silencias."] = "Du unterbrichst Zauber und bringst den Zaubernden zum Schweigen.",
	["Interrumpes y silencias hechizos."] = "Du unterbrichst Zauber und bringst Zaubernde zum Schweigen.",
	["Intimidación: tu mascota aturde al enemigo."] = "Einschüchterung: Dein Begleiter betäubt den Gegner.",
	["Invita a tu clan con un clic, y arreglos"] = "Lade deinen Clan mit einem Klick ein – und Korrekturen",
	["Invitaciones a hermandades"] = "Gildeneinladungen",
	["Invitaciones de grupo de desconocidos"] = "Gruppeneinladungen von Fremden",
	["Invitación a %s para %s enviada. Si no puede unirse, el juego te dirá por qué."] = "Einladung in %s an %s gesendet. Wenn er nicht beitreten kann, sagt dir das Spiel warum.",
	["Invitar"] = "Einladen",
	["Invitar a %s"] = "In %s einladen",
	["Invitar a una comunidad sin bloqueos"] = "In eine Community einladen ohne Sperre",
	["Invitar al clan"] = "In Gilde oder Community einladen",
	["Invitar al grupo"] = "In Gruppe einladen",
	["Invitar, comerciar, susurrar…"] = "Einladen, handeln, flüstern…",
	["Invitaste a %s a tu grupo."] = "Du hast %s in deine Gruppe eingeladen.",
	["Invoca un espíritu de jabalí: mátenlo o que alguien lo tanquee."] = "Er beschwört einen Ebergeist: Tötet ihn oder lasst ihn von jemandem tanken.",
	["Invócalo antes de pelear."] = "Beschwöre ihn vor dem Kampf.",
	["Ir"] = "Los",
	["Ir a la zona recomendada"] = "Zur empfohlenen Zone gehen",
	["Ir a un lugar"] = "Zu einem Ort gehen",
	["Ir a: %s"] = "Gehe zu: %s",
	["Ir al mapa del juego"] = "Zur Spielkarte",
	["Ir al resumen"] = "Zur Übersicht",
	["Ir por el camino es más seguro que cortar por en medio: los caminos tienen menos enemigos."] = "Auf dem Weg zu bleiben ist sicherer als querfeldein: Auf Wegen gibt es weniger Gegner.",
	["Ira al romper un miedo: los rivales te asustan mucho."] = "Wut beim Brechen einer Furcht: Gegner setzen oft Furcht gegen dich ein.",
	["Ira aunque el rival huya o te frene."] = "Wut, auch wenn der Gegner flieht oder dich verlangsamt.",
	["Ira constante en peleas largas contra jefes."] = "Stetige Wut in langen Bosskämpfen.",
	["Ira constante."] = "Stetige Wut.",
	["Ira constante: nunca te quedas sin poder usar habilidades."] = "Stetige Wut: Dir gehen nie die Fähigkeiten aus.",
	["Ira gratis cada pocos segundos, aunque nadie te pegue."] = "Gratis-Wut alle paar Sekunden, auch wenn dich niemand trifft.",
	["Izquierdo"] = "Links",
	["Jaina Valiente fue alumna de Antonidas antes de fundar Theramore."] = "Jaina Prachtmeer war Schülerin von Antonidas, bevor sie Theramore gründete.",
	["JcJ"] = "PvP",
	["JcJ (12): rangos de honor 3, 7, 10, 13 y 14; exaltado con las 4 facciones de los campos de batalla; las semanas 4, 7 y 10 del viaje de temporada Campo de Honor."] = "PvP (12): Ehrenränge 3, 7, 10, 13 und 14; ehrfürchtig bei den 4 Schlachtfeldfraktionen; die Wochen 4, 7 und 10 der Saisonreise „Feld der Ehre“.",
	["Jefe"] = "Boss",
	["Jefe %d por descubrir"] = "Boss %d, noch zu entdecken",
	["Jefe final"] = "Endboss",
	["Jefes"] = "Bosse",
	["Jefes vencidos"] = "Besiegte Bosse",
	["Jefes vencidos, mazmorras hechas y botín anotado de este personaje. No toca tus ajustes."] = "Besiegte Bosse, abgeschlossene Dungeons und notierte Beute dieses Charakters. Deine Einstellungen bleiben.",
	["Jefes, botín y la entrada de cada mazmorra y banda."] = "Bosse, Beute und der Eingang jedes Dungeons und Schlachtzugs.",
	["Juega con cada personaje una vez y Alfa recordará sus bolsas y su banco."] = "Spiel jeden Charakter einmal, und Alfa merkt sich seine Taschen und seine Bank.",
	["Juega siempre en actitud defensiva con escudo."] = "Spiel immer in Verteidigungshaltung mit Schild.",
	["Juguetes y consumibles de pesca"] = "Angelspielzeuge und Verbrauchsgüter",
	["Junta %d de %s"] = "Sammle %d %s",
	["Junta 100 capturas."] = "Sammle 100 Fänge.",
	["Junta 1000 capturas."] = "Sammle 1000 Fänge.",
	["Junta 500 capturas."] = "Sammle 500 Fänge.",
	["Junta dos monstruos y usa Golpes de barrido: así subes más rápido."] = "Zieh zwei Monster und nutze Weitreichende Stöße: So levelst du schneller.",
	["Junta dos o tres monstruos, usa Atronar y Revancha: subes seguro y sin descansar."] = "Zieh zwei oder drei Monster, nutze Donnerknall und Rache: Du levelst sicher und ohne Rast.",
	["Junta lo gris y lo blanco para vender: suma más de lo que parece."] = "Sammle Graues und Weißes zum Verkaufen: Es kommt mehr zusammen, als man denkt.",
	["Junta los montones y acomoda tus objetos con un clic."] = "Stapelt und ordnet deine Gegenstände mit einem Klick.",
	["Junta los montones y acomoda tus objetos. No funciona en combate."] = "Stapelt und ordnet deine Gegenstände. Nicht im Kampf.",
	["Junta materiales de tu profesión donde más hay."] = "Sammle Materialien deines Berufs dort, wo es am meisten gibt.",
	["Junta materiales de tu profesión, con unas misiones de XP en medio."] = "Sammle Materialien deines Berufs, mit ein paar EP-Quests dazwischen.",
	["Junta misiones de la misma zona: haces varias en un solo viaje."] = "Sammle Quests aus derselben Zone: So erledigst du mehrere auf einer Reise.",
	["Junta varios monstruos: tus golpes sagrados alcanzan a todos."] = "Zieh mehrere Monster: Deine heiligen Schläge treffen alle.",
	["Juntando todo lo del juego. Es solo la primera vez que la abres."] = "Alles aus dem Spiel wird gesammelt. Das passiert nur beim ersten Öffnen.",
	["Juntar %s"] = "%s ansparen",
	["Juntar los materiales de mi profesión"] = "Materialien meines Berufs sammeln",
	["Juntar materiales para vender"] = "Materialien zum Verkaufen sammeln",
	["Juntar nodos cercanos al alejar"] = "Nahe Vorkommen beim Herauszoomen bündeln",
	["Juntar oro"] = "Gold ansparen",
	["Junto a la lupa del mapa del juego: las capas, el modo limpio y «Mapa de Alfa» para cambiar al de Alfa."] = "Neben der Lupe der Spielkarte: die Ebenen, der Fokusmodus und „Alfas Karte“, um zu Alfas Karte zu wechseln.",
	["Junto a tu guía hay un botón para buscar lo que tienes cerca: vuelo, banco, subasta, reparar, comerciantes y entrenadores."] = "Neben deinem Guide gibt es einen Button, um zu finden, was in der Nähe ist: Flug, Bank, Auktionshaus, Reparatur, Händler und Lehrer.",
	["Kael'thas fue miembro del Kirin Tor de Dalaran antes de guiar a los elfos de sangre."] = "Kael'thas war Mitglied der Kirin Tor von Dalaran, bevor er die Blutelfen anführte.",
	["Karazhan, la torre de Medivh, el último Guardián, se levanta sobre un cruce de líneas de magia natural."] = "Karazhan, der Turm von Medivh, dem letzten Wächter, erhebt sich über einer Kreuzung natürlicher Kraftlinien.",
	["Kargath, el campamento de la Horda, lleva el nombre de un viejo caudillo orco del clan Mano Destrozada."] = "Kargath, das Lager der Horde, ist nach einem alten Orcanführer vom Klan der Zerschmetterten Hand benannt.",
	["Kel'Thuzad era un archimago de Dalaran. Lo expulsaron por estudiar nigromancia y acabó al servicio del Rey Exánime."] = "Kel'Thuzad war ein Erzmagier aus Dalaran. Er wurde ausgestoßen, weil er Nekromantie studierte, und diente am Ende dem Lichkönig.",
	["Kel'Thuzad tiene un gato, el señor Bigglesworth, que lo acompaña en Naxxramas. ¡Ni se te ocurra hacerle daño!"] = "Kel'Thuzad hat einen Kater, Herrn Bigglesworth, der ihm in Naxxramas Gesellschaft leistet. Wag es ja nicht, ihm etwas zu tun!",
	["Khadgar fue el aprendiz de Medivh. Al pelear contra su maestro poseído envejeció de golpe y se quedó con el pelo blanco."] = "Khadgar war Medivhs Lehrling. Im Kampf gegen seinen besessenen Meister alterte er schlagartig und behielt weiße Haare.",
	["Khaz Modan es la tierra de los enanos, desde las nieves de Dun Morogh hasta los valles de Loch Modan."] = "Khaz Modan ist das Land der Zwerge, vom Schnee von Dun Morogh bis zu den Tälern von Loch Modan.",
	["Kil'jaeden encerró el alma de Ner'zhul en un bloque de hielo y lo arrojó a Rasganorte: así nació el Rey Exánime."] = "Kil'jaeden schloss Ner'zhuls Seele in einen Eisblock ein und schleuderte ihn nach Nordend: So entstand der Lichkönig.",
	["Kil'jaeden engañó a Ner'zhul, el chamán más sabio de Draenor, y su aprendiz Gul'dan terminó de entregar a los orcos a la Legión."] = "Kil'jaeden täuschte Ner'zhul, den weisesten Schamanen Draenors, und sein Lehrling Gul'dan lieferte die Orcs endgültig der Legion aus.",
	["Korialstrasz, el consorte de Alexstrasza, anduvo entre los mortales como Krasus, un mago del consejo de Dalaran."] = "Korialstrasz, Alexstraszas Gefährte, wandelte als Krasus, ein Magier aus Dalarans Rat, unter den Sterblichen.",
	["Kul Tiras es un reino isleño de marineros. Su gran almirante, Daelin Valiente, era el padre de Jaina."] = "Kul Tiras ist ein Inselkönigreich von Seefahrern. Sein Großadmiral Daelin Prachtmeer war Jainas Vater.",
	["La %s también está en el menú del juego."] = "%s gibt es auch im Spielmenü.",
	["La Abadía de Villanorte es de las más antiguas del reino; ahí empiezan su camino muchos aventureros humanos."] = "Die Abtei von Nordhain ist eine der ältesten des Königreichs; viele menschliche Abenteurer beginnen dort ihren Weg.",
	["La Alianza nació en la Segunda Guerra, cuando los reinos humanos, los enanos y los altos elfos se unieron contra la Horda."] = "Die Allianz entstand im Zweiten Krieg, als sich die Menschenreiche, die Zwerge und die Hochelfen gegen die Horde verbündeten.",
	["La B, Mayús+B, la tecla de cada bolsa y los comerciantes abren la ventana de Alfa. Apágalo para volver a las del juego."] = "B, Umschalt+B, die Taste jeder Tasche und Händler öffnen Alfas Fenster. Schalte es aus, um zu denen des Spiels zurückzukehren.",
	["La Capilla de la Esperanza de la Luz resistió a la Plaga en una batalla legendaria; hoy es el gran refugio del Alba Argenta."] = "Die Kapelle des Hoffnungsvollen Lichts hielt der Geißel in einer legendären Schlacht stand; heute ist sie die große Zuflucht der Argentumdämmerung.",
	["La Catedral de la Luz es el corazón de la fe en Ventormenta; sus sacerdotes atienden a toda la Alianza."] = "Die Kathedrale des Lichts ist das Herz des Glaubens in Sturmwind; ihre Priester dienen der ganzen Allianz.",
	["La Cresta de la Llama es el puesto de la Horda en las estepas, en lo alto de las rocas."] = "Flammenkamm ist der Außenposten der Horde in der Steppe, hoch oben auf den Felsen.",
	["La Cruzada Escarlata nació del dolor de Lordaeron tras la plaga, pero su odio la volvió tan cruel como lo que combate."] = "Der Scharlachrote Kreuzzug entstand aus Lordaerons Schmerz nach der Seuche, doch sein Hass machte ihn so grausam wie das, was er bekämpft.",
	["La Cruzada Escarlata tiene aquí su monasterio. Para ellos todo no-muerto debe arder, también los Renegados."] = "Der Scharlachrote Kreuzzug hat hier sein Kloster. Für ihn muss jeder Untote brennen, auch die Verlassenen.",
	["La Cuenca de Arathi, el campo de batalla, está en estas tierras: se pelea por la granja, la mina, el aserradero, los establos y la herrería."] = "Das Arathibecken, das Schlachtfeld, liegt in diesen Landen: Man kämpft um Hof, Mine, Sägewerk, Ställe und Schmiede.",
	["La Feria de la Luna Negra tiene su propia reputación, y se sube con sus vales y sus encargos."] = "Der Dunkelmond-Jahrmarkt hat einen eigenen Ruf, den du mit seinen Losen und Aufträgen steigerst.",
	["La Fortaleza de Grommash, en Orgrimmar, lleva el nombre de Grom Grito Infernal, el héroe que liberó a los orcos de la sangre demoníaca."] = "Die Feste Grommash in Orgrimmar trägt den Namen von Grom Höllschrei, dem Helden, der die Orcs vom Dämonenblut befreite.",
	["La Fuente del Sol, el corazón de Quel'Thalas, nació de un frasco de agua del Pozo de la Eternidad que los altos elfos se llevaron."] = "Der Sonnenbrunnen, das Herz von Quel'Thalas, entstand aus einer Phiole Wasser aus dem Brunnen der Ewigkeit, die die Hochelfen mitnahmen.",
	["La Garganta de Fuego quedó así por culpa del Hierro Negro: su hechicero-thane Thaurissan invocó a Ragnaros y la tierra se incendió."] = "Die Sengende Schlucht ist das Werk der Dunkeleisenzwerge: Ihr Zauberer-Thane Thaurissan beschwor Ragnaros, und das Land fing Feuer.",
	["La Gran Forja nunca se apaga: es el corazón de Forjaz y el orgullo de tu gente."] = "Die Große Schmiede erlischt nie: Sie ist das Herz von Eisenschmiede und der Stolz deines Volkes.",
	["La Gran Forja, en el corazón de Forjaz, nunca se apaga."] = "Die Große Schmiede im Herzen von Eisenschmiede erlischt nie.",
	["La Guardia Nocturna es la milicia de Villa Oscura: protege el pueblo de lobos, no-muertos y worgen."] = "Die Nachtwache ist die Miliz von Dunkelhain: Sie schützt den Ort vor Wölfen, Untoten und Worgen.",
	["La Guerra de los Ancestros fue la primera invasión de la Legión Ardiente a Azeroth, hace unos diez mil años."] = "Der Krieg der Ahnen war die erste Invasion der Brennenden Legion auf Azeroth, vor rund zehntausend Jahren.",
	["La Hermandad del Torio son enanos Hierro Negro que se separaron de su clan. Son maestros herreros y negocian con quien los respete."] = "Die Thoriumbruderschaft sind Dunkeleisenzwerge, die sich von ihrem Klan losgesagt haben. Sie sind Meisterschmiede und handeln mit jedem, der sie respektiert.",
	["La Hermandad del Torio, en La Garganta de Fuego, enseña planos que muchos herreros sueñan."] = "Die Thoriumbruderschaft in der Sengenden Schlucht lehrt Pläne, von denen viele Schmiede träumen.",
	["La Horda arrasó Ventormenta en la Primera Guerra. Los albañiles que la reconstruyeron no recibieron su pago, y de ese enojo nació la Hermandad Defias."] = "Die Horde zerstörte Sturmwind im Ersten Krieg. Die Steinmetze, die es wieder aufbauten, wurden nie bezahlt, und aus dieser Wut entstand die Defiasbruderschaft.",
	["La Horda tiene su propio pueblo al norte del marjal, para vigilar Theramore de cerca."] = "Die Horde hat im Norden der Marschen ein eigenes Dorf, um Theramore genau im Auge zu behalten.",
	["La Horda tiene una aldea en la costa de Desolace, y la Alianza un campamento en las montañas del norte."] = "Die Horde hat ein Dorf an der Küste von Desolace, und die Allianz ein Lager in den Bergen im Norden.",
	["La Jauría"] = "La Jauría",
	["La Jauría en el mapa"] = "La Jauría auf der Karte",
	["La Jauría: estado"] = "La Jauría: Status",
	["La Jauría: tu manada en el mapa, Seguir y el clan (/alfa manada ayuda)"] = "La Jauría: dein Rudel auf der Karte, Folgen und der Clan (/alfa manada ayuda)",
	["La Jauría: tus comandos"] = "La Jauría: deine Befehle",
	["La Legión Ardiente es el ejército de demonios de Sargeras, un titán caído que quiere quemar toda la creación."] = "Die Brennende Legion ist das Dämonenheer von Sargeras, einem gefallenen Titanen, der die ganze Schöpfung verbrennen will.",
	["La Liga de Arathor y los Rapiñadores se pelean la Cuenca de Arathi; las Centinelas Ala de Plata y la Escolta Grito de Guerra, la Garganta Grito de Guerra."] = "Der Bund von Arathor und die Entweihten kämpfen um das Arathibecken; die Silberschwingen-Schildwachen und die Vorhut des Kriegshymnenklans um die Kriegshymnenschlucht.",
	["La Liga de Expedicionarios, los arqueólogos de Forjaz, busca por todo el mundo las ruinas que cuenten el origen de los enanos."] = "Die Forscherliga, die Archäologen von Eisenschmiede, sucht in der ganzen Welt nach Ruinen, die vom Ursprung der Zwerge erzählen.",
	["La Luz para los humanos y enanos, Elune para los elfos de la noche y las sombras para muchos Renegados: cada sacerdote sirve a algo distinto."] = "Das Licht für Menschen und Zwerge, Elune für Nachtelfen und die Schatten für viele Verlassene: Jeder Priester dient etwas anderem.",
	["La Mano de Plata la fundó el arzobispo Alonsus Faol, y Uther fue su primer paladín."] = "Die Silberne Hand wurde von Erzbischof Alonsus Faol gegründet, und Uther war ihr erster Paladin.",
	["La Mano de Plata, la orden de paladines, la fundó el arzobispo Alonsus Faol, y Uther fue el primero de sus caballeros."] = "Die Silberne Hand, der Orden der Paladine, wurde von Erzbischof Alonsus Faol gegründet, und Uther war der erste ihrer Ritter.",
	["La Masacre fue Eldre'Thalas, una ciudad de los elfos Altonato de antes de la Gran División."] = "Düsterbruch war Eldre'Thalas, eine Stadt der hochgeborenen Elfen aus der Zeit vor der Großen Teilung.",
	["La Milicia Popular de la Colina del Centinela la formaron los propios granjeros cuando Ventormenta dejó de mandar soldados."] = "Die Volksmiliz auf der Späherkuppe gründeten die Bauern selbst, als Sturmwind keine Soldaten mehr schickte.",
	["La Montaña Roca Negra se alza entre esta garganta y las Estepas Ardientes. Dentro viven los Hierro Negro, Ragnaros y los dragones negros."] = "Der Schwarzfels erhebt sich zwischen dieser Schlucht und der Brennenden Steppe. Darin leben die Dunkeleisenzwerge, Ragnaros und die schwarzen Drachen.",
	["La Muralla de Thoradin separa Arathi de las Laderas de Trabalomas; lleva el nombre del rey que unió a los humanos."] = "Thoradins Wall trennt Arathi vom Vorgebirge des Hügellands; er trägt den Namen des Königs, der die Menschen einte.",
	["La Orden de Tirisfal, los magos secretos que elegían al Guardián de Azeroth, tomó su nombre de estos claros. Medivh fue el último Guardián."] = "Der Orden von Tirisfal, die geheimen Magier, die den Wächter von Azeroth erwählten, hat seinen Namen von diesen Lichtungen. Medivh war der letzte Wächter.",
	["La Plaga es el ejército no-muerto del Rey Exánime. Kel'Thuzad la extendió por Lordaeron con grano infectado."] = "Die Geißel ist das untote Heer des Lichkönigs. Kel'Thuzad verbreitete sie mit verseuchtem Getreide über Lordaeron.",
	["La Polimorfia convierte al enemigo en oveja. Yo me portaría muy bien con esa oveja, palabra de loba."] = "Verwandlung macht aus dem Gegner ein Schaf. Ich wäre ganz lieb zu diesem Schaf, Wolfsehrenwort.",
	["La Segadora de arcanita es una de las armas más famosas que puede forjar un herrero."] = "Der Arkanitschnitter ist eine der berühmtesten Waffen, die ein Schmied schmieden kann.",
	["La Sima Ígnea está bajo Orgrimmar: ahí se esconden brujos de un culto junto con troggs."] = "Der Flammenschlund liegt unter Orgrimmar: Dort verstecken sich Hexenmeister eines Kults zusammen mit Troggs.",
	["La Sociedad Real de Boticarios trabaja en Entrañas en una plaga nueva. Mejor no preguntes para quién."] = "Die Königliche Apothekervereinigung arbeitet in Unterstadt an einer neuen Seuche. Frag lieber nicht, für wen.",
	["La Sociedad Real de Boticarios trabaja en secreto en una plaga nueva... y no precisamente para los humanos solamente."] = "Die Königliche Apothekervereinigung arbeitet heimlich an einer neuen Seuche... und nicht nur für die Menschen.",
	["La Tercera Guerra empezó con la plaga del grano en Lordaeron y terminó en Hyjal con la caída de Archimonde."] = "Der Dritte Krieg begann mit der Getreideseuche in Lordaeron und endete am Hyjal mit Archimondes Fall.",
	["La Torre de Azora, en el este de Elwynn, es la casa de Theocritus, un mago al servicio del reino."] = "Der Turm von Azora im Osten von Elwynn ist das Zuhause von Theocritus, einem Magier im Dienst des Königreichs.",
	["La aldea Sen'jin, en la costa de Durotar, lleva el nombre del líder que dio su vida por su pueblo."] = "Das Dorf Sen'jin an der Küste von Durotar trägt den Namen des Anführers, der sein Leben für sein Volk gab.",
	["La ayuda de rotación está apagada"] = "Die Rotationshilfe ist aus",
	["La barra con el nombre de la zona y la hora toma los colores y la letra del estilo. Los botones de rastreo, calendario y correo quedan como siempre."] = "Die Leiste mit Zonenname und Uhrzeit übernimmt Farben und Schrift des Stils. Die Buttons für Verfolgung, Kalender und Post bleiben wie immer.",
	["La barra de acción, las barras extra, la de experiencia, el menú y las bolsas toman el estilo que elijas. Solo cambia su aspecto, fuera de combate; al apagarlo vuelven las del juego."] = "Aktionsleiste, Zusatzleisten, Erfahrungsleiste, Menü und Taschen übernehmen den gewählten Stil. Nur ihr Aussehen ändert sich, außerhalb des Kampfes; ausgeschaltet kommen die des Spiels zurück.",
	["La barra de pesca"] = "Die Angelleiste",
	["La barra de tu vuelo con sus paradas sale siempre al despegar."] = "Deine Flugleiste mit ihren Zwischenstopps erscheint beim Abflug immer.",
	["La barra de vida con el color de la clase de cada uno. Apagado: barra verde y el nombre con su color."] = "Die Gesundheitsleiste in der Klassenfarbe jedes Mitglieds. Aus: grüne Leiste und der Name in seiner Farbe.",
	["La base incluida trae %s lugares en %d zonas. Tú descubriste %s."] = "Die mitgelieferte Datenbank enthält %s Fundorte in %d Gebieten. Du hast %s entdeckt.",
	["La bienvenida con las novedades de esta versión."] = "Die Begrüßung mit den Neuerungen dieser Version.",
	["La bienvenida ocupa toda la pantalla, con el juego oscurecido detrás."] = "Die Begrüßung füllt den ganzen Bildschirm, mit dem Spiel abgedunkelt dahinter.",
	["La básica la venden los instructores y los vendedores de suministros de pesca."] = "Die einfache verkaufen Lehrer und Händler für Angelbedarf.",
	["La búsqueda de lugares cercanos no está disponible."] = "Die Suche nach Orten in der Nähe ist nicht verfügbar.",
	["La cadena de los Defias te lleva de Villadorada a los Páramos de Poniente y termina en las Minas de la Muerte, frente a VanCleef."] = "Die Defias-Questreihe führt dich von Goldhain nach Westfall und endet in den Todesminen, Auge in Auge mit VanCleef.",
	["La cadena no trae talentos válidos."] = "Der Text enthält keine gültigen Talente.",
	["La caja donde escribes toma el estilo, con el borde de acento mientras escribes. En Clásico WoW queda la del juego."] = "Das Eingabefeld übernimmt den Stil, mit dem Akzentrand während du schreibst. Bei Klassisches WoW bleibt das des Spiels.",
	["La cambiaste fuera de Alfa (menú del juego o consola)."] = "Du hast sie außerhalb von Alfa geändert (Spielmenü oder Konsole).",
	["La capa de escamas de Onyxia protege del aliento de Nefarian, y en su banda la piden todos."] = "Der Onyxiaschuppenumhang schützt vor Nefarians Atem, und in seinem Schlachtzug braucht ihn jeder.",
	["La cerveza es casi sagrada para tu gente: en Kharanos está la destilería Cebatruenos."] = "Bier ist deinem Volk fast heilig: In Kharanos steht die Brauerei Donnerbräu.",
	["La cola está vacía."] = "Die Warteschlange ist leer.",
	["La cura de ese clic pasa al botón central."] = "Die Heilung dieses Klicks wandert auf die mittlere Maustaste.",
	["La cámara no salta hacia ti por cada árbol o poste entre ella y tu personaje."] = "Die Kamera springt nicht bei jedem Baum oder Pfosten zwischen ihr und deinem Charakter auf dich zu.",
	["La cámara se mece un poco con tus pasos."] = "Die Kamera wiegt sich leicht mit deinen Schritten.",
	["La cámara se queda sobre el agua en lugar de meterse."] = "Die Kamera bleibt über dem Wasser, statt einzutauchen.",
	["La cámara te sigue"] = "Kamera folgt dir",
	["La de ahora pasa a tus sesiones anteriores."] = "Die aktuelle wandert zu deinen früheren Sitzungen.",
	["La de ahora pasa a tus sesiones anteriores. Tu diario y tus logros no cambian."] = "Die aktuelle wandert zu deinen früheren Sitzungen. Dein Tagebuch und deine Erfolge ändern sich nicht.",
	["La de tu clase mientras subes: cambia sola cuando pongas talentos."] = "Die deiner Klasse, solange du levelst: Sie wechselt von selbst, wenn du Talente verteilst.",
	["La derecha"] = "Rechts",
	["La dirección del texto sobre tu personaje."] = "Die Richtung des Textes über deinem Charakter.",
	["La empieza un objeto"] = "Startet durch einen Gegenstand",
	["La enciclopedia de La Jauría"] = "Die Enzyklopädie von La Jauría",
	["La enciclopedia no puede abrir todavía"] = "Die Enzyklopädie kann sich noch nicht öffnen",
	["La entrada de %s"] = "Der Eingang von %s",
	["La entrada de cada mazmorra en el minimapa, en verde las que ya hiciste. El mapa del mundo ya las marca con «Entradas de mazmorras»."] = "Der Eingang jedes Dungeons auf der Minikarte, in Grün die, die du schon gemacht hast. Die Weltkarte markiert sie bereits mit „Dungeon-Eingänge“.",
	["La familia Barov le entregó su castillo de Caer Darrow al Culto a cambio de vida eterna. Así nació Scholomance, y así les fue."] = "Die Familie Barov überließ dem Kult ihre Burg in Caer Darrow im Tausch gegen ewiges Leben. So entstand Scholomance, und so erging es ihnen.",
	["La flecha no está disponible ahora."] = "Der Pfeil ist gerade nicht verfügbar.",
	["La flecha que te guía"] = "Der Pfeil, der dich führt",
	["La flecha se mueve con su rastro y se detiene al llegar."] = "Der Pfeil bewegt sich mit der Spur und hält an, wenn du ankommst.",
	["La flecha sigue caminos por el suelo alrededor de acantilados, agua y muros, con los mapas para caminar de Alfa. Apagado: apunta directo a cada parada."] = "Der Pfeil folgt Wegen am Boden um Klippen, Wasser und Mauern herum, auf Alfas Wegekarten. Aus: Er zeigt direkt auf jede Station.",
	["La flecha te lleva a %s."] = "Der Pfeil führt dich zu %s.",
	["La flecha te lleva a este paso, no al de ahora."] = "Der Pfeil führt dich zu diesem Schritt, nicht zum aktuellen.",
	["La flecha te lleva a su entrada."] = "Der Pfeil führt dich zum Eingang.",
	["La flecha te lleva aquí."] = "Der Pfeil führt dich hierher.",
	["La flecha te lleva de un lugar al siguiente."] = "Der Pfeil führt dich von einem Ort zum nächsten.",
	["La flecha tomó otro destino: dejaste de seguir a %s."] = "Der Pfeil hat ein anderes Ziel: Du folgst %s nicht mehr.",
	["La flecha usa vuelos y tu piedra de hogar cuando conviene."] = "Der Pfeil nutzt Flüge und deinen Ruhestein, wenn es sich lohnt.",
	["La flecha y el camino"] = "Pfeil und Weg",
	["La flecha ya no sigue tu ruta de farmeo."] = "Der Pfeil folgt deiner Farmroute nicht mehr.",
	["La fuerza se cambia en la ventana, en Filtros."] = "Die Stärke änderst du im Fenster unter Filter.",
	["La guarida de Onyxia está en este marjal. Onyxia, hija de Alamuerte, se hace pasar por una noble humana en Ventormenta."] = "Onyxias Hort liegt in diesem Marschland. Onyxia, Todesschwinges Tochter, gibt sich in Sturmwind als menschliche Adlige aus.",
	["La guía en el minimapa"] = "Der Guide auf der Minikarte",
	["La guía que mejor te queda por tu nivel y donde estás."] = "Der Guide, der für deine Stufe und deinen Ort am besten passt.",
	["La guía que sigues, tu paso de ahora y todo lo de las guías a un clic."] = "Der Guide, dem du folgst, dein aktueller Schritt und alles rund um Guides mit einem Klick.",
	["La guía te lleva a entrenar en %d pasos."] = "Der Guide führt dich in %d Schritten zum Training.",
	["La guía te lleva a quien recibe cada una."] = "Der Guide führt dich zu dem, der jede annimmt.",
	["La haces de paso: abre %s."] = "Du machst sie nebenbei: Sie öffnet %s.",
	["La haré"] = "Mach ich",
	["La historia"] = "Die Geschichte",
	["La historia se guarda cuando el juego te muestra la misión."] = "Die Geschichte wird gespeichert, wenn das Spiel dir die Quest zeigt.",
	["La lengua de la Alianza es el común y la de la Horda, el orco. Por eso lo que le dices al otro bando le llega como palabras raras."] = "Die Sprache der Allianz ist die Gemeinsprache, die der Horde Orcisch. Deshalb kommt beim anderen Lager an, was du sagst, als Kauderwelsch.",
	["La letra del aspecto (Inter en el de Alfa, Fira Sans en Halo, la del juego en los demás) o la que elijas."] = "Die Schrift des Designs (Inter bei Alfas eigenem, Fira Sans bei Halo, die des Spiels bei den anderen) oder eine deiner Wahl.",
	["La lista está apagada: enciende «Tu lista de sonidos» en Comodidades (/alfa comodidades)."] = "Die Liste ist aus: Schalte „Deine Soundliste“ unter Komfort ein (/alfa comodidades).",
	["La lista por nivel y tu progreso."] = "Die Liste nach Stufe und dein Fortschritt.",
	["La lupa de la cabecera del rastreador abre el menú. También: /alfa cerca o tu tecla."] = "Die Lupe im Kopf des Trackers öffnet das Menü. Außerdem: /alfa cerca oder deine Taste.",
	["La línea de tiempo de Blizzard dice qué ataque viene y cuándo, y los mensajes grandes, lo peligroso. Alfa no inventa avisos: los prendes y ajustas en Ajustes."] = "Blizzards Zeitleiste sagt, welcher Angriff wann kommt, und die großen Meldungen zeigen, was gefährlich ist. Alfa erfindet keine Hinweise: Du schaltest sie in den Einstellungen ein und passt sie an.",
	["La línea de tu personaje ya no se corta: si no cabe, quita partes y nunca tu nombre ni tu nivel."] = "Die Zeile deines Charakters wird nicht mehr abgeschnitten: Passt sie nicht, fallen Teile weg, aber nie dein Name oder deine Stufe.",
	["La línea del camino también en el minimapa."] = "Die Routenlinie auch auf der Minikarte.",
	["La manada a la vista"] = "Das Rudel in Sicht",
	["La manada aúlla contigo."] = "Das Rudel heult mit dir.",
	["La manada crece"] = "Das Rudel wächst",
	["La manada es fuerte porque cada lobo lo es. Y tú lo eres."] = "Das Rudel ist stark, weil jeder Wolf stark ist. Und du bist es.",
	["La manada no te ve en el mapa"] = "Das Rudel sieht dich nicht auf der Karte",
	["La manada no ve a tu personaje en el mapa."] = "Das Rudel sieht deinen Charakter nicht auf der Karte.",
	["La manada te ve en el mapa"] = "Das Rudel sieht dich auf der Karte",
	["La manada te ve en el mapa: %s"] = "Das Rudel sieht dich auf der Karte: %s",
	["La manada ya no ve a tu personaje en el mapa."] = "Das Rudel sieht deinen Charakter nicht mehr auf der Karte.",
	["La manada ya ve a tu personaje en el mapa del juego."] = "Das Rudel sieht deinen Charakter jetzt auf der Spielkarte.",
	["La manada ya ve a tu personaje en el mapa del juego. Lo cambias cuando quieras en /alfa manada."] = "Das Rudel sieht deinen Charakter jetzt auf der Spielkarte. Ändern kannst du es jederzeit mit /alfa manada.",
	["La mazmorra"] = "Der Dungeon",
	["La mazmorra para mi nivel"] = "Der Dungeon für meine Stufe",
	["La mazmorra para tu nivel, sus jefes, botín, misiones y consejos."] = "Der Dungeon für deine Stufe, seine Bosse, Beute, Quests und Tipps.",
	["La mazmorra para tu nivel, sus misiones y cómo llegar."] = "Der Dungeon für deine Stufe, seine Quests und wie du hinkommst.",
	["La mazmorra para tu nivel; con un nombre, esa mazmorra (también: progreso, ajustes)"] = "Der Dungeon für deine Stufe; mit einem Namen dieser Dungeon (auch: progreso, ajustes)",
	["La mezcla de texturas del terreno."] = "Die Überblendung der Geländetexturen.",
	["La misión"] = "Die Quest",
	["La montura"] = "Das Reittier",
	["La niebla con cuerpo de valles, pantanos y amaneceres."] = "Der dichte Nebel von Tälern, Sümpfen und Morgendämmerungen.",
	["La pantalla se pone negra uno o dos segundos mientras el juego vuelve a arrancar los gráficos. No sales del juego ni pierdes nada."] = "Der Bildschirm wird ein, zwei Sekunden schwarz, während das Spiel die Grafik neu startet. Du verlässt das Spiel nicht und verlierst nichts.",
	["La pesca de Alfa está apagada"] = "Alfas Angeln ist aus",
	["La pesca se rehízo: una sola tecla para equiparte, lanzar y recoger, con diario, logros y una guía de 1 a 300."] = "Das Angeln wurde neu gebaut: eine Taste zum Ausrüsten, Auswerfen und Einholen, mit Tagebuch, Erfolgen und einem Guide von 1 bis 300.",
	["La piel verde de los orcos es una huella de la magia vil que usaron sus brujos en Draenor."] = "Die grüne Haut der Orcs ist eine Spur der Teufelsmagie, die ihre Hexenmeister auf Draenor benutzten.",
	["La precisión es lo más importante: con dos armas fallas mucho sin ella."] = "Trefferchance ist der wichtigste Wert: Mit zwei Waffen verfehlst du ohne sie oft.",
	["La primera vez: %s%s."] = "Das erste Mal: %s%s.",
	["La princesa Moira, hija de Magni Barbabronce, vive en las Profundidades de Roca Negra como esposa del emperador Thaurissan."] = "Prinzessin Moira, die Tochter von Magni Bronzebart, lebt in den Schwarzfelstiefen als Gemahlin von Imperator Thaurissan.",
	["La profesión"] = "Der Beruf",
	["La página de Bolsas; «abrir» abre tus bolsas y «banco» tu banco"] = "Die Seite Taschen; „open“ öffnet deine Taschen und „bank“ deine Bank",
	["La que te toca, con sus misiones y su botín."] = "Der passende für dich, mit seinen Quests und seiner Beute.",
	["La recoges ahora"] = "Du nimmst sie jetzt an",
	["La recomendada para ti y todas las demás"] = "Der für dich empfohlene und alle anderen",
	["La recomendada para ti y todas las demás."] = "Der für dich empfohlene und alle anderen.",
	["La ruta más rápida desde tu nivel, misión por misión."] = "Die schnellste Route ab deiner Stufe, Quest für Quest.",
	["La ruta no trae tramos."] = "Die Route enthält keine Etappen.",
	["La ruta te lleva a %s. La flecha está apagada: enciéndela en Ajustes > Guía para verla."] = "Die Route führt dich zu %s. Der Pfeil ist aus: Schalte ihn unter Einstellungen > Guide ein, um ihn zu sehen.",
	["La ruta ya no se salta para siempre una misión que todavía no puede revisar."] = "Die Route überspringt eine Quest, die sie noch nicht prüfen kann, nicht mehr für immer.",
	["La sabes"] = "Bekannt",
	["La sacas de tu plan."] = "Du nimmst sie aus deinem Plan.",
	["La sastrería usa la tela que sueltan los humanoides: lino, lana, seda, tejido mágico y tela rúnica."] = "Schneiderei nutzt den Stoff, den Humanoide fallen lassen: Leinen-, Woll-, Seiden-, Magie- und Runenstoff.",
	["La siguiente casilla cuesta %s y no te alcanza todavía."] = "Der nächste Platz kostet %s, und das reicht noch nicht.",
	["La siguiente casilla cuesta %s: cómprala con el botón del banco del juego, que ya está a la vista."] = "Das nächste Fach kostet %s: Kaufe es mit der Bankschaltfläche des Spiels, die jetzt sichtbar ist.",
	["La subasta deja escanear todo cada 15 minutos. Falta %s."] = "Das Auktionshaus erlaubt alle 15 Minuten einen vollständigen Scan. Noch %s.",
	["La subasta no aceptó el escaneo. Intenta de nuevo más tarde."] = "Das Auktionshaus hat den Scan nicht angenommen. Versuch es später erneut.",
	["La subasta no envió subastas. Intenta de nuevo más tarde."] = "Das Auktionshaus hat keine Auktionen geschickt. Versuch es später erneut.",
	["La subasta no respondió. Puede que aún esté en espera: intenta en unos minutos."] = "Das Auktionshaus hat nicht geantwortet. Vielleicht läuft die Wartezeit noch: Versuch es in ein paar Minuten.",
	["La suma de lo que guardó Alfa de cada personaje (el tuyo, al día)."] = "Die Summe dessen, was Alfa von jedem Charakter gespeichert hat (deiner ist aktuell).",
	["La tecla del botón de tu barra con esa habilidad, sobre el ícono."] = "Die Taste des Knopfes in deiner Leiste mit dieser Fähigkeit, auf dem Symbol.",
	["La tecla del mapa abre este mapa"] = "Die Kartentaste öffnet diese Karte",
	["La tecla que abre el mapa del juego (M) abre el de Alfa; en él, un botón te lleva al del juego. Apágalo y la tecla vuelve a abrir el del juego. También puedes darle una tecla propia en Opciones > Teclado > Alfa."] = "Die Taste, die die Spielkarte öffnet (M), öffnet Alfas Karte; darin bringt dich ein Knopf zur Spielkarte. Schalte es aus, und die Taste öffnet wieder die Spielkarte. Du kannst ihr auch eine eigene Taste geben unter Optionen > Tastaturbelegung > Alfa.",
	["La tecla que usabas en tu otro addon de pesca (%s) ahora pesca con Alfa."] = "Die Taste, die du in deinem anderen Angel-Addon benutzt hast (%s), angelt jetzt mit Alfa.",
	["La tela rúnica sale de humanoides de nivel 50 o más: los trols de las Tierras del Interior o los sátiros de Frondavil son buena opción."] = "Runenstoff gibt es von Humanoiden ab Stufe 50: Die Trolle im Hinterland oder die Satyrn im Teufelswald sind eine gute Wahl.",
	["La tela vil sale de sátiros y demonios de Frondavil y Azshara."] = "Teufelsstoff gibt es von Satyrn und Dämonen im Teufelswald und in Azshara.",
	["La tomo otra vez"] = "Ich nehme sie noch mal an",
	["La tribu Zandalar se considera la primera de todos los trols. Sus sacerdotes acampan en la Isla de Yojamba para frenar a Hakkar."] = "Der Stamm der Zandalar hält sich für den ersten aller Trolle. Seine Priester lagern auf der Insel Yojamba, um Hakkar aufzuhalten.",
	["La trituradora tira a la gente: vuelve a llamar su atención rápido."] = "Der Schredder schleudert Leute herum: Zieh seine Aufmerksamkeit schnell zurück.",
	["La tuya tiene %d semanas: salen seguido."] = "Deine ist %d Wochen alt: Updates kommen oft.",
	["La venta se detuvo: vendiste %d de %d."] = "Verkauf gestoppt: %d von %d verkauft.",
	["La ventana"] = "Das Fenster",
	["La ventana de talentos del juego"] = "Das Talentfenster des Spiels",
	["La ventana del Legado del juego"] = "Das Vermächtnis-Fenster des Spiels",
	["La última: %s."] = "Das letzte Mal: %s.",
	["Lady Sylvanas Brisaveloz gobierna a los Renegados. Fue general forestal de Quel'Thalas antes de que Arthas la matara."] = "Lady Sylvanas Windläufer herrscht über die Verlassenen. Sie war Waldläufergeneralin von Quel'Thalas, bevor Arthas sie tötete.",
	["Lady Vashj, que fue dama de compañía de Azshara, ahora guía a sus naga al servicio de Illidan."] = "Lady Vashj, einst eine Zofe Azsharas, führt jetzt ihre Naga im Dienst von Illidan.",
	["Lanza bolas de fuego y fuego a su alrededor: interrúmpelo y, si peleas de lejos, aléjate."] = "Er wirkt Feuerbälle und Feuer um sich herum: Unterbrich ihn und halte Abstand, wenn du auf Distanz kämpfst.",
	["Lanza bombas de humo que aturden: sal del humo."] = "Er wirft Rauchbomben, die betäuben: Raus aus dem Rauch.",
	["Lanza enredaderas que tumban a todos los que están cerca: si peleas de lejos, quédate lejos."] = "Er wirkt Ranken, die alle in seiner Nähe umwerfen: Wenn du auf Distanz kämpfst, bleib weg.",
	["Lanza fuego a su alrededor: si peleas de lejos, aléjate de él."] = "Er schleudert Feuer um sich: Wenn du auf Distanz kämpfst, halte dich von ihm fern.",
	["Lanza hechizos de tierra y pone tótems: rompan los tótems primero."] = "Er wirkt Erdzauber und stellt Totems auf: Zerstört zuerst die Totems.",
	["Lanza metal fundido: si no tanqueas, no te quedes pegado a él."] = "Er wirft geschmolzenes Metall: Wenn du nicht tankst, stell dich nicht direkt neben ihn.",
	["Lanza rayos y se puede curar: interrumpe sus hechizos."] = "Sie wirkt Blitze und kann sich heilen: Unterbrich ihre Zauber.",
	["Lanza ráfagas arcanas: interrúmpelo."] = "Er wirkt arkane Explosionen: Unterbrich ihn.",
	["Lanza sombras: interrúmpelo."] = "Er wirkt Schattenzauber: Unterbrich ihn.",
	["Lanza telarañas y una maldición: quita la maldición si puedes."] = "Er verschießt Netze und wirkt einen Fluch: Entferne den Fluch, wenn du kannst.",
	["Lanza tormentas de arena que se mueven por la sala: no te pares en ellas."] = "Er erzeugt Sandstürme, die durch den Raum ziehen: Stell dich nicht hinein.",
	["Lanza tu hechizo más fuerte desde lejos y remata con los instantáneos."] = "Wirk deinen stärksten Zauber aus der Ferne und erledige mit den Spontanzaubern.",
	["Lanza tu hechizo más fuerte primero y remata con un choque."] = "Wirk zuerst deinen stärksten Zauber und erledige mit einem Schock.",
	["Lanza una nube de veneno hacia adelante: gíralo lejos del grupo."] = "Sie speit eine Giftwolke nach vorn: Dreh sie von der Gruppe weg.",
	["Lanza una red que deja quieto a un jugador: no es grave, sigue atacando."] = "Er wirft ein Netz, das einen Spieler festhält: Nicht schlimm, greif weiter an.",
	["Lanza veneno a todos: quita el veneno si puedes."] = "Er vergiftet alle: Entferne das Gift, wenn du kannst.",
	["Lanzado"] = "Ausgeworfen",
	["Lanzamientos"] = "Würfe",
	["Lanzamientos: %d de %d"] = "Würfe: %d von %d",
	["Las Cavernas del Tiempo guardan los momentos más importantes de la historia, y el Vuelo Bronce no deja que nadie los cambie."] = "Die Höhlen der Zeit bewahren die wichtigsten Momente der Geschichte, und der bronzene Drachenschwarm lässt niemanden sie ändern.",
	["Las Estepas Ardientes se incendiaron cuando Ragnaros despertó, y sus brasas siguen sin apagarse."] = "Die Brennende Steppe fing Feuer, als Ragnaros erwachte, und ihre Glut ist bis heute nicht erloschen.",
	["Las Islas del Eco eran el hogar de los Lanza Negra, hasta que el brujo Zalazane sometió a muchos con su vudú y los demás tuvieron que mudarse a tierra firme."] = "Die Echoinseln waren die Heimat der Dunkelspeere, bis der Hexendoktor Zalazane viele mit seinem Voodoo unterwarf und die übrigen aufs Festland ziehen mussten.",
	["Las Minas de la Muerte esconden el refugio de VanCleef... y hasta un barco pirata."] = "Die Todesminen verbergen VanCleefs Versteck... und sogar ein Piratenschiff.",
	["Las Montañas Crestagrana deben su nombre a sus rocas rojizas."] = "Das Rotkammgebirge verdankt seinen Namen seinen rötlichen Felsen.",
	["Las Profundidades de Roca Negra son una ciudad enana entera bajo la montaña: la capital de los Hierro Negro."] = "Die Schwarzfelstiefen sind eine ganze Zwergenstadt unter dem Berg: die Hauptstadt der Dunkeleisenzwerge.",
	["Las Rocas Rojas de Mulgore son un lugar sagrado: ahí descansan los ancestros de los tauren."] = "Die Roten Felsen von Mulgore sind ein heiliger Ort: Dort ruhen die Ahnen der Tauren.",
	["Las Rocas Rojas son el lugar más sagrado de Mulgore: ahí descansan los ancestros de tu gente."] = "Die Roten Felsen sind der heiligste Ort von Mulgore: Dort ruhen die Ahnen deines Volkes.",
	["Las aguas de nivel 20 a 35. El rango Experto se aprende con el libro que vende el pescador de Bahía del Botín."] = "Die Gewässer der Stufen 20 bis 35. Den Rang Experte lernst du mit dem Buch, das der Angler in Beutebucht verkauft.",
	["Las barras de abajo"] = "Die unteren Leisten",
	["Las bendiciones mayores duran más y cubren a toda una clase del grupo. ¡Ahorran mucho maná!"] = "Große Segen halten länger und gelten für eine ganze Klasse der Gruppe. Sie sparen viel Mana!",
	["Las bolsas que coses siempre se venden: todo el mundo quiere más espacio."] = "Taschen, die du nähst, verkaufen sich immer: Jeder will mehr Platz.",
	["Las bombas y granadas te salvan en mazmorras y en peleas contra el otro bando."] = "Bomben und Granaten retten dich in Dungeons und in Kämpfen gegen die andere Fraktion.",
	["Las cajas cerradas las abren los pícaros; ofrécelas en el chat y a veces hasta te regalan el servicio."] = "Verschlossene Kästchen öffnen die Schurken; biete sie im Chat an, manchmal machen sie es sogar umsonst.",
	["Las cartas de la Luna Negra caen de enemigos por todo el mundo; un mazo completo se cambia en la Feria por un abalorio poderoso."] = "Dunkelmondkarten droppen von Gegnern in der ganzen Welt; ein vollständiges Deck tauschst du auf dem Jahrmarkt gegen ein mächtiges Schmuckstück.",
	["Las casas de subastas neutrales de Bahía del Botín, Gadgetzan y Vista Eterna cobran más comisión, pero te dejan comerciar con el otro bando."] = "Die neutralen Auktionshäuser in Beutebucht, Gadgetzan und der Ewigen Warte nehmen mehr Gebühr, lassen dich aber mit der anderen Fraktion handeln.",
	["Las centinelas de Vallefresno pelean sin descanso contra los leñadores orcos de Grito de Guerra."] = "Die Schildwachen des Eschentals kämpfen unermüdlich gegen die Holzfäller der Kriegshymnenorcs.",
	["Las centinelas domestican sables de hielo en Cuna del Invierno, y se los confían solo a quien se gana su respeto."] = "Die Schildwachen zähmen Frostsäbler in Winterquell und vertrauen sie nur denen an, die sich ihren Respekt verdienen.",
	["Las criaturas que invocan los enemigos por un rato."] = "Die Kreaturen, die Gegner für eine Weile beschwören.",
	["Las cuentas"] = "Die Rechnung",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "Testaccounts können nicht teilen: Das Spiel erlaubt es nicht.",
	["Las de tu ruta, las de la guía o todas: se eligen en Ajustes > Misiones, con lo demás de las misiones."] = "Die deiner Route, die des Guides oder alle: Das wählst du unter Einstellungen > Quests, zusammen mit allem anderen zu Quests.",
	["Las demás"] = "Die übrigen",
	["Las demás ranuras"] = "Die übrigen Plätze",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "Beide steigen von selbst, während du tötest und reist, und was du sammelst, verkauft sich gut: Gold für dein Reittier und deine Fähigkeiten.",
	["Las dríades son hijas de Cenarius, y los guardianes de la arboleda, sus hijos."] = "Die Dryaden sind die Töchter des Cenarius, und die Hüter des Hains seine Söhne.",
	["Las esquinas de la pantalla se oscurecen poco a poco, como en una foto."] = "Die Bildschirmecken dunkeln allmählich ab, wie auf einem Foto.",
	["Las excavaciones de los enanos despertaron a los troggs, y ahora Thelsamar tiene que cuidarse de ellos."] = "Die Grabungen der Zwerge haben die Troggs geweckt, und jetzt muss Thelsamar sich vor ihnen in Acht nehmen.",
	["Las explicaciones vuelven a salir."] = "Die Erklärungen werden wieder angezeigt.",
	["Las flores cantoras corrompidas de Frondavil se pueden purificar; al hacerlo te dan una bendición que dura un buen rato."] = "Die verderbten Singblumen im Teufelswald lassen sich reinigen; dafür bekommst du einen Segen, der eine gute Weile hält.",
	["Las fronteras entre zonas ya no parpadean al mover el mapa."] = "Die Grenzen zwischen Zonen flackern nicht mehr, wenn du die Karte bewegst.",
	["Las gafas de ingeniero solo las pueden usar ingenieros: ¡lúcelas con orgullo!"] = "Ingenieursbrillen können nur Ingenieure tragen: Trag sie mit Stolz!",
	["Las hierbas de nivel alto se venden muy bien en la casa de subastas."] = "Hochstufige Kräuter verkaufen sich im Auktionshaus sehr gut.",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "Die Zeilen, die „Ansagen“ in den Chat deiner Gruppe oder deines Schlachtzugs schreibt.",
	["Las marca con una flecha."] = "Upgrades bekommen einen Pfeil.",
	["Las marcas de la manada también en el minimapa, no solo en el mapa del mundo."] = "Die Markierungen des Rudels auch auf der Minikarte, nicht nur auf der Weltkarte.",
	["Las marcas en el suelo de hechizos y áreas. Apagarlas esconde avisos de combate: mejor dejarlas encendidas."] = "Die Bodenmarkierungen von Zaubern und Bereichen. Ausgeschaltet verbergen sie Kampfwarnungen: Lass sie besser an.",
	["Las mejores misiones que ya puedes tomar cerca de ti, en el orden más corto."] = "Die besten Quests in deiner Nähe, die du schon annehmen kannst, in der kürzesten Reihenfolge.",
	["Las mesetas de Cima del Trueno están unidas por puentes, y a la ciudad se sube en elevadores."] = "Die Hochebenen von Donnerfels sind durch Brücken verbunden, und in die Stadt fährt man mit Aufzügen hinauf.",
	["Las metas se cumplen solas al hacerlas; las notas las marcas tú. Ordénalas como quieras."] = "Ziele erfüllen sich von selbst, wenn du sie erledigst; Notizen hakst du selbst ab. Ordne sie, wie du willst.",
	["Las misiones de Molino Tarren mandan a la Horda contra las granjas humanas de las laderas."] = "Die Quests in Tarrens Mühle schicken die Horde gegen die Menschenhöfe im Vorgebirge.",
	["Las misiones grises dan poca XP. Entrégalas y sigue adelante."] = "Graue Quests geben wenig EP. Gib sie ab und mach weiter.",
	["Las misiones previas y el nivel que pide, para poder tomarla."] = "Die vorherigen Quests und die nötige Stufe, damit du sie annehmen kannst.",
	["Las misiones que más experiencia dan cerca de ti."] = "Die Quests in deiner Nähe, die die meiste Erfahrung geben.",
	["Las misiones repetibles de reputación, como entregar tela, también son una forma de farmeo."] = "Wiederholbare Rufquests, wie das Abgeben von Stoff, sind auch eine Art Farmen.",
	["Las monturas de los gnomos son mecazancudos, aves mecánicas que ellos mismos inventaron."] = "Die Reittiere der Gnome sind Roboschreiter, mechanische Vögel, die sie selbst erfunden haben.",
	["Las monturas de otra raza de tu bando pueden pedir reputación con su ciudad: la de tu raza siempre se puede."] = "Reittiere eines anderen Volkes deiner Fraktion können Ruf bei dessen Stadt verlangen: Die deines Volkes gehen immer.",
	["Las monturas de tu raza"] = "Die Reittiere deines Volkes",
	["Las monturas épicas del Clásico cuestan bastante oro; juntarlo poco a poco es parte de la aventura."] = "Die epischen Reittiere in Classic kosten ordentlich Gold; es nach und nach zu sparen gehört zum Abenteuer.",
	["Las ondas al caminar o nadar en el agua."] = "Die Wellen beim Gehen oder Schwimmen im Wasser.",
	["Las orillas de la pantalla un poco más oscuras."] = "Leicht abgedunkelte Bildschirmränder.",
	["Las pestañas toman la letra y los colores del estilo; la elegida lleva la línea de acento. En Clásico WoW quedan las del juego."] = "Die Tabs übernehmen Schrift und Farben des Stils; der gewählte bekommt die Akzentlinie. Bei Klassisches WoW bleiben die des Spiels.",
	["Las piedras de afilar y los contrapesos que haces le sirven a guerreros y pícaros: siempre tienen compradores."] = "Die Wetzsteine und Gewichtssteine, die du machst, helfen Kriegern und Schurken: Sie finden immer Käufer.",
	["Las piedras de salud que creas le salvan la vida a todo tu grupo."] = "Die Gesundheitssteine, die du erschaffst, retten deiner ganzen Gruppe das Leben.",
	["Las placas de nombre de los enemigos."] = "Die Namensplaketten der Gegner.",
	["Las plantas de herboristería."] = "Pflanzen für Kräuterkunde.",
	["Las pociones de vida y maná siempre se venden: toda mazmorra las pide."] = "Heil- und Manatränke verkaufen sich immer: Jeder Dungeon braucht sie.",
	["Las primeras misiones de un humano en Villanorte van de kóbolds, bandidos Defias... y lobos. No todos somos buenos, ¿eh?"] = "Die ersten Quests eines Menschen in Nordhain drehen sich um Kobolde, Defias-Banditen... und Wölfe. Nicht alle von uns sind nett, was?",
	["Las profesiones de fabricación dan retos del Legado al llegar a 150, 225 y 300."] = "Herstellungsberufe geben Vermächtnis-Herausforderungen bei 150, 225 und 300.",
	["Las profesiones de recolección dan oro desde el nivel 1. ¡Hierbas o minería!"] = "Sammelberufe bringen ab Stufe 1 Gold. Kräuter oder Bergbau!",
	["Las que Lya ya te dijo sus tres veces. Con «Volver a mostrarlos» salen otra vez."] = "Die Sätze, die Lya dir schon dreimal gesagt hat. Mit „Wieder zeigen“ kommen sie wieder.",
	["Las que me faltan"] = "Die mir fehlen",
	["Las que se hacen una sola vez."] = "Die, die man nur einmal macht.",
	["Las que se repiten cada día."] = "Die, die sich jeden Tag wiederholen.",
	["Las que se repiten cada semana."] = "Die, die sich jede Woche wiederholen.",
	["Las que tengo"] = "Die ich habe",
	["Las que vienen después, más pequeñas a la derecha."] = "Die folgenden, kleiner, rechts daneben.",
	["Las que ya hiciste no cuentan."] = "Bereits erledigte Quests zählen nicht.",
	["Las ranuras que tu tecla nunca cambia: cabeza, manos, pies, abalorios y las demás."] = "Die Plätze, die deine Taste nie wechselt: Kopf, Hände, Füße, Schmuckstücke und die übrigen.",
	["Las recetas se compran a vendedores de comida y algunas caen de enemigos."] = "Rezepte kauft man bei Nahrungshändlern, und manche droppen von Gegnern.",
	["Las ruinas de Eldarath fueron una ciudad élfica; hoy están llenas de naga."] = "Die Ruinen von Eldarath waren einst eine Elfenstadt; heute sind sie voller Naga.",
	["Las rutas y los planes que armas en la página Ruta de Alfa."] = "Die Routen und Pläne, die du auf Alfas Seite Route erstellst.",
	["Las sacerdotisas de Elune guían a tu pueblo, y Tyrande lo gobierna desde el Templo de la Luna."] = "Die Priesterinnen der Elune leiten dein Volk, und Tyrande regiert es vom Tempel des Mondes aus.",
	["Las sesiones guardadas de este personaje."] = "Die gespeicherten Sitzungen dieses Charakters.",
	["Las sesiones, las zonas y los objetos de este personaje."] = "Die Sitzungen, Gebiete und Gegenstände dieses Charakters.",
	["Las vendas suben de lino a lana, seda, tejido mágico y tela rúnica."] = "Verbände steigen von Leinen über Wolle, Seide und Magiestoff bis Runenstoff auf.",
	["Las ventanas de chat, sus pestañas y la caja para escribir toman el estilo que elijas abajo y cambian con él. Al apagarlo vuelve el chat de siempre, sin /reload."] = "Die Chatfenster, ihre Tabs und das Eingabefeld übernehmen den unten gewählten Stil und wechseln mit ihm. Ausgeschaltet kommt der gewohnte Chat zurück, ohne /reload.",
	["Lavanda"] = "Lavendel",
	["Lechúcico"] = "Mondkingestalt",
	["Lectura del agua"] = "Das Wasser lesen",
	["Lee el precio más bajo de cada objeto en toda la subasta. No compra ni publica nada. Se puede usar cada 15 minutos."] = "Liest den niedrigsten Preis jedes Gegenstands im ganzen Auktionshaus. Kauft und stellt nichts ein. Alle 15 Minuten nutzbar.",
	["Lee los objetivos de la misión antes de salir: te ahorras vueltas."] = "Lies die Questziele, bevor du losziehst: Das spart Umwege.",
	["Leeroy Jenkins se hizo famoso por lanzarse solo, gritando su nombre, a una sala llena de dragoncitos en la Cumbre de Roca Negra."] = "Leeroy Jenkins wurde berühmt, weil er allein und seinen eigenen Namen brüllend in einen Raum voller Welpen in der Schwarzfelsspitze stürmte.",
	["Legado"] = "Vermächtnis",
	["Legendario"] = "Legendär",
	["Lejos de aquí"] = "Weit weg",
	["Lejos de aquí: %s"] = "Weit weg: %s",
	["Letra del estilo"] = "Schrift des Stils",
	["Letras grandes en el centro de la pantalla cuando el jefe hace algo importante."] = "Große Schrift in der Bildschirmmitte, wenn der Boss etwas Wichtiges tut.",
	["Leyenda"] = "Legende",
	["Leyendo precios... %d%%"] = "Lese Preise... %d%%",
	["Leyendo tus bolsas…"] = "Deine Taschen werden gelesen…",
	["Libera tu sello en el enemigo: daño extra."] = "Entfessle dein Siegel auf den Gegner: zusätzlicher Schaden.",
	["Liberar tu espíritu en campos de batalla"] = "Geist auf Schlachtfeldern freilassen",
