	["Libro"] = "Buch",
	["Ligado: no se subasta"] = "Gebunden: nicht versteigerbar",
	["Limpien a sus ayudantes antes de empezar con él."] = "Räumt seine Helfer weg, bevor ihr ihn angreift.",
	["Lista"] = "Bereit",
	["Lista de pasos"] = "Schrittliste",
	["Lista para entrar"] = "Bereit zum Betreten",
	["Lista para entregar"] = "Bereit zur Abgabe",
	["Listas"] = "Bereit",
	["Listas para entregar"] = "Bereit zur Abgabe",
	["Listo"] = "Fertig",
