	["Listo, fijarlos"] = "Fertig, fixieren",
	["Listo: %d habilidades nuevas en tu barra de %s."] = "Fertig: %d neue Fähigkeiten in deiner Leiste für %s.",
	["Listo: 1 habilidad nueva en tu barra de %s."] = "Fertig: 1 neue Fähigkeit in deiner Leiste für %s.",
	["Listo: aprendiste %d rangos de talento"] = "Fertig: Du hast %d Talentränge gelernt",
	["Listo: aprendiste 1 rango de talento"] = "Fertig: Du hast 1 Talentrang gelernt",
	["Listo: te abrimos un susurro para %s. Revisa el mensaje y pulsa Intro."] = "Fertig: Wir haben ein Flüstern an %s geöffnet. Prüf die Nachricht und drück Enter.",
	["Listo: tu mapa también funciona en los marcos de Blizzard."] = "Fertig: Deine Belegung funktioniert auch in Blizzards Rahmen.",
	["Llama a varios lobos al empezar: usen ataques en área o maten primero a los lobos."] = "Zu Beginn ruft er mehrere Wölfe: Nutzt Flächenangriffe oder tötet zuerst die Wölfe.",
	["Llave"] = "Schlüssel",
	["Llavero"] = "Schlüsselbund",
	["Llaves"] = "Schlüssel",
	["Llega Lya, una loba compañera que guarda la historia de cada misión y te cuenta datos de cada zona."] = "Hier kommt Lya, eine Wolfsgefährtin, die die Geschichte jeder Quest aufbewahrt und dir Fakten zu jeder Zone erzählt.",
	["Llega a 150 de habilidad."] = "Erreiche Fertigkeit 150.",
	["Llega a 225 de habilidad."] = "Erreiche Fertigkeit 225.",
	["Llega a 75 de habilidad."] = "Erreiche Fertigkeit 75.",
	["Llega a la habilidad máxima de pesca."] = "Erreiche die höchste Angelfertigkeit.",
	["Llega a la maestría Diestro con una captura."] = "Erreiche mit einem Fang die Meisterschaft Geschickt.",
	["Llega a nivel %d"] = "Erreiche Stufe %d",
	["Llega a nivel 25 con cualquier clase"] = "Erreiche mit einer beliebigen Klasse Stufe 25",
	["Llega al nivel 40 (te faltan %d)"] = "Erreiche Stufe 40 (noch %d)",
	["Llega con %d puntos del legado ganados en tu cuenta."] = "Erreiche %d auf deinem Account verdiente Vermächtnispunkte.",
	["Llega con ayudantes naga: mátenlos primero."] = "Sie kommt mit Naga-Helfern: Tötet sie zuerst.",
	["Llega con guardias: tírenlos aparte si pueden."] = "Er kommt mit Wachen: Zieht sie von ihm weg, wenn ihr könnt.",
	["Llega con lobos: elimínenlos primero."] = "Er kommt mit Wölfen: Erledigt sie zuerst.",
	["Llega con su perro: una persona debe tanquear a cada uno, o maten al perro primero."] = "Er bringt seinen Hund mit: Je eine Person tankt einen, oder tötet zuerst den Hund.",
	["Llega en el nivel %d"] = "Kommt auf Stufe %d",
	["Llegar a nivel %d"] = "Stufe %d erreichen",
	["Llegar a un nivel"] = "Eine Stufe erreichen",
	["Llegas al rival con ira para pegar de inmediato."] = "Du erreichst den Gegner mit Wut, um sofort zuzuschlagen.",
	["Llegaste al final; quedaron %d pasos sin hacer."] = "Du hast das Ende erreicht; %d Schritte blieben offen.",
	["Llegaste con %s."] = "Du hast %s erreicht.",
	["Llenar mi barra"] = "Meine Leiste füllen",
	["Lleva al máximo la distancia de la cámara (la de Opciones > Controles). Al apagarlo vuelve la que tenías."] = "Stellt den Kameraabstand (den unter Optionen > Steuerung) aufs Maximum. Beim Ausschalten kommt deiner zurück.",
	["Lleva siempre un sello puesto aunque estés curando."] = "Halte immer ein Siegel aktiv, auch wenn du heilst.",
	["Lleva siempre vendas y comida: descansar poco y seguro es más rápido que morir."] = "Hab immer Verbände und Essen dabei: Kurz und sicher rasten ist schneller als sterben.",
	["Llevarla a Mis planes"] = "Zu „Meine Pläne“ hinzufügen",
	["Llevas %s ahora. Solo oro entero (10 = 10 de oro)."] = "Du hast jetzt %s dabei. Nur ganzes Gold (10 = 10 Gold).",
	["Llevas %s jugando. Estírate, toma agua y regresas con más fuerza."] = "Du spielst seit %s. Streck dich, trink Wasser und komm stärker zurück.",
	["Llevas %s. La manada te espera aunque te tomes un respiro."] = "Schon %s. Das Rudel wartet auf dich, auch wenn du eine Pause machst.",
	["Llevas %s. Si cierras sesión en una posada, ganas XP descansada."] = "Schon %s. Wenn du dich in einem Gasthaus ausloggst, bekommst du Ruhebonus.",
	["Llorar"] = "Weinen",
	["Llámala antes de pelear."] = "Ruf es vor dem Kampf.",
	["Llévame"] = "Bring mich hin",
	["Llévame a la entrada"] = "Bring mich zum Eingang",
	["Llévame a la subasta"] = "Bring mich zum Auktionshaus",
	["Llévame a lo que falta"] = "Bring mich zu dem, was fehlt",
	["Llévame a reparar"] = "Bring mich zum Reparieren",
	["Llévame a un vendedor"] = "Bring mich zu einem Händler",
	["Llévame al banco"] = "Bring mich zur Bank",
	["Llévame al comerciante"] = "Bring mich zu einem Händler",
	["Llévame al instructor"] = "Bring mich zum Lehrer",
	["Llévame con mi entrenador"] = "Bring mich zu meinem Lehrer",
	["Lo acompañan otros lanzadores: interrúmpanlos."] = "Andere Zauberwirker begleiten ihn: Unterbrecht sie.",
	["Lo alto de cada compañero."] = "Wie hoch jedes Mitglied ist.",
	["Lo ancho de cada compañero."] = "Wie breit jedes Mitglied ist.",
	["Lo apagas o lo enciendes cuando quieras en Manada > La Jauría."] = "Ein- oder ausschalten kannst du es jederzeit unter Rudel > La Jauría.",
	["Lo conozco de memoria"] = "Kenne ich auswendig",
	["Lo de %s y %s tiene su historia. ¿Te la platico?"] = "Die Sache mit %s und %s hat ihre Geschichte. Willst du sie hören?",
	["Lo demás, de un vistazo"] = "Der Rest auf einen Blick",
	["Lo enseña un instructor de la profesión"] = "Wird von einem Berufslehrer gelehrt",
	["Lo enseña un instructor en %s"] = "Wird von einem Lehrer in %s gelehrt",
	["Lo esencial"] = "Das Wichtigste",
	["Lo estás siguiendo"] = "Du folgst ihm",
	["Lo estás siguiendo."] = "Du folgst der Person.",
	["Lo gris véndelo a los vendedores, no en la subasta: nadie lo va a comprar ahí."] = "Verkauf Graues an Händler, nicht im Auktionshaus: Dort kauft es niemand.",
	["Lo gris y lo que marcaste como chatarra. Nunca lo que marcaste para conservar ni lo que pide una misión."] = "Graue Gegenstände und was du als Plunder markiert hast. Nie, was du zum Behalten markiert hast oder was eine Quest braucht.",
	["Lo justo para abrir la siguiente fila."] = "Gerade genug, um die nächste Reihe zu öffnen.",
	["Lo marca como tu objetivo"] = "Macht es zu deinem Ziel",
	["Lo mejor de los dos lados. Si no sabes cuál elegir, elige este."] = "Das Beste aus beiden Seiten. Wenn du nicht weißt, was du wählen sollst, nimm diesen.",
	["Lo mejor para ti"] = "Das Beste für dich",
	["Lo mejor para tu nivel"] = "Das Beste für deine Stufe",
	["Lo menos que espera Lya entre un consejo y otro. Lo importante no espera."] = "Wie lange Lya mindestens zwischen zwei Tipps wartet. Wichtiges wartet nicht.",
	["Lo menos que espera Lya entre una historia y otra. Nunca en combate ni en mazmorras."] = "Wie lange Lya mindestens zwischen zwei Geschichten wartet. Nie im Kampf oder in Dungeons.",
	["Lo más cerca"] = "Am nächsten",
	["Lo más cerca de ti"] = "Am nächsten bei dir",
	["Lo más ligero: para equipos modestos o para subir los FPS en peleas grandes."] = "Das Leichteste: für schwächere Rechner oder für mehr FPS in großen Kämpfen.",
	["Lo más parecido"] = "Am ähnlichsten",
	["Lo nuevo de esta versión"] = "Neu in dieser Version",
	["Lo nuevo de esta versión, en pocas palabras."] = "Was diese Version bringt, in wenigen Worten.",
	["Lo nuevo en Alfa %s"] = "Neu in Alfa %s",
	["Lo nuevo en Alfa 1.0"] = "Neu in Alfa 1.0",
	["Lo pequeño que hace el juego más cómodo: el minimapa, el chat y las barras con el estilo de Alfa, marcos, cuadro de información, probador, cámara y sonidos; y en sus pestañas, viajes, invitaciones, comerciantes y más."] = "Die kleinen Dinge, die das Spiel bequemer machen: Minikarte, Chat und Leisten im Stil von Alfa, Rahmen, Tooltip, Anprobe, Kamera und Klänge; und in den Reitern Reisen, Einladungen, Händler und mehr.",
	["Lo pequeño que hace el juego más cómodo: misiones, vuelos, minimapa, chat y barras con el estilo de Alfa, marcos, cuadro de información, probador, cámara y sonidos."] = "Die kleinen Dinge, die das Spiel bequemer machen: Quests, Flüge, Minikarte, Chat und Leisten in Alfas Stil, Rahmen, Tooltip, Anprobe, Kamera und Klänge.",
	["Lo pescado en esta sesión"] = "In dieser Sitzung geangelt",
	["Lo piden estas misiones"] = "Quests, die es verlangen",
	["Lo pones al empezar a pelear."] = "Du setzt es zu Kampfbeginn ein.",
	["Lo que Alfa acepta, rechaza o comparte sola. Mantén presionado Mayús para decidir tú en el momento."] = "Was Alfa von selbst annimmt, ablehnt oder teilt. Halte Umschalt gedrückt, um im Moment selbst zu entscheiden.",
	["Lo que Lya sabe de aquí"] = "Was Lya über diesen Ort weiß",
	["Lo que buscas en la Enciclopedia"] = "Was du in der Enzyklopädie nachschlägst",
	["Lo que comparte alguien de tu grupo con Alfa llega a tus marcadores, con su nombre, y te avisa para seguirlo."] = "Was jemand aus deiner Gruppe mit Alfa teilt, landet mit seinem Namen in deinen Markierungen, und du bekommst Bescheid, um ihm zu folgen.",
	["Lo que conoce Alfa"] = "Was Alfa kennt",
	["Lo que cuentan las misiones que vas tomando"] = "Was die Quests erzählen, die du annimmst",
	["Lo que da"] = "Was es liefert",
	["Lo que dice el diario de monturas"] = "Was die Reittiersammlung sagt",
	["Lo que el menú del juego no enseña, a tu gusto"] = "Was das Spielmenü nicht zeigt, nach deinem Geschmack",
	["Lo que encuentras en la manada"] = "Was dich im Rudel erwartet",
	["Lo que este personaje lleva en las mazmorras: se guarda solo al vencer jefes y recoger botín."] = "Was dieser Charakter in Dungeons geschafft hat: wird von selbst gespeichert, wenn du Bosse besiegst und Beute aufhebst.",
	["Lo que ganaste la última vez que jugaste con este personaje."] = "Was du beim letzten Spielen mit diesem Charakter erreicht hast.",
	["Lo que gastan tus hechizos"] = "Was deine Zauber verbrauchen",
	["Lo que hay dentro"] = "Was drin ist",
	["Lo que llevas"] = "Was du trägst",
	["Lo que llevas pescado: %s."] = "Was du bisher geangelt hast: %s.",
	["Lo que me sirve"] = "Was mir nützt",
	["Lo que menos vale: %s"] = "Am wenigsten wert: %s",
	["Lo que más conviene ahora"] = "Was sich jetzt am meisten lohnt",
	["Lo que obtuviste en esta sesión"] = "Was du in dieser Sitzung bekommen hast",
	["Lo que pescaste"] = "Was du geangelt hast",
	["Lo que pide %s antes, en orden."] = "Was %s zuerst braucht, in Reihenfolge.",
	["Lo que quieras contarle al desarrollador de Alfa."] = "Was du dem Entwickler von Alfa sagen möchtest.",
	["Lo que quieras; la marcas tú cuando la hagas."] = "Was du willst; du hakst sie ab, wenn du sie erledigst.",
	["Lo que sacas en %s: %s."] = "Was du in %s fängst: %s.",
	["Lo que se pesca aquí"] = "Was man hier angelt",
	["Lo que se queda la subasta de cada venta. Suele ser 5 % en la de tu facción y 15 % en la neutral. Es un estimado."] = "Was das Auktionshaus von jedem Verkauf einbehält. Meist 5 % beim Auktionshaus deiner Fraktion und 15 % beim neutralen. Ein Schätzwert.",
	["Lo que sigue en tu build no está en tu árbol"] = "Was als Nächstes in deinem Build kommt, ist nicht in deinem Baum",
	["Lo que sigue pide este nivel: hasta entonces, la guía no te manda allá."] = "Was als Nächstes kommt, braucht diese Stufe: Bis dahin schickt dich der Guide nicht dorthin.",
	["Lo que sugiere Alfa"] = "Was Alfa vorschlägt",
	["Lo que te ha contado"] = "Was sie dir erzählt hat",
	["Lo que te pasa a ti: curación recibida, esquivas, recursos. Puede necesitar /reload la primera vez."] = "Was dir passiert: erhaltene Heilung, Ausweichen, Ressourcen. Braucht beim ersten Mal eventuell /reload.",
	["Lo que te piden"] = "Worum man dich bittet",
	["Lo que tenía ya está hecho, omitido o fuera de tu registro. Ármalo otra vez con las misiones que tienes ahora."] = "Was er hatte, ist erledigt, übersprungen oder nicht mehr in deinem Questlog. Erstelle ihn mit deinen aktuellen Quests neu.",
	["Lo que tu build necesita de tu equipo y dónde conseguirlo."] = "Was dein Build von deiner Ausrüstung braucht und wo du es bekommst.",
	["Lo que tu clase se pone antes de pelear está activo."] = "Der Buff, den deine Klasse vor dem Kampf nutzt, ist aktiv.",
	["Lo que tu profesión de recolección junta mejor."] = "Was dein Sammelberuf am besten sammelt.",
	["Lo que vale"] = "Was es wert ist",
	["Lo que ya tienes en el banco"] = "Was du schon in der Bank hast",
	["Lo recolectaste %d veces"] = "Du hast es %d-mal gesammelt",
	["Lo recolectaste 1 vez"] = "Du hast es einmal gesammelt",
	["Lo revisa el desarrollador de Alfa. En ese canal nadie más ve tu mensaje. Si aún no estás en el Discord, entra con la invitación de arriba."] = "Der Entwickler von Alfa liest es. In diesem Kanal sieht sonst niemand deine Nachricht. Wenn du noch nicht auf dem Discord bist, tritt über die Einladung oben bei.",
	["Lo sigues"] = "Du folgst ihm",
	["Lo sigues: el rastreador te muestra la meta de ahora y la flecha va a cada lugar."] = "Du folgst ihm: Der Tracker zeigt das aktuelle Ziel, und der Pfeil führt zu jedem Ort.",
	["Lo siguiente"] = "Als Nächstes",
	["Lo siguiente para ti"] = "Als Nächstes für dich",
	["Lo sueltan"] = "Fallen gelassen von",
	["Lo último que consultaste"] = "Zuletzt nachgeschlagen",
	["Lobo"] = "Wolf",
	["Lobos conectados"] = "Wölfe online",
	["Logrado el %s"] = "Erreicht am %s",
	["Logrados"] = "Erreicht",
	["Logro de pesca: %s"] = "Angelerfolg: %s",
	["Logros"] = "Erfolge",
	["Logros de pesca"] = "Angelerfolge",
	["Lord Kazzak, un demonio enorme, ronda las Tierras Devastadas; en el Clásico es un jefe de mundo para bandas."] = "Lord Kazzak, ein riesiger Dämon, streift durch die Verwüsteten Lande; in Classic ist er ein Weltboss für Schlachtzüge.",
	["Lord Xavius, el consejero de Azshara, convenció a los Altonato de abrirle la puerta a Sargeras. Cuando murió, Sargeras lo trajo de vuelta como el primer sátiro."] = "Lord Xavius, Azsharas Berater, überzeugte die Hochgeborenen, Sargeras das Tor zu öffnen. Als er starb, holte Sargeras ihn als ersten Satyr zurück.",
	["Los Altonato eran la nobleza élfica que vivía para la magia del Pozo. Su reina, Azshara, era tan bella que su pueblo la adoraba."] = "Die Hochgeborenen waren der Elfenadel, der für die Magie des Brunnens lebte. Ihre Königin Azshara war so schön, dass ihr Volk sie anbetete.",
	["Los Amani pelearon contra los altos elfos durante miles de años. Su capital, Zul'Aman, está en los bosques cerca de Quel'Thalas."] = "Die Amani kämpften tausende Jahre gegen die Hochelfen. Ihre Hauptstadt Zul'Aman liegt in den Wäldern nahe Quel'Thalas.",
	["Los Barbabronce ganaron la Guerra de los Tres Martillos, y por eso Forjaz es suya."] = "Die Bronzebärte gewannen den Krieg der drei Hämmer, und deshalb gehört Eisenschmiede ihnen.",
	["Los Claros de Tirisfal guardan las ruinas de Lordaeron, el reino de Arthas. Bajo su antigua capital, los Renegados levantaron Entrañas."] = "Tirisfal birgt die Ruinen von Lordaeron, dem Königreich von Arthas. Unter seiner alten Hauptstadt errichteten die Verlassenen Unterstadt.",
	["Los Defias usan cosechadores mecánicos que trabajan solos en los campos... y no les gustan las visitas."] = "Die Defias nutzen Erntegolems, die die Felder von selbst bestellen... und Besuch nicht mögen.",
	["Los Furiarena de Zul'Farrak son trols del desierto, primos lejanos de los Lanza Negra."] = "Die Sandwut von Zul'Farrak sind Wüstentrolle, entfernte Vettern der Dunkelspeere.",
	["Los Gurubashi llamaron a Hakkar, el Desollador de Almas. Cuando vieron lo que hacía, las demás tribus se unieron para echarlo."] = "Die Gurubashi riefen Hakkar den Seelenschinder herbei. Als sie sahen, was er tat, schlossen sich die anderen Stämme zusammen, um ihn zu vertreiben.",
	["Los Hierro Negro invocaron a Ragnaros sin querer al final de la Guerra de los Tres Martillos, y desde entonces son sus esclavos."] = "Die Dunkeleisenzwerge beschworen Ragnaros am Ende des Kriegs der drei Hämmer aus Versehen, und seitdem sind sie seine Sklaven.",
	["Los Hierro Negro también excavan en Uldaman, buscando lo mismo que los enanos de Forjaz."] = "Auch die Dunkeleisenzwerge graben in Uldaman, auf der Suche nach demselben wie die Zwerge von Eisenschmiede.",
	["Los Lanza Negra suelen terminar sus frases con un «mon». ¡Se pega, mon!"] = "Die Dunkelspeere beenden ihre Sätze oft mit einem „Mann“. Das färbt ab, Mann!",
	["Los PNJ dejan de hablar al saludarte o al darte misiones. También calla las voces de error."] = "NPCs sprechen nicht mehr, wenn sie dich begrüßen oder dir Quests geben. Schaltet auch die Fehlerstimmen stumm.",
	["Los Perdidos del pantano son draenei que llegaron de Draenor y quedaron cambiados para siempre."] = "Die Verlorenen im Sumpf sind Draenei, die von Draenor kamen und für immer verändert wurden.",
	["Los Páramos de Poniente eran el granero de Ventormenta; hoy muchas de sus granjas están en manos de la Hermandad Defias."] = "Westfall war die Kornkammer Sturmwinds; heute sind viele seiner Höfe in der Hand der Defiasbruderschaft.",
	["Los Renegados aguantan bajo el agua mucho más que los vivos. ¡No necesitan respirar tanto!"] = "Die Verlassenen halten es unter Wasser viel länger aus als die Lebenden. Sie müssen nicht so viel atmen!",
	["Los Renegados entraron a la Horda gracias a los tauren, que esperaban encontrarles una cura. Muchos orcos aún no se fían de ellos."] = "Die Verlassenen kamen dank der Tauren in die Horde, die hofften, ein Heilmittel für sie zu finden. Viele Orcs trauen ihnen noch immer nicht.",
	["Los Renegados hicieron de Rémol, un viejo pueblo humano, su primera parada en Tirisfal."] = "Die Verlassenen machten Brill, einen alten Menschenort, zu ihrem ersten Halt in Tirisfal.",
	["Los Renegados nuevos despiertan en Camposanto, en Tirisfal, como no-muertos libres del Rey Exánime."] = "Neue Verlassene erwachen in Todesend in Tirisfal, als Untote, die vom Lichkönig befreit sind.",
	["Los Renegados pueden comerse cadáveres para recuperar vida. Yo prefiero las salchichas, gracias."] = "Die Verlassenen können Leichen fressen, um Gesundheit zurückzugewinnen. Ich nehme lieber Würstchen, danke.",
	["Los Renegados recuerdan quiénes fueron en vida, y eso pesa más que cualquier herida."] = "Die Verlassenen erinnern sich, wer sie im Leben waren, und das wiegt schwerer als jede Wunde.",
	["Los Renegados son no-muertos que recuperaron su voluntad cuando el poder del Rey Exánime se debilitó."] = "Die Verlassenen sind Untote, die ihren freien Willen zurückerlangten, als die Macht des Lichkönigs schwand.",
	["Los Tótem Siniestro son tauren que no quieren a la Horda; su jefa Magatha vive en la misma Cima del Trueno."] = "Die Grimmtotem sind Tauren, die die Horde nicht mögen; ihre Anführerin Magatha lebt mitten in Donnerfels.",
	["Los ajustes de los recordatorios están en la búsqueda de la ventana de Alfa."] = "Die Einstellungen der Erinnerungen findest du in der Suche des Alfa-Fensters.",
	["Los altos elfos pelearon con la Alianza en la Segunda Guerra por una vieja deuda de sangre con el linaje de Thoradin."] = "Die Hochelfen kämpften im Zweiten Krieg mit der Allianz, wegen einer alten Blutschuld gegenüber Thoradins Linie.",
	["Los altos elfos que sobrevivieron a la Plaga empezaron a llamarse elfos de sangre, en honor a los suyos caídos. Kael'thas los guía."] = "Die Hochelfen, die die Geißel überlebten, nannten sich zu Ehren ihrer Gefallenen Blutelfen. Kael'thas führt sie an.",
	["Los antídotos que haces curan venenos. ¡En las arañas de Vallefresno se agradecen!"] = "Die Gegengifte, die du machst, heilen Gifte. Bei den Spinnen im Eschental ist man dankbar dafür!",
	["Los aqir eran un imperio antiguo de insectos que peleó contra los trols. De ellos vienen los qiraji de Ahn'Qiraj y los nerubianos del norte."] = "Die Aqir waren ein altes Insektenreich, das gegen die Trolle kämpfte. Von ihnen stammen die Qiraji von Ahn'Qiraj und die Neruber im Norden ab.",
	["Los ayudantes de los enemigos."] = "Die Helfer der Gegner.",
	["Los botones de otros addons alrededor del minimapa (también el de Alfa) solo aparecen al pasar el ratón por encima."] = "Die Knöpfe anderer Addons um die Minikarte (auch der von Alfa) erscheinen nur, wenn die Maus darüber ist.",
	["Los cebos suben tu habilidad de pesca un rato: úsalos en aguas difíciles."] = "Köder erhöhen eine Weile deine Angelfertigkeit: Nutze sie in schwierigen Gewässern.",
	["Los cementerios del Ocaso están llenos de no-muertos levantados por nigromantes que se esconden en el bosque."] = "Die Friedhöfe des Dämmerwalds sind voller Untoter, erweckt von Nekromanten, die sich im Wald verstecken.",
	["Los centauros dicen descender de Zaetar, hijo del semidiós Cenarius, y de Theradras, la princesa de la tierra. Pelean entre sus clanes casi tanto como contra los demás."] = "Die Zentauren behaupten, von Zaetar, dem Sohn des Halbgotts Cenarius, und von Theradras, der Prinzessin der Erde, abzustammen. Ihre Klans bekämpfen sich fast so sehr wie alle anderen.",
	["Los cinco Aspectos Dragón recibieron su poder de los titanes: Alexstrasza la vida, Ysera el sueño, Nozdormu el tiempo, Malygos la magia y Neltharion la tierra."] = "Die fünf Drachenaspekte erhielten ihre Macht von den Titanen: Alexstrasza das Leben, Ysera den Traum, Nozdormu die Zeit, Malygos die Magie und Neltharion die Erde.",
	["Los clanes Gelkis y Magram de Desolace pelean entre sí, y ambos buscan aliados entre los aventureros."] = "Die Klans Gelkis und Magram in Desolace bekämpfen einander, und beide suchen Verbündete unter den Abenteurern.",
	["Los clanes orcos tienen historias distintas: Lobo Gélido, Grito de Guerra, Roca Negra, Faucedraco... cada uno con su orgullo."] = "Die Orcklans haben ganz unterschiedliche Geschichten: Frostwolf, Kriegshymne, Schwarzfels, Drachenmal... jeder mit seinem eigenen Stolz.",
	["Los cruzados escarlata vienen en grupos y algunos curan: interrumpan a los que curan."] = "Die Kreuzzügler des Scharlachroten Kreuzzugs kommen in Gruppen, und einige heilen: Unterbrecht die Heiler.",
	["Los críticos hacen el doble de daño y al guerrero le dan más ira."] = "Krits machen doppelten Schaden und geben dem Krieger mehr Wut.",
	["Los cuatro dragones verdes de la pesadilla, Ysondre, Lethon, Emeriss y Taerar, aparecen junto a los grandes árboles del Sueño."] = "Die vier grünen Drachen des Albtraums, Ysondre, Lethon, Emeriss und Taerar, erscheinen bei den großen Bäumen des Traums.",
	["Los cuatro señores elementales son Ragnaros del fuego, Al'Akir del aire, Therazane de la tierra y Neptulon del agua."] = "Die vier Elementarfürsten sind Ragnaros des Feuers, Al'Akir der Luft, Therazane der Erde und Neptulon des Wassers.",
	["Los cultistas del Martillo Crepuscular usan piedras de viento para invocar a sus señores; con su disfraz, tú también puedes."] = "Die Kultisten des Schattenhammers nutzen Windsteine, um ihre Fürsten zu beschwören; mit ihrer Verkleidung kannst du das auch.",
	["Los datos de Alfa no cargaron (%s)."] = "Alfas Daten wurden nicht geladen (%s).",
	["Los datos de Alfa no traen botín propio de sus jefes."] = "Alfas Daten enthalten keine eigene Beute für seine Bosse.",
	["Los datos de las mazmorras no están cargados."] = "Die Dungeondaten sind nicht geladen.",
	["Los datos de las mazmorras se cargan fuera de combate. Esta página se llena sola al terminar la pelea."] = "Dungeon-Daten werden außerhalb des Kampfes geladen. Diese Seite füllt sich von selbst, wenn der Kampf vorbei ist.",
	["Los datos del mundo (Codex) no están disponibles: faltan los bancos, las misiones y de dónde sale cada cosa."] = "Die Weltdaten (Codex) sind nicht verfügbar: Schwärme, Quests und Herkunft fehlen.",
	["Los datos del mundo de Alfa están apagados: activa «Alfa Codex» en la lista de addons."] = "Alfas Weltdaten sind ausgeschaltet: Aktiviere „Alfa Codex“ in der AddOn-Liste.",
	["Los datos son del medidor oficial del juego: tú, tu grupo o banda y sus mascotas."] = "Die Daten stammen vom offiziellen Schadensmesser des Spiels: du, deine Gruppe oder dein Schlachtzug und ihre Begleiter.",
	["Los dioses antiguos son seres de antes de los titanes, encerrados bajo la tierra de Azeroth. C'Thun y Yogg-Saron susurran a quien quiera escuchar."] = "Die Alten Götter sind Wesen, die älter als die Titanen sind, eingesperrt unter dem Boden Azeroths. C'Thun und Yogg-Saron flüstern jedem zu, der zuhören will.",
	["Los dioses antiguos susurran en la mente de los mortales; muchos cultos, como el Martillo Crepuscular, nacieron de escucharlos."] = "Die Alten Götter flüstern im Geist der Sterblichen; viele Kulte, wie der Schattenhammer, entstanden, weil man ihnen zuhörte.",
	["Los dos"] = "Beide",
	["Los dos bandos"] = "Beide Fraktionen",
	["Los dracoleones son las monturas voladoras de la Horda; los grifos, las de la Alianza; y los hipogrifos, las de los elfos de la noche."] = "Windreiter sind die Flugreittiere der Horde, Greifen die der Allianz und Hippogryphen die der Nachtelfen.",
	["Los dracónidos negros rondan la entrada de la guarida de Onyxia, al sur del marjal."] = "Schwarze Drachkin streifen am Eingang von Onyxias Hort im Süden der Marschen umher.",
	["Los dracónidos son los soldados de los dragones; los negros sirven a Nefarian en la Montaña Roca Negra."] = "Die Drachkin sind die Soldaten der Drachen; die schwarzen dienen Nefarian im Schwarzfels.",
	["Los draenei huyeron de su mundo, Argus, con el profeta Velen. Su nombre quiere decir «los exiliados»."] = "Die Draenei flohen mit dem Propheten Velen von ihrer Welt Argus. Ihr Name bedeutet „die Verbannten“.",
	["Los dragones cromáticos, con escamas de todos los colores, son experimentos de Nefarian. Su obra más temida es Chromaggus."] = "Chromatische Drachen mit Schuppen in allen Farben sind Nefarians Experimente. Seine gefürchtetste Schöpfung ist Chromaggus.",
	["Los dragones negros se disfrazan de humanos para engañar: Onyxia es Lady Katrana Prestor en Ventormenta, y Nefarian se hace llamar Lord Victor Nefarius."] = "Schwarze Drachen verkleiden sich als Menschen, um zu täuschen: Onyxia ist Lady Katrana Prestor in Sturmwind, und Nefarian nennt sich Lord Victor Nefarius.",
	["Los dragones verdes siguen vigilando el templo hundido para que nadie vuelva a llamar a Hakkar."] = "Die grünen Drachen bewachen den versunkenen Tempel bis heute, damit niemand Hakkar wieder ruft.",
	["Los elementales de fuego de La Garganta de Fuego y del Cráter de Un'Goro sueltan materiales de fuego que piden muchas profesiones."] = "Die Feuerelementare der Sengenden Schlucht und des Kraters von Un'Goro lassen Feuermaterialien fallen, die viele Berufe brauchen.",
	["Los elementales de fuego y las arañas de lava son los vecinos de siempre de La Garganta de Fuego."] = "Feuerelementare und Lavaspinnen sind die alten Nachbarn in der Sengenden Schlucht.",
	["Los elfos de la noche fueron inmortales gracias a Nordrassil, hasta que lo sacrificaron para vencer a Archimonde en el Monte Hyjal."] = "Die Nachtelfen waren dank Nordrassil unsterblich, bis sie ihn opferten, um Archimonde am Berg Hyjal zu besiegen.",
	["Los elfos de la noche montan sables, grandes felinos. No es por nada, pero un lobo es más simpático."] = "Nachtelfen reiten Säbler, große Raubkatzen. Ich will ja nichts sagen, aber ein Wolf ist netter.",
	["Los elfos de la noche nuevos empiezan en la Cañada Umbría, en Teldrassil, entre arañas y fuegos fatuos."] = "Neue Nachtelfen beginnen im Laubschattental auf Teldrassil, zwischen Spinnen und Irrwischen.",
	["Los elfos de la noche pueden fundirse con las sombras cuando se quedan quietos."] = "Nachtelfen können mit den Schatten verschmelzen, wenn sie stillstehen.",
	["Los elfos de la noche se unieron a la Alianza después de la Tercera Guerra."] = "Die Nachtelfen traten nach dem Dritten Krieg der Allianz bei.",
	["Los enanos Hierro Negro tomaron Dun Modr, al norte de Los Humedales, y desde ahí molestan a quien cruce el puente."] = "Die Dunkeleisenzwerge haben Dun Modr im Norden des Sumpflands eingenommen und belästigen von dort jeden, der die Brücke überquert.",
	["Los enanos creen descender de los terráneos de piedra de los titanes, y por eso la Liga de Expedicionarios excava sin parar."] = "Die Zwerge glauben, von den steinernen Irdenen der Titanen abzustammen, und deshalb gräbt die Forscherliga ununterbrochen.",
	["Los enanos de Forjaz pelean contra los Hierro Negro en Los Humedales y en las Tierras Inhóspitas."] = "Die Zwerge von Eisenschmiede kämpfen im Sumpfland und im Ödland gegen die Dunkeleisenzwerge.",
	["Los enanos nuevos empiezan en un valle helado de Dun Morogh, peleando contra trols de las nieves y troggs."] = "Neue Zwerge beginnen in einem eisigen Tal von Dun Morogh und kämpfen gegen Eistrolle und Troggs.",
	["Los encantadores también hacen varitas: los magos, sacerdotes y brujos te lo agradecerán."] = "Verzauberer machen auch Zauberstäbe: Magier, Priester und Hexenmeister werden es dir danken.",
	["Los enemigos de alrededor pegan menos."] = "Gegner um dich herum treffen schwächer.",
	["Los enemigos de tus misiones marcados sobre su placa de nombre y los objetos de misión brillando en tus bolsas."] = "Gegner deiner Quests über ihrer Namensplakette markiert und Questgegenstände, die in deinen Taschen leuchten.",
	["Los enemigos lanzan radiación y veneno: lleven pociones de vida."] = "Die Gegner setzen Strahlung und Gift ein: Bringt Heiltränke mit.",
	["Los enemigos más débiles, que el juego marca con un signo de menos."] = "Die schwächsten Gegner, die das Spiel mit einem Minuszeichen markiert.",
	["Los espíritus de las elfas caídas que la Plaga esclaviza se vuelven banshees. Sylvanas es la más famosa de todas."] = "Die Geister gefallener Elfinnen, die die Geißel versklavt, werden zu Banshees. Sylvanas ist die berühmteste von allen.",
	["Los fragmentos de alma se ganan drenando el alma del enemigo justo cuando muere."] = "Seelensplitter bekommst du, indem du dem Gegner genau bei seinem Tod die Seele entziehst.",
	["Los frascos del Clásico duran dos horas y aguantan aunque mueras: por eso las bandas los piden tanto."] = "Fläschchen halten in Classic zwei Stunden und bleiben auch beim Tod: Darum wollen Schlachtzüge sie so oft.",
	["Los frascos más poderosos llevan Loto negro, la hierba más rara de Azeroth."] = "Die stärksten Fläschchen brauchen Schwarzen Lotus, das seltenste Kraut Azeroths.",
	["Los fuegos artificiales también son ingeniería. ¡Uno para festejar cada nivel!"] = "Feuerwerk ist auch Ingenieurskunst. Eins für jede Stufe, um sie zu feiern!",
	["Los fuegos fatuos son espíritus de elfos de la noche que siguen cuidando el bosque después de morir."] = "Irrwische sind Geister von Nachtelfen, die auch nach dem Tod weiter den Wald hüten.",
	["Los furbolgs Fauces de Madera son de los pocos que no se han corrompido; sus túneles llevan a Cuna del Invierno y al Claro de la Luna."] = "Die Furbolgs der Holzschlunde gehören zu den wenigen, die nicht verdorben sind; ihre Tunnel führen nach Winterquell und zur Mondlichtung.",
	["Los furbolgs de Costa Oscura se están corrompiendo, y los elfos de Auberdine no saben bien por qué."] = "Die Furbolgs der Dunkelküste werden verdorben, und die Elfen von Auberdine wissen nicht so recht, warum.",
	["Los furbolgs eran un pueblo pacífico de hombres oso, pero la corrupción de los demonios enloqueció a muchas de sus tribus."] = "Die Furbolgs waren ein friedliches Bärenvolk, doch die Verderbnis der Dämonen hat viele ihrer Stämme in den Wahnsinn getrieben.",
	["Los geomantes lanzan fuego y ponen tótems: interrúmpanlos y rompan los tótems."] = "Die Geomanten wirken Feuer und stellen Totems auf: Unterbrecht sie und zerstört die Totems.",
	["Los gnomos empiezan con los enanos en Dun Morogh: Gnomeregan está perdida y tu gente vive refugiada en Forjaz."] = "Gnome beginnen zusammen mit den Zwergen in Dun Morogh: Gnomeregan ist verloren, und dein Volk lebt als Flüchtlinge in Eisenschmiede.",
	["Los gnomos inventaron el Tranvía Subterráneo que une Forjaz con Ventormenta."] = "Die Gnome erfanden die Tiefenbahn, die Eisenschmiede mit Sturmwind verbindet.",
	["Los gnomos que se quedaron en Gnomeregan quedaron dañados por la radiación; algunos perdieron la razón."] = "Die Gnome, die in Gnomeregan blieben, wurden durch die Strahlung geschädigt; manche verloren den Verstand.",
	["Los goblins de la fundición tienen ayudantes cerca: miren alrededor antes de atacar."] = "Die Goblins in der Gießerei haben Helfer in der Nähe: Schaut euch um, bevor ihr angreift.",
	["Los goblins vienen de la isla de Kezan, y su gran ciudad es Minahonda. Le son más leales al oro que a cualquier bando."] = "Goblins stammen von der Insel Kezan, und ihre große Stadt ist Lorenhall. Sie sind dem Gold treuer als jeder Fraktion.",
	["Los grandes árboles que hablan en Darnassus y Vallefresno son Ancestros, guardianes del bosque."] = "Die großen sprechenden Bäume in Darnassus und im Eschental sind Urtume, Wächter des Waldes.",
	["Los grifos (o dragones) a los lados de la barra principal."] = "Die Greifen (oder Wyvern) an den Seiten der Hauptleiste.",
	["Los grifos (o dragones) a los lados de la barra principal. «Del color del estilo» necesita el estilo de las barras; «Ocultos» funciona siempre."] = "Die Greifen (oder Wyvern) an den Seiten der Hauptleiste. „In der Farbe des Stils“ braucht den Leistenstil; „Versteckt“ geht immer.",
	["Los gules, las abominaciones y las gárgolas son los soldados más comunes de la Plaga. Las abominaciones se cosen con partes de muchos cadáveres."] = "Ghule, Monstrositäten und Gargoyles sind die häufigsten Soldaten der Geißel. Monstrositäten werden aus vielen Leichen zusammengenäht.",
	["Los herreros hacen llaves que abren cofres y cajas cerradas. ¡Útil y divertido!"] = "Schmiede machen Schlüssel, die Truhen und verschlossene Kästchen öffnen. Nützlich und lustig!",
	["Los humanos fueron los primeros en aprender magia de los altos elfos, allá en las Guerras Trol."] = "Die Menschen lernten als Erste Magie von den Hochelfen, damals in den Trollkriegen.",
	["Los infernales son demonios que la Legión arroja desde el cielo como meteoritos."] = "Höllenbestien sind Dämonen, die die Legion wie Meteore vom Himmel schleudert.",
	["Los ingenieros pueden fabricar mascotas mecánicas, como una ardilla."] = "Ingenieure können mechanische Haustiere bauen, etwa ein Eichhörnchen.",
	["Los instructores y vendedores de pesca se ven en el mapa y el minimapa."] = "Angellehrer und -händler erscheinen auf Karte und Minikarte.",
	["Los jefes opcionales y raros se descubren al terminar la mazmorra."] = "Optionale und rare Bosse werden entdeckt, wenn du den Dungeon abschließt.",
	["Los jefes se descubren al vencerlos: su nombre y su botín quedan ocultos hasta entonces. Sus consejos siempre se pueden ver."] = "Bosse werden entdeckt, wenn du sie besiegst: Name und Beute bleiben bis dahin verborgen. Ihre Tipps kannst du immer ansehen.",
	["Los kits de armadura que haces le sirven a todo el mundo: siempre hay quien los compre."] = "Die Rüstungssets, die du machst, kann jeder brauchen: Es findet sich immer ein Käufer.",
	["Los kodos son los compañeros de viaje de los tauren, y en Desolace está su cementerio."] = "Kodos sind die Reisegefährten der Tauren, und ihr Friedhof liegt in Desolace.",
	["Los kóbolds de las minas de Elwynn cuidan sus velas como un tesoro: bajo tierra, la luz lo es todo."] = "Die Kobolde in den Minen von Elwynn hüten ihre Kerzen wie einen Schatz: Unter der Erde ist Licht alles.",
	["Los lobos aprenden Aullido furioso, que sube el daño de tu grupo. ¡Ya ves, los lobos somos lo máximo!"] = "Wölfe lernen Wütendes Geheul, das den Schaden deiner Gruppe erhöht. Siehst du, wir Wölfe sind die Besten!",
	["Los lobos que se dejan ver en el mapa. Un clic en su marca y la flecha te lleva."] = "Die Wölfe, die sich auf der Karte zeigen. Ein Klick auf ihre Markierung, und der Pfeil führt dich hin.",
	["Los lobos que usan Alfa y se dejan ver en el mapa, y tu grupo, que ves ahora."] = "Die Wölfe, die Alfa nutzen und sich auf der Karte zeigen, und deine Gruppe, die du jetzt siehst.",
	["Los logros de la manada: se ganan pescando, cocinando lo que pescas y explorando aguas nuevas. Cada uno se anuncia una sola vez."] = "Die Erfolge des Rudels: Du verdienst sie durch Angeln, durch das Kochen deines Fangs und durch das Erkunden neuer Gewässer. Jeder wird nur einmal verkündet.",
	["Los lugares que pides ver en el mapa desde la Enciclopedia."] = "Die Orte, die du aus der Enzyklopädie auf der Karte sehen willst.",
	["Los maestros de vuelo de tu facción y los neutrales: verdes si ya los conoces, ámbar con «?» si te falta descubrirlos. Clic: seguirlo con la flecha."] = "Die Flugmeister deiner Fraktion und neutrale: grün, wenn du sie kennst, bernsteinfarben mit „?“, wenn du sie noch entdecken musst. Klick: mit dem Pfeil folgen.",
	["Los magos de Dalaran forman el Kirin Tor, su consejo de sabios."] = "Die Magier von Dalaran bilden die Kirin Tor, ihren Rat der Weisen.",
	["Los marcos de Curación están apagados"] = "Die Heilungsrahmen sind aus",
	["Los marcos se mueven fuera de combate."] = "Die Rahmen lassen sich außerhalb des Kampfes verschieben.",
	["Los marcos, fondos, botones y letras del propio juego, con títulos en oro."] = "Die Rahmen, Hintergründe, Knöpfe und Schriften des Spiels, mit goldenen Titeln.",
	["Los mismos marcadores de misiones en el minimapa."] = "Dieselben Questmarkierungen auf der Minikarte.",
	["Los múrlocs hablan con gorgoteos y burbujas: ese «mrglglgl» es su idioma de verdad."] = "Murlocs sprechen in Gurgeln und Blubbern: Dieses „Mrglglgl“ ist ihre echte Sprache.",
	["Los nagas y sátiros lanzan escarcha y rayos: interrumpan a los lanzadores primero."] = "Naga und Satyrn wirken Frost und Blitze: Unterbrecht zuerst die Zauberwirker.",
	["Los nerubianos, arañas gigantes de Rasganorte, pelearon contra el Rey Exánime y perdieron; muchos hoy le sirven."] = "Die Neruber, Riesenspinnen aus Nordend, kämpften gegen den Lichkönig und verloren; viele dienen ihm jetzt.",
	["Los no-muertos de la Plaga no sienten miedo ni cansancio, y por eso es tan difícil detenerlos."] = "Die Untoten der Geißel kennen weder Furcht noch Müdigkeit, und deshalb sind sie so schwer aufzuhalten.",
	["Los nodos de la zona que miras, con su nombre, nivel y cuántas veces los recolectaste al pasar el ratón. Clic en uno: la flecha te lleva."] = "Die Vorkommen des Gebiets, das du ansiehst; fahr mit der Maus über eins für Name, Stufe und wie oft du es gesammelt hast. Klick auf eins: Der Pfeil führt dich hin.",
	["Los nodos que se pisarían en pantalla van en un solo pin con su cantidad. Al acercar el mapa se separan."] = "Vorkommen, die sich auf dem Bildschirm überlappen würden, teilen sich einen Pin mit ihrer Anzahl. Beim Hineinzoomen trennen sie sich.",
	["Los nodos que tienes cerca. El punto del rastreo del juego dice si ahora hay algo ahí."] = "Die Vorkommen in deiner Nähe. Der Suchpunkt des Spiels zeigt, ob gerade etwas da ist.",
	["Los nodos que trae Alfa. Sin esto solo ves los que tú descubriste."] = "Die Vorkommen, die Alfa mitbringt. Ohne diese Option siehst du nur die, die du selbst entdeckt hast.",
	["Los números de las habilidades de tu mascota."] = "Die Zahlen der Fähigkeiten deines Begleiters.",
	["Los números de lo que curas encima de quien recibe."] = "Die Zahlen deiner Heilung über dem, der sie erhält.",
	["Los números de los golpes de tu mascota."] = "Die Zahlen der Nahkampftreffer deines Begleiters.",
	["Los números de tu daño encima de quien golpeas."] = "Die Zahlen deines Schadens über dem, den du triffst.",
	["Los oasis de Los Baldíos se están secando y llenando de bestias raras: los Druidas del Colmillo, que salieron de las Cuevas de los Lamentos, los corrompen."] = "Die Oasen des Brachlands trocknen aus und füllen sich mit seltsamen Bestien: Die Druiden des Giftzahns, die aus den Höhlen des Wehklagens kamen, verderben sie.",
	["Los objetos se juntan al final de tus bolsas en lugar de al principio."] = "Gegenstände sammeln sich am Ende deiner Taschen statt am Anfang.",
	["Los orcos Faucedraco siguen en Los Humedales, aunque ya sin la Reina Dragón."] = "Die Drachenmalorcs sind noch im Sumpfland, wenn auch ohne die Drachenkönigin.",
	["Los orcos Roca Negra de Rend se adueñaron de la cumbre de la montaña y la llaman su hogar."] = "Rends Schwarzfelsorcs haben sich den Gipfel des Berges angeeignet und nennen ihn ihr Zuhause.",
	["Los orcos Roca Negra ocupan una vieja fortaleza humana al este de las montañas."] = "Schwarzfelsorcs besetzen eine alte Menschenfestung östlich der Berge.",
	["Los orcos llegaron de Draenor corrompidos por la sangre de Mannoroth. Thrall los sacó de los campos de internamiento y fundó la nueva Horda."] = "Die Orcs kamen von Draenor, verdorben durch das Blut von Mannoroth. Thrall befreite sie aus den Internierungslagern und gründete die neue Horde.",
	["Los orcos nuevos empiezan en el Valle de los Retos, en Durotar, donde prueban su valor."] = "Neue Orcs beginnen im Tal der Prüfungen in Durotar, wo sie ihren Mut beweisen.",
	["Los orcos vienen de Draenor, un mundo que hoy está roto y se llama Terrallende."] = "Die Orcs stammen von Draenor, einer Welt, die heute zerbrochen ist und Scherbenwelt heißt.",
	["Los otros %d puntos del plan llegan con tus próximos niveles."] = "Die anderen %d Punkte des Plans kommen mit deinen nächsten Stufen.",
	["Los peleteros hacen carcajes y bolsas de munición para los cazadores."] = "Lederer machen Köcher und Munitionsbeutel für Jäger.",
	["Los portales a pie que puedes usar, con a dónde llevan."] = "Die begehbaren Portale, die du benutzen kannst, mit ihrem Ziel.",
	["Los precios cambian: después de estos días Alfa te recuerda escanear otra vez."] = "Preise ändern sich: Nach so vielen Tagen erinnert dich Alfa, erneut zu scannen.",
	["Los primeros caballeros de la muerte los creó Gul'dan: cuerpos de caballeros humanos caídos con almas de brujos orcos."] = "Die ersten Todesritter schuf Gul'dan: Körper gefallener menschlicher Ritter mit den Seelen von Orc-Hexenmeistern.",
	["Los puntos de ruta que ponen otros addons, y el comando /way, apuntan la flecha de Alfa. Un addon que espere los ajustes de otro addon de puntos de ruta puede no funcionar con esto encendido."] = "Wegpunkte, die andere Addons setzen, und der Befehl /way steuern Alfas Pfeil. Ein Addon, das die Einstellungen eines anderen Wegpunkt-Addons erwartet, funktioniert damit eventuell nicht.",
	["Los puntos de vuelo y de viaje ya se ven en el mapa."] = "Flugpunkte und Reisepunkte sind jetzt auf der Karte zu sehen.",
	["Los puntos que ganas en la cuenta también llenan el registro del Legado: premios de aspecto, sin ventaja en el juego. Al salir Forever son un rifle de réplica de Forjaz (juguete), la cría de oso espectral (mascota), el tabardo del oso espectral y las riendas del oso espectral (montura)."] = "Die Punkte, die du auf dem Account verdienst, füllen auch die Vermächtnis-Belohnungsleiste: kosmetische Belohnungen, ohne Spielvorteil. Zum Start von Forever sind das ein nachgebautes Eisenschmiede-Luftgewehr (Spielzeug), das Spektralbärenjunge (Haustier), der Wappenrock des Spektralbären und die Zügel des Spektralbären (Reittier).",
	["Los puntos que ganas también llenan el registro del Legado, con premios de aspecto como la cría de oso espectral."] = "Die Punkte, die du verdienst, füllen auch die Vermächtnis-Belohnungsleiste, mit kosmetischen Belohnungen wie dem Spektralbärenjungen.",
	["Los raros están apagados (página Descubrir)."] = "Rares sind ausgeschaltet (Seite Entdecken).",
	["Los raros también en el minimapa."] = "Rares auch auf der Minikarte.",
	["Los recolectaste %d veces en total"] = "Du hast sie insgesamt %d-mal gesammelt",
	["Los sacerdotes Atal'ai siguieron adorando a Hakkar en secreto. Los desterraron, y levantaron su templo en el Pantano de las Penas."] = "Die Priester der Atal'ai beteten Hakkar heimlich weiter an. Sie wurden verbannt und errichteten ihren Tempel in den Sümpfen des Elends.",
	["Los servicios también en el minimapa."] = "Dienste auch auf der Minikarte.",
	["Los señores del terror, como Mal'Ganis, Balnazzar y Varimathras, eran los carceleros que la Legión le puso al Rey Exánime."] = "Die Schreckenslords wie Mal'Ganis, Balnazzar und Varimathras waren die Kerkermeister, die die Legion dem Lichkönig vorsetzte.",
	["Los señores elementales servían a los dioses antiguos. Cuando los titanes encerraron a esos dioses, desterraron a los elementales a sus propios planos."] = "Die Elementarfürsten dienten den Alten Göttern. Als die Titanen diese Götter einsperrten, verbannten sie die Elementare auf ihre eigenen Ebenen.",
	["Los sumos sacerdotes de Zul'Gurub tomaron el poder de los loa animales: el murciélago, la serpiente, la araña, la pantera y el tigre."] = "Die Hohepriester von Zul'Gurub nahmen sich die Macht der tierischen Loa: Fledermaus, Schlange, Spinne, Panther und Tiger.",
	["Los sátiros de Azshara sueltan tela vil, muy buscada por los sastres."] = "Die Satyrn von Azshara lassen Teufelsstoff fallen, den Schneider sehr gern haben.",
	["Los talentos confirmados no se quitan gratis: revisa la lista antes de aceptar."] = "Bestätigte Talente lassen sich nicht kostenlos entfernen: Prüf die Liste, bevor du annimmst.",
	["Los talentos que siguen en el plan no están en tu árbol o no se pueden tomar todavía. Ponlos a mano en la ventana de talentos del juego o elige otro build."] = "Die nächsten Talente des Plans sind nicht in deinem Baum oder können noch nicht genommen werden. Verteile sie von Hand im Talentfenster des Spiels oder wähle einen anderen Build.",
	["Los tauren Tótem Siniestro tienen campamentos en Las Mil Agujas, y no son nada amigables."] = "Die Grimmtotem-Tauren haben Lager in Tausend Nadeln, und sie sind überhaupt nicht freundlich.",
	["Los tauren ayudaron a los Renegados a entrar a la Horda, con la esperanza de encontrarles una cura."] = "Die Tauren halfen den Verlassenen, der Horde beizutreten, in der Hoffnung, ein Heilmittel für sie zu finden.",
	["Los tauren de Viento Libre viven en lo alto de Las Mil Agujas, a salvo de los centauros."] = "Die Tauren von Freiwind leben hoch oben in Tausend Nadeln, sicher vor den Zentauren.",
	["Los tauren de Viento Libre viven en lo alto de las agujas, unidas por puentes colgantes, a salvo de los centauros de abajo."] = "Die Tauren von Freiwind leben hoch oben auf den Nadeln, verbunden durch Hängebrücken, sicher vor den Zentauren unten.",
	["Los tauren honran a la Madre Tierra. Dicen que el sol y la luna son sus ojos: An'she y Mu'sha."] = "Die Tauren ehren die Erdmutter. Sie sagen, Sonne und Mond seien ihre Augen: An'she und Mu'sha.",
	["Los tauren llaman An'she al sol y Mu'sha a la luna: los ojos de la Madre Tierra."] = "Die Tauren nennen die Sonne An'she und den Mond Mu'sha: die Augen der Erdmutter.",
	["Los tauren nuevos empiezan en el Campamento Narache, en Mulgore."] = "Neue Tauren beginnen im Camp Narache in Mulgore.",
	["Los tauren vivían como nómadas, acosados por los centauros, hasta que Cairne Pezuña de Sangre se alió con Thrall. Con la ayuda de la Horda encontraron su hogar en Mulgore."] = "Die Tauren lebten als Nomaden, gejagt von den Zentauren, bis Cairne Bluthuf sich mit Thrall verbündete. Mit Hilfe der Horde fanden sie in Mulgore ihre Heimat.",
	["Los tesoros también en el minimapa."] = "Schätze auch auf der Minikarte.",
	["Los titanes dejaron guardianes de piedra y metal en Azeroth. En Uldaman todavía hay uno despierto: Archaedas."] = "Die Titanen hinterließen Wächter aus Stein und Metall auf Azeroth. In Uldaman ist einer noch wach: Archaedas.",
	["Los titanes le dieron forma a Azeroth y dejaron guardianes y ciudades, como Uldaman, para cuidar su obra."] = "Die Titanen formten Azeroth und hinterließen Wächter und Städte wie Uldaman, um ihr Werk zu hüten.",
	["Los titanes son seres colosales que recorren el cosmos poniendo orden en los mundos. Los más famosos forman el Panteón, que guiaba Aman'Thul."] = "Die Titanen sind gewaltige Wesen, die durch den Kosmos ziehen und Ordnung in die Welten bringen. Die berühmtesten bilden das Pantheon, das Aman'Thul anführte.",
	["Los titanes usaron este cráter como un jardín de pruebas para la vida; por eso hay dinosaurios y plantas gigantes."] = "Die Titanen nutzten diesen Krater als Versuchsgarten für das Leben; deshalb gibt es hier Dinosaurier und riesige Pflanzen.",
	["Los troggs huyen cuando tienen poca vida y traen amigos: deténganlos antes de que escapen."] = "Troggs fliehen bei wenig Gesundheit und holen Freunde: Haltet sie auf, bevor sie entkommen.",
	["Los troggs invadieron Gnomeregan, y los gnomos inundaron su propia ciudad de radiación al intentar sacarlos. Fue idea del mekigeniero Termochufe."] = "Die Troggs fielen in Gnomeregan ein, und die Gnome verseuchten ihre eigene Stadt mit Strahlung, als sie sie vertreiben wollten. Es war die Idee von Robogenieur Thermadraht.",
	["Los troggs salieron de las profundidades de Uldaman. Todo indica que son una creación antigua de los titanes que salió mal."] = "Die Troggs kamen aus den Tiefen von Uldaman. Alles deutet darauf hin, dass sie eine alte, misslungene Schöpfung der Titanen sind.",
	["Los trols Lanza Negra conocieron a Thrall en las islas donde naufragó su flota rumbo a Kalimdor. Su líder Sen'jin murió ahí, y desde entonces los guía su hijo Vol'jin."] = "Die Dunkelspeertrolle trafen Thrall auf den Inseln, wo seine Flotte auf dem Weg nach Kalimdor Schiffbruch erlitt. Ihr Anführer Sen'jin starb dort, und seitdem führt sie sein Sohn Vol'jin.",
	["Los trols Lanza Negra empiezan con los orcos, en el Valle de los Retos de Durotar."] = "Dunkelspeertrolle beginnen mit den Orcs im Tal der Prüfungen in Durotar.",
	["Los trols adoran a espíritus llamados loa. Hakkar es uno de ellos, y de los más peligrosos."] = "Trolle verehren Geister, die Loa heißen. Hakkar ist einer von ihnen, und einer der gefährlichsten.",
	["Los trols de estas tierras descienden de los Amani, el antiguo imperio de los trols del bosque. En Jintha'Alor siguen levantando sus altares."] = "Die Trolle dieser Lande stammen von den Amani ab, dem alten Reich der Waldtrolle. In Jintha'Alor errichten sie noch immer ihre Altäre.",
	["Los vendedores de suministros de pesca tienen cañas, lombrices y baratijas."] = "Händler für Angelbedarf haben Angeln, Würmer und Tand.",
	["Los worgen son hombres lobo de origen misterioso. Arugal los trajo a Lordaeron. ¡No me confundas con ellos, eh!"] = "Die Worgen sind Werwölfe unbekannter Herkunft. Arugal brachte sie nach Lordaeron. Verwechsle mich bloß nicht mit ihnen!",
	["Los zepelines salen de las torres junto a Orgrimmar hacia Entrañas y hacia Grom'gol, en la Vega de Tuercespina."] = "Die Zeppeline starten von den Türmen bei Orgrimmar nach Unterstadt und nach Grom'gol im Schlingendorntal.",
	["Los árboles del Legado son tres: Profesiones, Aventura y Recursos. Al salir Forever, cada personaje gasta hasta 16 puntos."] = "Es gibt drei Vermächtnis-Bäume: Berufe, Abenteuer und Findigkeit. Zum Start von Forever gibt jeder Charakter bis zu 16 Punkte aus.",
	["Los íconos, los nombres y tu flecha se mueven pegados al mapa al hacer zoom o arrastrar: ya no brincan un píxel."] = "Symbole, Namen und dein Pfeil bleiben beim Zoomen oder Ziehen fest an der Karte: Sie springen nicht mehr um einen Pixel.",
	["Los últimos Altonato de Kalimdor siguen en La Masacre: se llaman Shen'dralar y cuidan su vieja biblioteca."] = "Die letzten Hochgeborenen Kalimdors sind noch in Düsterbruch: Sie heißen Shen'dralar und hüten ihre alte Bibliothek.",
	["Los últimos puntos."] = "Die letzten Punkte.",
	["Lothar cayó ante Orgrim Martillo Maldito al pie de la Montaña Roca Negra. Turalyon tomó su lugar y ganó la Segunda Guerra."] = "Lothar fiel am Fuß des Schwarzfels durch Orgrim Schicksalshammer. Turalyon nahm seinen Platz ein und gewann den Zweiten Krieg.",
	["Luego cópialo con Ctrl+C."] = "Kopier ihn dann mit Strg+C.",
	["Lugar"] = "Position",
	["Lugar conocido: el punto del rastreo del juego dice si ahora hay algo."] = "Bekannter Fundort: Der Suchpunkt des Spiels zeigt, ob gerade etwas da ist.",
	["Lugar de los marcos"] = "Position der Rahmen",
	["Lugar desconocido"] = "Unbekannter Ort",
	["Lugar: %s"] = "Ort: %s",
	["Luna"] = "Mond",
	["Luz y efectos"] = "Licht und Effekte",
	["Lya"] = "Lya",
	["Lya ahora es una loba negra de cuerpo completo, con 39 cuadros de animación: se sienta, corre, se busca la cola, bosteza y duerme enroscada."] = "Lya ist jetzt eine schwarze Wölfin in voller Gestalt, mit 39 Animationsbildern: Sie sitzt, rennt, jagt ihren Schwanz, gähnt und schläft eingerollt.",
	["Lya cuenta historias"] = "Lya erzählt Geschichten",
	["Lya de cuerpo completo"] = "Lya in voller Gestalt",
	["Lya en tu pantalla"] = "Lya auf deinem Bildschirm",
	["Lya está calladita"] = "Lya ist ganz still",
	["Lya está descansando"] = "Lya ruht sich aus",
	["Lya fue una gran perrita: noble, leal y siempre al lado de los suyos, la gordita consentida de la casa. Alfa la recuerda así, como la loba que cuida a la manada y nunca deja a nadie atrás."] = "Lya war eine wunderbare kleine Hündin: edel, treu und immer an der Seite ihrer Familie, das verwöhnte Pummelchen des Hauses. Alfa erinnert sich so an sie: als die Wölfin, die über das Rudel wacht und niemanden zurücklässt.",
	["Lya guarda la historia de cada misión que tomas, aunque la aceptes sin leerla. Tú sigue la flecha: ella se acuerda de todo."] = "Lya speichert die Geschichte jeder Quest, die du annimmst, auch wenn du sie ungelesen annimmst. Folg du dem Pfeil: Sie merkt sich alles.",
	["Lya platica mucho más: lore de Warcraft, datos de cada zona, de tu raza, tu clase y tus profesiones, y consejos de eventos y de farmeo. ¡Y le encantan las salchichas!"] = "Lya plaudert viel mehr: Warcraft-Lore, Fakten zu jeder Zone, zu deinem Volk, deiner Klasse und deinen Berufen, und Tipps zu Festen und zum Farmen. Und sie liebt Würstchen!",
	["Lya se fue a descansar. Vuelve con /alfa lya."] = "Lya ruht sich aus. Hol sie mit /alfa lya zurück.",
	["Lya se queda calladita una hora. Aquí sigue, cuidándote."] = "Lya bleibt eine Stunde still. Sie ist trotzdem da und passt auf dich auf.",
	["Lya te acompaña"] = "Lya begleitet dich",
	["Lya te espera"] = "Lya wartet auf dich",
	["Lya tiene mucho que contar"] = "Lya hat viel zu erzählen",
	["Lya volvió. Dale clic cuando quieras un consejo."] = "Lya ist zurück. Klick sie an, wann immer du einen Tipp willst.",
	["Lya vuelve a contarte sus consejos desde el principio."] = "Lya erzählt dir ihre Tipps wieder von vorn.",
	["Lya vuelve a hablar."] = "Lya spricht wieder.",
	["Lya, la loba de confianza del Alfa"] = "Lya, die treue Wölfin des Alfa",
	["Lánzalo antes de la siguiente pelea."] = "Wirk ihn vor dem nächsten Kampf.",
	["Lánzalo antes de pelear."] = "Vor dem Kampf wirken.",
	["Línea de la ruta"] = "Routenlinie",
	["Línea de tiempo apagada"] = "Zeitleiste aus",
	["Línea de tiempo del jefe"] = "Boss-Zeitleiste",
	["Línea de tiempo prendida"] = "Zeitleiste an",
	["Maestro"] = "Meister",
	["Maestro de armas"] = "Waffenmeister",
	["Maestro de batalla"] = "Kampfmeister",
	["Maestro de establos"] = "Stallmeister",
	["Maestro de vuelo"] = "Flugmeister",
	["Maestro del agua"] = "Meister des Wassers",
	["Maestros de armas"] = "Waffenmeister",
	["Maestros de batalla"] = "Kampfmeister",
	["Maestros de establos"] = "Stallmeister",
	["Maestros de vuelo"] = "Flugmeister",
	["Maestría elemental: tu siguiente hechizo es crítico y gratis."] = "Elementarbeherrschung: Dein nächster Zauber trifft kritisch und kostet nichts.",
	["Maestría nueva: %s (%d)"] = "Neue Meisterschaft: %s (%d)",
	["Mago"] = "Magier",
	["Maiev Cantosombrío fue la carcelera de Illidan durante diez mil años, al frente de las Vigilantes."] = "Maiev Schattensang war zehntausend Jahre lang Illidans Kerkermeisterin, an der Spitze der Wächterinnen.",
	["Mal'Ganis, el señor del terror, guió la plaga en Lordaeron. Arthas lo persiguió hasta Rasganorte, y esa cacería lo perdió."] = "Mal'Ganis, der Schreckenslord, lenkte die Seuche in Lordaeron. Arthas jagte ihn bis nach Nordend, und diese Jagd wurde sein Verderben.",
	["Maldiciones y daño con el tiempo: pones tus hechizos y el monstruo muere solo mientras pasas al siguiente."] = "Flüche und Schaden über Zeit: Du setzt deine Zauber, und das Monster stirbt von selbst, während du zum nächsten gehst.",
	["Maldición que hace cada vez más daño."] = "Ein Fluch, der immer mehr Schaden macht.",
	["Malfurion Tempestira fue el primer druida de los elfos de la noche. Aprendió del semidiós Cenarius, a quien llamaba shan'do: «maestro honrado»."] = "Malfurion Sturmgrimm war der erste Druide der Nachtelfen. Er lernte vom Halbgott Cenarius, den er Shan'do nannte: „verehrter Lehrer“.",
	["Malfurion Tempestira, el gran druida, está perdido en el Sueño Esmeralda, y Tyrande lo espera."] = "Malfurion Sturmgrimm, der große Druide, ist im Smaragdgrünen Traum verloren, und Tyrande wartet auf ihn.",
	["Malla"] = "Kette",
	["Malygos, el Tejehechizos, guía a los dragones azules. La traición de Alamuerte casi acaba con su vuelo, y nunca se repuso del todo."] = "Malygos, der Zauberweber, führt die blauen Drachen. Todesschwinges Verrat hätte seinen Schwarm fast ausgelöscht, und er hat sich nie ganz davon erholt.",
