	["Manos"] = "Hände",
	["Mantén Furia recta encendida cuando tanquees."] = "Halte Zorn der Gerechtigkeit aktiv, wenn du tankst.",
	["Mantén Grito de batalla siempre puesto."] = "Halte Schlachtruf immer aktiv.",
	["Mantén Seccionar en el rival para que no huya."] = "Halte Kniesehne auf dem Gegner, damit er nicht flieht.",
	["Mantén al monstruo lejos: tu mascota lo detiene mientras disparas."] = "Halt das Monster auf Abstand: Dein Tier hält es fest, während du schießt.",
