	["Mapa y marcadores"] = "Karte und Markierungen",
	["Mar abierto y zonas de nivel 35 en adelante. El rango Artesano lo da Nat Pagle en el Marjal Revolcafango con su misión."] = "Offenes Meer und Zonen ab Stufe 35. Den Rang Fachmann gibt dir Nat Pagle in den Düstermarschen mit seiner Quest.",
	["Maraudon es sagrado para los centauros: ahí descansa el espíritu de Zaetar, el padre de su raza."] = "Maraudon ist den Zentauren heilig: Dort ruht der Geist von Zaetar, dem Vater ihres Volkes.",
	["Marca a los enemigos y empieza por el más peligroso."] = "Markiere die Gegner und fang mit dem gefährlichsten an.",
	["Marca al enemigo: todos le pegan más."] = "Markiere den Gegner: Alle treffen ihn härter.",
	["Marca de lo Salvaje"] = "Mal der Wildnis",
	["Marca el botón de tu barra que tiene la habilidad sugerida."] = "Markiert den Knopf in deiner Leiste mit der vorgeschlagenen Fähigkeit.",
	["Marca en el mapa a los instructores y vendedores de pesca de tu facción."] = "Markiert die Angellehrer und -händler deiner Fraktion auf der Karte.",
	["Marca en el minimapa la entrada de cada mazmorra (en verde las que ya hiciste). El mapa del mundo ya las marca solo."] = "Markiert den Eingang jedes Dungeons auf der Minikarte (in Grün die, die du schon gemacht hast). Die Weltkarte markiert sie schon von selbst.",
