	["Mazmorras y bandas"] = "Dungeons und Schlachtzüge",
	["Mazmorras: los avisos de jefes que tu juego sí trae ya no salen apagados."] = "Dungeons: Die Bosswarnungen, die dein Spiel hat, erscheinen nicht mehr als ausgeschaltet.",
	["Mazthoril es la guarida de los dragones azules, siempre atentos a quién usa la magia."] = "Mazthoril ist der Hort der blauen Drachen, die stets im Auge behalten, wer Magie benutzt.",
	["Me encanta cazar contigo. ¡Vamos por la siguiente!"] = "Ich jage so gern mit dir. Auf zur nächsten!",
	["Me gusta cuidarte la espalda. Para eso estoy."] = "Ich halte dir gern den Rücken frei. Dafür bin ich da.",
	["Me gusta este paso tranquilo. Así se disfruta el camino."] = "Ich mag dieses gemütliche Tempo. So genießt man den Weg.",
	["Me gusta ir contigo. Se nota que sabes lo que haces."] = "Ich bin gern mit dir unterwegs. Man merkt, dass du weißt, was du tust.",
	["Media"] = "Mittel",
	["Medianos y graves"] = "Mittlere und kritische",
	["Medias"] = "Mittel",
	["Medidor de daño"] = "Schadensmesser",
	["Medio"] = "Mittel",
	["Medivh era hijo de Aegwynn, la Guardiana anterior. Ella escondió en él el poder del Guardián sin saber que Sargeras también se escondía ahí."] = "Medivh war der Sohn von Aegwynn, der vorherigen Wächterin. Sie verbarg die Macht des Wächters in ihm, ohne zu wissen, dass sich auch Sargeras dort versteckte.",
	["Medivh era hijo de Aegwynn, la Guardiana, y de Nielas Aran, un mago de la corte de Ventormenta."] = "Medivh war der Sohn von Aegwynn, der Wächterin, und Nielas Aran, einem Hofmagier von Sturmwind.",
	["Medivh murió a manos de Khadgar y Lothar, pero años después regresó como el misterioso profeta que llevó a Thrall a Kalimdor."] = "Medivh starb durch Khadgar und Lothar, kehrte aber Jahre später als der geheimnisvolle Prophet zurück, der Thrall nach Kalimdor führte.",
	["Medivh, poseído por Sargeras, abrió el camino para que la Horda llegara a Azeroth."] = "Medivh, besessen von Sargeras, ebnete der Horde den Weg nach Azeroth.",
