	["Mi entrenador"] = "Mein Lehrer",
	["Mi oreja derecha se para sola cuando alguien dice «salchicha». Pruébalo."] = "Mein rechtes Ohr stellt sich von selbst auf, wenn jemand „Würstchen“ sagt. Probier's aus.",
	["Mi panza hizo un ruido. No fui yo, fue la panza."] = "Mein Bauch hat geknurrt. Das war nicht ich, das war der Bauch.",
	["Mi plan"] = "Mein Plan",
	["Mi plan perfecto: una buena cacería y luego salchichas junto a la fogata."] = "Mein perfekter Plan: eine gute Jagd und danach Würstchen am Lagerfeuer.",
