	["Mi ruta: subir rápido"] = "Meine Route: schnell leveln",
	["Mientras caminas o corres, tu tecla hace lo de siempre (con Espacio, saltar)."] = "Beim Gehen oder Laufen macht deine Taste das Gewohnte (mit Leertaste: springen).",
	["Mientras el corcho está en el agua, una línea fina con el tiempo, tu habilidad y lo último que sacaste."] = "Solange der Schwimmer im Wasser ist, eine dünne Zeile mit der Zeit, deiner Fertigkeit und deinem letzten Fang.",
	["Mientras estás aquí"] = "Während du hier bist",
	["Mientras estás aquí: %s"] = "Wenn du schon hier bist: %s",
	["Mientras la haces"] = "Währenddessen",
	["Mientras los druidas dormían en el Sueño Esmeralda, las Centinelas de Tyrande cuidaron solas los bosques de Kalimdor."] = "Während die Druiden im Smaragdgrünen Traum schliefen, hüteten Tyrandes Schildwachen die Wälder Kalimdors allein.",
	["Mientras más alto el nivel de las bestias, mejor el cuero que sueltan."] = "Je höher die Stufe der Bestien, desto besser das Leder, das sie geben.",
	["Mientras más nivel tenga la bestia, más habilidad te pide para desollarla."] = "Je höher die Stufe der Bestie, desto mehr Fertigkeit brauchst du, um sie zu häuten.",
	["Mientras pescas"] = "Beim Angeln",
	["Mientras pescas se ve solo el mundo y la barra de pesca. Nunca en combate: al empezar uno, todo vuelve."] = "Beim Angeln siehst du nur die Welt und die Angelleiste. Nie im Kampf: Beginnt einer, kommt alles zurück.",
	["Mientras pescas, el juego se sigue oyendo aunque estés en otra ventana."] = "Beim Angeln hörst du das Spiel weiter, auch wenn du in einem anderen Fenster bist.",
	["Mientras tenga la maldición, cura antes de que la vida baje mucho."] = "Solange der Fluch wirkt, heile früh, bevor die Gesundheit stark sinkt.",
	["Mientras vuelas en grifo, la línea de tu viaje en el mapa de Alfa: por dónde vas y dónde aterrizas."] = "Während du mit dem Greifen fliegst, die Linie deiner Reise auf Alfas Karte: wo du gerade bist und wo du landest.",
	["Mientras, junta el oro: con la equitación y la montura se va casi todo."] = "Spar inzwischen Gold an: Reitfertigkeit und Reittier verschlingen fast alles.",
	["Mil y un peces"] = "Tausendundein Fisch",
	["Mina, herboriza, pesca en un banco o abre un cofre: aquí verás cuánto, qué te dio cada nodo y en qué zona."] = "Bau Erz ab, pflück Kräuter, angle in einem Schwarm oder öffne eine Truhe: Hier siehst du, wie viel, was dir jedes Vorkommen gab und in welchem Gebiet.",
	["Minas, hierbas y tesoros en tu mapa"] = "Erze, Kräuter und Schätze auf deiner Karte",
	["Minería"] = "Bergbau",
	["Minería, hierbas, pesca y tesoros en tu mapa y minimapa, con rutas de farmeo e historial."] = "Bergbau, Kräuter, Angeln und Schätze auf deiner Karte und Minikarte, mit Farmrouten und Verlauf.",
	["Minería, hierbas, pesca y tesoros también en el mapa grande de Alfa: al acercarte a una zona salen agrupados, con su cantidad."] = "Bergbau, Kräuter, Angeln und Schätze auch auf Alfas großer Karte: Zoome in eine Zone, und sie erscheinen gruppiert mit ihrer Anzahl.",
	["Minimapa"] = "Minikarte",
