	["Moviendo"] = "Verschieben",
	["Mucho daño con tu arma a distancia: disparos fuertes antes de que el monstruo llegue."] = "Viel Schaden mit deiner Fernkampfwaffe: starke Schüsse, bevor das Monster ankommt.",
	["Mucho maná y hechizos arcanos potentes: el mago que menos descansa."] = "Viel Mana und mächtige Arkanzauber: der Magier, der am wenigsten rastet.",
	["Mucho tiempo sin verte, %s. Repasa tus misiones antes de salir."] = "Lange nicht gesehen, %s. Geh deine Quests durch, bevor du losziehst.",
	["Muchos"] = "Viele",
	["Muchos enemigos duermen a un jugador: no es grave, el sueño se quita solo."] = "Viele Gegner schläfern einen Spieler ein: Nicht schlimm, der Schlaf vergeht von selbst.",
	["Muchos: consejos del momento y de vez en cuando uno de Alfa. Pocos: menos seguido. Solo importantes: al morir, al subir de nivel y en tus logros."] = "Viele: Tipps zum Moment und ab und zu einer über Alfa. Wenige: seltener. Nur wichtige: wenn du stirbst, aufsteigst und bei deinen Meilensteinen.",
	["Muchísima amenaza en un golpe."] = "Enorm viel Bedrohung mit einem Schlag.",
	["Muelles y torres de zepelín, con a dónde van."] = "Anleger und Zeppelintürme, mit ihren Zielen.",
	["Muertes"] = "Tode",
	["Muerto"] = "Tot",
	["Muestra la ventana de guía y la flecha, y cierra esta ventana para que las veas."] = "Zeigt das Guide-Fenster und den Pfeil und schließt dieses Fenster, damit du sie siehst.",
	["Muestra la vida en número, debajo del nombre."] = "Zeigt die Gesundheit als Zahl unter dem Namen.",
	["Muestra lo que aún no exploras, con un tono más frío para distinguirlo."] = "Zeigt, was du noch nicht erkundet hast, in einem kühleren Farbton zur Unterscheidung.",
	["Muestra un aviso de ejemplo para que veas dónde sale."] = "Zeigt einen Beispielhinweis, damit du siehst, wo er erscheint.",
	["Muestra un ícono encima del corcho: así sabes que tu tecla lo va a recoger."] = "Zeigt ein Symbol über dem Schwimmer: So weißt du, dass deine Taste ihn einholt.",
	["Mueve tus marcos"] = "Verschieb deine Rahmen",
	["Mundo"] = "Welt",
	["Munición"] = "Munition",
	["Muradin Barbabronce acompañó a Arthas a Rasganorte. Cuando Arthas tomó la espada, un trozo de hielo golpeó a Muradin y lo dieron por muerto."] = "Muradin Bronzebart begleitete Arthas nach Nordend. Als Arthas das Schwert nahm, traf ein Eisbrocken Muradin, und man hielt ihn für tot.",
	["Muradin Barbabronce le enseñó a Arthas a pelear cuando el príncipe era joven."] = "Muradin Bronzebart brachte Arthas das Kämpfen bei, als der Prinz jung war.",
	["Muro de escudo dura más."] = "Schildwall hält länger.",
	["Muro de escudo dura más: te salva en los jefes."] = "Schildwall hält länger: Er rettet dich bei Bossen.",
	["Muy pronto"] = "Demnächst",
	["Muéstrala u ocúltala. También con su tecla o con /alfa guia."] = "Ein- oder ausblenden. Auch mit seiner Taste oder mit /alfa guia.",
	["Muévete a las zonas de nivel 10 a 20. Las lombrices ayudan a que no se escapen. Pide el rango Experto desde 125."] = "Wechsle in Zonen der Stufen 10 bis 20. Würmer helfen, dass die Fische nicht entkommen. Ab 125 hol dir den Rang Experte.",
