	["Más Golpes heroicos: más daño por pelea."] = "Mehr Heldenhafte Stöße: mehr Schaden pro Kampf.",
	["Más adelante"] = "Später",
	["Más adelante eliges entre ingeniería gnómica y goblin: los inventos gnómicos fallan a veces de forma muy graciosa, y los goblin explotan más."] = "Später wählst du zwischen Gnomen- und Goblin-Ingenieurskunst: Gnomische Erfindungen versagen manchmal sehr komisch, und Goblin-Erfindungen explodieren öfter.",
	["Más adelante eliges especialidad: de escamas de dragón, elemental o tribal."] = "Später wählst du eine Spezialisierung: Drachenschuppen-, Elementar- oder Stammeslederverarbeitung.",
	["Más adelante eliges especialidad: forjador de armaduras o armero, y los armeros, entre espadas, mazas y hachas."] = "Später wählst du eine Spezialisierung: Rüstungsschmied oder Waffenschmied, und Waffenschmiede wählen zwischen Schwertern, Streitkolben und Äxten.",
	["Más adelante: %s."] = "Später: %s.",
	["Más aguante y seguridad. Matas un poco más lento, pero casi no mueres."] = "Mehr Ausdauer und Sicherheit. Du tötest etwas langsamer, stirbst aber fast nie.",
	["Más alto, atraviesa objetos más grandes antes de acercarse."] = "Höher: geht durch größere Objekte, bevor sie näher heranrückt.",
	["Más alto, los objetos lejanos tardan más en desaparecer."] = "Höher: Entfernte Objekte verschwinden später.",
	["Más alto, más nítido. Demasiado puede marcar bordes y brillos."] = "Höher ist schärfer. Zu viel kann Kanten und Glanzlichter überzeichnen.",
	["Más alto, ves más a los lados."] = "Höher zeigt mehr zu den Seiten.",
