	["No encontré habilidades de %s que ya sepas. Arrástralas desde tu libro de hechizos con la forma puesta."] = "Ich habe keine Fähigkeiten für %s gefunden, die du schon kennst. Zieh sie aus deinem Zauberbuch, während die Gestalt aktiv ist.",
	["No encontré misiones de clase para ti ahora."] = "Ich habe gerade keine Klassenquests für dich gefunden.",
	["No encontré una mazmorra llamada «%s»."] = "Ich habe keinen Dungeon namens „%s“ gefunden.",
	["No entregué %s: pide materiales de oficio. Entrégala tú si quieres."] = "%s nicht abgegeben: Sie verlangt Handwerkswaren. Gib sie selbst ab, wenn du willst.",
	["No entregué %s: pide oro o monedas. Entrégala tú si quieres."] = "%s nicht abgegeben: Sie verlangt Gold oder Währung. Gib sie selbst ab, wenn du willst.",
	["No es para ti"] = "Nicht für dich",
	["No es para tu clase"] = "Nicht für deine Klasse",
	["No es para tu raza"] = "Nicht für dein Volk",
	["No está al salir Forever. Cuando llegue, lo que ganes ahí cuenta en los otros modos, pero no al revés, y los retos de JcJ no se pueden hacer ahí."] = "Zum Start von Forever nicht dabei. Wenn er kommt, zählt, was du dort verdienst, in den anderen Modi, aber nicht umgekehrt, und PvP-Herausforderungen sind dort nicht machbar.",
	["No está en tu árbol"] = "Nicht in deinem Baum",
