	["No estás siguiendo a nadie."] = "Du folgst niemandem.",
	["No gastes todo en equipo: aprender a montar a nivel 40 es la mejor inversión del camino."] = "Gib nicht alles für Ausrüstung aus: Auf Stufe 40 reiten zu lernen ist die beste Investition unterwegs.",
	["No había explicaciones calladas: ya salen todas."] = "Es waren keine Erklärungen stummgeschaltet: Alle werden schon angezeigt.",
	["No hay bancos de peces conocidos en esta zona: aquí se pesca en aguas abiertas."] = "In dieser Zone sind keine Fischschwärme bekannt: Hier angelst du in offenem Wasser.",
	["No hay guías así"] = "Keine solchen Guides",
	["No hay misiones para ti cerca de aquí. Prueba en el pueblo más cercano o sigue tu ruta."] = "Hier in der Nähe gibt es keine Quests für dich. Versuch es im nächsten Ort oder folge deiner Route.",
	["No hay misiones que convenga dejar"] = "Keine Quests, die sich abzubrechen lohnen",
	["No hay misiones que puedas tomar ahora: te llevo a la entrada."] = "Gerade keine Quest, die du annehmen kannst: Ich bringe dich zum Eingang.",
	["No hay nada que comprar: o ya tienes todo lo del plan hasta tu nivel, o no tienes puntos libres."] = "Es gibt nichts zu kaufen: Entweder hast du schon alles aus dem Plan bis zu deiner Stufe, oder du hast keine freien Punkte.",
	["No hay nodos conocidos en esta zona."] = "Keine bekannten Vorkommen in diesem Gebiet.",
	["No hay prisa: el camino también se disfruta."] = "Keine Eile: Auch der Weg will genossen werden.",
	["No hay un build exacto para %s y %s: este es el que más se parece."] = "Es gibt keinen genauen Build für %s und %s: Das ist der ähnlichste.",
	["No hay un camino que Alfa pueda guiar para esto."] = "Hierfür gibt es keinen Weg, den Alfa führen kann.",
	["No ignores los objetos verdes: si no te sirven, desencántalos o súbelos a la subasta."] = "Übersieh grüne Gegenstände nicht: Wenn sie dir nichts nützen, entzaubere sie oder stell sie ins Auktionshaus.",
	["No la agregué"] = "Ich habe sie nicht hinzugefügt",
	["No la usas"] = "Nicht benötigt",
	["No llevas chatarra para vender."] = "Du hast keinen Plunder zum Verkaufen.",
	["No llevas juguetes ni consumibles de pesca. Lo que tenga que ver con pescar aparece aquí solo."] = "Du hast keine Angelspielzeuge oder -verbrauchsgüter dabei. Alles, was mit Angeln zu tun hat, erscheint hier von selbst.",
	["No llevas nada de pesca. Compra una caña con un vendedor de suministros de pesca: la guía te dice dónde."] = "Du hast nichts zum Angeln dabei. Kauf eine Angel bei einem Händler für Angelbedarf: Der Guide sagt dir, wo.",
	["No llevas nada para depositar con esa opción."] = "Du hast nichts, was mit dieser Option eingelagert wird.",
	["No llevas nada que convenga vender: guarda algo en el banco."] = "Nichts, was sich zu verkaufen lohnt: Lagere etwas in der Bank ein.",
	["No llevas nada que depositar"] = "Nichts zum Einlagern",
	["No lo puedes usar todavía"] = "Du kannst es noch nicht benutzen",
	["No mostrar"] = "Nicht zeigen",
	["No muestra los ataques que todavía tardan mucho: la barra queda más limpia."] = "Blendet Angriffe aus, die noch lange dauern: Die Leiste bleibt übersichtlicher.",
	["No muestra los ataques que ya deberían haber llegado y esperan su momento."] = "Blendet Angriffe aus, die eigentlich schon fällig sind und auf ihren Moment warten.",
