	["No pude guardar esa meta: revisa lo que escribiste."] = "Ich konnte dieses Ziel nicht speichern: Prüf, was du eingegeben hast.",
	["No pude leer dónde estás."] = "Ich konnte nicht lesen, wo du bist.",
	["No pude leer los datos del mundo de Alfa: vuelve a instalar Alfa."] = "Ich konnte Alfas Weltdaten nicht lesen: Installiere Alfa neu.",
	["No pude poner la flecha ahí."] = "Ich konnte den Pfeil dort nicht hinsetzen.",
	["No pude poner la flecha ahí. Inténtalo otra vez en un momento."] = "Ich konnte den Pfeil dort nicht hinsetzen. Versuch es gleich noch mal.",
