	["No se encontró el chat."] = "Der Chat wurde nicht gefunden.",
	["No se encontró la carpeta Alfa_Codex. Reinstala Alfa completo."] = "Der Ordner Alfa_Codex wurde nicht gefunden. Installiere Alfa komplett neu.",
	["No se encontró nada mejor cerca de tu nivel. Vuelve a buscar al subir unos niveles."] = "Nahe deiner Stufe wurde nichts Besseres gefunden. Such nach ein paar Stufen erneut.",
	["No se pudieron leer los datos del juego."] = "Die Spieldaten konnten nicht gelesen werden.",
	["No se pudo"] = "Hat nicht geklappt",
	["No se pudo abrir el Codex de Alfa (la base de objetos). Revisa que el addon Alfa Codex esté activado."] = "Alfas Codex (die Gegenstandsdatenbank) konnte nicht geöffnet werden. Prüf, ob das Addon Alfa Codex aktiviert ist.",
	["No se pudo armar la guía (%s)."] = "Der Guide konnte nicht erstellt werden (%s).",
	["No se pudo armar la guía."] = "Der Guide konnte nicht erstellt werden.",
	["No se pudo buscar el lugar más cercano."] = "Der nächste Ort konnte nicht gesucht werden.",
	["No se pudo comprar: %s"] = "Kauf nicht möglich: %s",
	["No se pudo enviar la invitación a %s. Prueba desde la ventana de Hermandad y comunidades."] = "Die Einladung an %s konnte nicht gesendet werden. Versuche es im Fenster „Gilde & Communitys“.",
	["No se pudo leer el escaneo. Intenta de nuevo más tarde."] = "Der Scan konnte nicht gelesen werden. Versuch es später erneut.",
	["No se pudo marcar: falta el motor de Alfa."] = "Markieren nicht möglich: Alfas Kern fehlt.",
	["No se pudo mostrar el banco del juego para comprar la casilla."] = "Die Bank des Spiels konnte nicht angezeigt werden, um das Fach zu kaufen.",
	["No se pudo probar ahora"] = "Test gerade nicht möglich",
	["No se puede dibujar el mapa continuo. El mapa del juego sigue funcionando con todas las capas de Alfa."] = "Die durchgehende Karte kann nicht gezeichnet werden. Die Spielkarte funktioniert weiter mit allen Ebenen von Alfa.",
	["No se puede en combate."] = "Nicht im Kampf.",
	["No se puede ordenar en combate."] = "Im Kampf kann nicht sortiert werden.",
	["No se puede vender."] = "Kann nicht verkauft werden.",
	["No se pueden cambiar bolsas en combate."] = "Im Kampf kannst du keine Taschen wechseln.",
	["No se sabe en qué lugar está."] = "Fundort unbekannt.",
	["No se ve en pantalla. Tráela de vuelta cuando quieras (también con /alfa lya)."] = "Sie ist nicht auf dem Bildschirm. Hol sie zurück, wann du willst (auch mit /alfa lya).",
	["No siempre aparece en la mina: si lo ves, es un jefe más con buen botín."] = "Er erscheint nicht immer in der Mine: Wenn du ihn siehst, ist er ein zusätzlicher Boss mit guter Beute.",
	["No siempre aparece. Pone un dolor de sombras: cura a quien lo tenga."] = "Nicht immer da. Er wirkt einen Schattenschmerz: Heile alle, die ihn haben.",
	["No sigues ninguna guía"] = "Du folgst keinem Guide",
	["No son para ti"] = "Nicht für dich",
	["No sé de dónde sale este objeto."] = "Ich weiß nicht, woher dieser Gegenstand kommt.",
	["No sé dónde se entrega"] = "Abgabeort unbekannt",
	["No sé dónde se entrega %s: la saqué de la ruta."] = "Ich weiß nicht, wo %s abgegeben wird: Ich habe sie aus der Route genommen.",
	["No sé dónde se entrega %s: la saqué del plan."] = "Ich weiß nicht, wo %s abgegeben wird: Ich habe sie aus dem Plan genommen.",
	["No sé dónde se junta este material."] = "Ich weiß nicht, wo man dieses Material sammelt.",
	["No sé dónde se junta: búscalo en la Enciclopedia para ver de dónde sale."] = "Ich weiß nicht, wo man es sammelt: Schlag es in der Enzyklopädie nach, um zu sehen, woher es kommt.",
	["No sé en qué zona estás."] = "Ich weiß nicht, in welchem Gebiet du bist.",
	["No sé qué misión es."] = "Ich weiß nicht, welche Quest das ist.",
	["No sé si alguien en Azeroth cocina salchichas como las de casa... pero si encuentras una receta, ¡me avisas!"] = "Ich weiß nicht, ob jemand in Azeroth Würstchen kocht wie die von zu Hause... aber wenn du ein Rezept findest, sag mir Bescheid!",
	["No sé si se puede tomar"] = "Unklar, ob sie annehmbar ist",
	["No te alcanza"] = "Reicht nicht",
	["No tienes cebos. Los venden los vendedores de suministros de pesca; la guía dice cuáles sirven a tu habilidad."] = "Du hast keine Köder. Händler für Angelbedarf verkaufen sie; der Guide sagt dir, welche zu deiner Fertigkeit passen.",
	["No tienes demonio: el abisario aguanta los golpes por ti."] = "Du hast keinen Dämon: Der Leerwandler steckt die Schläge für dich ein.",
	["No tienes demonio: invoca uno antes de pelear."] = "Du hast keinen Dämon: Beschwöre einen vor dem Kampf.",
	["No tienes demonio: invócalo al instante, aun peleando."] = "Du hast keinen Dämon: Beschwöre ihn sofort, auch mitten im Kampf.",
	["No tienes marcadores en el mapa de Alfa. Pon uno en el mapa y vuelve aquí."] = "Du hast keine Markierungen auf Alfas Karte. Setz eine auf der Karte und komm hierher zurück.",
	["No tienes mascota: llámala."] = "Du hast keinen Begleiter: Ruf ihn.",
	["No tienes mascota: si murió, revívela."] = "Du hast keinen Begleiter: Wenn er gestorben ist, belebe ihn wieder.",
	["No tienes misiones para este plan con ese filtro."] = "Du hast mit diesem Filter keine Quests für diesen Plan.",
	["No tienes puntos libres. El siguiente talento del plan (%s) te toca en el nivel %d."] = "Du hast keine freien Punkte. Das nächste Talent des Plans (%s) ist auf Stufe %d dran.",
	["No tienes un sello puesto: ponte uno."] = "Du hast kein Siegel aktiv: Leg eins an.",
	["No volver a mostrar"] = "Nicht mehr zeigen",
	["No, por ahora"] = "Nein, vorerst nicht",
