	["Nota libre"] = "Freie Notiz",
	["Novedades de Alfa %s"] = "Neuigkeiten in Alfa %s",
	["Nozdormu, el Atemporal, cuida el curso del tiempo. Dicen que conoce el día de su propia muerte, y aun así sigue con su deber."] = "Nozdormu, der Zeitlose, hütet den Lauf der Zeit. Man sagt, er kennt den Tag seines eigenen Todes und erfüllt trotzdem seine Pflicht.",
	["Nuestra manada en Discord: ayuda, avisos y reportes. Haz clic en el enlace y cópialo con Ctrl+C."] = "Unser Rudel auf Discord: Hilfe, Neuigkeiten und Fehlerberichte. Klick auf den Link und kopiere ihn mit Strg+C.",
