	["Ocultas"] = "Verborgen",
	["Ocultas como en el juego, reveladas, o reveladas con un tono más frío para saber dónde no has estado."] = "Verborgen wie im Spiel, aufgedeckt oder aufgedeckt mit kühlerem Farbton, damit du weißt, wo du noch nicht warst.",
