	["Ojo de pescador"] = "Anglerauge",
	["Ojo por aquí: %s tiene sus sorpresas."] = "Vorsicht hier: %s hat so seine Überraschungen.",
	["Ojo: tu clic para lanzar de Blizzard usa %d de estas teclas, y ese manda también aquí. Para igualarlos, usa «Usar también en los marcos de Blizzard»."] = "Achtung: Blizzards Klickzauber nutzt %d dieser Klicks und hat auch hier Vorrang. Um sie anzugleichen, nutze „Auch in Blizzards Rahmen nutzen“.",
	["Ojo: tu equipo anda al %d%%. Un herrero te lo deja como nuevo."] = "Achtung: Deine Ausrüstung ist bei %d%%. Ein Schmied macht sie wie neu.",
	["Olas y superficie del agua. Llega hasta Ultra (3) y no más: valores mayores pueden cerrar el juego, por eso Alfa no los deja."] = "Wellen und Wasseroberfläche. Geht bis Ultra (3) und nicht weiter: Höhere Werte können das Spiel abstürzen lassen, deshalb lässt Alfa sie nicht zu.",
	["Olor a fogata"] = "Duft von Lagerfeuer",
	["Olvidar"] = "Vergessen",
	["Olvidar mi progreso aquí"] = "Meinen Fortschritt hier vergessen",
	["Omite este paso: la guía sigue con el siguiente. Puedes volver a él con Anterior."] = "Überspringt diesen Schritt: Der Guide macht mit dem nächsten weiter. Mit „Vorheriger“ kommst du zu ihm zurück.",
	["Omite este paso: la guía sigue con el siguiente. Puedes volver a él desde «Ver detalle»."] = "Überspringt diesen Schritt: Der Guide macht mit dem nächsten weiter. Über „Details ansehen“ kannst du zu ihm zurück.",
	["Omitir"] = "Überspringen",
	["Omitir el paso %d"] = "Schritt %d überspringen",
