	["Orden"] = "Reihenfolge",
	["Ordenar"] = "Sortieren",
	["Ordenar de derecha a izquierda"] = "Von rechts nach links sortieren",
	["Orgrim Martillo Maldito murió peleando junto a Thrall durante la liberación de un campo de internamiento."] = "Orgrim Schicksalshammer starb an Thralls Seite bei der Befreiung eines Internierungslagers.",
	["Orgrim Martillo Maldito tomó el mando de la Horda y desarmó el Consejo de la Sombra de Gul'dan."] = "Orgrim Schicksalshammer übernahm die Führung der Horde und zerschlug Gul'dans Schattenrat.",
	["Orgrimmar está tallada en un cañón, y cada pueblo de la Horda tiene su propio valle dentro de la ciudad."] = "Orgrimmar ist in eine Schlucht gehauen, und jedes Volk der Horde hat sein eigenes Tal in der Stadt.",
	["Orgrimmar lleva el nombre de Orgrim Martillo Maldito, el jefe de guerra que liberó a Thrall y le dejó su armadura y su martillo."] = "Orgrimmar trägt den Namen von Orgrim Schicksalshammer, dem Kriegshäuptling, der Thrall befreite und ihm Rüstung und Hammer hinterließ.",
	["Orillas de sombra difuminadas, como la luz de verdad."] = "Weiche Schattenränder, wie bei echtem Licht.",
	["Oro"] = "Gold",
	["Oro de hoy"] = "Gold heute",
	["Oro neto por sesión"] = "Gold netto pro Sitzung",
	["Oro para la montura"] = "Gold für das Reittier",
