	["Otro (%s)"] = "Anderes (%s)",
	["Otro addon de bolsas está activo"] = "Ein anderes Taschen-Addon ist aktiv",
	["Otro addon de pesca está activo"] = "Ein anderes Angel-Addon ist aktiv",
	["Otro addon de pesca está activo. Para que no choquen, la pesca de Alfa queda en pausa: desactiva uno de los dos en la lista de addons."] = "Ein anderes Angel-Addon ist aktiv. Damit sie sich nicht in die Quere kommen, pausiert Alfas Angeln: Deaktiviere eines der beiden in der AddOn-Liste.",
	["Otro dato"] = "Noch einer",
	["Otro golpe fuerte para tu rotación."] = "Ein weiterer starker Schlag für deine Rotation.",
	["Otro golpe fuerte."] = "Ein weiterer starker Schlag.",
	["Otros"] = "Sonstiges",
	["Otros addons pueden poner puntos de ruta"] = "Andere Addons dürfen Wegpunkte setzen",
	["Otros caminos"] = "Andere Wege",
	["Otros jugadores"] = "Andere Spieler",
	["PNJ"] = "NPCs",
	["PNJ %d"] = "NPC %d",
	["Paciencia de lobo"] = "Geduld eines Wolfs",
	["Paisaje"] = "Landschaft",
	["Paisaje de la manada"] = "Landschaft des Rudels",
	["Paisaje y gráficos"] = "Landschaft und Grafik",
	["Paladín"] = "Paladin",
	["Panel de estadísticas"] = "Werte-Panel",
	["Pantalla de película para capturas y paseos. Solo cambia cómo se ve: no da más FPS."] = "Ein Kinolook für Screenshots und Ausflüge. Ändert nur das Aussehen: bringt keine FPS.",
	["Pantalla gris al morir"] = "Grauer Bildschirm beim Tod",
	["Para abandonar"] = "Zum Abbrechen",
	["Para abrirlo con la tecla del mapa, enciende «Abrir el mapa de Alfa con la tecla del mapa» abajo."] = "Um sie mit der Kartentaste zu öffnen, schalte unten „Alfas Karte mit der Kartentaste öffnen“ ein.",
	["Para alguien de tu hermandad, agrega su rango."] = "Zeigt bei Mitgliedern deiner Gilde ihren Rang.",
	["Para armar la espada legendaria de Thunderaan, el Buscavientos, hacen falta dos ataduras que sueltan Garr y el barón Geddon en el Núcleo de Magma."] = "Um das legendäre Schwert von Thunderaan, dem Windsucher, zusammenzusetzen, brauchst du zwei Bindungen, die Garr und Baron Geddon im Geschmolzenen Kern fallen lassen.",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Für jeden Gegenstand vergleicht Alfa drei Wege: an den Händler verkaufen, im Auktionshaus einstellen oder umwandeln (mit einem Rezept, das du kennst, oder durch Entzaubern).",
	["Para capturas y paseos. No da más FPS."] = "Für Screenshots und Ausflüge. Bringt keine FPS.",
	["Para cerrarle el paso a la Legión, Malfurion y sus aliados destruyeron el Pozo de la Eternidad. La explosión hundió el centro de Kalimdor."] = "Um die Legion auszusperren, zerstörten Malfurion und seine Verbündeten den Brunnen der Ewigkeit. Die Explosion versenkte das Herz Kalimdors.",
	["Para comprar espacio, habla con un banquero."] = "Um Platz zu kaufen, sprich mit einem Bankier.",
	["Para conservar"] = "Zum Behalten",
	["Para cruzar de los Reinos del Este a Kalimdor, toma un barco en el Puerto de Menethil, en Los Humedales."] = "Um von den Östlichen Königreichen nach Kalimdor zu gelangen, nimm ein Schiff im Hafen von Menethil im Sumpfland.",
	["Para depositar, habla con un banquero."] = "Zum Einlagern sprich mit einem Bankier.",
	["Para empezar"] = "Zum Start",
	["Para encantar necesitas una vara rúnica; con el tiempo la mejoras."] = "Zum Verzaubern brauchst du eine Runenverzierte Rute; mit der Zeit verbesserst du sie.",
	["Para entregar"] = "Zum Abgeben",
	["Para gastar"] = "Zu vergeben",
	["Para invitar a %s a %s: abre «Hermandad y comunidades», elige %s, pulsa «Invitar a miembro» y escribe: %s"] = "Um %s in %s einzuladen: Öffne „Gilde & Communitys“, wähle %s, klicke auf „Mitglied einladen“ und gib ein: %s",
	["Para ir de Los Humedales a las Tierras Altas de Arathi cruza el Puente Thandol, pero ojo con los Hierro Negro."] = "Um vom Sumpfland ins Arathihochland zu kommen, überquere den Thandolübergang, aber pass auf die Dunkeleisenzwerge auf.",
	["Para llegar a la Fuente del Sol, la Plaga de Arthas arrasó Quel'Thalas y su capital, Lunargenta."] = "Um den Sonnenbrunnen zu erreichen, verwüstete Arthas' Geißel Quel'Thalas und seine Hauptstadt Silbermond.",
	["Para lo que elegiste no hay uno con este estilo: Alfa usa el más cercano."] = "Für deine Wahl gibt es keinen mit diesem Stil: Alfa nutzt den ähnlichsten.",
	["Para mi nivel (±3)"] = "Für meine Stufe (±3)",
	["Para minar torio, el Cráter de Un'Goro y Cuna del Invierno tienen muchas vetas."] = "Für Thorium haben der Krater von Un'Goro und Winterquell viele Adern.",
	["Para mí"] = "Für mich",
	["Para no chocar con él, Alfa no reemplaza tus bolsas mientras esté activo. Igual puedes abrir la ventana de Alfa desde aquí."] = "Damit es keine Konflikte gibt, ersetzt Alfa deine Taschen nicht, solange es aktiv ist. Alfas Fenster kannst du trotzdem von hier öffnen.",
	["Para no moverla sin querer. Sin bloquear, arrástrala a donde quieras."] = "Damit du sie nicht aus Versehen verschiebst. Entsperrt kannst du sie hinziehen, wohin du willst.",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "Damit du deine Gruppe nicht doppelt siehst. Änderung außerhalb des Kampfes.",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "Damit sie sich nicht in die Quere kommen, übernimmt Alfa weder deine Taste noch ändert es deine Einstellungen. Deaktiviere eines der beiden in der AddOn-Liste (Charakterauswahl) und lade neu. Behältst du Alfa, übernimmt es von selbst die Taste, die du im anderen Addon benutzt hast.",
	["Para que no dejes botín tirado por falta de espacio."] = "Damit du keine Beute aus Platzmangel liegen lässt.",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "Für alle, die lieber mit Linksklick anvisieren: Die Heilung dieses Klicks wandert auf die mittlere Taste. Deine Voreinstellung wird erneut angewendet.",
	["Para recoger ahora"] = "Jetzt zum Annehmen",
	["Para subir de nivel"] = "Bis zum Stufenaufstieg",
	["Para subir solo, el daño de las sombras ayuda mucho: los hechizos que dañan con el tiempo trabajan por ti."] = "Um allein zu leveln, hilft Schattenschaden sehr: Zauber mit Schaden über Zeit arbeiten für dich.",
	["Para tela de nivel bajo, los Defias de los Páramos de Poniente sueltan lino y lana a montones."] = "Für niedrigstufigen Stoff lassen die Defias in Westfall Leinen und Wolle haufenweise fallen.",
	["Para templar la espada élfica Quel'Serrar hay que dejarla en el piso y que Onyxia le eche su aliento de fuego encima."] = "Um das Elfenschwert Quel'Serrar zu härten, musst du es auf den Boden legen und Onyxia ihren Feueratem darauf speien lassen.",
	["Para ti"] = "Für dich",
	["Para ti ahora"] = "Für dich jetzt",
	["Para tu %s"] = "Als %s",
	["Para tu habilidad conviene pescar en: %s."] = "Für deine Fertigkeit lohnt sich das Angeln in: %s.",
	["Para tu nivel"] = "Für deine Stufe",
	["Para tu nivel (%d)"] = "Für deine Stufe (%d)",
