	["Pediste %s; el juego lo dejó en %s."] = "Du wolltest %s; das Spiel hat %s gesetzt.",
	["Pega aquí (Ctrl+V) el texto de una ruta de Alfa."] = "Füge hier (Strg+V) den Text einer Alfa-Route ein.",
	["Pega aquí una cadena que empiece con ALFA1; (Ctrl + V) y pulsa Importar. Alfa revisa cada talento contra tu árbol."] = "Füge hier einen Text ein, der mit ALFA1; beginnt (Strg + V), und drück „Importieren“. Alfa prüft jedes Talent gegen deinen Baum.",
	["Pega fuerte pero no tiene trucos: es un buen jefe para aprender."] = "Er schlägt hart zu, hat aber keine Tricks: ein guter Boss zum Lernen.",
	["Pega fuerte y se protege con un escudo de luz: empieza con la vida llena."] = "Er schlägt hart zu und schützt sich mit einem Schild aus Licht: Fang mit voller Gesundheit an.",
	["Pega muchas veces seguidas al tanque: no dejes que su vida baje de la mitad."] = "Er schlägt den Tank oft hintereinander: Lass dessen Gesundheit nicht unter die Hälfte fallen.",
	["Pega muy fuerte: empieza la pelea con la vida llena."] = "Er schlägt sehr hart zu: Beginn den Kampf mit voller Gesundheit.",
	["Pega primero una cadena de build de Alfa."] = "Füge zuerst einen Alfa-Build-Text ein.",
