	["Pega una cadena de escala de estadísticas (Ctrl+V), la que copiaste desde donde la compartieron."] = "Füge einen Werteskala-Text ein (Strg+V), den du dort kopiert hast, wo er geteilt wurde.",
	["Pega varias veces seguidas: empieza con la vida llena."] = "Er schlägt mehrmals hintereinander zu: Fang mit voller Gesundheit an.",
	["Pegas a dos: útil contra mascotas y grupos."] = "Du triffst zwei: nützlich gegen Begleiter und Gruppen.",
	["Pegas más después de recibir críticos."] = "Du triffst härter, nachdem du Krits erlitten hast.",
	["Pegas más fuerte después de recibir críticos."] = "Du schlägst härter zu, nachdem du Krits erlitten hast.",
	["Pegas más fuerte después de recibir un golpe crítico."] = "Du schlägst härter zu, nachdem du einen kritischen Treffer erlitten hast.",
	["Pelea con un solo monstruo a la vez; si vienen dos, usa Golpes de barrido."] = "Kämpf immer nur gegen ein Monster; wenn zwei kommen, nutze Weitreichende Stöße.",
	["Pelea siempre con la vida llena; no encadenes monstruos sin descansar."] = "Kämpf immer mit voller Gesundheit; reih keine Monster ohne Rast aneinander.",
	["Pelear contra otros jugadores: aguantar, frenar y rematar."] = "Gegen andere Spieler kämpfen: durchhalten, bremsen und erledigen.",
	["Peletería"] = "Lederverarbeitung",
	["Peletería hace cuero con armadura y aguante para la forma de oso."] = "Lederverarbeitung macht Leder mit Rüstung und Ausdauer für die Bärengestalt.",
	["Peletería hace malla para ti; Desuello te da el material sin gastar oro."] = "Lederverarbeitung macht Kettenrüstung für dich; Kürschnerei liefert das Material, ohne Gold auszugeben.",
	["Peletería hace piezas de cuero con agilidad y aguante; Desuello te da el cuero."] = "Lederverarbeitung macht Lederteile mit Beweglichkeit und Ausdauer; Kürschnerei liefert dir das Leder.",
