	["Pon Seccionar en cuanto llegues al rival y mantenlo puesto."] = "Setz Kniesehne, sobald du den Gegner erreichst, und halte sie aktiv.",
	["Pon ahora"] = "Jetzt nehmen",
	["Pon todos tus hechizos de daño en el tiempo y deja que tu demonio aguante."] = "Setz alle deine Zauber mit Schaden über Zeit und lass deinen Dämon das Monster halten.",
