	["Que la manada vea a mi personaje en el mapa"] = "Das Rudel soll meinen Charakter auf der Karte sehen",
	["Que me vean en el mapa"] = "Mich auf der Karte zeigen",
	["Queda 1"] = "Noch 1",
	["Queda lejos: unos %s de camino"] = "Weit weg: etwa %s unterwegs",
	["Quedan %d"] = "Noch %d",
	["Quedan %d casillas libres y no llevas nada que convenga vender: guarda algo en el banco."] = "Noch %d freie Plätze und nichts, was sich zu verkaufen lohnt: Lagere etwas in der Bank ein.",
	["Quedan %d casillas libres. Puedes vender %s (unos %s)."] = "Noch %d freie Plätze. Du kannst %s verkaufen (etwa %s).",
	["Quedan %s"] = "Noch %s",
	["Quedó sin pasos: agrega tramos o recalcula."] = "Keine Schritte mehr: Füge Etappen hinzu oder berechne neu.",
	["Quema al enemigo un rato."] = "Verbrennt den Gegner eine Weile.",
	["Quien instala Alfa ya tiene encendidos los colores de clase, el cuadro de información, el probador, el minimapa y las barras con el estilo de Alfa."] = "Neue Installationen haben Klassenfarben, Tooltip, Anprobe, Minikarte und Leisten im Stil von Alfa schon eingeschaltet.",
	["Quien lleva la insignia de La Jauría la luce en el borde de su retrato: en el tuyo, el de tu objetivo y el de tu foco."] = "Wer das Abzeichen von La Jauría trägt, zeigt es am Rand seines Porträts: deinem, dem deines Ziels und dem deines Fokus.",
	["Quien repara tu equipo"] = "Wer deine Ausrüstung repariert",
	["Quien use Alfa en tu grupo lo recibe y puede seguirlo."] = "Wer in deiner Gruppe Alfa nutzt, erhält sie und kann ihr folgen.",
	["Quienes usan Alfa y comparten te ven en su mapa y pueden seguirte, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase cada 10 segundos mientras te mueves (cada 4 minutos si estás quieto), nunca dentro de mazmorras. Va por un canal oculto de Alfa: no sale en el chat, pero alguien que entre a ese canal con otro addon podría leerlo."] = "Wer Alfa nutzt und teilt, sieht dich auf seiner Karte und kann dir folgen, und du ihnen. Deine Zone, Position, Stufe und Klasse gehen alle 10 Sekunden raus, während du dich bewegst (alle 4 Minuten, wenn du stillstehst), nie in Dungeons. Es läuft über einen versteckten Alfa-Kanal: Es erscheint nicht im Chat, aber jemand, der dem Kanal mit einem anderen Addon beitritt, könnte es lesen.",
	["Quienes van contigo y usan Alfa ven cómo vas en las misiones que comparten."] = "Wer mit dir unterwegs ist und Alfa nutzt, sieht deinen Fortschritt in den Quests, die ihr teilt.",
	["Quiero"] = "Ich will",
	["Quiero unirme"] = "Ich will beitreten",
	["Quieto"] = "Stehen",
	["Quita el corte visible donde termina una capa de sombra y empieza la siguiente."] = "Entfernt die sichtbare Naht, wo eine Schattenebene endet und die nächste beginnt.",
	["Quita la columna de botones junto al chat (menú, canales y voz). Los comandos como /s, /g o /canal siguen igual."] = "Entfernt die Button-Spalte neben dem Chat (Menü, Kanäle und Sprache). Befehle wie /s, /g oder /channel funktionieren weiter.",
	["Quita los grifos de los lados de la barra principal. Edit Mode también tiene su propia opción para esto."] = "Entfernt die Greifen an den Seiten der Hauptleiste. Edit Mode hat dafür auch eine eigene Option.",
