	["Qué se pinta en tus mapas"] = "Was auf deinen Karten gezeichnet wird",
	["Qué se refleja en el agua: el cielo, el terreno y lo demás."] = "Was sich im Wasser spiegelt: der Himmel, das Gelände und der Rest.",
	["Qué se ve"] = "Was angezeigt wird",
	["Qué son"] = "Was sie sind",
	["Qué son, cómo se gana cada uno, en qué se gastan y cuántos tienes."] = "Was sie sind, wie man jeden verdient, wofür man sie ausgibt und wie viele du hast.",
	["Qué talento poner ahora y por qué, tu build en dos clics, tu árbol y tu equipo."] = "Welches Talent du jetzt nimmst und warum, dein Build in zwei Klicks, dein Baum und deine Ausrüstung.",
	["Qué talento poner y por qué, ayuda de rotación y el daño del grupo."] = "Welches Talent und warum, eine Rotationshilfe und der Schaden deiner Gruppe.",
