	["Retirarse a tiempo también es estrategia. Corre hacia tus aliados."] = "Rechtzeitig zurückziehen ist auch Strategie. Lauf zu deinen Verbündeten.",
	["Retos"] = "Herausforderungen",
	["Retos de tu cuenta que dan puntos para los árboles del Legado"] = "Account-Herausforderungen, die Punkte für die Vermächtnis-Bäume geben",
	["Revancha fuerte desde temprano."] = "Starke Rache schon früh.",
	["Revancha más fuerte y puede aturdir."] = "Stärkere Rache, die betäuben kann.",
	["Revancha pega fuerte y puede aturdir: tu golpe principal al subir."] = "Rache trifft hart und kann betäuben: dein Hauptschlag beim Leveln.",
	["Revancha pega más y puede aturdir: tu mejor golpe de amenaza."] = "Rache trifft härter und kann betäuben: dein bester Bedrohungsschlag.",
	["Revancha: barata y con mucha amenaza tras bloquear o esquivar."] = "Rache: günstig und viel Bedrohung nach Blocken oder Ausweichen.",
	["Reveladas"] = "Aufgedeckt",
	["Reveladas con otro tono"] = "Aufgedeckt, anders getönt",
	["Reverencia"] = "Verbeugen",
	["Revisa la lista antes de abandonar."] = "Prüf die Liste, bevor du abbrichst.",
	["Revisa lo que elegiste. Cada cosa se cambia aquí con «Cambiar» o después en Ajustes."] = "Prüf, was du gewählt hast. Jeden Punkt änderst du hier mit „Ändern“ oder später in den Einstellungen.",
	["Revisa miles de misiones para elegir las que sí puedes tomar: tarda unos segundos."] = "Es prüft Tausende Quests, um die zu wählen, die du wirklich annehmen kannst: Das dauert ein paar Sekunden.",
	["Revisa tu equipo al subir de nivel: una mejora pequeña también cuenta."] = "Prüf deine Ausrüstung beim Stufenaufstieg: Auch eine kleine Verbesserung zählt.",
	["Revisando tu registro..."] = "Dein Questlog wird geprüft...",
	["Revisión rápida"] = "Schnellcheck",
	["Rexxar, el señor de las bestias, recorre los caminos de Desolace con su osa Misha."] = "Rexxar, der Tierfürst, streift mit seiner Bärin Misha über die Wege von Desolace.",
	["Rexxar, mitad orco y mitad ogro, es un señor de las bestias que ayudó a fundar Durotar. Siempre lo acompaña su osa Misha."] = "Rexxar, halb Orc und halb Oger, ist ein Tierfürst, der half, Durotar zu gründen. Seine Bärin Misha ist immer an seiner Seite.",
	["Reír"] = "Lachen",
	["Ritmo: %s XP por hora; subes de nivel en %s."] = "Tempo: %s EP pro Stunde; du steigst in %s auf.",
	["Rocal es el gran bastión de la Horda en el sur de los Reinos del Este."] = "Steinard ist die große Bastion der Horde im Süden der Östlichen Königreiche.",
	["Rojo"] = "Rot",
	["Rosa"] = "Rosa",
	["Rueda abajo"] = "Mausrad runter",
	["Rueda arriba"] = "Mausrad hoch",
	["Rueda del ratón: acercar o alejar donde está el cursor. Arrastrar: mover el mapa (al soltar rápido sigue un poco). Doble clic: acercar."] = "Mausrad: an der Cursorposition hinein- oder herauszoomen. Ziehen: Karte bewegen (schnell loslassen, und sie gleitet etwas weiter). Doppelklick: hineinzoomen.",
	["Rueda: zoom  ·  Arrastra: mover  ·  Clic derecho: marcador  ·  Ctrl+clic: llévame"] = "Rad: Zoom  ·  Ziehen: bewegen  ·  Rechtsklick: Markierung  ·  Strg+Klick: bring mich hin",
	["Rugir"] = "Brüllen",
	["Rut'theran es el muelle al pie del árbol; de ahí un portal te sube a Darnassus."] = "Rut'theran ist der Steg am Fuß des Baums; von dort bringt dich ein Portal hinauf nach Darnassus.",
	["Ruta"] = "Route",
	["Ruta %d/%d: %s"] = "Route %d/%d: %s",
	["Ruta borrada"] = "Route gelöscht",
	["Ruta en el minimapa"] = "Route auf der Minikarte",
	["Ruta en marcha"] = "Route läuft",
	["Ruta importada"] = "Importierte Route",
	["Ruta lista en %s: %s"] = "Route fertig in %s: %s",
	["Rutas propias"] = "Eigene Routen",
	["Saca %d para la primera maestría (%s)."] = "Fang %d für die erste Meisterschaft (%s).",
	["Saca 15 capturas seguidas sin que se te escape ninguna."] = "Fang 15 Mal hintereinander, ohne dass dir einer entkommt.",
	["Saca 25 capturas de bancos de peces."] = "Fang 25 Mal aus Fischschwärmen.",
	["Saca tu primera captura del agua."] = "Zieh deinen ersten Fang aus dem Wasser.",
	["Saca una captura en Tuercespina durante el concurso de pesca."] = "Fang etwas im Schlingendorntal während des Anglerwettbewerbs.",
	["Sacarla"] = "Rausnehmen",
	["Sacerdote"] = "Priester",
	["Sagrado"] = "Heilig",
	["Sagrado para subir"] = "Heilig zum Leveln",
	["Sal de combate y vuelve a intentarlo."] = "Verlass den Kampf und versuch es erneut.",
	["Sale en aguas abiertas; los datos del juego no dicen dónde. Tu diario lo anota cuando lo saques."] = "Kommt aus offenem Wasser; die Spieldaten sagen nicht, wo. Dein Tagebuch notiert es, wenn du ihn fängst.",
	["Salen de tu registro. Para hacerlas otra vez tendrías que volver a pedirlas."] = "Sie verschwinden aus deinem Questlog. Um sie erneut zu machen, müsstest du sie wieder annehmen.",
	["Salidas de zona"] = "Zonenausgänge",
	["Salir del modo limpio"] = "Fokusmodus verlassen",
	["Saltar la charla de una sola opción"] = "Gespräche mit nur einer Option überspringen",
	["Saltar las misiones grises"] = "Graue Quests überspringen",
	["Saltarla"] = "Überspringen",
	["Salud cada 5 s"] = "Gesundheit alle 5 Sek.",
	["Saludar"] = "Winken",
	["Saludos y diálogos de los PNJ"] = "Begrüßungen und Dialoge der NPCs",
	["Sanación"] = "Heilung",
	["Sanador"] = "Heiler",
	["Sangrado fuerte desde el nivel 13; lo necesitas para Heridas profundas."] = "Starke Blutung ab Stufe 13; du brauchst sie für Tiefe Wunden.",
	["Sangrado fuerte; abre Heridas profundas."] = "Starke Blutung; öffnet Tiefe Wunden.",
	["Sangre fría: tu siguiente remate es crítico seguro."] = "Kaltblütigkeit: Dein nächster Finishing Move trifft sicher kritisch.",
	["Sapphiron, el dragón de escarcha de Naxxramas, fue un dragón azul antes de que la Plaga lo levantara."] = "Saphiron, der Frostwyrm von Naxxramas, war ein blauer Drache, bevor die Geißel ihn erweckte.",
	["Sargeras fue el gran campeón del Panteón. De tanto pelear contra demonios concluyó que la creación no tenía remedio, y fundó la Legión Ardiente."] = "Sargeras war der große Champion des Pantheons. Nach so vielen Kämpfen gegen Dämonen kam er zu dem Schluss, dass die Schöpfung nicht zu retten sei, und gründete die Brennende Legion.",
	["Sastrería"] = "Schneiderei",
	["Sastrería hace tu ropa con lo que cae en mazmorras, y Encantamiento deshace lo que no usas y mejora tu equipo."] = "Schneiderei macht deine Kleidung aus dem, was in Dungeons droppt, und Verzauberkunst entzaubert, was du nicht nutzt, und verbessert deine Ausrüstung.",
	["Sastrería y Encantamiento: tu equipo siempre al día."] = "Schneiderei und Verzauberkunst: Deine Ausrüstung ist immer aktuell.",
	["Scholomance, en la isla de Caer Darrow, es la escuela donde la Plaga enseña nigromancia. Antes fue el hogar de la familia Barov."] = "Scholomance auf der Insel Caer Darrow ist die Schule, in der die Geißel Nekromantie lehrt. Früher war es das Zuhause der Familie Barov.",
	["Se abandona con «Abandonar marcadas», que pide confirmación."] = "Abgebrochen wird mit „Markierte abbrechen“, das eine Bestätigung verlangt.",
	["Se abre a nivel %d: te faltan %d niveles. Mientras, sigue tu ruta."] = "Er öffnet sich auf Stufe %d: Dir fehlen %d Stufen. Folge so lange deiner Route.",
	["Se abre al salir de combate."] = "Öffnet sich, wenn der Kampf vorbei ist.",
	["Se abre al terminar %s."] = "Sie öffnet sich, wenn du %s abschließt.",
	["Se abren con la B. Elige la vista (todo junto, por categorías o por bolsa), busca por nombre o nivel y arrastra tus bolsas en su barra para cambiarlas."] = "Sie öffnen sich mit B. Wähle die Ansicht (alles zusammen, nach Kategorie oder nach Tasche), such nach Name oder Stufe und zieh deine Taschen in ihrer Leiste, um sie zu tauschen.",
	["Se acabaron los textos cortados con «…» en Hoy, La Jauría, Buscar cerca y la Enciclopedia."] = "Schluss mit Texten, die mit „…“ abgeschnitten werden, in „Heute“, La Jauría, „In der Nähe suchen“ und der Enzyklopädie.",
	["Se acabó el aviso «Alfa_Builds se ha bloqueado…»: la ventana de talentos, el clic para lanzar y el Legado ahora los abre el juego, y tus hechizos se lanzan sin problema desde el libro."] = "Schluss mit der Meldung „Alfa_Builds wurde blockiert…“: Talentfenster, Klickzauber und Vermächtnis öffnet jetzt das Spiel selbst, und deine Zauber wirken problemlos aus dem Zauberbuch.",
	["Se acabó tu XP descansada"] = "Dein Ruhebonus ist aufgebraucht",
	["Se acelera a sí mismo y lanza rayos: interrúmpelo."] = "Er beschleunigt sich selbst und wirkt Blitze: Unterbrich ihn.",
	["Se acelera a sí mismo: interrúmpelo si puedes."] = "Er beschleunigt sich selbst: Unterbrich ihn, wenn du kannst.",
	["Se activó Claridad: tu siguiente hechizo es gratis."] = "Freizaubern aktiv: Dein nächster Zauber ist kostenlos.",
	["Se activó Claridad: tus Misiles arcanos salen gratis."] = "Freizaubern aktiv: Deine Arkanen Geschosse sind kostenlos.",
	["Se activó Trance de las Sombras: tu Descarga de las Sombras es instantánea."] = "Schattentrance aktiv: Dein Schattenblitz ist sofort.",
	["Se agregó el sonido %d a tu lista."] = "Sound %d zu deiner Liste hinzugefügt.",
	["Se aplica al salir de combate."] = "Wird nach dem Kampf angewendet.",
	["Se aprende con %s"] = "Erlernt durch %s",
	["Se borra el progreso de mazmorras de este personaje. No se puede deshacer."] = "Der Dungeon-Fortschritt dieses Charakters wird gelöscht. Das lässt sich nicht rückgängig machen.",
	["Se borran las sesiones guardadas de este personaje. La sesión de ahora sigue contando."] = "Die gespeicherten Sitzungen dieses Charakters werden gelöscht. Die aktuelle Sitzung zählt weiter.",
	["Se borran las sesiones, las zonas y los objetos de este personaje. No se puede deshacer."] = "Die Sitzungen, Gebiete und Gegenstände dieses Charakters werden gelöscht. Das lässt sich nicht rückgängig machen.",
	["Se borran los %d marcadores de todos tus personajes. No se puede deshacer."] = "Die %d Markierungen aller deiner Charaktere werden gelöscht. Das lässt sich nicht rückgängig machen.",
	["Se borran los jefes vencidos, las veces completada y el botín anotado de %s para este personaje."] = "Besiegte Bosse, Abschlüsse und notierte Beute von %s werden für diesen Charakter gelöscht.",
	["Se borran los precios guardados de la subasta de este reino y facción. Tus recetas se quedan."] = "Die gespeicherten Auktionspreise dieses Realms und dieser Fraktion werden gelöscht. Deine Rezepte bleiben.",
	["Se borran todas las peleas guardadas, también en la ventana del medidor del juego."] = "Alle gespeicherten Kämpfe werden gelöscht, auch im Fenster des Schadensmessers des Spiels.",
	["Se borran tus sesiones, tu diario, tus logros y tus metas de este personaje. Tu habilidad de pesca no cambia."] = "Deine Sitzungen, dein Tagebuch, deine Erfolge und Ziele dieses Charakters werden gelöscht. Deine Angelfertigkeit ändert sich nicht.",
	["Se carga al salir de combate"] = "Wird nach dem Kampf geladen",
	["Se cerró la subasta antes de recibir los precios. Vuelve a intentarlo después."] = "Das Auktionshaus wurde geschlossen, bevor die Preise ankamen. Versuch es später erneut.",
	["Se cerró la ventana de clic para lanzar de Blizzard. Vuelve a pulsar «Abrir clic para lanzar» para abrirla."] = "Das Klickzauber-Fenster von Blizzard wurde geschlossen. Klick noch mal auf „Klickzauber öffnen“, um es zu öffnen.",
	["Se cumple al llegar a ese nivel."] = "Erfüllt, wenn du diese Stufe erreichst.",
	["Se cura a sí mismo: interrumpe su curación."] = "Er heilt sich selbst: Unterbrich seine Heilung.",
	["Se cura comiendo: mátenlo rápido."] = "Er heilt sich durch Essen: Tötet ihn schnell.",
	["Se cura: interrúmpelo."] = "Er heilt sich: Unterbrich ihn.",
	["Se descubren todos los jefes de %s, como si la hubieras terminado. Si te equivocas, puedes olvidar tu progreso aquí."] = "Alle Bosse von %s werden aufgedeckt, als hättest du ihn abgeschlossen. Falls das ein Versehen war, kannst du deinen Fortschritt hier vergessen.",
	["Se detuvo al cerrar el banco: guardaste %d y faltaron %d."] = "Gestoppt, als die Bank geschlossen wurde: %d eingelagert, %d blieben übrig.",
	["Se detuvo al entrar en combate: guardaste %d y faltaron %d."] = "Gestoppt bei Kampfbeginn: %d eingelagert, %d blieben übrig.",
	["Se enfurece al final: guarden su mejor daño."] = "Am Ende wird er wütend: Hebt euch euren besten Schaden auf.",
	["Se enfurece con poca vida: termínenlo rápido."] = "Bei wenig Gesundheit wird er wütend: Erledigt ihn schnell.",
	["Se enfurece y pega más fuerte con el tiempo: mátenlo rápido."] = "Er wird mit der Zeit wütender und schlägt härter zu: Tötet ihn schnell.",
	["Se entrega con %s"] = "Abgabe bei %s",
	["Se entrega dentro"] = "Wird drinnen abgegeben",
	["Se escapó"] = "Entkommen",
	["Se fabrica"] = "Hergestellt",
	["Se marcan como chatarra"] = "Werden als Plunder markiert",
	["Se me antoja un buen filete de jabalí. Solo digo."] = "Ich hätte richtig Lust auf ein Eberfilet. Ich sag ja nur.",
	["Se pelea bajo el agua: vigila tu barra de respiración y sube a tomar aire si hace falta."] = "Der Kampf findet unter Wasser statt: Achte auf deine Atemleiste und tauch bei Bedarf zum Luftholen auf.",
	["Se pesca"] = "Geangelt",
	["Se protege con su escudo y aturde: ataquen a los otros dos primero."] = "Er schützt sich mit seinem Schild und betäubt: Greift zuerst die anderen beiden an.",
	["Se puede al salir de combate."] = "Möglich, sobald der Kampf vorbei ist.",
	["Se puede anunciar al salir de combate."] = "Ansagen ist nach dem Kampf möglich.",
	["Se puede enviar ahora: %s"] = "Senden gerade möglich: %s",
	["Se pueden conseguir"] = "Erhältlich",
	["Se pusieron %d de %d opciones"] = "%d von %d Optionen wurden gesetzt",
	["Se queda en el modo limpio."] = "Bleibt im Fokusmodus.",
	["Se quita de tu lista. Si lo necesitas otra vez, vuelve a importar su cadena."] = "Er wird aus deiner Liste entfernt. Wenn du ihn wieder brauchst, importiere seinen Text erneut.",
	["Se quitan los nodos que anotaste al recolectar y cuántas veces los recolectaste. La base incluida se queda. No se puede deshacer."] = "Die Vorkommen, die du beim Sammeln notiert hast, und wie oft du sie gesammelt hast, werden entfernt. Die mitgelieferte Datenbank bleibt. Das lässt sich nicht rückgängig machen.",
	["Se quitó el sonido %d de tu lista."] = "Sound %d aus deiner Liste entfernt.",
	["Se saltan (no están en tu árbol): %s."] = "Übersprungen (nicht in deinem Baum): %s.",
	["Se teletransporta a las orillas de la sala: si peleas cuerpo a cuerpo, síguelo."] = "Er teleportiert sich an die Ränder des Raums: Wenn du im Nahkampf kämpfst, folge ihm.",
	["Se toma dentro de la mazmorra: ahí la verás."] = "Wird im Dungeon angenommen: Dort siehst du sie.",
	["Se ve después de reiniciar los gráficos."] = "Wirkt nach einem Neustart der Grafik.",
	["Se vende ahora"] = "Wird jetzt verkauft",
	["Se vende en"] = "Verkauft von",
	["Se vende en %s cada uno."] = "Verkauft sich für %s pro Stück.",
	["Seccionar puede inmovilizar al rival: no se te escapa."] = "Kniesehne kann den Gegner bewegungsunfähig machen: Er entkommt dir nicht.",
	["Seccionar puede inmovilizar: nadie se te escapa para traer amigos."] = "Kniesehne kann bewegungsunfähig machen: Niemand entkommt dir, um Freunde zu holen.",
	["Secundaria"] = "Sekundär",
	["Secundaria [mano]"] = "Schildhand",
	["Sed de sangre: tu golpe más fuerte, cada vez que esté listo."] = "Blutdurst: dein stärkster Schlag, jedes Mal, wenn er bereit ist.",
	["Seguimiento"] = "Folgen",
	["Seguir"] = "Folgen",
	["Seguir (flecha y ruta)"] = "Folgen (Pfeil und Route)",
	["Seguir a %s"] = "%s folgen",
	["Seguir con %s"] = "Weiter mit %s",
	["Seguir el terreno"] = "Dem Gelände folgen",
	["Seguir esta guía"] = "Diesem Guide folgen",
	["Seguir esta ruta"] = "Dieser Route folgen",
	["Seguir este build"] = "Diesem Build folgen",
	["Seguir este plan"] = "Diesem Plan folgen",
	["Seguir jugando"] = "Weiterspielen",
	["Seguir muestra tu guía y la flecha, y cierra esta ventana para que las veas."] = "„Folgen“ zeigt deinen Guide und den Pfeil und schließt dieses Fenster, damit du sie siehst.",
	["Seguir por aquí"] = "Hier entlang",
	["Seguir ruta"] = "Route folgen",
	["Seguir sola con la siguiente guía"] = "Von selbst mit dem nächsten Guide weitermachen",
	["Seguir un build de %s"] = "Einem Build für %s folgen",
	["Segundos junto a la barra"] = "Sekunden neben der Leiste",
	["Según su leyenda, los jabaespines nacieron de la sangre de Agamaggan, el gran jabalí semidiós. Por eso viven entre espinas gigantes."] = "Ihrer Legende nach entstanden die Stacheleber aus dem Blut von Agamaggan, dem großen Eberhalbgott. Darum leben sie zwischen riesigen Dornen.",
	["Seleccionar objetivo"] = "Anvisieren",
	["Seleccionar para copiar"] = "Zum Kopieren markieren",
	["Seleccionar todo"] = "Alles auswählen",
	["Sello"] = "Siegel",
	["Sepia"] = "Sepia",
	["Servicio"] = "Dienst",
	["Servicios"] = "Dienste",
	["Servicios en el minimapa"] = "Dienste auf der Minikarte",
	["Será una mejora más adelante"] = "Wird später ein Upgrade",
	["Sesiones anteriores"] = "Frühere Sitzungen",
	["Sesiones que guarda el diario"] = "Sitzungen, die das Tagebuch speichert",
	["Sesiones, diario, logros y metas de este personaje. No se puede deshacer."] = "Sitzungen, Tagebuch, Erfolge und Ziele dieses Charakters. Lässt sich nicht rückgängig machen.",
	["Sesión de pesca nueva."] = "Neue Angelsitzung.",
	["Señalar"] = "Zeigen",
	["Señor de las aguas"] = "Herr der Gewässer",
	["Si aguantas bien, usa Golpe heroico con la ira sobrante para más amenaza."] = "Wenn du gut durchhältst, nutze Heldenhafter Stoß mit übriger Wut für mehr Bedrohung.",
	["Si algo sale mal, tu habilidad para desaparecer te saca de la pelea. Úsala antes de que sea tarde."] = "Wenn etwas schiefgeht, holt dich deine Fähigkeit zu verschwinden aus dem Kampf. Nutze sie, bevor es zu spät ist.",
	["Si alguien de la manada te pasa uno, impórtalo y Alfa te guía con él punto por punto."] = "Wenn dir jemand aus dem Rudel einen gibt, importiere ihn, und Alfa führt dich Punkt für Punkt damit.",
	["Si alguien huye, puede traer a más presos: deténganlo con un ataque que lo frene."] = "Wenn jemand flieht, kann er weitere Gefangene holen: Haltet ihn mit einem verlangsamenden Angriff auf.",
	["Si alguna vez ves salchichas en una posada, guárdame una… o dos."] = "Wenn du mal Würstchen in einem Gasthaus siehst, heb mir eins auf… oder zwei.",
	["Si bajas por el Gran Elevador, verás por qué se llama así: cientos de agujas de roca."] = "Wenn du mit dem Großen Aufzug hinunterfährst, siehst du, warum es so heißt: Hunderte Felsnadeln.",
	["Si en estas fechas ves calabazas en las posadas, es Halloween: los posaderos te dan dulces con truco o trato, y a veces un disfraz."] = "Wenn du um diese Zeit Kürbisse in den Gasthäusern siehst, sind Schlotternächte: Die Gastwirte geben dir Süßes oder Saures und manchmal ein Kostüm.",
	["Si en estas fechas ves faroles y fuegos artificiales, es el Festival Lunar: visita a los Ancestros por el mundo, que cada uno te da una moneda."] = "Wenn du um diese Zeit Laternen und Feuerwerk siehst, ist Mondfest: Besuch die Ahnen überall in der Welt, jeder gibt dir eine Münze.",
	["Si en febrero las ciudades huelen a perfume, es «Amor en el aire»: la gente reparte regalos y hasta los guardias reciben detalles."] = "Wenn die Städte im Februar nach Parfüm duften, liegt „Liebe in der Luft“: Die Leute verteilen Geschenke, und sogar die Wachen bekommen Aufmerksamkeiten.",
	["Si encuentras un hueso, es mío. ¿Trato hecho?"] = "Wenn du einen Knochen findest, gehört er mir. Abgemacht?",
	["Si eres desollador, las zonas llenas de bestias, como raptores, kodos o felinos, te dan cuero sin parar."] = "Als Kürschner geben dir Zonen voller Bestien wie Raptoren, Kodos oder Katzen ohne Ende Leder.",
	["Si está fuera de tu alcance, su marco se ve más tenue."] = "Ist es außer Reichweite, wirkt sein Rahmen blasser.",
	["Si fabricas para otros, cobra justo: la gente vuelve y te recomienda."] = "Wenn du für andere herstellst, verlang faire Preise: Die Leute kommen wieder und empfehlen dich.",
	["Si hoy cuesta, mañana sale. Aquí sigo contigo."] = "Wenn es heute schwer ist, klappt es morgen. Ich bin noch bei dir.",
	["Si juegas sin grupo, la ventana se esconde."] = "Wenn du ohne Gruppe spielst, verbirgt sich das Fenster.",
	["Si la pelea va mal, desvanécete y vuelve a empezar."] = "Wenn der Kampf schlecht läuft, nutze Verschwinden und fang neu an.",
	["Si la recompensa tiene varias opciones, eliges tú."] = "Wenn die Belohnung mehrere Optionen hat, wählst du.",
	["Si la terminas"] = "Wenn du sie abschließt",
	["Si la vida baja de la mitad y el sanador no llega, usa Último recurso."] = "Wenn deine Gesundheit unter die Hälfte fällt und der Heiler nicht nachkommt, nutze Letztes Gefecht.",
	["Si le haces el gesto de gallina a una gallina de granja muchas veces, a veces te pide ayuda... y la historia termina en mascota."] = "Wenn du einem Bauernhuhn oft genug das Hühner-Emote machst, bittet es dich manchmal um Hilfe... und die Geschichte endet mit einem Haustier.",
	["Si llega a 0 % se rompe y deja de darte sus estadísticas. Repara cuanto antes con un herrero o un vendedor que repare."] = "Bei 0 % sind seine Werte weg, weil es zerbricht. Repariere so bald wie möglich bei einem Schmied oder einem Händler, der repariert.",
	["Si llegas a exaltado con otra raza de tu bando, te venden sus monturas. ¡Un kodo para un orco o un sable de la noche para un humano!"] = "Wenn du bei einem anderen Volk deiner Fraktion ehrfürchtig bist, verkaufen sie dir ihre Reittiere. Ein Kodo für einen Orc oder ein Nachtsäbler für einen Menschen!",
	["Si llevas puesto el abalorio del Alba Argenta, los no-muertos de las Tierras de la Peste sueltan piedras que cambias por reputación y fichas."] = "Trägst du das Schmuckstück der Argentumdämmerung, lassen die Untoten der Pestländer Steine fallen, die du gegen Ruf und Abzeichen eintauschst.",
	["Si lo que te dan mejora tu equipo, te lo pones al salir de combate."] = "Ist, was du bekommst, eine Verbesserung, legst du es nach dem Kampf an.",
	["Si moviste los avisos y ya no los encuentras."] = "Falls du die Hinweise verschoben hast und sie nicht mehr findest.",
	["Si mueres seguido, cambia al estilo Tranquilo."] = "Wenn du oft stirbst, wechsle zum Stil „Ruhig“.",
	["Si necesitas silencio, con clic derecho me callas un rato."] = "Wenn du Ruhe brauchst, bring mich mit Rechtsklick eine Weile zum Schweigen.",
	["Si no eres druida, al Claro de la Luna se llega por los túneles de los Fauces de Madera, desde Frondavil."] = "Wenn du kein Druide bist, erreichst du die Mondlichtung durch die Tunnel der Holzschlunde vom Teufelswald aus.",
	["Si no tienes ninguna abierta, abre la recomendada para tu nivel."] = "Wenn du keinen offen hast, öffnet es den für deine Stufe empfohlenen.",
	["Si nos perdemos en %s, tú lees el mapa y yo sigo el rastro."] = "Wenn wir uns in %s verlaufen, liest du die Karte und ich folge der Spur.",
	["Si peleas de lejos, quédate lejos de ella."] = "Wenn du auf Distanz kämpfst, halte dich von ihr fern.",
	["Si quieres matar más rápido en solitario, cambia a Armas cuando tengas oro para reiniciar."] = "Wenn du solo schneller töten willst, wechsle zu Waffen, sobald du Gold zum Zurücksetzen hast.",
	["Si quieres, tu personaje aparece en el mapa del juego de los lobos que usan Alfa, y ellos en el tuyo: quién anda cerca, dónde y, con un clic, la flecha te lleva. Solo es el lugar de tu personaje dentro de WoW, nunca tu ubicación real. Tu grupo se ve siempre."] = "Wenn du willst, erscheint dein Charakter auf der Spielkarte der Wölfe, die Alfa nutzen, und sie auf deiner: wer in der Nähe ist, wo, und mit einem Klick führt dich der Pfeil hin. Es ist nur der Ort deines Charakters in WoW, nie dein echter Standort. Deine Gruppe siehst du immer.",
	["Si sigues el consejo"] = "Wenn du dem Tipp folgst",
	["Si sigues la cadena del mariscal Windsor, en Ventormenta destaparás quién es en realidad Lady Prestor."] = "Folgst du der Questreihe von Marschall Windsor, entlarvst du in Sturmwind, wer Lady Prestor wirklich ist.",
	["Si sigues la historia del Templo Sumergido, en el pantano te espera Itharius, un dragón verde."] = "Folgst du der Geschichte des Versunkenen Tempels, wartet im Sumpf Itharius auf dich, ein grüner Drache.",
	["Si sigues los consejos"] = "Wenn du den Tipps folgst",
	["Si sigues los consejos ganas %s"] = "Wenn du den Tipps folgst, verdienst du %s",
	["Si te alcanzan, usa tus golpes cuerpo a cuerpo y aléjate otra vez."] = "Wenn sie dich erreichen, nutze deine Nahkampfschläge und geh wieder auf Abstand.",
	["Si te baja mucho la vida, cambia a actitud defensiva: tu ira no se pierde."] = "Wenn deine Gesundheit stark sinkt, wechsle in die Verteidigungshaltung: Deine Wut geht nicht verloren.",
	["Si te pegan mientras te vendas, se corta: aléjate un poco antes de usarla."] = "Wenn du beim Verbinden getroffen wirst, bricht es ab: Geh ein Stück weg, bevor du den Verband benutzt.",
	["Si te quedas sin lanzar"] = "Wenn du nicht mehr auswirfst",
	["Si te sobra un pedacito de carne, aquí hay una panza que lo recibe con gusto."] = "Wenn du ein Stückchen Fleisch übrig hast, gibt es hier einen Bauch, der es gern nimmt.",
	["Si tienes poco tiempo, si no tienes con quién jugar o quién te ayude, puedes apoyarte en Alfa y en Lya en tu travesía."] = "Wenn du wenig Zeit hast, niemanden zum Spielen oder niemanden, der dir hilft, kannst du dich auf deiner Reise auf Alfa und Lya stützen.",
	["Si tu caña no tiene cebo, tu tecla pone el mejor que tengas (o el que prefieras) antes de lanzar."] = "Hat deine Angel keinen Köder, bringt deine Taste vor dem Auswerfen den besten an, den du hast (oder deinen bevorzugten).",
	["Si tu objetivo es un jugador, su fondo toma el color de su clase en lugar del de su reacción."] = "Ist dein Ziel ein Spieler, nimmt sein Hintergrund die Klassenfarbe statt der Reaktionsfarbe an.",
	["Si tu rango lo permite, la hermandad paga y tu dinero pone el resto."] = "Wenn dein Rang es erlaubt, zahlt die Gilde und dein Geld deckt den Rest.",
	["Si tú o tus personajes pueden"] = "Wenn du oder deine Charaktere es können",
	["Si un día ganamos mucho oro, yo ya sé en qué gastarlo: salchichas."] = "Wenn wir eines Tages viel Gold verdienen, weiß ich schon, wofür: Würstchen.",
	["Si un enemigo te persigue, no corras: acércate al tanque."] = "Wenn dich ein Gegner verfolgt, lauf nicht weg: Geh zum Tank.",
	["Si un enemigo viene hacia ti, llévalo hacia el tanque: no corras lejos."] = "Wenn ein Gegner auf dich zukommt, bring ihn zum Tank: Lauf nicht weit weg.",
	["Si un lugar está lleno de jugadores farmeando lo mismo, cámbiate de zona: te rinde más."] = "Wenn ein Ort voller Spieler ist, die dasselbe farmen, wechsle die Zone: Das bringt dir mehr.",
	["Si un monstruo esquiva, usa Abrumar enseguida (Alfa te avisa)."] = "Wenn ein Monster ausweicht, nutze sofort Überwältigen (Alfa warnt dich).",
	["Si una misión se pone difícil, pide ayuda en el chat. En manada todo pesa menos."] = "Wenn eine Quest schwer wird, bitte im Chat um Hilfe. Im Rudel wiegt alles weniger.",
	["Si una subasta no se vende, pierdes el depósito: no pongas precios fuera de la realidad."] = "Wenn sich eine Auktion nicht verkauft, verlierst du die Anzahlung: Setz keine unrealistischen Preise.",
	["Si vendes todo al comerciante"] = "Wenn du alles an Händler verkaufst",
	["Si ves a otro lobo por ahí, salúdalo de mi parte."] = "Wenn du dort draußen einen anderen Wolf siehst, grüß ihn von mir.",
	["Si ves carpas de colores en Villadorada o en Mulgore, llegó la Feria de la Luna Negra: hay juegos, premios y cartas que se juntan en mazos."] = "Wenn du bunte Zelte in Goldhain oder Mulgore siehst, ist der Dunkelmond-Jahrmarkt da: Es gibt Spiele, Preise und Karten, die man zu Decks sammelt.",
	["Si viajas con un mago, pídele un portal a la capital: te ahorra mucho camino."] = "Wenn du mit einem Magier reist, bitte ihn um ein Portal in die Hauptstadt: Das spart viel Weg.",
	["Siempre"] = "Immer",
	["Siempre con cebo"] = "Immer mit Köder",
	["Siempre: te ofrece la historia de cada misión y un dato de cada zona nueva. A veces: de las misiones que tomas sin leer, y no siempre. Solo si le pido: con clic derecho, «Cuéntame algo de aquí». Las historias se guardan igual."] = "Immer: Sie bietet dir die Geschichte jeder Quest und einen Fakt zu jeder neuen Zone an. Manchmal: zu den Quests, die du ungelesen annimmst, und nicht jedes Mal. Nur auf Nachfrage: mit Rechtsklick „Erzähl mir etwas über diesen Ort“. Die Geschichten werden so oder so gespeichert.",
	["Sigilo"] = "Verstohlenheit",
	["Sigilo y emboscadas: tú eliges cuándo pelear y desapareces cuando quieres."] = "Verstohlenheit und Hinterhalte: Du entscheidest, wann du kämpfst, und verschwindest, wann du willst.",
	["Siglos después de la División, los Altonato que no soltaban la magia arcana fueron desterrados. Cruzaron el mar y fundaron Quel'Thalas: son los altos elfos."] = "Jahrhunderte nach der Teilung wurden die Hochgeborenen, die nicht von der arkanen Magie lassen wollten, verbannt. Sie überquerten das Meer und gründeten Quel'Thalas: Das sind die Hochelfen.",
	["Siglos después, los orcos Faucedraco usaron el Alma de Demonio para tener presa a Alexstrasza y criar dragones de guerra para la Horda."] = "Jahrhunderte später benutzten die Drachenmalorcs die Dämonenseele, um Alexstrasza gefangen zu halten und Kriegsdrachen für die Horde zu züchten.",
	["Sigue a tu lado, pero no habla hasta las %s."] = "Sie ist noch an deiner Seite, spricht aber erst wieder um %s.",
	["Sigue a tu lado, pero no habla por un rato."] = "Sie ist noch an deiner Seite, spricht aber eine Weile nicht.",
	["Sigue donde ibas"] = "Weiter, wo du warst",
	["Sigue la flecha."] = "Folge dem Pfeil.",
	["Sigue la flecha: las paradas van en el orden más corto, juntas por PNJ."] = "Folge dem Pfeil: Die Halte kommen in der kürzesten Reihenfolge, gebündelt nach NPC.",
	["Sigue subiendo: %d de %d"] = "Steig weiter: %d von %d",
	["Sigue: %s"] = "Weiter: %s",
	["Sigue: %s. Lee sus consejos antes de la pelea."] = "Als Nächstes: %s. Lies vor dem Kampf seine Tipps.",
	["Sigues a %s"] = "Du folgst %s",
	["Sigues con tu equipo de pesca."] = "Du trägst noch deine Angelausrüstung.",
	["Siguiendo"] = "Folgen aktiv",
	["Siguiendo a %s."] = "Folge %s.",
	["Siguiendo el rastro"] = "Auf der Spur",
	["Siguiendo el rastro de %s. La flecha te lleva hasta su posición."] = "Folge der Spur von %s. Der Pfeil führt dich zu der Person.",
	["Siguiendo tu ruta de %s"] = "Du folgst deiner Route für %s",
	["Siguiente"] = "Weiter",
	["Siguiente parada:"] = "Nächster Halt:",
	["Siguiente paso de la guía"] = "Nächster Schritt des Guides",
	["Siguiente: %s (%d de %d)"] = "Nächster: %s (%d von %d)",
	["Silencia los sonidos que agregues por su número de archivo (FileDataID): /alfa silenciar <número>; /alfa silenciar quitar <número> lo quita."] = "Schaltet Sounds stumm, die du über ihre Dateinummer (FileDataID) hinzufügst: /alfa silenciar <Nummer>; /alfa silenciar quitar <Nummer> entfernt ihn wieder.",
	["Silenciar 1 hora"] = "1 Stunde stumm",
	["Silenciar sonidos"] = "Sounds stummschalten",
	["Silenciar un sonido por su número (FileDataID)"] = "Einen Sound über seine Nummer stummschalten (FileDataID)",
	["Silithus es la puerta de Ahn'Qiraj, donde los silítidos y los qiraji sirven al dios antiguo C'Thun."] = "Silithus ist das Tor nach Ahn'Qiraj, wo die Silithiden und die Qiraji dem Alten Gott C'Thun dienen.",
	["Sin Minería no ves filones; sin Herboristería, hierbas; sin Pesca, bancos. Los tesoros siempre se ven."] = "Ohne Bergbau siehst du keine Erzadern, ohne Kräuterkunde keine Kräuter, ohne Angeln keine Schwärme. Schätze siehst du immer.",
	["Sin Pesca"] = "Kein Angeln",
	["Sin XP descansada"] = "Kein Ruhebonus",
	["Sin acción"] = "Keine Aktion",
	["Sin activar"] = "Nicht aktiv",
	["Sin aprender"] = "Nicht erlernt",
	["Sin aullido"] = "Ohne Heulen",
	["Sin bloqueos y más claro"] = "Ohne Blockaden und klarer",
	["Sin cambiar de forma."] = "Nicht verwandelt.",
	["Sin cambios"] = "Keine Änderung",
	["Sin datos"] = "Keine Daten",
	["Sin demonio"] = "Kein Dämon",
	["Sin el ratón encima, la barra guarda sus botones y deja solo lo que pasa."] = "Ohne Maus darüber verstaut die Leiste ihre Buttons und zeigt nur, was passiert.",
	["Sin encantar"] = "Nicht verzaubert",
	["Sin fuente conocida"] = "Keine bekannte Quelle",
	["Sin grupo"] = "Keine Gruppe",
	["Sin límite de tiempo"] = "Ohne Zeitlimit",
	["Sin mascota"] = "Kein Tier",
	["Sin metas todavía"] = "Noch keine Ziele",
	["Sin metas todavía. Pulsa + para ponerte una: un pez, capturas, tiempo o valor."] = "Noch keine Ziele. Drück +, um eins zu setzen: ein Fisch, Fänge, Zeit oder Wert.",
	["Sin metas todavía: ábrelo y agrégale una."] = "Noch keine Ziele: Öffne ihn und füg eins hinzu.",
	["Sin munición"] = "Keine Munition",
	["Sin objeto"] = "Kein Gegenstand",
	["Sin otros personajes, uno solo puede ganar 29: 3 por subir de nivel, 6 de profesiones, 12 de JcJ, 2 de aventura y 6 de mazmorras y bandas. El resto sale de subir otras clases."] = "Ohne weitere Charaktere kann einer allein 29 verdienen: 3 durchs Leveln, 6 durch Berufe, 12 durch PvP, 2 durch Abenteuer und 6 durch Dungeons und Schlachtzüge. Der Rest kommt vom Leveln anderer Klassen.",
	["Sin precio todavía: escanea la subasta."] = "Noch kein Preis: Scanne das Auktionshaus.",
	["Sin precios"] = "Keine Preise",
	["Sin precios todavía"] = "Noch keine Preise",
	["Sin profesión"] = "Kein Beruf",
	["Sin sello"] = "Kein Siegel",
	["Sin tecla"] = "Keine Taste",
	["Sin tinte"] = "Keine Tönung",
	["Sin ubicación"] = "Kein Standort",
	["Sin ubicación ahora: en una instancia o fuera del mapa"] = "Gerade kein Standort: in einer Instanz oder außerhalb der Karte",
	["Sin veneno"] = "Kein Gift",
	["Sin zona"] = "Kein Gebiet",
	["Sobre Lya"] = "Über Lya",
	["Sobre tu compañero, este clic %s."] = "Auf deinem Gruppenmitglied: Dieser Klick %s.",
	["Solo %s"] = "Nur %s",
	["Solo al acabarse"] = "Nur wenn er aufgebraucht ist",
	["Solo al moverte"] = "Nur beim Bewegen",
	["Solo buffs"] = "Nur Buffs",
	["Solo con quienes usan Alfa y aceptaron compartir. Tú decides."] = "Nur mit Leuten, die Alfa nutzen und dem Teilen zugestimmt haben. Du entscheidest.",
	["Solo cuando estás en grupo"] = "Nur in einer Gruppe",
	["Solo el botín que me sirve"] = "Nur Beute, die ich nutzen kann",
	["Solo en una fiesta del año"] = "Nur während eines jährlichen Festes",
	["Solo en warcraft.wiki.gg e Icy Veins: cuántos puntos pide cada premio (15, 25, 40 y 55). Ninguna fuente publica cuánto cuesta cada rango de los árboles: míralo en la ventana del Legado."] = "Nur auf warcraft.wiki.gg und Icy Veins: wie viele Punkte jede Belohnung braucht (15, 25, 40 und 55). Keine Quelle nennt die Kosten der einzelnen Baumränge: Sieh im Vermächtnis-Fenster nach.",
	["Solo encontré %d misiones que te sirvan ahora."] = "Ich habe nur %d Quests gefunden, die gerade zu dir passen.",
	["Solo importantes"] = "Nur wichtige",
	["Solo la entrada"] = "Nur der Eingang",
	["Solo las misiones de tu ruta"] = "Nur die Quests deiner Route",
	["Solo las que puedes tomar: tu bando, raza, clase y nivel, y que no hayas hecho."] = "Nur die, die du annehmen kannst: deine Fraktion, dein Volk, deine Klasse und Stufe, und noch nicht erledigt.",
	["Solo lo de mi papel"] = "Nur meine Rolle",
	["Solo lo que tu clase puede usar y le conviene a tu especialización."] = "Nur, was deine Klasse nutzen kann und zu deiner Spezialisierung passt.",
	["Solo lo que tu personaje puede usar hoy: clase, armadura, armas, nivel y profesión."] = "Nur, was dein Charakter heute nutzen kann: Klasse, Rüstung, Waffen, Stufe und Beruf.",
	["Solo lo que ya puedes recolectar"] = "Nur, was du schon sammeln kannst",
	["Solo los de la zona donde estás."] = "Nur die im Gebiet, in dem du bist.",
	["Solo los de tus profesiones, en el mapa del mundo y en el minimapa."] = "Nur die deiner Berufe, auf Weltkarte und Minikarte.",
	["Solo los graves"] = "Nur kritische",
	["Solo los que me apuntan a mí"] = "Nur die, die auf mich zielen",
	["Solo misiones de XP, las mejores cerca de ti, en tres tandas."] = "Nur EP-Quests, die besten in deiner Nähe, in drei Runden.",
	["Solo para %s."] = "Nur für %s.",
	["Solo para mirar: tu paso de ahora no cambia. Alfa avanza sola cuando lo cumples."] = "Nur zum Anschauen: Dein aktueller Schritt bleibt gleich. Alfa geht von selbst weiter, wenn du ihn erfüllst.",
	["Solo puedes tener dos principales a la vez; las secundarias son libres. Se aprenden con su entrenador en las ciudades."] = "Du kannst nur zwei Hauptberufe gleichzeitig haben; Nebenberufe sind frei. Du lernst sie bei ihrem Lehrer in den Städten.",
	["Solo salen los clanes donde puedes invitar, y Alfa te confirma en el chat a quién invitaste. Lo apagas en La Jauría > Invitar."] = "Es erscheinen nur die Orte, in die du einladen darfst, und Alfa bestätigt im Chat, wen du eingeladen hast. Abschalten unter La Jauría > Einladen.",
	["Solo se admite la versión 1 de la cadena de escala."] = "Nur Version 1 des Skalen-Texts wird unterstützt.",
	["Solo si falta"] = "Nur wenn er fehlt",
	["Solo si le pido"] = "Nur auf Nachfrage",
	["Solo sirve con un monitor HDR y el HDR de Windows encendido (Configuración > Pantalla). Sin eso, déjalo apagado: los colores se ven lavados."] = "Funktioniert nur mit einem HDR-Monitor und eingeschaltetem Windows-HDR (Einstellungen > Anzeige). Sonst lass es aus: Die Farben wirken ausgewaschen.",
	["Solo tocan gráficos: nunca la cámara, el ratón ni la interfaz. «Deshacer» devuelve lo que tenías antes del último que aplicaste."] = "Sie ändern nur die Grafik: nie Kamera, Maus oder Oberfläche. „Rückgängig“ holt zurück, was du vor der zuletzt angewendeten hattest.",
	["Solo tu grupo y quienes usan Alfa y aceptaron compartir."] = "Nur deine Gruppe und alle, die Alfa nutzen und dem Teilen zugestimmt haben.",
	["Solo tú"] = "Nur du",
	["Solo tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Nur du, deine Gruppe, deine Markierungen und der nächste Schritt des Guides.",
	["Sombra"] = "Schatten",
	["Sombra para subir"] = "Schatten zum Leveln",
	["Sombra suave en rincones, pliegues y bajo los objetos: da volumen a todo."] = "Sanfte Schatten in Ecken, Falten und unter Objekten: gibt allem Tiefe.",
	["Sombras"] = "Schatten",
	["Sombras con bordes más finos. Usa más memoria de video."] = "Schatten mit feineren Kanten. Braucht mehr Grafikspeicher.",
	["Sombras suaves"] = "Weiche Schatten",
	["Son %s más que venderlo todo al comerciante."] = "Das sind %s mehr, als alles beim Händler zu verkaufen.",
	["Son puntos de tu cuenta: los ganas con los retos del Legado (logros de Forever) en cualquier personaje, y cada personaje los gasta por su cuenta en sus árboles."] = "Es sind Account-Punkte: Du verdienst sie mit den Vermächtnis-Herausforderungen (Erfolge von Forever) auf jedem Charakter, und jeder Charakter gibt sie selbst in seinen Bäumen aus.",
	["Son tres enanos que pelean juntos: uno dispara de lejos, otro es muy veloz y otro se protege con escudo. Mátenlos uno por uno."] = "Drei Zwerge, die zusammen kämpfen: Einer schießt aus der Ferne, einer ist sehr schnell und einer schützt sich mit einem Schild. Tötet sie einen nach dem anderen.",
	["Sonido"] = "Ton",
	["Sonido con el juego en segundo plano"] = "Ton bei Spiel im Hintergrund",
	["Sonido de los avisos"] = "Hinweiston",
	["Sonido en los avisos urgentes"] = "Ton bei dringenden Hinweisen",
	["Sonido suave"] = "Sanfter Klang",
	["Sonido y avisos"] = "Ton und Hinweise",
	["Sonidos de gestos"] = "Emote-Sounds",
	["Sonidos de mascotas"] = "Tiergeräusche",
	["Sonidos en tu lista (%d): %s"] = "Sounds in deiner Liste (%d): %s",
	["Sonidos suaves del juego: nada de voces ni sonidos repetidos."] = "Sanfte Spielgeräusche: keine Stimmen und keine Wiederholungen.",
	["Sorpresa"] = "Überraschung",
	["Sorpresas y cofres"] = "Überraschungen und Truhen",
	["Stromgarde, la heredera de Strom, resiste a medias: trols, ogros y el Sindicato se pelean por sus ruinas."] = "Stromgarde, die Erbin von Strom, hält sich nur mühsam: Trolle, Oger und das Syndikat kämpfen um seine Ruinen.",
	["Su arpón envenena: quita el veneno si puedes."] = "Seine Harpune vergiftet: Entferne das Gift, wenn du kannst.",
	["Su botín está por descubrir"] = "Seine Beute ist noch zu entdecken",
	["Su electricidad salta de un jugador a otro: sepárense."] = "Seine Elektrizität springt von Spieler zu Spieler: Verteilt euch.",
	["Su final no alcanzó a guardarse."] = "Ihr Ende konnte nicht mehr gespeichert werden.",
	["Su mordida envenena: quita el veneno si puedes."] = "Sein Biss vergiftet: Entferne das Gift, wenn du kannst.",
	["Su oro y sus recompensas ya son tuyos: solo falta entregarlas."] = "Ihr Gold und ihre Belohnungen gehören schon dir: Du musst sie nur noch abgeben.",
	["Su rayo salta de un jugador a otro: no se queden todos juntos."] = "Sein Blitz springt von Spieler zu Spieler: Steht nicht alle zusammen.",
	["Su rayo salta de un jugador a otro: sepárense un poco."] = "Sein Blitz springt von Spieler zu Spieler: Verteilt euch ein wenig.",
	["Suave"] = "Sanft",
	["Subasta"] = "Auktion",
	["Subasta:"] = "Auktion:",
	["Subastador"] = "Auktionator",
	["Subastadores"] = "Auktionatoren",
	["Subastar"] = "Versteigern",
	["Subastar %d"] = "%d versteigern",
	["Sube los efectos y baja la música y el ambiente para que oigas el chapoteo. Al terminar, todo vuelve a como estaba."] = "Dreht die Effekte lauter und Musik und Umgebung leiser, damit du das Platschen hörst. Danach ist alles wie vorher.",
	["Sube tu profesión o junta sus materiales donde más hay."] = "Steigere deinen Beruf oder sammle seine Materialien dort, wo es am meisten gibt.",
	["Sube tus oficios con lo que tienes cerca."] = "Steigere deine Berufe mit dem, was in der Nähe ist.",
	["Subidón de adrenalina: recuperas energía mucho más rápido."] = "Adrenalinrausch: Du regenerierst Energie viel schneller.",
	["Subir"] = "Nach oben",
	["Subir %s a %d"] = "%s auf %d steigern",
	["Subir cocina y pesca juntas"] = "Kochkunst und Angeln zusammen steigern",
	["Subir como tanque: más lento que Armas, pero casi nunca mueres, juntas varios monstruos a la vez y llegas listo para tanquear cualquier mazmorra."] = "Leveln als Tank: langsamer als Waffen, aber du stirbst fast nie, ziehst mehrere Monster gleichzeitig und bist bereit, jeden Dungeon zu tanken.",
	["Subir de nivel"] = "Leveln",
	["Subir de nivel, profesiones, hacer oro o mazmorras: dos clics y Alfa te lleva."] = "Leveln, Berufe, Gold machen oder Dungeons: zwei Klicks, und Alfa bringt dich hin.",
	["Subir de nivel, profesiones, oro o mazmorras."] = "Leveln, Berufe, Gold oder Dungeons.",
	["Subir el sonido al pescar"] = "Lauter beim Angeln",
	["Subir rápido"] = "Schnell leveln",
	["Subir solo"] = "Solo leveln",
	["Subir una profesión"] = "Einen Beruf steigern",
	["Succionar vida: daño con el tiempo que te cura."] = "Lebensentzug: Schaden über Zeit, der dich heilt.",
	["Suelta"] = "Beute",
	["Suelta el lanzamiento de ahora y lanza otra vez, sin poner equipo ni cebo."] = "Bricht den aktuellen Wurf ab und wirft erneut aus, ohne Ausrüstung oder Köder.",
	["Suelta lo que tienes en el cursor y vuelve a intentarlo."] = "Lass los, was du am Cursor hast, und versuch es noch mal.",
	["Suelta una carta que empieza una misión: revisa su botín."] = "Er lässt einen Brief fallen, der eine Quest startet: Schau dir seine Beute an.",
	["Suelta una llave que abre una puerta más adelante: alguien debe recogerla."] = "Er lässt einen Schlüssel fallen, der weiter vorne eine Tür öffnet: Jemand muss ihn aufheben.",
	["Suelta una nube de enfermedad a su alrededor: quiten enfermedades."] = "Er setzt eine Krankheitswolke um sich frei: Entfernt Krankheiten.",
	["Suelta una ola de fuego a su alrededor: si peleas de lejos, quédate lejos de él."] = "Er sendet eine Feuerwelle um sich aus: Wenn du auf Distanz kämpfst, halte dich von ihm fern.",
	["Suena ahora, aunque el aullido esté apagado."] = "Spielt es jetzt ab, auch wenn das Heulen aus ist.",
	["Sueño con una montaña de salchichas... y yo en la punta, feliz."] = "Ich träume von einem Berg aus Würstchen... und ich ganz oben, glücklich.",
	["Sugerida para ti: %s"] = "Vorschlag für dich: %s",
	["Sugerir qué vender"] = "Vorschlagen, was verkauft wird",
	["Sugiere con la prioridad de Alfa para tu clase. Apagado, usa la ayuda de Blizzard cuando el juego da una sugerencia que Alfa puede leer; en combate Forever la oculta, así que ahí sigue la de Alfa."] = "Schlägt mit der Priorität von Alfa für deine Klasse vor. Aus: nutzt Blizzards Kampfhilfe, wenn das Spiel einen Vorschlag gibt, den Alfa lesen kann; im Kampf verbirgt Forever ihn, dort gilt die von Alfa.",
	["Sulfuras es el martillo de Ragnaros. Con su ojo, los más valientes pueden forjar una versión legendaria."] = "Sulfuras ist Ragnaros' Hammer. Mit seinem Auge können die Mutigsten eine legendäre Version schmieden.",
	["Suma tus sesiones de hoy con este personaje."] = "Zählt deine heutigen Sitzungen mit diesem Charakter zusammen.",
	["Suma «conseguir este objeto» a tu plan de ahora (o a uno nuevo)."] = "Fügt „diesen Gegenstand besorgen“ zu deinem aktuellen Plan (oder einem neuen) hinzu.",
	["Supervivencia"] = "Überleben",
	["Supervivencia para subir"] = "Überleben zum Leveln",
	["Sus bolas de sombra pegan mucho: interrúmpelo."] = "Seine Schattenblitze treffen hart: Unterbrich ihn.",
	["Sus consejos"] = "Ihre Tipps",
	["Sus consejos te esperan en Alfa."] = "Seine Tipps warten in Alfa auf dich.",
	["Sus jefes, su botín, sus misiones y cómo llegar."] = "Seine Bosse, seine Beute, seine Quests und wie du hinkommst.",
	["Sus misiones dan"] = "Seine Quests geben",
	["Sus rayos saltan entre jugadores: sepárense."] = "Ihre Blitze springen zwischen Spielern: Verteilt euch.",
	["Sutileza"] = "Täuschung",
	["Sutileza para subir"] = "Täuschung zum Leveln",
	["Sylvanas era hermana de Alleria y de Vereesa Brisaveloz. Hoy guía a los Renegados con mano firme."] = "Sylvanas war die Schwester von Alleria und Vereesa Windläufer. Heute führt sie die Verlassenen mit fester Hand.",
	["Sylvanas recibe en el Barrio Real de Entrañas, con Varimathras a su lado."] = "Sylvanas empfängt im Königsviertel von Unterstadt, mit Varimathras an ihrer Seite.",
	["Sylvanas tiene dos hermanas: Alleria, que se fue más allá del Portal Oscuro, y Vereesa, que se casó con el mago Rhonin."] = "Sylvanas hat zwei Schwestern: Alleria, die jenseits des Dunklen Portals ging, und Vereesa, die den Magier Rhonin heiratete.",
	["Sí"] = "Ja",
	["Sí, que la manada me vea"] = "Ja, das Rudel soll mich sehen",
	["Sí, que me vean"] = "Ja, sie sollen mich sehen",
	["Sí, ya la hice"] = "Ja, schon gemacht",
	["Tabardo"] = "Wappenrock",
	["Talentos"] = "Talente",
	["Talentos de %s"] = "Talente von %s",
	["Talentos te dice cuál sigue."] = "Talente zeigt dir, welches als Nächstes dran ist.",
	["Talentos y combate"] = "Talente und Kampf",
	["Talentos: qué poner ahora y tu build (/alfa builds aplicar | equipo | compartir)"] = "Talente: was du jetzt nimmst und dein Build (/alfa builds aplicar | equipo | compartir)",
	["Tamaño"] = "Größe",
	["Tamaño de la barra"] = "Größe der Leiste",
	["Tamaño de las casillas"] = "Platzgröße",
	["Tamaño de lo que atraviesa"] = "Größe dessen, was sie durchdringt",
	["Tamaño del ícono"] = "Symbolgröße",
	["Tamaño en el mapa"] = "Größe auf der Karte",
	["Tamaño en el minimapa"] = "Größe auf der Minikarte",
	["También con /alfa dps. No se cierra con Esc, para que la tengas a la vista al pelear."] = "Auch mit /alfa dps. Es schließt sich nicht mit Esc, damit du es beim Kämpfen im Blick hast.",
	["También cuando el juego hace brillar otra habilidad"] = "Auch wenn das Spiel eine andere Fähigkeit aufleuchten lässt",
	["También dentro de cuevas, criptas y edificios."] = "Auch in Höhlen, Krypten und Gebäuden.",
	["También el de venenos, sangrados y efectos que duran."] = "Auch der von Giften, Blutungen und anhaltenden Effekten.",
	["También en el minimapa"] = "Auch auf der Minikarte",
	["También en montura"] = "Auch auf Reittier",
	["También está en el menú de opciones del juego."] = "Gibt es auch im Optionsmenü des Spiels.",
	["También fuera de combate"] = "Auch außerhalb des Kampfes",
	["También las de las mascotas de enemigos."] = "Auch die der Begleiter von Gegnern.",
	["También las que no son de la guía (de esas se encarga \"Aceptar misiones de la guía\"). No toma misiones grises, no entrega las que piden oro, monedas o materiales de oficio, y si hay varias recompensas eliges tú. Mantén presionado Mayús para hacerlo tú."] = "Auch die, die nicht zum Guide gehören (um die kümmert sich „Guide-Quests annehmen“). Graue Quests bleiben liegen, Quests, die Gold, Währung oder Handwerkswaren verlangen, werden nicht abgegeben, und bei mehreren Belohnungen wählst du. Halte Umschalt gedrückt, um es selbst zu machen.",
	["También las que no son de tu guía"] = "Auch die, die nicht zu deinem Guide gehören",
	["Tanque"] = "Tank",
	["Tanque de amenaza"] = "Bedrohungs-Tank",
	["Tanque de escudo"] = "Schild-Tank",
	["Tanque muralla"] = "Mauer-Tank",
	["Taretha Foxton, una muchacha humana de Durnholde, fue la amiga de Thrall y lo ayudó a escapar."] = "Taretha Foxton, ein Menschenmädchen aus Durnholde, war Thralls Freundin und half ihm bei der Flucht.",
	["Tarjeta de habilidades nuevas al subir de nivel"] = "Karte mit neuen Fähigkeiten beim Stufenaufstieg",
	["Tauren"] = "Tauren",
	["Te abrimos un susurro para %s con tu mensaje. Revísalo y pulsa Intro para enviarlo."] = "Wir haben ein Flüstern an %s mit deiner Nachricht geöffnet. Prüf sie und drück Enter zum Senden.",
	["Te avisa al momento de %s."] = "Sagt dir sofort Bescheid, wenn %s aufleuchten.",
	["Te avisa cuando tu clase tiene algo que aprovechar ahora, como una habilidad que se encendió."] = "Sagt dir, wenn deine Klasse gerade etwas nutzen kann, etwa eine Fähigkeit, die aufgeleuchtet ist.",
	["Te da %s."] = "Gibt dir %s.",
	["Te da consejos cortos y ánimo sin repetirse: cada frase sale tres veces como mucho. Dale clic para pedirle uno; clic derecho para sus opciones."] = "Sie gibt dir kurze Tipps und Mut, ohne sich zu wiederholen: Jeder Satz erscheint höchstens dreimal. Klick sie an, um einen zu bekommen; Rechtsklick für ihre Optionen.",
	["Te da poder de ataque: cada golpe pega más. Para el guerrero también sube el bloqueo con escudo."] = "Gibt dir Angriffskraft: Jeder Schlag trifft härter. Beim Krieger erhöht es auch den Schildblock.",
	["Te damos la bienvenida a Alfa, el todo en uno de La Jauría."] = "Willkommen bei Alfa, dem All-in-one von La Jauría.",
	["Te dice qué pieza está por romperse, para que la repares a tiempo."] = "Sagt dir, welches Teil bald kaputtgeht, damit du es rechtzeitig reparierst.",
	["Te enseña %s."] = "Lehrt dich %s.",
	["Te enseña Pesca y sus rangos. También vende la caña básica."] = "Lehrt Angeln und seine Ränge. Verkauft auch die einfache Angel.",
	["Te falta"] = "Fehlt",
	["Te falta %s"] = "Es fehlt: %s",
	["Te falta 1 nivel para tomarla."] = "Dir fehlt 1 Stufe, um sie anzunehmen.",
	["Te falta 1 paso"] = "Noch 1 Schritt",
	["Te falta Aspecto del halcón: más poder a distancia."] = "Aspekt des Falken fehlt: mehr Distanzangriffskraft.",
	["Te falta Aura de disparo certero: más poder a distancia para tu grupo."] = "Dir fehlt Aura des Volltreffers: mehr Distanzangriffskraft für deine Gruppe.",
	["Te falta Bendición de poderío: más poder de ataque."] = "Segen der Macht fehlt: mehr Angriffskraft.",
	["Te falta Escudo de relámpagos."] = "Blitzschlagschild fehlt.",
	["Te falta Escudo sagrado: bloqueas más."] = "Heiliger Schild fehlt: Du blockst mehr.",
	["Te falta Espinas."] = "Dornen fehlt.",
	["Te falta Fuego interior: más armadura."] = "Inneres Feuer fehlt: mehr Rüstung.",
	["Te falta Grito de batalla: más poder de ataque para ti y tu grupo."] = "Schlachtruf fehlt: mehr Angriffskraft für dich und deine Gruppe.",
	["Te falta Intelecto Arcano: más maná."] = "Arkane Intelligenz fehlt: mehr Mana.",
	["Te falta Marca de lo Salvaje."] = "Mal der Wildnis fehlt.",
	["Te falta Palabra de poder: entereza: más vida."] = "Machtwort: Seelenstärke fehlt: mehr Gesundheit.",
	["Te falta aprender la receta."] = "Du musst noch das Rezept lernen.",
	["Te falta el tótem de Fuerza de la tierra: más fuerza."] = "Dir fehlt das Totem der Erdstärke: mehr Stärke.",
	["Te falta ira: Enfurecer te la da."] = "Dir fehlt Wut: Wutanfall gibt sie dir.",
	["Te falta ira: Ira sangrienta te la da gratis."] = "Dir fehlt Wut: Blutrausch gibt sie dir kostenlos.",
	["Te falta ira: esta habilidad te la da al recibir golpes."] = "Dir fehlt Wut: Diese Fähigkeit gibt sie dir, wenn du Treffer einsteckst.",
	["Te falta la forma de las Sombras: más daño de sombras y menos daño recibido."] = "Dir fehlt Schattengestalt: mehr Schattenschaden und weniger erlittener Schaden.",
	["Te falta la forma de lechúcico lunar: más daño con tus hechizos."] = "Dir fehlt Mondkingestalt: mehr Schaden mit deinen Zaubern.",
	["Te falta la profesión"] = "Beruf fehlt",
	["Te falta reputación"] = "Zu wenig Ruf",
	["Te falta tu armadura demoníaca."] = "Dir fehlt deine Dämonenrüstung.",
	["Te falta tu armadura: ponte una."] = "Dir fehlt deine Rüstung: Leg eine an.",
	["Te falta un aspecto: el del halcón da más poder a distancia."] = "Dir fehlt ein Aspekt: Der des Falken gibt mehr Distanzangriffskraft.",
	["Te falta un aspecto: el del mono te ayuda a esquivar."] = "Dir fehlt ein Aspekt: Der des Affen hilft dir auszuweichen.",
	["Te falta una bendición: Poderío da más poder de ataque."] = "Dir fehlt ein Segen: Macht gibt mehr Angriffskraft.",
	["Te falta una bendición: Sabiduría te devuelve maná."] = "Dir fehlt ein Segen: Weisheit gibt dir Mana zurück.",
	["Te falta una bendición: Santuario reduce el daño que recibes."] = "Dir fehlt ein Segen: Refugium verringert den erlittenen Schaden.",
	["Te faltan %d niveles para tomarla."] = "Dir fehlen %d Stufen, um sie anzunehmen.",
	["Te faltan %d pasos"] = "Noch %d Schritte",
	["Te faltan %s"] = "Dir fehlen %s",
	["Te faltan %s XP para el nivel %d"] = "Noch %s EP bis Stufe %d",
	["Te faltan %s XP para el nivel %d, a tu ritmo actual."] = "Dir fehlen %s EP bis Stufe %d, bei deinem aktuellen Tempo.",
	["Te faltan ingredientes para el siguiente lote."] = "Dir fehlen Zutaten für den nächsten Durchgang.",
	["Te faltan ingredientes."] = "Dir fehlen Zutaten.",
	["Te faltan niveles para llegar a %d: la guía te lo marca y sigues subiendo con tu ruta."] = "Dir fehlen Stufen, um %d zu erreichen: Der Guide markiert es, und du levelst mit deiner Route weiter.",
	["Te faltan niveles: cada nivel desde el 10 te da un punto."] = "Dir fehlen Stufen: Jede Stufe ab 10 gibt dir einen Punkt.",
	["Te la da %s, en %s."] = "%s gibt sie dir, in %s.",
	["Te la da %s."] = "%s gibt sie dir.",
	["Te la dio %s"] = "Von %s",
	["Te la dio %s · Se entrega con %s"] = "Von %s · Abgabe bei %s",
	["Te la dio y la recibe %s"] = "Von %s vergeben und angenommen",
	["Te lleva a las misiones de tu ruta que ya puedes tomar."] = "Führt dich zu den Quests deiner Route, die du schon annehmen kannst.",
	["Te llevo a %s"] = "Ich bringe dich zu %s",
	["Te llevo a la mejor fuente. Recuerda que una montura pide nivel, equitación y oro."] = "Ich bringe dich zur besten Quelle. Denk dran: Ein Reittier braucht Stufe, Reiten und Gold.",
	["Te llevo a quien recibe cada una y recoges las que siguen."] = "Ich bringe dich zu dem, der jede annimmt, und du nimmst die folgenden an.",
	["Te lo da un PNJ"] = "Von einem NPC",
	["Te lo enseña cualquier instructor de pesca. Hasta que lo aprendas, tu habilidad no pasa del tope."] = "Jeder Angellehrer bringt es dir bei. Bis du es lernst, steigt deine Fertigkeit nicht über die Obergrenze.",
	["Te lo enseña tu entrenador."] = "Dein Lehrer bringt es dir bei.",
	["Te lo pido de corazón: nunca desuelles a un lobo enfrente de mí, ¿sí?"] = "Ich bitte dich von Herzen: Häute nie einen Wolf vor meinen Augen, ja?",
	["Te los enseña tu entrenador."] = "Dein Lehrer bringt sie dir bei.",
	["Te queda 1 espacio"] = "Noch 1 Platz frei",
	["Te queda muy poco maná: Estimular lo recupera."] = "Dein Mana ist fast leer: Anregen füllt es auf.",
	["Te queda muy poco maná: Evocación lo recupera."] = "Dein Mana ist fast leer: Hervorrufung füllt es auf.",
	["Te queda poca XP descansada"] = "Dein Ruhebonus geht zur Neige",
	["Te queda poco maná y te sobra vida: cambia vida por maná."] = "Wenig Mana und Gesundheit übrig: Tausch Gesundheit gegen Mana.",
	["Te queda poco maná: cambia vida por maná."] = "Dein Mana ist knapp: Tausch Gesundheit gegen Mana.",
	["Te queda poco maná: usa tu varita."] = "Dein Mana wird knapp: Benutze deinen Zauberstab.",
	["Te quedan %d de %d espacios"] = "Noch %d von %d Plätzen frei",
	["Te saluda según la hora, comenta la zona y a veces se sienta a pedirte algo con su huesito."] = "Sie begrüßt dich je nach Tageszeit, kommentiert die Zone und setzt sich manchmal hin, um mit ihrem Knöchelchen zu betteln.",
	["Te sobra ira y hay varios enemigos: tu siguiente golpe alcanza a dos."] = "Du hast Wut übrig und mehrere Gegner: Dein nächster Schlag trifft zwei.",
	["Te sobra ira: gástala en tu siguiente golpe."] = "Du hast Wut übrig: Gib sie für deinen nächsten Schlag aus.",
	["Te sobra ira: tu siguiente golpe es más fuerte."] = "Du hast Wut übrig: Dein nächster Schlag ist stärker.",
	["Te sugiere objetivos de pasos más adelante que tienes muy cerca."] = "Schlägt Ziele aus späteren Schritten vor, die ganz in deiner Nähe sind.",
	["Te sugiere qué habilidad usar ahora y cuáles siguen. Solo sugiere: nunca presiona nada por ti."] = "Schlägt vor, welche Fähigkeit du jetzt einsetzen solltest und welche folgen. Es schlägt nur vor: Es drückt nie etwas für dich.",
	["Tecla del modo pesca"] = "Taste des Angelmodus",
	["Tecla fija para pescar"] = "Feste Angeltaste",
	["Tecla para abrir o cerrar el modo"] = "Taste zum Öffnen oder Schließen des Modus",
	["Tecla para volver a lanzar"] = "Taste zum erneuten Auswerfen",
	["Tecla y modo pesca"] = "Taste und Angelmodus",
	["Tela"] = "Stoff",
	["Teldrassil es tan grande que entre sus ramas hay colinas, lagos y cuevas."] = "Teldrassil ist so riesig, dass es in seinen Ästen Hügel, Seen und Höhlen gibt.",
	["Teldrassil es un árbol del mundo que los elfos de la noche plantaron sin la bendición de los dragones. Por eso no les dio la inmortalidad."] = "Teldrassil ist ein Weltenbaum, den die Nachtelfen ohne den Segen der Drachen pflanzten. Deshalb schenkte er ihnen keine Unsterblichkeit.",
	["Teldrassil se plantó para recuperar la inmortalidad, pero sin la bendición de los dragones. Algo en él no anda bien."] = "Teldrassil wurde gepflanzt, um die Unsterblichkeit zurückzugewinnen, aber ohne den Segen der Drachen. Mit ihm stimmt etwas nicht.",
	["Ten siempre a mano una poción de vida: este build no perdona errores."] = "Hab immer einen Heiltrank griffbereit: Dieser Build verzeiht keine Fehler.",
	["Tenga o no"] = "Ob vorhanden oder nicht",
	["Tengo hambre… ¿me compartes algo de tu mochila?"] = "Ich habe Hunger… teilst du etwas aus deinem Rucksack mit mir?",
	["Terenas Menethil, rey de Lordaeron, unió a los reinos en la Alianza de Lordaeron. Años después, su propio hijo Arthas lo mató en su trono."] = "Terenas Menethil, König von Lordaeron, vereinte die Reiche in der Allianz von Lordaeron. Jahre später tötete ihn sein eigener Sohn Arthas auf seinem Thron.",
	["Termina la configuración para usar Alfa (2 minutos)."] = "Schließ die Einrichtung ab, um Alfa zu nutzen (2 Minuten).",
	["Terminada"] = "Abgeschlossen",
	["Terminado: cumpliste todas sus metas."] = "Fertig: Du hast alle seine Ziele erfüllt.",
	["Terminar la cadena de Lord Valthalak también es un reto del Legado."] = "Die Questreihe von Lord Valthalak abzuschließen ist ebenfalls eine Vermächtnis-Herausforderung.",
	["Terminaste %d de sus misiones: entrégalas y recoge las que siguen."] = "Du hast %d seiner Quests abgeschlossen: Gib sie ab und nimm die folgenden an.",
	["Terminaste 1 de sus misiones: entrégala y recoge las que siguen."] = "Du hast 1 seiner Quests abgeschlossen: Gib sie ab und nimm die folgenden an.",
	["Terminaste esta guía."] = "Du hast diesen Guide abgeschlossen.",
	["Terminaste esta guía. Elige la siguiente para seguir subiendo."] = "Du hast diesen Guide abgeschlossen. Wähle den nächsten, um weiter zu leveln.",
	["Termínala antes de entregarla."] = "Schließ sie ab, bevor du sie abgibst.",
	["Terreno, como el minimapa"] = "Gelände, wie die Minikarte",
	["Terreno: al acercarte se ve el suelo real del minimapa, con sus montañas, ríos y tonos. Clásico: solo el mapa pintado del juego."] = "Gelände: Beim Hineinzoomen siehst du den echten Boden der Minikarte, mit Bergen, Flüssen und Farbtönen. Klassisch: nur die gemalte Karte des Spiels.",
	["Tesoro"] = "Schatz",
	["Tesoros"] = "Schätze",
	["Tesoros en el mapa"] = "Schätze auf der Karte",
	["Tesoros en el minimapa"] = "Schätze auf der Minikarte",
	["Texto de combate flotante"] = "Schwebender Kampftext",
	["Texto sobre tu personaje"] = "Text über deinem Charakter",
	["Textos y cajas mejor alineados en las ventanas de Alfa."] = "Texte und Kästen in Alfas Fenstern besser ausgerichtet.",
	["Texturas del mundo"] = "Welttexturen",
	["Texturas del suelo"] = "Bodentexturen",
	["Texturas proyectadas"] = "Projizierte Texturen",
	["Texturas y nitidez"] = "Texturen und Schärfe",
	["Theradras, la princesa de la tierra, es hija de Therazane. Amó a Zaetar, hijo de Cenarius, y sus hijos, los centauros, terminaron matándolo."] = "Theradras, die Prinzessin der Erde, ist Therazanes Tochter. Sie liebte Zaetar, den Sohn des Cenarius, und ihre Kinder, die Zentauren, töteten ihn am Ende.",
	["Theramore la fundó Jaina Valiente con los humanos que salieron de Lordaeron antes de su caída."] = "Theramore wurde von Jaina Prachtmeer mit den Menschen gegründet, die Lordaeron vor seinem Fall verließen.",
	["Thrall eligió esta tierra roja y seca para que los orcos libres empezaran de nuevo, lejos de los campos de internamiento de los humanos."] = "Thrall wählte dieses rote, trockene Land, damit die freien Orcs neu anfangen konnten, fern der Internierungslager der Menschen.",
	["Thrall es el chamán más famoso: los elementos le responden como a nadie."] = "Thrall ist der berühmteste Schamane: Die Elemente antworten ihm wie keinem anderen.",
	["Thrall gobierna la Horda desde Orgrimmar como jefe de guerra, con la mirada puesta en la paz."] = "Thrall führt die Horde von Orgrimmar aus als Kriegshäuptling, den Blick auf den Frieden gerichtet.",
	["Thrall liberó a los orcos de los campos de internamiento con la ayuda de Grom Grito Infernal y de Orgrim Martillo Maldito."] = "Thrall befreite die Orcs aus den Internierungslagern mit Hilfe von Grom Höllschrei und Orgrim Schicksalshammer.",
	["Thrall nació en Draenor, hijo de Durotan y Draka. Aedelas Blackmoore lo encontró de bebé y lo llamó «Thrall», que quiere decir esclavo."] = "Thrall wurde auf Draenor geboren, Sohn von Durotan und Draka. Aedelas Schwarzmoor fand ihn als Baby und nannte ihn „Thrall“, was Sklave bedeutet.",
	["Thrall quiere que los orcos recuperen el honor que tenían antes de la corrupción demoníaca."] = "Thrall will, dass die Orcs die Ehre zurückgewinnen, die sie vor der dämonischen Verderbnis hatten.",
	["Tiempo"] = "Zeit",
	["Tiempo de juego por sesión"] = "Spielzeit pro Sitzung",
	["Tiempo hasta que pica"] = "Zeit bis zum Anbeißen",
	["Tiempo máximo entre los dos clics. Súbelo si tus dobles clics no lanzan."] = "Längste Zeit zwischen den beiden Klicks. Erhöhe sie, wenn deine Doppelklicks nicht auswerfen.",
	["Tiempo pescando"] = "Angelzeit",
	["Tiene cuatro partes que se hacen por separado: Cementerio, Biblioteca, Armería y Catedral, de la más fácil a la más difícil."] = "Vier Flügel, die getrennt gemacht werden: Friedhof, Bibliothek, Waffenkammer und Kathedrale, vom leichtesten zum schwersten.",
	["Tienes"] = "Du hast",
	["Tienes %d"] = "Du hast %d",
	["Tienes %d  ·  en %s"] = "Du hast %d  ·  in %s",
	["Tienes %d casillas libres"] = "Du hast %d freie Plätze",
	["Tienes %d de %d"] = "Du hast %d von %d",
	["Tienes %d de %d casillas de bolsa en el banco."] = "Du hast %d von %d Taschenplätzen in der Bank.",
	["Tienes %d de %d casillas de bolsa. La siguiente cuesta %s; después pon una bolsa en ella."] = "Du hast %d von %d Taschenplätzen. Der nächste kostet %s; steck danach eine Tasche hinein.",
	["Tienes %d encendidas. Abajo está cada una, con lo que hace, por si quieres cambiar algo."] = "Du hast %d an. Unten steht jede, mit dem, was sie tut, falls du etwas ändern willst.",
	["Tienes %d misiones listas para entregar"] = "Du hast %d Quests bereit zur Abgabe",
	["Tienes %d misiones listas para entregar. ¿Las juntamos en una ruta?"] = "Du hast %d Quests zum Abgeben bereit. Sollen wir sie zu einer Route zusammenfassen?",
	["Tienes %d para gastar"] = "Du hast %d zu vergeben",
	["Tienes %d piezas mejores para pescar en tus bolsas."] = "Du hast %d bessere Angelteile in deinen Taschen.",
	["Tienes %d puntos de talento: empieza por %s"] = "Du hast %d Talentpunkte: Fang mit %s an",
	["Tienes %d puntos fuera de %s. Alfa nunca quita talentos: para seguir este build, reinicia tus talentos con tu entrenador de clase y Alfa te los vuelve a poner con un clic. O elige el build de la rama que ya llevas."] = "Du hast %d Punkte außerhalb von %s. Alfa entfernt nie Talente: Um diesem Build zu folgen, setz deine Talente bei deinem Klassenlehrer zurück, und Alfa verteilt sie dir mit einem Klick neu. Oder wähle den Build des Zweigs, den du schon hast.",
	["Tienes %d puntos libres, pero los talentos que siguen en %s no existen en tu árbol (puede que cambiaran con un parche). Ponlos a mano en la ventana del juego o prueba otro estilo."] = "Du hast %d freie Punkte, aber die nächsten Talente in %s gibt es in deinem Baum nicht (vielleicht hat ein Patch sie geändert). Verteile sie von Hand im Fenster des Spiels oder probier einen anderen Stil.",
	["Tienes %s de %s"] = "Du hast %s von %s",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "Du hast %s Preise aus deinen Suchen. Um alle zu kennen, scanne im Auktionshaus.",
	["Tienes 1 misión lista para entregar"] = "Du hast 1 Quest bereit zur Abgabe",
	["Tienes 5 puntos de combo y estás en grupo: el sangrado rinde más."] = "Du hast 5 Combopunkte und bist in einer Gruppe: Die Blutung lohnt sich mehr.",
	["Tienes 5 puntos de combo: el remate más fuerte."] = "Du hast 5 Combopunkte: der stärkste Finishing-Move.",
	["Tienes 5 puntos de combo: muerde fuerte."] = "Du hast 5 Combopunkte: Beiß kräftig zu.",
	["Tienes 6 guías abiertas"] = "Du hast 6 Guides offen",
	["Tienes activado «Rechazar invitaciones a hermandad» en Ajustes > Comodidades > Social: apágalo para que te llegue la invitación."] = "„Gildeneinladungen ablehnen“ ist unter Einstellungen > Komfort > Sozial eingeschaltet: Schalte es aus, damit dich die Einladung erreicht.",
	["Tienes cambios sin confirmar en la ventana de talentos: se descartan antes de aplicar."] = "Du hast unbestätigte Änderungen im Talentfenster: Sie werden vor dem Anwenden verworfen.",
	["Tienes cambios sin guardar en la ventana de talentos del juego: guárdalos o deshazlos ahí primero"] = "Du hast ungespeicherte Änderungen im Talentfenster des Spiels: Speichere sie dort oder mache sie zuerst rückgängig",
	["Tienes encendido «solo las misiones de mi ruta»: solo acepta las de tu ruta."] = "Du hast „nur die Quests meiner Route“ an: Es nimmt nur die Quests deiner Route an.",
	["Tienes furia: úsalo antes de la siguiente pelea, te da más poder de ataque a ti y a tu grupo."] = "Du hast Wut: Setz ihn vor dem nächsten Kampf ein, er gibt dir und deiner Gruppe mehr Angriffskraft.",
	["Tienes habilidades nuevas"] = "Du hast neue Fähigkeiten",
	["Tienes habilidades sin aprender (%d). Aprenderlas te hace más fuerte."] = "Du hast unerlernte Fähigkeiten (%d). Sie zu lernen macht dich stärker.",
	["Tienes la %s, %d versiones atrás."] = "Du hast %s, %d Versionen zurück.",
	["Tienes la %s."] = "Du hast %s.",
	["Tienes más rangos de los que pide tu build."] = "Du hast mehr Ränge, als dein Build verlangt.",
	["Tienes puesto «%s». Abre la ventana para afinar cada detalle: distancia, pasto, niebla, agua, cámara, placas y filtros."] = "Du hast „%s“ gesetzt. Öffne das Fenster, um jedes Detail feinzujustieren: Sichtweite, Gras, Nebel, Wasser, Kamera, Namensplaketten und Filter.",
	["Tienes puntos fuera del plan: Alfa no los quita, solo agrega."] = "Du hast Punkte außerhalb des Plans: Alfa entfernt sie nicht, es fügt nur hinzu.",
	["Tienes seis guías abiertas: cierra una y vuelve a intentarlo."] = "Du hast sechs Guides offen: Schließ einen und versuch es noch mal.",
	["Tienes todo %s"] = "Du hast alles von %s",
	["Tienes un hechizo para ir al Claro de la Luna, el santuario de los druidas."] = "Du hast einen Zauber, um zur Mondlichtung zu reisen, dem Heiligtum der Druiden.",
	["Tienes un punto de talento: %s"] = "Du hast einen Talentpunkt: %s",
	["Tienes una misión de clase"] = "Du hast eine Klassenquest",
	["Tinte de color"] = "Farbtönung",
	["Tipo"] = "Typ",
	["Tirion Vadín fue expulsado de la Mano de Plata por defender a Eitrigg, un orco que le salvó la vida. Hoy Eitrigg aconseja a Thrall en Orgrimmar."] = "Tirion Fordring wurde aus der Silbernen Hand verstoßen, weil er Eitrigg verteidigte, einen Orc, der ihm das Leben rettete. Heute berät Eitrigg Thrall in Orgrimmar.",
	["Tirion Vadín, el paladín expulsado de la orden, vive solo en una cabaña de estas tierras."] = "Tirion Fordring, der aus dem Orden verstoßene Paladin, lebt allein in einer Hütte in diesen Landen.",
	["Toca ahora"] = "Jetzt dran",
	["Toca el interruptor para poner o quitar una; lo que tocas manda sobre el filtro."] = "Klick auf den Schalter, um eine hinzuzufügen oder zu entfernen; was du anklickst, hat Vorrang vor dem Filter.",
	["Toda calidad"] = "Jede Qualität",
	["Toda fuente"] = "Jede Quelle",
	["Toda la cuenta"] = "Ganzer Account",
	["Toda ranura"] = "Alle Plätze",
	["Todas"] = "Alle",
	["Todas (%d)"] = "Alle (%d)",
	["Todas las guías de profesiones"] = "Alle Berufsguides",
	["Todas las guías por zona y nivel, con la que Alfa te sugiere para ti."] = "Alle Guides nach Gebiet und Stufe, mit dem, den Alfa dir vorschlägt.",
	["Todas las mascotas de compañía: dónde salen, cuánto cuestan y cuáles te faltan."] = "Alle Haustiere: woher sie kommen, was sie kosten und welche dir fehlen.",
	["Todas las mazmorras"] = "Alle Dungeons",
	["Todas las metas, notas y pasos de esta guía en otra ventana."] = "Alle Ziele, Notizen und Schritte dieses Guides in einem anderen Fenster.",
	["Todas las misiones"] = "Alle Quests",
	["Todas las misiones que Lya te guardó, por zona, con su historia completa. También con /alfa historias."] = "Alle Quests, die Lya für dich gespeichert hat, nach Zone, mit ihrer ganzen Geschichte. Auch mit /alfa historias.",
	["Todas las monturas: cómo se consigue cada una, qué pide y si ya la tienes."] = "Alle Reittiere: wie du jedes bekommst, was es verlangt und ob du es schon hast.",
	["Todas las profesiones"] = "Alle Berufe",
	["Todas las zonas"] = "Alle Zonen",
	["Todas las zonas y razas"] = "Alle Gebiete und Völker",
	["Todavía es pronto"] = "Es ist noch zu früh",
	["Todavía nada en esta sesión"] = "Noch nichts in dieser Sitzung",
	["Todavía no"] = "Noch nicht",
	["Todavía no conoces sus hechizos: se llenan al aprenderlos."] = "Du kennst seine Zauber noch nicht: Sie füllen sich, sobald du sie lernst.",
	["Todavía no conozco tus recetas"] = "Ich kenne deine Rezepte noch nicht",
	["Todavía no es para ti"] = "Noch nicht für dich",
	["Todavía no estás en una hermandad. En la página La Jauría ves cómo unirte a la manada."] = "Du bist noch in keiner Gilde. Auf der Seite La Jauría siehst du, wie du dem Rudel beitrittst.",
	["Todavía no has pescado nada en esta sesión"] = "Du hast in dieser Sitzung noch nichts geangelt",
	["Todavía no hay ayuda de rotación para ti"] = "Für dich gibt es noch keine Rotationshilfe",
	["Todavía no hay datos de este personaje"] = "Noch keine Daten von diesem Charakter",
	["Todavía no hay datos para esta gráfica."] = "Noch keine Daten für dieses Diagramm.",
	["Todavía no hay foto de este banco"] = "Noch kein Stand dieser Bank",
	["Todavía no hay peleas"] = "Noch keine Kämpfe",
	["Todavía no hay progreso"] = "Noch kein Fortschritt",
	["Todavía no hay una pelea anterior"] = "Noch kein vorheriger Kampf",
	["Todavía no hay una pelea que anunciar."] = "Noch kein Kampf zum Ansagen.",
	["Todavía no lo pescas"] = "Noch nicht geangelt",
	["Todavía no lo recolectas"] = "Noch nicht gesammelt",
	["Todavía no lo sacas del agua. Cuando lo hagas, aquí verás cuántos llevas, cuándo y dónde."] = "Du hast ihn noch nicht aus dem Wasser gezogen. Sobald du es tust, siehst du hier, wie viele, wann und wo.",
	["Todavía no pescas en %s. Lo que saques aquí se anota por zona."] = "Du hast in %s noch nicht geangelt. Was du hier fängst, wird nach Zone notiert.",
	["Todavía no puedes conseguirlo: %s."] = "Du kannst es noch nicht bekommen: %s.",
	["Todavía no recolectas nada"] = "Noch nichts gesammelt",
	["Todavía no sabes pescar"] = "Du kannst noch nicht angeln",
	["Todavía no se puede tomar: Alfa la recoge cuando se abra."] = "Kann noch nicht angenommen werden: Alfa nimmt sie an, sobald sie sich öffnet.",
	["Todavía no sigues ninguna guía. Elige una y Alfa te lleva paso a paso, con la flecha y la ruta."] = "Du folgst noch keinem Guide. Wähle einen, und Alfa führt dich Schritt für Schritt, mit Pfeil und Route.",
	["Todavía no te alcanza."] = "Das reicht noch nicht.",
	["Todavía no tienes escalas propias. Pega una cadena de escala arriba."] = "Du hast noch keine eigenen Skalen. Füge oben einen Skalen-Text ein.",
	["Todavía no tienes marcadores"] = "Du hast noch keine Markierungen",
	["Todavía no tienes rutas propias"] = "Du hast noch keine eigenen Routen",
	["Todavía no tienes talentos para compartir."] = "Du hast noch keine Talente zum Teilen.",
	["Todavía no tienes una guía abierta. Elige una y Alfa te lleva paso a paso: a dónde ir, qué hacer y con quién hablar."] = "Du hast noch keinen Guide geöffnet. Wähle einen, und Alfa führt dich Schritt für Schritt: wohin du gehst, was du tust und mit wem du sprichst.",
	["Todavía quedan pilones de los titanes en el cráter, y funcionan con cristales de colores."] = "Im Krater stehen noch Pylone der Titanen, und sie laufen mit farbigen Kristallen.",
	["Todo"] = "Alles",
	["Todo Azeroth en un solo lienzo: acerca con la rueda, arrastra para moverte y pon tus marcadores con clic derecho."] = "Ganz Azeroth auf einer Leinwand: Zoom mit dem Rad, zieh, um dich zu bewegen, und setz deine Markierungen mit Rechtsklick.",
	["Todo a la mano"] = "Alles griffbereit",
	["Todo al máximo seguro. Pide una tarjeta de video fuerte."] = "Alles auf dem sicheren Maximum. Braucht eine starke Grafikkarte.",
	["Todo bien (lo más gastado: %d%%)"] = "Alles gut (am meisten abgenutzt: %d%%)",
	["Todo como estaba antes de Alfa"] = "Alles wie vor Alfa",
	["Todo con tu estilo"] = "Alles in deinem Stil",
	["Todo el juego, aunque no lo tengas"] = "Das ganze Spiel, auch was du nicht hast",
	["Todo el juego, aunque no lo tengas: objetos, PNJ, misiones, zonas y raros."] = "Das ganze Spiel, auch was du nicht hast: Gegenstände, NPCs, Quests, Gebiete und Rares.",
	["Todo el juego, aunque no lo tengas: objetos, monturas, mascotas, PNJ, misiones, zonas y raros."] = "Das ganze Spiel, auch was du nicht hast: Gegenstände, Reittiere, Haustiere, NPCs, Quests, Zonen und Rare.",
	["Todo en orden"] = "Alles in Ordnung",
	["Todo esto lo hace Alfa sola al hablar con quien da o recibe una misión. Mantén presionado Mayús para hacerlo tú en el momento."] = "All das macht Alfa von selbst, wenn du mit jemandem sprichst, der eine Quest vergibt oder annimmt. Halte Umschalt gedrückt, um es im Moment selbst zu machen.",
	["Todo junto"] = "Alles zusammen",
	["Todo junto muestra cada casilla en su lugar; por categorías agrupa equipo, consumibles, misiones y materiales; por bolsa pone cada bolsa en su bloque."] = "„Alles zusammen“ zeigt jeden Platz an seiner Stelle; „nach Kategorie“ gruppiert Ausrüstung, Verbrauchsgüter, Questgegenstände und Materialien; „nach Tasche“ setzt jede Tasche in einen eigenen Block.",
	["Todo listo"] = "Alles bereit",
	["Todo lo que no sea equipo"] = "Alles außer Ausrüstung",
	["Todo lo que se pinta en tus mapas, en un solo lugar. Lo de otros módulos de Alfa también llega aquí."] = "Alles, was auf deinen Karten gezeichnet wird, an einem Ort. Was andere Module von Alfa hinzufügen, landet auch hier.",
	["Todo nivel"] = "Jede Stufe",
	["Todo objeto, PNJ, misión, zona y raro, con dónde conseguirlo y «Guíame»."] = "Jeder Gegenstand, NPC, jede Quest, jedes Gebiet und jeder Rare, mit Fundort und „Führ mich“.",
	["Todo oficio"] = "Jede Funktion",
	["Todo para el daño: críticos, sangrados y Abrumar muy seguido. Matas rapidísimo, pero no hay defensa extra: si se te juntan muchos, corre."] = "Alles für den Schaden: Krits, Blutungen und sehr oft Überwältigen. Du tötest blitzschnell, aber ohne zusätzliche Verteidigung: Wenn sich viele auf dich stürzen, lauf.",
	["Todo subtipo"] = "Alle Untertypen",
	["Todo tipo"] = "Alle Typen",
	["Todos"] = "Alle",
	["Todos llegan a %s"] = "Alle führen zu %s",
	["Todos los de ese tipo, o solo uno (por ejemplo, solo cobre). Entre paréntesis, cuántos hay en tu zona."] = "Alle dieser Art oder nur eine (zum Beispiel nur Kupfer). In Klammern, wie viele es in deinem Gebiet gibt.",
	["Todos los materiales"] = "Alle Materialien",
	["Todos los niveles"] = "Alle Stufen",
	["Todos los objetos, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "Alle Gegenstände, NPCs, Quests, Gebiete und Rares, auch die, die du nicht hast: wer es fallen lässt und wie oft, wer es verkauft und wo, welche Quest es gibt und wie du hinkommst.",
	["Todos los objetos, monturas, mascotas, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "Alle Gegenstände, Reittiere, Haustiere, NPCs, Quests, Zonen und Rare, auch was du nicht hast: wer es mit welcher Chance droppt, wer es wo verkauft, welche Quest es gibt und wie du hinkommst.",
	["Todos los paladines sueñan con la Crematoria, la espada de Alexandros Mograine."] = "Jeder Paladin träumt vom Aschenbringer, dem Schwert von Alexandros Mograine.",
	["Todos los pasos"] = "Alle Schritte",
	["Todos los pasos de esta guía; clic en uno para verlo."] = "Alle Schritte dieses Guides; klick auf einen, um ihn anzusehen.",
	["Todos los pasos de la guía en la ventana de guía."] = "Alle Schritte des Guides im Guide-Fenster.",
	["Todos los tipos"] = "Alle Typen",
	["Todos tus puntos ya están gastados y parte de ellos fuera de este build. Para cambiarte a este build, reinicia tus talentos con tu entrenador de clase; después Alfa te los aplica con un clic."] = "Alle deine Punkte sind schon verteilt, und ein Teil davon außerhalb dieses Builds. Um zu diesem Build zu wechseln, setz deine Talente bei deinem Klassenlehrer zurück; danach wendet Alfa sie mit einem Klick an.",
	["Todos: también los avisos leves. Solo los graves: únicamente lo que puede matarte."] = "Alle: auch leichte Warnungen. Nur kritische: nur das, was dich töten kann.",
	["Toma el botín de la pesca enseguida, aunque tengas apagado el botín automático del juego."] = "Plündert den Fang sofort, auch wenn das automatische Plündern des Spiels aus ist.",
	["Toma las de tu ruta que tienes cerca"] = "Nimm die Quests deiner Route in der Nähe an",
	["Toma las mejores de cerca que ya puedes hacer."] = "Nimm die besten Quests in der Nähe an, die du schon machen kannst.",
	["Toma las mejores misiones de por aquí y después ciérralas juntas."] = "Nimm die besten Quests hier an und schließ sie danach gemeinsam ab.",
	["Toma todo el botín de una vez cuando tienes el despojo automático."] = "Nimmt die ganze Beute auf einmal, wenn automatisches Plündern an ist.",
	["Toma unas misiones cerca y Alfa las cierra contigo por el camino más corto."] = "Nimm ein paar Quests in der Nähe an, und Alfa schließt sie mit dir auf dem kürzesten Weg ab.",
	["Tomar %s"] = "%s annehmen",
	["Tomar el vuelo de tu ruta"] = "Den Flug deiner Route nehmen",
	["Tomar la mejor recompensa"] = "Die beste Belohnung nehmen",
	["Tomarla"] = "Annehmen",
	["Tomarla, completarla o entregarla."] = "Annehmen, abschließen oder abgeben.",
	["Tomaste otra misión de su grupo: esta ya no se abre."] = "Du hast eine andere Quest ihrer Gruppe angenommen: Diese öffnet sich nicht mehr.",
	["Top %d de %s"] = "Top %d %s",
	["Top de daño"] = "Schadens-Top",
	["Tope por personaje"] = "Obergrenze pro Charakter",
	["Tortura mental: daño constante y frena al enemigo."] = "Gedankenschinden: stetiger Schaden, und es verlangsamt den Gegner.",
	["Total"] = "Gesamt",
	["Tramo %d de %d: %s."] = "Etappe %d von %d: %s.",
	["Trampas, golpes cuerpo a cuerpo de emergencia y mucha agilidad: el cazador más difícil de atrapar."] = "Fallen, Nahkampfschläge für den Notfall und viel Beweglichkeit: der Jäger, der am schwersten zu fassen ist.",
	["Tranquilo"] = "Ruhig",
	["Transformar"] = "Umwandeln",
	["Transformar %d"] = "%d verarbeiten",
	["Transmutar hierro en oro existe de verdad: el sueño de todo alquimista."] = "Eisen in Gold zu transmutieren gibt es wirklich: der Traum jedes Alchemisten.",
	["Tras aceptar o entregar, cierra la ventana del PNJ si solo ofrece misiones que tu guía no hace."] = "Schließt nach dem Annehmen oder Abgeben das NPC-Fenster, wenn es nur Quests anbietet, die dein Guide nicht macht.",
	["Tras la Guerra de los Tres Martillos, los Martillo Salvaje se fueron a Grim Batol y luego al Interior; los Hierro Negro, a la Montaña Roca Negra."] = "Nach dem Krieg der drei Hämmer zogen die Wildhammer nach Grim Batol und später ins Hinterland; die Dunkeleisenzwerge in den Schwarzfels.",
	["Tras la Segunda Guerra, mantener a los orcos en los campos de internamiento costaba una fortuna. Esos impuestos ayudaron a romper la Alianza."] = "Nach dem Zweiten Krieg kostete es ein Vermögen, die Orcs in den Internierungslagern zu halten. Diese Steuern halfen, die Allianz zu zerbrechen.",
	["Tras las Guerras Trol, el viejo Arathor se repartió en siete reinos: Lordaeron, Ventormenta, Gilneas, Alterac, Stromgarde, Kul Tiras y Dalaran."] = "Nach den Trollkriegen zerfiel das alte Arathor in sieben Königreiche: Lordaeron, Sturmwind, Gilneas, Alterac, Stromgarde, Kul Tiras und Dalaran.",
	["Tratado"] = "Buchband",
	["Tres caminos para cada objeto"] = "Drei Wege für jeden Gegenstand",
	["Tres estilos y el lobo"] = "Drei Stile und der Wolf",
	["Tres pasos y listo"] = "Drei Schritte, fertig",
