	["Trilineal"] = "Trilinear",
	["Trinquete es un puerto goblin neutral: ahí se tolera a cualquiera que traiga oro, y su barco lleva hasta Bahía del Botín."] = "Ratschet ist ein neutraler Goblinhafen: Dort ist jeder willkommen, der Gold mitbringt, und sein Schiff fährt nach Beutebucht.",
