	["Tu equipo está al %d%%. Mejor repararlo antes de la siguiente pelea."] = "Deine Ausrüstung ist bei %d%%. Besser vor dem nächsten Kampf reparieren.",
	["Tu equipo se está gastando"] = "Deine Ausrüstung verschleißt",
	["Tu equipo, tus bolsas y tu entrenamiento están al día."] = "Ausrüstung, Taschen und Training sind auf dem neuesten Stand.",
	["Tu escudo protege mucho, pero deja al aliado con el alma debilitada un rato: no puedes ponérselo otra vez enseguida."] = "Dein Schild schützt viel, hinterlässt beim Verbündeten aber eine Weile eine Geschwächte Seele: Du kannst ihm nicht sofort einen neuen geben.",
	["Tu especialización"] = "Deine Spezialisierung",
	["Tu estilo"] = "Dein Stil",
	["Tu estilo (Alfa, Clásico WoW o Cristal), el color de acento y el aullido."] = "Dein Stil (Alfa, Klassisches WoW oder Glas), die Akzentfarbe und das Heulen.",
	["Tu estilo: %s"] = "Dein Stil: %s",
	["Tu facción (%s)"] = "Deine Fraktion (%s)",
	["Tu forma de viaje es un felino veloz... pero en una carrera yo no te la pondría fácil."] = "Deine Reisegestalt ist eine flinke Katze... aber bei einem Wettrennen würde ich es dir nicht leicht machen.",
	["Tu gente no confía en la magia arcana: recuerda bien lo que pasó con Azshara y el Pozo de la Eternidad."] = "Dein Volk traut der arkanen Magie nicht: Es erinnert sich gut daran, was mit Azshara und dem Brunnen der Ewigkeit geschah.",
	["Tu gente, los humanos, desciende de las tribus que el rey Thoradin unió en Arathor hace miles de años."] = "Dein Volk, die Menschen, stammt von den Stämmen ab, die König Thoradin vor Tausenden von Jahren in Arathor einte.",
	["Tu golpe más fuerte desde el nivel 40 hasta el 60."] = "Dein stärkster Schlag von Stufe 40 bis 60.",
	["Tu golpe más fuerte desde el nivel 40."] = "Dein stärkster Schlag ab Stufe 40.",
	["Tu golpe más fuerte, crece con tu bloqueo."] = "Dein stärkster Schlag, wächst mit deinem Blockwert.",
	["Tu golpe más fuerte, y además reduce las curas del enemigo."] = "Dein stärkster Schlag, der außerdem die Heilung des Gegners senkt.",
	["Tu golpe más fuerte."] = "Dein stärkster Schlag.",
	["Tu golpe principal contra jefes."] = "Dein Hauptschlag gegen Bosse.",
	["Tu golpe principal."] = "Dein Hauptschlag.",
	["Tu grupo"] = "Deine Gruppe",
	["Tu grupo en el mapa"] = "Deine Gruppe auf der Karte",
	["Tu grupo o banda en el mapa y el minimapa, con el color de su clase."] = "Deine Gruppe oder dein Schlachtzug auf Karte und Minikarte, in ihrer Klassenfarbe.",
	["Tu grupo y tu banda con su vida, para curar con un clic. Se cambia fuera de combate."] = "Deine Gruppe und dein Schlachtzug mit ihrer Gesundheit, um mit einem Klick zu heilen. Änderung außerhalb des Kampfes.",
	["Tu grupo, tu hermandad y tus amigos en el mapa, con Seguir y la página del clan."] = "Deine Gruppe, deine Gilde und deine Freunde auf der Karte, mit Folgen und der Clanseite.",
	["Tu guía"] = "Dein Guide",
	["Tu guía deja fuera las misiones que ya no dan experiencia, salvo que otra las necesite."] = "Dein Guide lässt Quests weg, die keine Erfahrung mehr geben, außer eine andere braucht sie.",
	["Tu guía está lista. Ábrela para ver tu paso."] = "Dein Guide ist bereit. Öffne ihn, um deinen Schritt zu sehen.",
	["Tu guía puede elegir y avanzar sola, o preguntarte en cada cruce."] = "Dein Guide kann selbst wählen und weitermachen oder dich an jeder Abzweigung fragen.",
	["Tu guía te lleva a entrenar en %d pasos."] = "Dein Guide führt dich in %d Schritten zum Trainieren.",
	["Tu guía te lleva a entrenar en este paso."] = "Dein Guide führt dich in diesem Schritt zum Trainieren.",
	["Tu guía te lleva a tomarla."] = "Dein Guide führt dich hin, um sie anzunehmen.",
	["Tu guía terminó y el camino se abre"] = "Dein Guide ist zu Ende, und der Weg teilt sich",
	["Tu guía ya no te manda a entregar misiones sin terminar: primero te lleva a lo que falta, y «Cerrar mis misiones» se pone al día sola."] = "Dein Guide schickt dich nicht mehr los, um unfertige Quests abzugeben: Er führt dich zuerst zu dem, was fehlt, und „Meine Quests abschließen“ hält sich von selbst aktuell.",
	["Tu hechizo principal de fuego."] = "Dein wichtigster Feuerzauber.",
	["Tu hechizo principal."] = "Dein wichtigster Zauber.",
	["Tu hechizo principal: daño y frena al enemigo."] = "Dein wichtigster Zauber: Schaden, und er verlangsamt den Gegner.",
	["Tu hermandad conectada"] = "Deine Gilde online",
	["Tu hermandad y tu grupo reciben los horarios que tomas, y tú los suyos."] = "Deine Gilde und deine Gruppe bekommen die Zeiten, die du nimmst, und du ihre.",
	["Tu historial"] = "Dein Verlauf",
	["Tu insignia de La Jauría en el borde de tu retrato, y en el de tu objetivo si la lleva."] = "Dein Abzeichen von La Jauría am Rand deines Porträts – und an dem deines Ziels, wenn es eines trägt.",
	["Tu insignia en los retratos"] = "Dein Abzeichen an den Porträts",
	["Tu instalación está mezclada o incompleta (%s). Cierra el juego, borra todas las carpetas de Alfa en Interface/AddOns e instala Alfa de nuevo con la app de CurseForge o el zip más reciente (no \"Source code\")."] = "Deine Installation ist gemischt oder unvollständig (%s). Schließe das Spiel, lösche jeden Alfa-Ordner in Interface/AddOns und installiere Alfa neu mit der CurseForge-App oder dem neuesten Zip (nicht „Source code“).",
	["Tu ira se llena al pegar y al recibir golpes: entra a la pelea con Cargar para empezar con ira."] = "Deine Wut füllt sich, wenn du triffst und getroffen wirst: Eröffne den Kampf mit Sturmangriff, um mit Wut zu beginnen.",
	["Tu libro no tiene hechizos para aliados"] = "Dein Zauberbuch hat keine Zauber für Verbündete",
	["Tu lista de sonidos"] = "Deine Soundliste",
	["Tu lista de sonidos está vacía. Agrega uno con /alfa silenciar <número>."] = "Deine Soundliste ist leer. Füge einen mit /alfa silenciar <Nummer> hinzu.",
	["Tu lista de sonidos quedó vacía."] = "Deine Soundliste ist jetzt leer.",
	["Tu lista: síguelos con la flecha, compártelos con el grupo, cámbialos o bórralos."] = "Deine Liste: Folge ihnen mit dem Pfeil, teile sie mit der Gruppe, ändere oder lösche sie.",
	["Tu loba compañera: consejos cortos, ánimo y nunca te deja atrás."] = "Deine Wolfsgefährtin: kurze Tipps, Ermutigung, und sie lässt dich nie zurück.",
	["Tu loba compañera: te da consejos y ánimo. También con /alfa lya."] = "Deine Wolfsgefährtin: Sie gibt dir Tipps und Mut. Auch mit /alfa lya.",
	["Tu lugar resalta más: tu flecha lleva un aro y un pulso suave, y se ve bien hasta en la nieve."] = "Dein Standort fällt mehr auf: Dein Pfeil hat einen Ring und ein sanftes Pulsieren und ist sogar im Schnee gut zu sehen.",
	["Tu manada"] = "Dein Rudel",
	["Tu manada en el mapa: tu grupo y quienes usan Alfa y comparten. Síguelos con la flecha, invítalos y conoce al clan."] = "Dein Rudel auf der Karte: deine Gruppe und alle, die Alfa nutzen und teilen. Folge ihnen mit dem Pfeil, lade sie ein und lerne den Clan kennen.",
	["Tu manada está fuera del mapa"] = "Dein Rudel ist außerhalb der Karte",
	["Tu mapa"] = "Deine Karte",
	["Tu mapa del ratón está vacío: elige algo en una ranura primero."] = "Deine Mausbelegung ist leer: Wähle zuerst etwas für einen Platz.",
	["Tu marcador"] = "Deine Markierung",
	["Tu mascota"] = "Dein Tier",
	["Tu mascota aprende habilidades de otras bestias: doma una que sepa lo que quieres y te lo enseña."] = "Dein Begleiter lernt Fähigkeiten von anderen Wildtieren: Zähme eines, das kann, was du willst, und es bringt es dir bei.",
	["Tu mascota hace gran parte del trabajo y aguanta los golpes: la forma más fácil y segura de subir con cazador."] = "Dein Tier erledigt einen Großteil der Arbeit und steckt die Schläge ein: der einfachste und sicherste Weg, einen Jäger zu leveln.",
	["Tu mascota tiene poca vida: cúrala."] = "Dein Begleiter hat wenig Gesundheit: Heil ihn.",
	["Tu montura de clase"] = "Dein Klassenreittier",
	["Tu montura rápida (nivel 60)"] = "Dein schnelles Reittier (Stufe 60)",
	["Tu munición"] = "Deine Munition",
	["Tu nivel"] = "Deine Stufe",
	["Tu nivel, reparar, comida y bebida, y la entrada de la mazmorra para ti."] = "Deine Stufe, Reparatur, Essen und Trinken und der Dungeoneingang für dich.",
	["Tu nota"] = "Deine Notiz",
	["Tu objetivo esquivó: Abrumar no se puede esquivar y pega fuerte. Necesita actitud de batalla."] = "Dein Ziel ist ausgewichen: Überwältigen kann nicht ausgewichen werden und trifft hart. Braucht Kampfhaltung.",
	["Tu oro"] = "Dein Gold",
	["Tu pantalla y tu compañera"] = "Dein Bildschirm und deine Begleiterin",
	["Tu paso de ahora es el %d."] = "Dein aktueller Schritt ist Nr. %d.",
	["Tu paso de ahora es el %d: %s."] = "Dein aktueller Schritt ist Nr. %d: %s.",
	["Tu personaje"] = "Dein Charakter",
	["Tu personaje aparece en el mapa de quienes también se dejan ver. Solo su lugar en el juego y nunca dentro de mazmorras; va por un canal oculto que alguien con otro addon podría leer."] = "Dein Charakter erscheint auf der Karte derer, die sich ebenfalls zeigen. Nur sein Ort im Spiel und nie in Dungeons; es läuft über einen versteckten Kanal, den jemand mit einem anderen Addon lesen könnte.",
	["Tu personaje deja de decir \"No tengo suficiente maná\", \"Eso todavía no está listo\" y parecidas. El texto rojo sigue."] = "Dein Charakter sagt nicht mehr „Nicht genug Mana“, „Das ist noch nicht bereit“ und Ähnliches. Der rote Text bleibt.",
	["Tu personaje no aparece en el mapa de nadie de La Jauría. Lo cambias cuando quieras en la página de La Jauría."] = "Dein Charakter erscheint auf niemandes Karte bei La Jauría. Ändern kannst du es jederzeit auf der Seite La Jauría.",
	["Tu personaje todavía no recolecta. Con Minería o Herboristería, Alfa une las minas o las hierbas de tu zona en una vuelta corta. Te las enseña un instructor de profesión."] = "Dein Charakter sammelt noch nichts. Mit Bergbau oder Kräuterkunde verbindet Alfa die Erzvorkommen oder Kräuter deines Gebiets zu einer kurzen Runde. Beibringen kann sie dir ein Berufslehrer.",
	["Tu pesca"] = "Dein Angeln",
	["Tu pesca está al máximo"] = "Deine Angelfertigkeit ist auf dem Maximum",
	["Tu piedra de hogar te regresa a tu posada. Úsala para ahorrar caminata."] = "Dein Ruhestein bringt dich zurück zu deinem Gasthaus. Nutz ihn, um Laufwege zu sparen.",
	["Tu piedra de hogar y el descanso"] = "Dein Ruhestein und Erholung",
	["Tu pieza más gastada: %s al %d %%."] = "Dein am meisten abgenutztes Teil: %s bei %d %%.",
	["Tu plan"] = "Dein Plan",
	["Tu plan está en Talentos."] = "Dein Plan ist unter Talente.",
	["Tu plan no pudo agregarlo."] = "Dein Plan konnte es nicht hinzufügen.",
	["Tu plan no tiene metas"] = "Dein Plan hat keine Ziele",
	["Tu plan no tiene metas todavía"] = "Dein Plan hat noch keine Ziele",
	["Tu plan se quedó sin paso"] = "Dein Plan hat keinen Schritt mehr",
	["Tu plan se quedó sin paso. Seguir lo vuelve a armar con las misiones que tienes ahora."] = "Dein Plan hat keinen Schritt mehr. Folgen erstellt ihn mit deinen aktuellen Quests neu.",
	["Tu posición en la parte de abajo del minimapa."] = "Deine Position unten auf der Minikarte.",
	["Tu posición y la del cursor bajo el mapa."] = "Deine Position und die des Cursors unter der Karte.",
	["Tu primer punto, en el nivel 10."] = "Dein erster Punkt kommt auf Stufe 10.",
	["Tu primer talento"] = "Dein erstes Talent",
	["Tu primera guía"] = "Dein erster Guide",
	["Tu primera montura (nivel 40)"] = "Dein erstes Reittier (Stufe 40)",
	["Tu primera sesión entra al diario cuando salgas del juego. La manada te espera: ¡a cazar!"] = "Deine erste Sitzung kommt ins Tagebuch, wenn du das Spiel verlässt. Das Rudel wartet: auf zur Jagd!",
	["Tu prioridad"] = "Deine Priorität",
	["Tu prioridad: %s"] = "Deine Priorität: %s",
	["Tu progreso"] = "Dein Fortschritt",
	["Tu propia lista de metas, en el orden que quieras: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota. Alfa las mide solas y te lleva a cada una."] = "Deine eigene Zielliste, in der Reihenfolge, die du willst: ein Gegenstand, Gold, ein Beruf, ein Ort, eine Quest, eine Stufe oder eine Notiz. Alfa misst sie selbst und führt dich zu jedem.",
	["Tu propio marco aparece aunque no estés en grupo, para curarte con un clic."] = "Dein eigener Rahmen erscheint auch, wenn du nicht in einer Gruppe bist, damit du dich mit einem Klick heilen kannst.",
	["Tu prueba"] = "Dein Test",
	["Tu rama: %s"] = "Dein Talentbaum: %s",
	["Tu rastro"] = "Deine Spur",
	["Tu ratón"] = "Deine Maus",
	["Tu registro está lleno: cierra algunas misiones primero."] = "Dein Questlog ist voll: Schließ zuerst ein paar Quests ab.",
	["Tu registro está vacío"] = "Dein Questlog ist leer",
	["Tu reporte, listo para pegar"] = "Dein Bericht, bereit zum Einfügen",
	["Tu ritmo de los últimos 15 minutos"] = "Dein Tempo der letzten 15 Minuten",
	["Tu ritmo de los últimos 15 minutos, con el contador de XP de Alfa."] = "Dein Tempo der letzten 15 Minuten, aus Alfas EP-Tracker.",
	["Tu ruta de %d tramos."] = "Deine Route mit %d Etappen.",
	["Tu ruta de %s en %s está lista"] = "Deine Route für %s in %s ist bereit",
	["Tu ruta dibujada en el mapa de Alfa hasta tu destino, que late para que lo encuentres; arriba ves a qué distancia está y cuánto falta, y un clic te muestra todo el camino."] = "Deine Route auf Alfas Karte bis zu deinem Ziel, das pulsiert, damit du es findest; oben siehst du, wie weit es ist und wie lange es noch dauert, und ein Klick zeigt dir den ganzen Weg.",
	["Tu ruta está vacía"] = "Deine Route ist leer",
	["Tu ruta no pudo agregarlo."] = "Deine Route konnte es nicht hinzufügen.",
	["Tu ruta no tiene tramos todavía"] = "Deine Route hat noch keine Etappen",
	["Tu ruta pasa por ahí."] = "Deine Route führt dort vorbei.",
	["Tu ruta personalizada, armada por Alfa con tus tramos."] = "Deine eigene Route, von Alfa aus deinen Etappen gebaut.",
	["Tu ruta se actualizó"] = "Deine Route wurde aktualisiert",
	["Tu ruta, paso a paso"] = "Deine Route, Schritt für Schritt",
	["Tu ruta, tus misiones y tus guías (/alfa rutas ayuda)."] = "Deine Route, deine Quests und deine Guides (/alfa rutas ayuda).",
	["Tu sesión anterior (%s): %s"] = "Deine letzte Sitzung (%s): %s",
	["Tu sesión anterior, %s"] = "Deine letzte Sitzung, %s",
	["Tu sesión de ahora"] = "Deine aktuelle Sitzung",
	["Tu sesión de pesca ya estaba vacía: la nueva empieza con tu primer lanzamiento."] = "Deine Angelsitzung war schon leer: Die neue beginnt mit deinem ersten Auswurf.",
	["Tu sesión, tu diario, recordatorios y tu siguiente paso, con el color de tu clase."] = "Deine Sitzung, dein Tagebuch, Erinnerungen und dein nächster Schritt, in deiner Klassenfarbe.",
	["Tu siguiente mazmorra"] = "Dein nächster Dungeon",
	["Tu siguiente paso"] = "Dein nächster Schritt",
	["Tu siguiente paso, lo urgente y lo de tu clase, de un vistazo."] = "Dein nächster Schritt, das Dringende und deine Klasse auf einen Blick.",
	["Tu siguiente talento"] = "Dein nächstes Talent",
	["Tu tecla del mapa (%s) lo abre."] = "Deine Kartentaste (%s) öffnet sie.",
	["Tu tecla primero te pone la mejor caña y lo que tengas con bonificación de pesca (sombrero, guantes, botas, abalorios)."] = "Deine Taste legt dir zuerst die beste Angel und alles mit Angelbonus an (Hut, Handschuhe, Stiefel, Schmuckstücke).",
	["Tu tecla y tus ajustes del juego quedan como siempre. Enciéndela para pescar con una sola tecla."] = "Deine Taste und deine Spieleinstellungen bleiben wie immer. Schalte es ein, um mit einer einzigen Taste zu angeln.",
	["Tu ventana de Alfa"] = "Dein Alfa-Fenster",
	["Tu vida baja: Rejuvenecimiento te cura poco a poco."] = "Deine Gesundheit sinkt: Verjüngung heilt dich nach und nach.",
	["Tu vida baja: Renovar te cura poco a poco."] = "Deine Gesundheit sinkt: Erneuerung heilt dich nach und nach.",
	["Tu vida baja: el escudo absorbe el daño."] = "Deine Gesundheit sinkt: Der Schild absorbiert den Schaden.",
	["Tu vida está a punto de acabarse: Imposición de manos te cura entero."] = "Deine Gesundheit ist fast aufgebraucht: Handauflegung heilt dich vollständig.",
	["Tu vida está baja: cúrate rápido."] = "Deine Gesundheit ist niedrig: Heil dich schnell.",
	["Tu vida está baja: cúrate."] = "Deine Gesundheit ist niedrig: Heil dich.",
	["Tu vida está baja: róbasela al enemigo."] = "Deine Gesundheit ist niedrig: Stiehl sie dem Gegner.",
	["Tu vida está muy baja: cúrate rápido."] = "Deine Gesundheit ist sehr niedrig: Heil dich schnell.",
	["Tu vuelo en el mapa"] = "Dein Flug auf der Karte",
	["Tu árbol"] = "Dein Baum",
	["Tu última sesión: %s · %s"] = "Deine letzte Sitzung: %s · %s",
	["Tu último escaneo fue %s. Escanea otra vez en la casa de subastas para tener precios al día."] = "Dein letzter Scan war %s. Scanne erneut im Auktionshaus, damit die Preise aktuell sind.",
	["Turalyon y Alleria Brisaveloz cruzaron el Portal Oscuro tras la guerra para cerrarles el paso a los orcos, y no regresaron."] = "Turalyon und Alleria Windläufer gingen nach dem Krieg durch das Dunkle Portal, um den Orcs den Weg abzuschneiden, und kehrten nie zurück.",
	["Tus %d puntos están donde tu build los pide. Lo que sigue es el equipo: piezas con las estadísticas que le sirven a tu build."] = "Deine %d Punkte sind dort, wo dein Build sie will. Als Nächstes kommt die Ausrüstung: Teile mit den Werten, die dein Build braucht.",
	["Tus actitudes son de batalla, defensiva y rabiosa; elige la que pida el momento."] = "Deine Haltungen sind Kampf-, Verteidigungs- und Berserkerhaltung; wähl die, die der Moment verlangt.",
	["Tus ajustes pasan una prueba de guardar y recargar en cada versión, para que nunca se pierdan."] = "Deine Einstellungen durchlaufen in jeder Version einen Test zum Speichern und Neuladen, damit sie nie verloren gehen.",
	["Tus avisos"] = "Deine Hinweise",
	["Tus bolsas"] = "Deine Taschen",
	["Tus bolsas están casi llenas"] = "Deine Taschen sind fast voll",
	["Tus bolsas están llenas"] = "Deine Taschen sind voll",
	["Tus bolsas están vacías"] = "Deine Taschen sind leer",
	["Tus bolsas piden auxilio (%d libres). Vende o tira lo que ya no uses."] = "Deine Taschen rufen um Hilfe (%d frei). Verkauf oder wirf weg, was du nicht mehr brauchst.",
	["Tus bolsas se están llenando"] = "Deine Taschen werden voll",
	["Tus bolsas se están llenando: queda 1 casilla."] = "Deine Taschen werden voll: noch 1 Platz.",
	["Tus bolsas se están llenando: quedan %d casillas."] = "Deine Taschen werden voll: noch %d Plätze.",
	["Tus bolsas y tu banco en una sola ventana, y lo que lleva cada uno de tus personajes."] = "Deine Taschen und deine Bank in einem Fenster, und was jeder deiner Charaktere bei sich hat.",
	["Tus builds importados"] = "Deine importierten Builds",
	["Tus clics"] = "Deine Klicks",
	["Tus clics de Curación se aplican al salir de combate."] = "Deine Heilungsklicks gelten, sobald du den Kampf verlässt.",
	["Tus clics vuelven a los del preajuste. Lo que cambiaste a mano se pierde."] = "Deine Klicks kehren zu denen der Voreinstellung zurück. Was du von Hand geändert hast, geht verloren.",
	["Tus comodidades están listas"] = "Deine Komfortfunktionen sind bereit",
	["Tus compañeros de grupo y de banda en el mapa de Alfa."] = "Deine Gruppen- und Schlachtzugsmitglieder auf Alfas Karte.",
	["Tus críticos de habilidades pegan todavía más."] = "Deine Fähigkeitskrits treffen noch härter.",
	["Tus críticos hacen muchísimo daño."] = "Deine Krits machen enorm viel Schaden.",
	["Tus críticos hacen sangrar: matas más rápido y sufres menos."] = "Deine Krits lassen bluten: Du tötest schneller und leidest weniger.",
	["Tus críticos sangran."] = "Deine Krits verursachen Blutungen.",
	["Tus críticos sangran: más daño y amenaza."] = "Deine Krits verursachen Blutungen: mehr Schaden und Bedrohung.",
	["Tus curas curan más."] = "Deine Heilungen heilen mehr.",
	["Tus datos"] = "Deine Daten",
	["Tus demonios llegan con misiones: diablillo, abisario, súcubo y manáfago; y más adelante, el infernal y el guardia apocalíptico."] = "Deine Dämonen bekommst du durch Quests: Wichtel, Leerwandler, Sukkubus und Teufelsjäger; und später die Höllenbestie und die Verdammniswache.",
	["Tus estadísticas"] = "Deine Werte",
	["Tus flechas de mejora no usan tu build"] = "Deine Upgrade-Pfeile nutzen deinen Build nicht",
	["Tus flechas de mejora usan tu build"] = "Deine Upgrade-Pfeile nutzen deinen Build",
	["Tus golpes alcanzan a un segundo enemigo: perfecto cuando se te juntan dos."] = "Deine Schläge treffen einen zweiten Gegner: perfekt, wenn sich zwei auf dich stürzen.",
	["Tus gritos llegan más lejos y duran más: ayudas a todo el grupo."] = "Deine Rufe reichen weiter und halten länger: Du hilfst der ganzen Gruppe.",
	["Tus habilidades cuestan menos ira."] = "Deine Fähigkeiten kosten weniger Wut.",
	["Tus habilidades de ira te curan: menos descanso."] = "Deine Wut-Fähigkeiten heilen dich: weniger Rast.",
	["Tus habilidades nuevas"] = "Deine neuen Fähigkeiten",
	["Tus hechizos de daño pegan más."] = "Deine Schadenszauber treffen härter.",
	["Tus hechizos de escarcha frenan: el monstruo casi nunca llega a pegarte."] = "Deine Frostzauber verlangsamen: Das Monster kommt fast nie dazu, dich zu treffen.",
	["Tus hechizos fallan menos."] = "Deine Zauber verfehlen seltener.",
	["Tus hechizos hacen crítico más seguido."] = "Deine Zauber treffen öfter kritisch.",
	["Tus herramientas de combate"] = "Deine Kampfwerkzeuge",
	["Tus historias"] = "Deine Geschichten",
	["Tus llaves junto a tus bolsas."] = "Deine Schlüssel neben deinen Taschen.",
	["Tus marcadores"] = "Deine Markierungen",
	["Tus marcadores en el mapa de Alfa y en el del juego."] = "Deine Markierungen auf Alfas Karte und auf der des Spiels.",
	["Tus marcadores también en el minimapa, cuando estás cerca."] = "Deine Markierungen auch auf der Minikarte, wenn du in der Nähe bist.",
	["Tus marcos de combate volvieron a su lugar de siempre."] = "Deine Kampffenster sind wieder an ihrem gewohnten Platz.",
	["Tus marcos de combate vuelven a su lugar de siempre."] = "Deine Kampfrahmen kehren an ihren üblichen Platz zurück.",
	["Tus marcos de curación están apagados"] = "Deine Heilungsrahmen sind aus",
	["Tus marcos están listos"] = "Deine Rahmen sind bereit",
	["Tus metas en tu orden: un objeto, oro, una profesión, un lugar..."] = "Deine Ziele in deiner Reihenfolge: ein Gegenstand, Gold, ein Beruf, ein Ort...",
	["Tus misiones"] = "Deine Quests",
	["Tus misiones abiertas, para terminarlas y entregarlas por el camino más corto."] = "Deine offenen Quests, um sie abzuschließen und auf dem kürzesten Weg abzugeben.",
	["Tus números"] = "Deine Zahlen",
	["Tus personajes"] = "Deine Charaktere",
	["Tus precios de la subasta son viejos: escanéala otra vez."] = "Deine Auktionspreise sind alt: Scanne das Auktionshaus erneut.",
	["Tus profesiones"] = "Deine Berufe",
	["Tus próximos golpes también alcanzan a otro enemigo."] = "Deine nächsten Schläge treffen auch einen weiteren Gegner.",
	["Tus puntos"] = "Deine Punkte",
	["Tus puntos van por otro camino"] = "Deine Punkte gingen einen anderen Weg",
	["Tus recetas de pescado, la cola de cocina y la fogata."] = "Deine Fischrezepte, die Kochwarteschlange und das Lagerfeuer.",
	["Tus recetas que dejan ganancia"] = "Deine Rezepte mit Gewinn",
	["Tus talentos"] = "Deine Talente",
	["Tus tótems de tierra, fuego, agua y aire se ganan con misiones a lo largo de tu camino."] = "Deine Erd-, Feuer-, Wasser- und Lufttotems verdienst du dir mit Quests auf deinem Weg.",
	["Tyrande liberó a Illidan para pelear contra la Plaga, y Maiev, su carcelera, nunca se lo perdonó."] = "Tyrande befreite Illidan, um gegen die Geißel zu kämpfen, und Maiev, seine Kerkermeisterin, hat ihr das nie verziehen.",
	["Tótem"] = "Totem",
	["Tótems"] = "Totems",
	["Tótems enemigos"] = "Gegnerische Totems",
	["Tú"] = "Du",
	["Tú recibes los golpes y proteges al grupo. Necesitas escudo."] = "Du steckst die Schläge ein und schützt die Gruppe. Du brauchst einen Schild.",
	["Ubicación de %s"] = "Standort von %s",
	["Ultra"] = "Ultra",
	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "Eine Waffe in jeder Hand und viel Wut: der mit dem meisten Schaden in der Gruppe.",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "Eine große Zweihandwaffe und Schläge, die bluten lassen. Der einfachste Weg zum Leveln.",
	["Un aturdimiento cuando lo necesites."] = "Eine Betäubung, wann immer du sie brauchst.",
	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "Ein Wolfsgeheul aus dem Spiel selbst, wenn du Alfa in jeder Sitzung zum ersten Mal öffnest.",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "Ein Hinweis mit seinen Bossen und wie viele du besiegt hast, einen Klick von ihren Tipps entfernt.",
	["Un aviso corto con el lugar, su zona y el tiempo de camino."] = "Ein kurzer Hinweis mit dem Ort, seiner Zone und der Reisezeit.",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "Ein kurzer Hinweis, wenn eine Fähigkeit aufleuchtet, die davon abhängt, was gerade passiert ist, wie Überwältigen, nachdem der Gegner ausgewichen ist.",
	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "Ein Hinweis, wenn du einen neuen Boss besiegst, einen Klick von seiner Beute entfernt.",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "Ein Hinweis und ein Streifen in deinen Taschen: was du verkaufen und was du behalten solltest und zu welchem Händler du gehst, mit einem Klick, um den Plunder zu markieren.",
	["Un barrido oscuro y suave sobre los íconos mientras su recarga corre."] = "Eine sanfte dunkle Animation über den Symbolen, solange ihre Abklingzeit läuft.",
	["Un borde del color de la calidad: verde, azul, morado..."] = "Ein Rahmen in der Farbe der Qualität: grün, blau, lila...",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "Ein pulsierender grüner Rand auf dem Knopf deiner Leiste mit der vorgeschlagenen Fähigkeit, damit du sie schnell findest.",
	["Un brujo con dos compañeros puede invocar al resto del grupo a la entrada de una mazmorra."] = "Ein Hexenmeister mit zwei Helfern kann den Rest der Gruppe zum Eingang eines Dungeons beschwören.",
	["Un buzón"] = "Ein Briefkasten",
	["Un clic bajito cuando Lya te dice algo."] = "Ein leises Klicken, wenn Lya dir etwas sagt.",
	["Un clic y queda solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Ein Klick, und nur das Wesentliche bleibt: du, deine Gruppe, deine Markierungen und der nächste Schritt des Guides.",
	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "Ein kleines, verschiebbares Feld mit deiner Gesundheit und den Werten, die für deine Klasse am meisten zählen. Im Kampf verbirgt das Spiel manche Zahlen: Der letzte lesbare Wert bleibt stehen.",
	["Un enemigo"] = "Ein Gegner",
	["Un error, una mejora o un comentario, directo al desarrollador"] = "Ein Fehler, eine Idee oder ein Kommentar, direkt an den Entwickler",
	["Un fondo del color de tu clase bajo tu nombre."] = "Ein Hintergrund in deiner Klassenfarbe unter deinem Namen.",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "Ein gewaltiger Schildschlag mit enorm viel Bedrohung.",
	["Un golpe más para gastar ira."] = "Ein weiterer Schlag, um Wut auszugeben.",
	["Un golpe nuevo y fuerte para tu barra."] = "Ein neuer, starker Schlag für deine Leiste.",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "Ein großer Schadensschub für schwere Monster; außerdem befreit er dich von Furcht.",
	["Un grano fino de cine sobre el mundo."] = "Eine feine Filmkörnung über der Welt.",
	["Un grano fino, como de cine. Casi no cuesta: se mueve unas 14 veces por segundo y solo mientras se ve."] = "Eine feine Körnung wie im Kino. Kostet fast nichts: Sie bewegt sich etwa 14-mal pro Sekunde und nur, solange sie zu sehen ist.",
	["Un hechizo de tus barras tiene un rango viejo"] = "Ein Zauber in deinen Leisten hat einen alten Rang",
	["Un mapa de una pieza: al acercar ya no se ven pedazos pegados, y el terreno se une sin rayas ni cuadros."] = "Eine Karte aus einem Guss: Beim Heranzoomen sieht man keine zusammengeklebten Stücke mehr, und das Gelände fügt sich ohne Linien oder Kästchen zusammen.",
	["Un mapa impecable"] = "Eine makellose Karte",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "Ein goldener Rahmen um Gegenstände für eine Quest (mit „!“, wenn einer eine startet).",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "Ein Gegenstand, den du willst: Alfa erstellt den Weg dorthin, mit allem, was vorher nötig ist.",
	["Un paisaje más bonito"] = "Eine schönere Landschaft",
	["Un pescadito asado no me caería nada mal."] = "Ein gegrilltes Fischlein wäre jetzt nicht schlecht.",
	["Un pescadito asado para la loba que te acompaña no estaría nada mal, ¿eh?"] = "Ein gebratenes Fischchen für die Wölfin, die dich begleitet, wäre gar nicht schlecht, oder?",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "Ein kleiner nummerierter Pin, wo dich die nächsten Schritte hinführen.",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "Ein wenig kritische Treffer, Ausweichen und Rüstung.",
	["Un poco de vida de vuelta después de críticos."] = "Ein wenig Gesundheit zurück nach Krits.",
	["Un poco más de defensa."] = "Etwas mehr Verteidigung.",
	["Un poco más de ira al cargar."] = "Etwas mehr Wut beim Sturmangriff.",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "Ein Punkt, um die nächste Reihe zu öffnen und etwas seltener zu verfehlen.",
	["Un servicio cercano, un marcador de tu mapa, donde estás ahora o la entrada de una mazmorra."] = "Ein Dienst in der Nähe, eine Markierung auf deiner Karte, wo du gerade bist oder der Eingang eines Dungeons.",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "Ein Ausrufezeichen über jedem, der Quests für deine Stufe anbietet.",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "Ein Fragezeichen über jedem, der eine fertige Quest entgegennimmt.",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "Ein einziges Addon mit allem, was du beim Spielen brauchst: Schritt-für-Schritt-Guides mit Pfeil und Route, Karte, Taschen, Builds, Heilen per Klick, Sammeln, Dungeons, Angeln und Handel. Alles im selben Stil.",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "Ein Tank, der hart zuschlägt: viel Bedrohung für Gruppen mit viel Schaden, dafür weniger zusätzliche Verteidigung. Für Tanks mit etwas Erfahrung.",
	["Un tramo más en la ruta que armas en la página Ruta: Alfa elige el camino para conseguirlo."] = "Eine Etappe mehr in der Route, die du auf der Seite Route baust: Alfa wählt den Weg, um es zu bekommen.",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "Ein Symbol mit der Fähigkeit, die jetzt am besten ist. Es zeigt nur an: Es drückt nie etwas für dich.",
	["Un ícono de misión en la placa de nombre de los enemigos y personajes que todavía necesitas para una misión de tu registro. En mazmorras el juego oculta esos datos y no se marcan."] = "Ein Questsymbol auf der Namensplakette der Gegner und Figuren, die du noch für eine Quest in deinem Questlog brauchst. In Dungeons verbirgt das Spiel diese Daten, und sie werden nicht markiert.",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "Eine große empfohlene Aktion und dein Weg in ein paar Klicks.",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "Eine Leiste mit den Angriffen, die der Boss gleich einsetzt, und wie lange es bis zu jedem dauert. So weißt du, wann du ausweichen oder dich verteidigen musst.",
	["Una bienvenida nueva en 9 pasos con la intro del lobo: eliges el idioma de Alfa (hay 10) y cada cosa que hace sola por ti."] = "Eine neue Begrüßung in 9 Schritten mit dem Wolfsintro: Du wählst Alfas Sprache (es gibt 10) und alles, was es selbst für dich erledigt.",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "Eine Textzeile enthält einen ganzen Build: Du kopierst sie, gibst sie weiter, und sie fügen sie ein.",
	["Una cantidad de oro; se cumple cuando la llevas encima."] = "Eine Menge Gold; erfüllt, sobald du sie dabeihast.",
	["Una categoría…"] = "Eine Kategorie…",
	["Una cuenta de prueba no puede compartir"] = "Ein Testaccount kann nicht teilen",
	["Una fila con vuelo, posada, reparar, banco, buzón y tu entrenador, a un clic."] = "Eine Reihe mit Flug, Gasthaus, Reparatur, Bank, Briefkasten und deinem Lehrer, einen Klick entfernt.",
	["Una flecha en pantalla que apunta a tu siguiente objetivo, con la distancia. Apagada: tú decides por dónde ir."] = "Ein Pfeil auf dem Bildschirm, der mit Entfernung auf dein nächstes Ziel zeigt. Aus: Du entscheidest selbst, wo es langgeht.",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "Ein grüner Pfeil auf jedem Gegenstand in deinen Taschen, der ein Upgrade für deine Spezialisierung ist.",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "Ein grüner Pfeil auf Ausrüstung, die besser ist als deine angelegte, passend zu Klasse und Stufe.",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "Ein hellgrüner Streifen zeigt Heilungen, die schon unterwegs sind.",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "Ein Guide für deine Stufe und dein Gebiet oder deine eigene Questroute.",
	["Una loba gordita como yo necesita sus tres comidas... y sus botanas."] = "Eine pummelige Wölfin wie ich braucht ihre drei Mahlzeiten... und ihre Snacks.",
	["Una loba negra que te da consejos y ánimo en el camino, sin estorbar. En memoria de una gran perrita."] = "Eine schwarze Wölfin, die dir unterwegs Tipps und Mut gibt, ohne zu stören. In Erinnerung an eine wunderbare kleine Hündin.",
	["Una línea corta debajo del ícono, como «Golpe mortal: recarga lista». Cada una sale hasta 4 veces y luego se calla; su × la calla antes."] = "Eine kurze Zeile unter dem Symbol, etwa „Tödlicher Stoß: Abklingzeit bereit“. Jede erscheint bis zu 4-mal und verstummt dann; ihr × bringt sie früher zum Schweigen.",
	["Una línea debajo del aviso con lo que pasó."] = "Eine Zeile unter dem Hinweis mit dem, was passiert ist.",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "Eine rote Linie oben warnt, wenn ein Gegner es auf dieses Mitglied abgesehen hat.",
	["Una mano"] = "Einhändig",
	["Una meta que marcas tú (el botón de hecha del rastreador o de esta lista)."] = "Ein Ziel, das du selbst abhakst (der Erledigt-Button im Tracker oder in dieser Liste).",
	["Una misión"] = "Eine Quest",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "Eine Münze auf grauen Gegenständen und dem, was du als Plunder markiert hast.",
	["Una nota con el instructor más cercano cuando tienes habilidades nuevas."] = "Ein Hinweis mit dem nächsten Lehrer, wenn du neue Fähigkeiten hast.",
	["Una revisión completa de todos los módulos: más de 60 arreglos."] = "Eine komplette Überprüfung aller Module: über 60 Korrekturen.",
	["Una revisión completa para la versión estable: más de 20 arreglos en mazmorras con grupo, combate, el mapa, Pesca, Talentos y más."] = "Eine komplette Überprüfung für die stabile Version: über 20 Korrekturen in Gruppendungeons, Kampf, Karte, Angeln, Talenten und mehr.",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Elige una de estas para empezar:"] = "Eine Route ist dein Baum aus Etappen: EP-, Gold- oder Klassenquests, Materialien oder Gegenstände. Wähl eine davon, um anzufangen:",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "Eine Route braucht mindestens 3 Orte, die deine Fertigkeit erreicht. Wähle unten eine andere Art oder Ressource, oder sammle hier: Alfa notiert jedes Vorkommen, das du findest.",
	["Una ruta por los mejores lugares para tu habilidad, con unas misiones de XP en medio."] = "Eine Route über die besten Orte für deine Fertigkeit, mit ein paar EP-Quests dazwischen.",
	["Una salchicha al día mantiene a la loba feliz. Es ciencia."] = "Ein Würstchen am Tag hält die Wölfin glücklich. Das ist Wissenschaft.",
	["Una sesión termina tras 20 minutos sin lanzar o cuando empiezas otra; entonces aparece aquí con lo que sacaste y dónde."] = "Eine Sitzung endet nach 20 Minuten ohne Auswerfen oder wenn du eine neue beginnst; dann erscheint sie hier mit deinem Fang und dem Ort.",
	["Una sesión tranquila: nada nuevo que contar."] = "Eine ruhige Sitzung: nichts Neues zu berichten.",
	["Una tecla para todo: equipo, cebo, lanzar y recoger. Con diario, guía, cocina, metas y estadísticas."] = "Eine Taste für alles: Ausrüstung, Köder, Auswerfen und Einholen. Mit Tagebuch, Guide, Kochen, Zielen und Statistiken.",
	["Une los %d lugares que tu habilidad alcanza en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "Verbindet die %d Orte, die deine Fertigkeit erreicht, zu einer kurzen Runde, zeichnet sie auf der Karte ein, und der Pfeil führt dich von Halt zu Halt.",
	["Unir las capas de sombra"] = "Schattenebenen überblenden",
	["Unirte al grupo de tus amigos"] = "Der Gruppe deiner Freunde beitreten",
	["Uno de los dragones verdes de la pesadilla aparece en el Bosque del Ocaso, junto a un gran árbol."] = "Einer der grünen Drachen des Albtraums erscheint im Dämmerwald neben einem großen Baum.",
	["Uno menos"] = "Einer weniger",
	["Uno más"] = "Einer mehr",
	["Unos pocos altos elfos siguen con la Alianza; viven en Quel'Danil, en las Tierras del Interior."] = "Ein paar Hochelfen sind noch bei der Allianz; sie leben in Quel'Danil im Hinterland.",
	["Usa %s"] = "Benutze %s",
	["Usa %s: tu tecla lo pone."] = "Nimm %s: Deine Taste bringt ihn an.",
	["Usa Bloquear con escudo cuando un jefe pegue fuerte."] = "Nutze Schildblock, wenn ein Boss hart zuschlägt.",
	["Usa Deseo de muerte al empezar contra un jefe."] = "Nutze Todeswunsch zu Beginn eines Bosskampfs.",
	["Usa Deseo de muerte con monstruos difíciles, no con los fáciles."] = "Nutze Todeswunsch bei schweren Monstern, nicht bei leichten.",
	["Usa Golpe mortal sobre todo contra sanadores."] = "Nutze Tödlicher Stoß vor allem gegen Heiler.",
	["Usa Golpes de barrido cuando haya dos o más enemigos juntos."] = "Nutze Weitreichende Stöße, wenn zwei oder mehr Gegner zusammenstehen.",
	["Usa Ira rabiosa para romper miedos."] = "Nutze Berserkerwut, um Furcht zu brechen.",
	["Usa Revancha cada vez que se ilumine y Hender armadura para sumar amenaza."] = "Nutze Rache jedes Mal, wenn es aufleuchtet, und Rüstung zerreißen für mehr Bedrohung.",
