	["Usa el juicio y vuelve a poner tu sello enseguida."] = "Nutze Richturteil und setz dein Siegel sofort wieder.",
	["Usa el número de abajo en lugar del que detecta el juego."] = "Nutzt die Zahl unten statt der, die das Spiel erkennt.",
	["Usa el número de abajo para el blanco normal."] = "Nutzt die Zahl unten für normales Weiß.",
	["Usa el resaltado del propio juego sobre el botón de la habilidad sugerida."] = "Nutzt die eigene Hervorhebung des Spiels auf dem Knopf der vorgeschlagenen Fähigkeit.",
	["Usa la forma felina con un monstruo y la de oso si vienen varios."] = "Nutze die Katzengestalt gegen ein Monster und die Bärengestalt, wenn mehrere kommen.",
	["Usa tu golpe principal para juntar puntos de combo y gástalos en tu remate."] = "Nutze deinen Hauptschlag, um Combopunkte aufzubauen, und gib sie für deinen Finishing-Move aus.",
	["Usa tu varita cuando quieras ahorrar maná."] = "Nutze deinen Zauberstab, wenn du Mana sparen willst.",
	["Usa tus hechizos de control si se te juntan dos monstruos."] = "Nutze deine Kontrollzauber, wenn sich zwei Monster auf dich stürzen.",
	["Usa un arma lenta y fuerte: tus mejoras de arma pegan con cada golpe."] = "Nutze eine langsame, starke Waffe: Deine Waffenverbesserungen treffen mit jedem Schlag.",
	["Usa una varita para rematar enemigos sin gastar maná."] = "Benutze einen Zauberstab, um Gegner ohne Manaverbrauch zu erledigen.",
