	["¡%d misiones entregadas hoy! Así se caza en manada."] = "%d Quests heute abgegeben! So jagt das Rudel.",
	["¡%d misiones hoy! Estás que no te para nadie."] = "%d Quests heute! Dich hält keiner auf.",
	["¡%s!"] = "%s!",
	["¡%s! Hace días que no te veía. En Hoy te digo dónde íbamos."] = "%s! Ich habe dich seit Tagen nicht gesehen. Unter „Heute“ sage ich dir, wo wir waren.",
	["¡%s! Te extrañé mucho. Vine corriendo en cuanto te vi llegar."] = "%s! Ich habe dich so vermisst. Ich bin sofort losgerannt, als ich dich gesehen habe.",
	["¡%s, volviste! Te extrañé tanto que no paraba de mover la cola."] = "%s, du bist zurück! Ich habe dich so vermisst, dass ich nicht aufhören konnte, mit dem Schwanz zu wedeln.",
	["¡Abrumar!"] = "Überwältigen!",
	["¡Ahí estás, %s! Si quieres un consejo, dame clic."] = "Da bist du ja, %s! Wenn du einen Tipp willst, klick mich an.",
	["¡Ahí estás, %s! Te estaba esperando… te extrañé."] = "Da bist du, %s! Ich habe auf dich gewartet… ich habe dich vermisst.",
	["¡Arriba, lobo! Antes de volver a pelear, recupera vida y maná."] = "Hoch mit dir, Wolf! Bevor du wieder kämpfst, hol dir Gesundheit und Mana zurück.",
	["¡Arriba, lobo! Caer es parte de la cacería. Al revivir, repara tu equipo."] = "Hoch mit dir, Wolf! Fallen gehört zur Jagd. Wenn du wieder lebst, reparier deine Ausrüstung.",
	["¡Arriba, lobo! Libera tu espíritu: la flecha te dice si conviene tu cuerpo o el sanador."] = "Hoch mit dir, Wolf! Lass deinen Geist frei: Der Pfeil zeigt dir, ob dein Körper oder der Geistheiler besser ist.",
	["¡Arriba, lobo! Si eran muchos, la próxima jálalos de uno en uno."] = "Hoch mit dir, Wolf! Waren es zu viele, zieh sie nächstes Mal einzeln.",
	["¡Arriba, nivel %d! Si tienes un punto de talento libre, no lo olvides."] = "Auf geht's, Stufe %d! Wenn du einen freien Talentpunkt hast, vergiss ihn nicht.",
	["¡Así se ve un aviso!"] = "So sieht ein Hinweis aus!",
	["¡Ataque de la victoria!"] = "Siegesrausch!",
	["¡Bien hecho! %s"] = "Gut gemacht! %s",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "Morgen, %s! Die Sonne ist über Azeroth aufgegangen. Gehen wir?",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "Guten Abend, %s! Wir Wölfinnen jagen nachts am besten.",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "Guten Tag, %s! Eine gute Zeit für ein paar Quests.",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "Hallo, %s! Schritt für Schritt kommt man weit.",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "Guten Morgen, %s! Strecken, gähnen und ich bin bereit.",
	["¡Completaste %s!"] = "Du hast %s abgeschlossen!",
	["¡Contraataque!"] = "Gegenangriff!",
	["¡De vuelta con la manada!"] = "Zurück beim Rudel!",
