	["¡Ejecutar!"] = "Hinrichten!",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "In Thelsamar gibt es Blutwurst! Die Thelsamar-Blutwurst ist fast ein Würstchen... kaufst du mir eine?",
	["¡Es ahora! Hasta las %s"] = "Jetzt läuft er! Bis %s",
	["¡Hola!"] = "Hallo!",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "Hallo! Ich bin Lya, die treue Wölfin des Alfa. Ich passe auf das Rudel auf und gehe den Weg mit dir.",
	["¡Hola, %s!"] = "Hallo, %s!",
	["¡Hola, %s! Hoy huele a buena cacería."] = "Hallo, %s! Heute riecht es nach einer guten Jagd.",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "Hallo, %s! Der Nachmittag sieht ruhig aus. Was jagen wir heute?",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "Hallo, %s! Eine Mondnacht: perfekt für das Rudel.",
	["¡Listo! %s precios guardados."] = "Fertig! %s Preise gespeichert.",
	["¡Listo! Alfa ya es tuyo"] = "Fertig! Alfa gehört dir",
	["¡Lo tienes! %s ×%d"] = "Hast du! %s ×%d",
	["¡Martillo de cólera!"] = "Hammer des Zorns!",
	["¡Mordedura de mangosta!"] = "Mungobiss!",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "Stufe %d! Nimm dir einen Moment, um damit anzugeben, du hast es dir verdient.",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "Stufe %d! Fester Schritt und scharfe Zähne.",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "Stufe %d! Deine Mühe zahlt sich aus. Weiter so.",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "Stufe %d! Auuu! So steigt man im Rudel auf.",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "Stufe %d, gut gemacht! Schau, ob dein Lehrer etwas Neues hat.",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "Stufe 10! Jetzt hast du Talente: Wähl sie in Ruhe, Talente hilft dir.",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "Stufe 20! Jetzt schaffst du echte Dungeons. Stellen wir eine Gruppe zusammen?",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "Stufe 30! Du hast schon die Hälfte des Weges. Das Rudel ist so stolz!",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "Stufe 40! Jetzt kannst du reiten lernen. Dein erstes Reittier wartet!",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "Stufe 50! Der Gipfel ist schon zu riechen. Spar Gold für das, was kommt.",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "Stufe 60! Du hast es geschafft, Alpha! Jetzt geht die große Jagd los.",
	["¡Plan terminado!"] = "Plan abgeschlossen!",
	["¡Primera vez! Nuevo en tu diario"] = "Zum ersten Mal! Neu in deinem Tagebuch",
	["¡Qué buena racha traes! Sigue así."] = "Was für eine Glückssträhne! Weiter so.",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "Schön, dass du wieder da bist, %s! Ich bin noch hier und halte dir den Rücken frei.",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "Schön, dich wiederzusehen! Das bringt diese Version für dich und dein Rudel.",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "Schön, dich zu sehen, %s! Das Rudel hat schon auf dich gewartet.",
	["¡Repara tu equipo!"] = "Repariere deine Ausrüstung!",
	["¡Revancha!"] = "Rache!",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "Du hast Stufe %d erreicht! Jede Stufe macht dich stärker.",
	["¡Te extrañé, %s! Corrí hasta aquí para verte."] = "Ich habe dich vermisst, %s! Ich bin den ganzen Weg gerannt, um dich zu sehen.",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "Ich habe dich vermisst, %s! Deine Route geht da weiter, wo du aufgehört hast.",
	["¡Terminaste %s!"] = "Du hast %s abgeschlossen!",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "Du hast diesen Guide abgeschlossen! Wähle den nächsten und steig mit dem Rudel weiter auf.",
	["¡Terminaste tu guía!"] = "Du hast deinen Guide abgeschlossen!",
	["¡Tú!"] = "Du!",
	["¡Volviste, %s! Estira las patas y vámonos."] = "Du bist zurück, %s! Streck die Pfoten und los geht's.",
	["¡Ya eres nivel %d! La manada aúlla por ti."] = "Du bist jetzt Stufe %d! Das Rudel heult für dich.",
	["¡Ya llegaste, %s! Te extrañé. ¿A dónde vamos hoy?"] = "Da bist du ja, %s! Ich habe dich vermisst. Wohin geht's heute?",
	["¡Ya terminaste %d misiones! Vamos a cobrar la recompensa."] = "Du hast %d Quests abgeschlossen! Holen wir uns die Belohnung.",
	["«%s» tiene su historia. ¿Te la cuento?"] = "„%s“ hat eine Geschichte. Soll ich sie dir erzählen?",
	["«%s» ya quedó. Su final vale la pena, ¿te lo cuento?"] = "„%s“ ist erledigt. Das Ende lohnt sich, soll ich es dir erzählen?",
	["«Alejar más la cámara» de Comodidades está encendido y manda sobre este valor al entrar."] = "„Kamera weiter herauszoomen“ unter Komfort ist eingeschaltet und überschreibt diesen Wert beim Einloggen.",
	["«Buscar cerca» en la página Hoy"] = "„In der Nähe suchen“ auf der Seite „Heute“",
	["«Buscar cerca» te lleva con flecha a lo que necesitas, y «Mis planes» arma tus propias metas, que se marcan solas."] = "„In der Nähe suchen“ führt dich mit dem Pfeil zu dem, was du brauchst, und „Meine Pläne“ erstellt deine eigenen Ziele, die sich selbst abhaken.",
	["«Cerrar mis misiones» está al día"] = "„Meine Quests abschließen“ ist aktuell",
	["«Igual que Alfa» sigue el estilo de Ajustes > Apariencia y cambia con él."] = "„Wie Alfa“ folgt dem Stil unter Einstellungen > Aussehen und wechselt mit ihm.",
	["«Invitar al clan» en el clic derecho"] = "„In Gilde oder Community einladen“ per Rechtsklick",
	["«Prepárame» recoge solo las que ya puedes tomar y te lleva a la entrada."] = "„Mach mich bereit“ nimmt nur die an, die du schon annehmen kannst, und bringt dich zum Eingang.",
	["«Seguir» en La Jauría ya no se suelta cuando tu guía cambia de paso ni cuando vas por tu cuerpo: al terminar, la flecha vuelve con quien sigues."] = "„Folgen“ in La Jauría lässt nicht mehr los, wenn dein Guide den Schritt wechselt oder du zu deinem Körper läufst: danach zeigt der Pfeil wieder auf die Person, der du folgst.",
	["«Siempre» sirve si un amigo encantador te ayuda. Las tablas de desencantar son estimadas."] = "„Immer“ passt, wenn dir ein befreundeter Verzauberer hilft. Die Entzauberungstabellen sind geschätzt.",
	["«Ver el siguiente» te deja mirar el paso que viene y lo dice claro; y un solo contador de pasos hechos."] = "„Nächsten ansehen“ lässt dich den kommenden Schritt anschauen und sagt das klar; dazu ein einziger Zähler für erledigte Schritte.",
	["¿Abandonar %d misiones?"] = "%d Quests abbrechen?",
	["¿Abandonar %d misión?"] = "%d Quest abbrechen?",
	["¿Algo raro?"] = "Stimmt was nicht?",
	["¿Aplicar estos talentos?"] = "Diese Talente anwenden?",
	["¿Borrar el diario?"] = "Tagebuch löschen?",
	["¿Borrar el historial?"] = "Verlauf löschen?",
	["¿Borrar esta ruta?"] = "Diese Route löschen?",
	["¿Borrar este build?"] = "Diesen Build löschen?",
	["¿Borrar este plan?"] = "Diesen Plan löschen?",
	["¿Borrar lo que descubriste?"] = "Deine Funde löschen?",
	["¿Borrar los precios?"] = "Preise löschen?",
	["¿Borrar todo tu progreso?"] = "Deinen gesamten Fortschritt löschen?",
	["¿Borrar todo tu registro de pesca?"] = "Dein ganzes Angelprotokoll löschen?",
	["¿Borrar todos tus marcadores?"] = "Alle deine Markierungen löschen?",
	["¿Cuánto decide Alfa por ti en el camino?"] = "Wie viel entscheidet Alfa unterwegs für dich?",
	["¿Cómo quieres hacerlo?"] = "Wie willst du es machen?",
	["¿Cómo quieres que se vea Alfa?"] = "Wie soll Alfa aussehen?",
	["¿Empezar el medidor de cero?"] = "Schadensmesser von vorn beginnen?",
	["¿Empezar una sesión nueva?"] = "Eine neue Sitzung beginnen?",
	["¿En qué idioma quieres Alfa?"] = "In welcher Sprache möchtest du Alfa?",
	["¿Eso que huele es pan de la posada? Mi nariz nunca se equivoca."] = "Riecht das da nach Brot aus dem Gasthaus? Meine Nase irrt sich nie.",
	["¿La haces con tu manada o la saltas?"] = "Machst du sie mit deinem Rudel oder überspringst du sie?",
	["¿La vuelves a tomar o la sacas de la ruta?"] = "Nimmst du sie noch mal an oder nimmst du sie aus der Route?",
	["¿Olvidar a este personaje?"] = "Diesen Charakter vergessen?",
	["¿Olvidar tu progreso?"] = "Deinen Fortschritt vergessen?",
	["¿Otra cosa hoy?"] = "Heute etwas anderes?",
	["¿Otra vez?"] = "Noch mal?",
	["¿Oíste eso? Nada… solo el viento. Sigamos."] = "Hast du das gehört? Nichts… nur der Wind. Weiter geht's.",
	["¿Paramos a comer? Mi panza ya está aullando."] = "Machen wir eine Essenspause? Mein Bauch heult schon.",
	["¿Por dónde sigues?"] = "Wo geht es weiter?",
	["¿Quieres cazar con nosotros? Pulsa el botón: Alfa busca a un oficial conectado y te abre un susurro con tu mensaje listo para que lo envíes con Intro."] = "Willst du mit uns jagen? Drück den Knopf: Alfa sucht einen Offizier, der online ist, und öffnet ein Flüstern mit deiner fertigen Nachricht, die du mit Enter abschickst.",
	["¿Quieres que la manada te vea en el mapa del juego?"] = "Soll das Rudel dich auf der Spielkarte sehen?",
	["¿Qué buscas?"] = "Was suchst du?",
	["¿Qué es Alfa?"] = "Was ist Alfa?",
	["¿Qué hace Alfa con comerciantes y viajes?"] = "Was macht Alfa bei Händlern und Reisen?",
	["¿Qué hace Alfa con tus misiones?"] = "Was macht Alfa mit deinen Quests?",
	["¿Qué hacemos hoy?"] = "Was machen wir heute?",
	["¿Qué hago con mis objetos?"] = "Was mache ich mit meinen Gegenständen?",
	["¿Qué nos quieres contar?"] = "Was möchtest du uns erzählen?",
	["¿Qué quieres hacer hoy?"] = "Was willst du heute machen?",
	["¿Qué quieres hacer?"] = "Was willst du machen?",
	["¿Qué responde Alfa por ti a otros jugadores?"] = "Was antwortet Alfa anderen Spielern für dich?",
	["¿Qué sigue?"] = "Was kommt als Nächstes?",
	["¿Reiniciar los gráficos?"] = "Grafik neu starten?",
	["¿Sabías que las lobas tenemos el mejor oído de la manada? Bueno, eso digo yo."] = "Wusstest du, dass wir Wölfinnen das beste Gehör im Rudel haben? Na ja, das sage ich zumindest.",
	["¿Sabías que…? Alfa junta tus misiones listas en una sola ruta corta."] = "Wusstest du schon…? Alfa fasst deine fertigen Quests zu einer kurzen Route zusammen.",
	["¿Sabías que…? Alfa tiene tres estilos: Alfa, Clásico WoW y Cristal. Y yo me pongo el que elijas."] = "Wusstest du schon…? Alfa hat drei Stile: Alfa, Klassisches WoW und Glas. Und ich trage den, den du wählst.",
	["¿Sabías que…? Alt+clic en un objeto lo abre en la Enciclopedia."] = "Wusstest du schon…? Alt+Klick auf einen Gegenstand öffnet ihn in der Enzyklopädie.",
	["¿Sabías que…? Buscar cerca te lleva al herrero, al banco o al vuelo más cercano."] = "Wusstest du schon…? „In der Nähe suchen“ bringt dich zum nächsten Schmied, zur Bank oder zum Flugmeister.",
	["¿Sabías que…? Comercio te dice si algo conviene venderlo, subastarlo o convertirlo."] = "Wusstest du schon…? Handel sagt dir, ob du etwas besser verkaufst, versteigerst oder verarbeitest.",
	["¿Sabías que…? Con /alfa reportar le cuentas a toxic3000 de un error o una idea."] = "Wusstest du schon…? Mit /alfa reportar erzählst du toxic3000 von einem Fehler oder einer Idee.",
	["¿Sabías que…? Con Pesca lanzas y recoges con una sola tecla."] = "Wusstest du schon…? Mit Angeln wirfst du aus und holst ein, alles mit einer Taste.",
	["¿Sabías que…? Con clic derecho sobre mí puedes silenciarme una hora o pedirme menos consejos."] = "Wusstest du schon…? Mit Rechtsklick auf mich kannst du mich eine Stunde stummschalten oder um weniger Tipps bitten.",
	["¿Sabías que…? Con el botón del minimapa ocultas todo Alfa y lo vuelves a traer."] = "Wusstest du schon…? Mit dem Minikarten-Button blendest du ganz Alfa aus und wieder ein.",
	["¿Sabías que…? El mapa de Alfa muestra el terreno, tus marcadores y lo que hay cerca."] = "Wusstest du schon…? Alfas Karte zeigt das Gelände, deine Markierungen und was in der Nähe ist.",
	["¿Sabías que…? En Bolsas ves tus bolsas, tu banco y lo de todos tus personajes."] = "Wusstest du schon…? Unter Taschen siehst du deine Taschen, deine Bank und den Besitz all deiner Charaktere.",
	["¿Sabías que…? En La Jauría ves a tu grupo y a la manada que usa Alfa."] = "Wusstest du schon…? Unter La Jauría siehst du deine Gruppe und das Rudel, das Alfa nutzt.",
	["¿Sabías que…? En Mis planes armas tu propia lista de metas y la flecha te guía."] = "Wusstest du schon…? Unter „Meine Pläne“ erstellst du deine eigene Zielliste, und der Pfeil führt dich.",
	["¿Sabías que…? En Talentos ves qué talento poner ahora y por qué."] = "Wusstest du schon…? Unter Talente siehst du, welches Talent du jetzt nehmen solltest und warum.",
	["¿Sabías que…? La Enciclopedia te dice dónde sale cada objeto, PNJ o misión."] = "Wusstest du schon…? Die Enzyklopädie sagt dir, wo es jeden Gegenstand, NPC oder jede Quest gibt.",
	["¿Sabías que…? La página Hoy te dice qué hacer ahora y lo urgente de tu personaje."] = "Wusstest du schon…? Die Seite „Heute“ sagt dir, was jetzt zu tun ist und was bei deinem Charakter dringend ist.",
	["¿Sabías que…? Mazmorras te dice cuál te toca y cómo prepararte."] = "Wusstest du schon…? Dungeons sagt dir, welcher dran ist und wie du dich vorbereitest.",
	["¿Sabías que…? Recolección te marca en el mapa minerales, hierbas y bancos de peces."] = "Wusstest du schon…? Sammeln markiert dir Erze, Kräuter und Fischschwärme auf der Karte.",
	["¿Te conté que mi comida favorita son las salchichas? Ninguna otra cosa se le acerca."] = "Hab ich dir erzählt, dass Würstchen mein Lieblingsessen sind? Nichts kommt da heran.",
	["¿Una carrerita hasta allá? Yo gano."] = "Ein Wettrennen bis dahin? Ich gewinne.",
	["¿Usar tu hechizo nuevo?"] = "Deinen neuen Zauber nutzen?",
	["¿Usar «%s»?"] = "„%s“ nutzen?",
	["¿Vender, subastar o transformar? (escanear, precio <objeto>)"] = "Verkaufen, versteigern oder umwandeln? (escanear = scannen, precio <Gegenstand> = Preis)",
	["¿Vender, subastar o transformar? Lo que más oro te deja con cada objeto."] = "Verkaufen, versteigern oder umwandeln? Was dir bei jedem Gegenstand am meisten Gold bringt.",
	["¿Volver a lo de antes?"] = "Vorherige Werte zurückholen?",
	["¿Ya exploraste todo %s? Siempre queda un rincón por ver."] = "Hast du schon ganz %s erkundet? Irgendeine Ecke bleibt immer.",
	["¿Ya hiciste esta mazmorra?"] = "Hast du diesen Dungeon schon gemacht?",
	["¿qué quieres hacer?"] = "was willst du machen?",
	["Ábrela con su botón en la barra de menú del juego: la fila de botones pequeños de abajo a la derecha."] = "Öffne es mit seinem Knopf in der Menüleiste des Spiels: die Reihe kleiner Knöpfe unten rechts.",
	["Ábrela con tu tecla de talentos (%s) o desde el menú del juego."] = "Öffne es mit deiner Talent-Taste (%s) oder über das Spielmenü.",
	["Ábrela con tu tecla de talentos o desde el menú del juego."] = "Öffne es mit deiner Talent-Taste oder über das Spielmenü.",
	["Ábrela con tu tecla del Legado (%s) o con su botón en la barra de menú del juego."] = "Öffne es mit deiner Vermächtnis-Taste (%s) oder mit seinem Knopf in der Menüleiste des Spiels.",
	["Ábrelo con /alfa o con el lobo del minimapa. Para cambiar algo de esto: /alfa bienvenida."] = "Öffne es mit /alfa oder dem Wolf an der Minikarte. Um etwas davon zu ändern: /alfa bienvenida.",
	["Ámbar"] = "Bernstein",
	["Ángel de la resurrección"] = "Geistheiler",
	["Ángeles de la resurrección"] = "Geistheiler",
	["Árboles, rocas, cercas y adornos: más alto, se ven completos desde más lejos."] = "Bäume, Felsen, Zäune und Dekoration: Höher zeigt sie aus größerer Entfernung vollständig.",
	["Área"] = "Fläche",
	["Élite"] = "Elite",
	["Épico"] = "Episch",
	["Éxito"] = "Erfolg",
	["Ícono"] = "Symbol",
	["Ícono de rotación"] = "Rotationssymbol",
	["Ícono sobre el corcho"] = "Symbol über dem Schwimmer",
	["Íconos de ayuda"] = "Hilfssymbole",
	["Íconos limpios y tus recursos en el mapa"] = "Saubere Symbole und deine Ressourcen auf der Karte",
	["Íconos sin bordes negros: el mapa y las ventanas de Alfa se ven limpios al hacer zoom o al teñirse de color."] = "Symbole ohne schwarze Ränder: Die Karte und Alfas Fenster sehen sauber aus, wenn du zoomst oder sie eingefärbt werden.",
	["Ídolo"] = "Götze",
	["×%d"] = "×%d",
	["Última posición enviada %s."] = "Letzte Position gesendet %s.",
	["Última: %s ×%d · %d en la sesión"] = "Zuletzt: %s ×%d · %d in der Sitzung",
	["Último envío: %s por %s, respuesta %s"] = "Letzter Versand: %s über %s, Antwort %s",
	["Último escaneo %s · %s objetos con precio."] = "Letzter Scan %s · %s Gegenstände mit Preis.",
	["Únete a un grupo o banda para anunciar el top."] = "Tritt einer Gruppe oder einem Schlachtzug bei, um das Top anzusagen.",
	["Únete a un grupo para compartir tus marcadores."] = "Tritt einer Gruppe bei, um deine Markierungen zu teilen.",
	["Único"] = "Einzigartig",
	["élite"] = "Elite",
	["épico"] = "episch",
	["última: %s"] = "zuletzt: %s",
	["• GatherLite, de Wuild (MIT): la base de nodos de recolección."] = "• GatherLite, von Wuild (MIT): die Datenbank der Sammelvorkommen.",
	["• Letras Inter, Fira Sans y Open Sans (SIL Open Font License 1.1)."] = "• Schriften Inter, Fira Sans und Open Sans (SIL Open Font License 1.1).",
	["• OpenMap, de OpenMap contributors (MIT): la lógica del mapa continuo y las máscaras de territorio."] = "• OpenMap, von OpenMap contributors (MIT): die Logik der durchgehenden Karte und die Gebietsmasken.",
	["• Polestar, de The Polestar authors (GPL-3.0): el motor de guías, navegación y datos (github.com/fitzforge/polestar)."] = "• Polestar, von The Polestar authors (GPL-3.0): die Engine für Guides, Navigation und Daten (github.com/fitzforge/polestar).",
	["• Shortest Path Forever, de Cillian Berragan (GPL-3.0-or-later): la navegación y los servicios cercanos."] = "• Shortest Path Forever, von Cillian Berragan (GPL-3.0-or-later): die Navigation und die Dienste in der Nähe.",
	["• TerrainWorldMap, de Dramacydal (MIT): la tabla de mosaicos del terreno del mapa."] = "• TerrainWorldMap, von Dramacydal (MIT): die Kacheltabelle des Kartengeländes.",
	["• pfQuest, de shagu (MIT): datos de misiones, PNJ y objetos."] = "• pfQuest, von shagu (MIT): Daten zu Quests, NPCs und Objekten.",
